-- 자동 생성 파일입니다. 고치지 말고 pnpm db:seed:generate로 다시 만듭니다.
begin;
set constraints all deferred;
insert into public.pantheons (slug, name, name_en, region, continent, earliest_source, era_label, era_year, summary, description, cover_exhibit_id)
select slug, name, name_en, region, continent, earliest_source, era_label, era_year, summary, description, cover_exhibit_id from jsonb_populate_recordset(null::public.pantheons, $seed$[{"slug":"egyptian","name":"이집트 신화","name_en":"Egyptian","region":"나일강 유역","continent":"africa","earliest_source":"피라미드 텍스트","era_label":"기원전 24세기경","era_year":-2400,"summary":"죽음 이후의 삶과 심판, 태양의 순환을 중심으로 삼천 년 넘게 이어진 신화입니다.","description":["이집트 신화는 나일강의 범람과 태양의 운행처럼 되풀이되는 자연의 질서를 신들의 이야기로 풀어냈습니다.","왕의 무덤 벽에 새긴 피라미드 텍스트에서 시작해 관 텍스트, 사자의 서로 이어지며 죽은 이가 저승을 지나 심판을 받는 과정이 자세히 기록되었습니다."],"cover_exhibit_id":"weighing-heart"},{"slug":"mesopotamian","name":"메소포타미아 신화","name_en":"Mesopotamian","region":"티그리스·유프라테스강 유역","continent":"asia","earliest_source":"수메르어 길가메시 시가","era_label":"기원전 21세기경","era_year":-2100,"summary":"점토판에 쐐기문자로 새긴, 인류가 남긴 가장 오래된 영웅 서사가 있는 신화입니다.","description":["수메르, 아카드, 바빌로니아, 아시리아로 이어진 도시 문명들은 신들을 도시의 수호자로 섬겼습니다.","죽음을 피하려 길을 떠난 길가메시의 이야기와 혼돈의 바다를 무찌르고 세계를 세운 마르두크의 창조 서사시 「에누마 엘리시」가 대표적입니다."],"cover_exhibit_id":"ishtar-gate-lion"},{"slug":"hindu","name":"인도 신화","name_en":"Hindu","region":"인도 아대륙","continent":"asia","earliest_source":"리그베다","era_label":"기원전 15세기경","era_year":-1500,"summary":"창조와 유지, 파괴가 끝없이 되풀이되는 우주관 위에 수많은 신과 화신이 등장합니다.","description":["베다의 찬가에서 시작한 인도 신화는 「마하바라타」, 「라마야나」 같은 서사시와 푸라나 문헌으로 넓어졌습니다.","세계를 유지하는 비슈누와 파괴와 재생의 신 시바, 지혜와 시작의 신 가네샤처럼 지금도 널리 숭배되는 신들이 많습니다."],"cover_exhibit_id":"shiva-nataraja"},{"slug":"greek","name":"그리스 신화","name_en":"Greek","region":"에게해 연안","continent":"europe","earliest_source":"호메로스 「일리아스」·「오디세이아」","era_label":"기원전 8세기경","era_year":-800,"summary":"올림포스의 열두 신과 영웅들의 이야기로, 서양 예술과 문학의 뿌리가 된 신화입니다.","description":["그리스 신화의 신들은 사람처럼 사랑하고 질투하며 다툽니다. 호메로스와 헤시오도스의 서사시가 그 이야기를 처음 글로 남겼습니다.","로마는 그리스의 신들을 자기 신들과 동일시해 받아들였고, 로마 시대에 만든 대리석 모작 덕분에 사라진 그리스 원작의 모습을 지금도 볼 수 있습니다."],"cover_exhibit_id":"artemision-bronze"},{"slug":"japanese","name":"일본 신화","name_en":"Japanese","region":"일본 열도","continent":"asia","earliest_source":"「고사기」","era_label":"712년","era_year":712,"summary":"천지가 열리고 섬들이 태어나는 이야기에서 시작해 태양신의 후손으로 이어지는 신화입니다.","description":["712년에 엮은 「고사기」와 720년의 「일본서기」에 이자나기와 이자나미의 국토 창조, 아마테라스와 스사노오의 이야기가 실려 있습니다.","에도 시대와 메이지 시대의 우키요에 화가들은 이 장면들을 목판화로 즐겨 그렸습니다."],"cover_exhibit_id":"amaterasu-iwato"},{"slug":"norse","name":"북유럽 신화","name_en":"Norse","region":"스칸디나비아·아이슬란드","continent":"europe","earliest_source":"「산문 에다」·「시 에다」","era_label":"13세기","era_year":1220,"summary":"거인과 싸우는 신들, 그리고 피할 수 없는 종말 라그나로크로 끝나는 신화입니다.","description":["북유럽 신화는 오랫동안 입으로 전해지다가 13세기 아이슬란드에서 스노리 스튀르류손의 「산문 에다」와 「시 에다」로 기록되었습니다.","19세기 낭만주의 시대에 스칸디나비아 화가들이 오딘과 토르를 다시 그리면서 오늘날 우리가 떠올리는 북유럽 신들의 모습이 만들어졌습니다."],"cover_exhibit_id":"thor-jotnar"},{"slug":"chinese","name":"중국 신화","name_en":"Chinese","region":"황허·창장 유역","continent":"asia","earliest_source":"「산해경」·「초사」","era_label":"기원전 4세기경","era_year":-350,"summary":"하늘과 땅을 가른 거인 반고, 사람을 빚은 여와, 불사의 복숭아를 기르는 서왕모의 이야기가 여러 책에 흩어져 전하는 신화입니다.","description":["중국 신화는 한 권의 경전이 아니라 「산해경」, 「초사」, 「회남자」 같은 여러 책에 조각조각 흩어져 전합니다.","천지를 연 반고 이야기는 3세기 삼국 시대 오나라의 기록에 처음 보이는 등, 오래된 이야기와 후대에 덧붙은 이야기가 섞여 있습니다. 많은 신이 도교 신앙 속에서 오늘날까지 섬겨집니다."],"cover_exhibit_id":"fuxi-nuwa"},{"slug":"celtic","name":"켈트 신화","name_en":"Celtic","region":"아일랜드·브리튼·갈리아","continent":"europe","earliest_source":"「둔 카우의 서」 (아일랜드 필사본)","era_label":"12세기","era_year":1100,"summary":"사슴뿔을 단 신, 까마귀로 날아다니는 전쟁의 여신, 아일랜드의 영웅 쿠 훌린이 등장하는 서유럽 켈트족의 신화입니다.","description":["갈리아 등 대륙 켈트족의 신화는 로마에 정복된 뒤 대부분 사라지고, 유물과 로마인의 기록으로만 일부 전합니다.","오늘날 알려진 이야기는 대부분 중세 아일랜드와 웨일스의 수도원에서 기록한 필사본에서 나왔습니다. 12세기 초에 만든 「둔 카우의 서」에는 쿠 훌린이 활약하는 얼스터 이야기가 실려 있습니다."],"cover_exhibit_id":"cernunnos-gundestrup"},{"slug":"aztec","name":"아즈텍 신화","name_en":"Aztec","region":"멕시코 중앙 고원","continent":"americas","earliest_source":"그림 문서(코덱스)","era_label":"15~16세기","era_year":1500,"summary":"네 번 무너진 세상 뒤의 다섯 번째 태양 아래에서, 깃털 달린 뱀과 연기 나는 거울의 신이 맞서는 신화입니다.","description":["아즈텍 사람들은 세상이 이미 네 번 멸망했고 지금은 다섯 번째 태양의 시대라고 믿었습니다. 테스카틀리포카, 케찰코아틀, 틀랄록이 앞선 시대의 태양이었다고 전합니다.","신들의 모습은 그림 문서인 코덱스에 남아 있습니다. 스페인 정복 이전에 만든 「보르자 코덱스」와 정복 무렵의 「보르보니쿠스 코덱스」가 대표적입니다."],"cover_exhibit_id":"tezcatlipoca-borgia"},{"slug":"korean","name":"한국 신화","name_en":"Korean","region":"한반도","continent":"asia","earliest_source":"「삼국유사」","era_label":"13세기","era_year":1281,"summary":"하늘에서 내려온 환웅과 웅녀의 아들 단군, 버려졌다가 저승길을 연 바리공주가 등장하는 신화입니다.","description":["한국 신화는 한 권의 경전으로 정리되지 않았습니다. 고려 때 「삼국유사」에 기록된 단군 같은 건국 신화와, 무당이 굿에서 부르는 서사 무가로 입에서 입으로 전해진 신화가 함께 있습니다.","무속에서는 산신, 제석, 바리공주처럼 집과 마을, 삶과 죽음을 지키는 여러 신을 무신도로 그려 모셨고, 이 그림들이 오늘날 신들의 모습을 보여 주는 자료가 되었습니다."],"cover_exhibit_id":"sansin-honolulu"},{"slug":"finnish","name":"핀란드 신화","name_en":"Finnish","region":"핀란드·카렐리아","continent":"europe","earliest_source":"아그리콜라의 신 목록 · 「칼레발라」","era_label":"1551년","era_year":1551,"summary":"노래로 세상을 움직이는 현자 베이네뫼이넨과 북쪽 나라의 여주인 로우히가 보물 삼포를 두고 다투는 신화입니다.","description":["핀란드 신화는 오랫동안 노래로만 전해졌습니다. 1551년 미카엘 아그리콜라가 시편 번역본 서문에 토착 신들의 이름을 적은 것이 가장 이른 기록입니다.","19세기에 엘리아스 뢴로트가 카렐리아 지방의 옛 노래를 모아 서사시 「칼레발라」(1835년 초판, 1849년 완전판)로 엮었고, 화가 악셀리 갈렌칼렐라가 그 장면들을 그렸습니다."],"cover_exhibit_id":"louhi-sampo"},{"slug":"maya","name":"마야 신화","name_en":"Maya","region":"유카탄반도·과테말라 고지","continent":"americas","earliest_source":"고전기 비문 · 「드레스덴 코덱스」 · 「포폴 부」","era_label":"3~9세기 (고전기 비문)","era_year":250,"summary":"옥수수로 사람을 빚은 창조 신들과, 저승의 신들을 꺾은 영웅 쌍둥이가 등장하는 마야 문명의 신화입니다.","description":["마야 사람들은 고전기(3~9세기)의 돌 비문과 토기에 신들의 이름과 모습을 남겼고, 나무껍질 종이로 만든 그림 문서 「드레스덴 코덱스」에는 비의 신 차크와 이참나가 여러 번 나옵니다.","창조 신화는 16세기 키체 마야 사람들이 기록한 「포폴 부」에 전합니다. 신들은 흙과 나무로 사람을 만들려다 실패하고, 마지막에 옥수수로 지금의 사람을 빚었다고 합니다."],"cover_exhibit_id":"maize-god-copan"},{"slug":"iranian","name":"이란 신화","name_en":"Iranian","region":"이란고원","continent":"asia","earliest_source":"「아베스타」","era_label":"기원전 1천년기경","era_year":-1000,"summary":"선한 지혜의 신 아후라 마즈다와 악의 영 앙그라 마이뉴가 맞서는, 조로아스터교와 그 이전 페르시아의 신화입니다.","description":["이란 신화는 조로아스터교 경전 「아베스타」와 그 이전의 인도·이란 공통 신앙을 바탕으로 합니다. 세상은 선과 악이 싸우는 무대이며, 사람은 선한 생각과 말, 행동으로 선의 편에 선다고 여겼습니다.","페르시아 왕들은 바위 부조에 신에게서 왕권의 고리를 받는 장면을 새겼고, 11세기 페르도우시의 서사시 「샤나메」는 이란의 신화와 전설을 영웅 이야기로 엮었습니다."],"cover_exhibit_id":"mithra-taq-bostan"},{"slug":"canaanite","name":"가나안 신화","name_en":"Canaanite","region":"레반트 (가나안)","continent":"asia","earliest_source":"우가리트 점토판","era_label":"기원전 14세기경","era_year":-1350,"summary":"폭풍의 신 바알이 바다의 신 얌, 죽음의 신 모트와 싸우는 이야기가 우가리트 점토판에 남은 레반트의 신화입니다.","description":["가나안 신화는 지금의 시리아·레바논·이스라엘 일대에서 섬긴 신들의 이야기입니다. 1928년 시리아 해안의 우가리트에서 쐐기문자 점토판이 발견되면서 내용이 알려졌습니다.","최고신 엘 아래에서 폭풍과 비의 신 바알이 왕권을 다투며, 그 이야기는 구약성경이 우상으로 배격한 바알 신앙의 배경이기도 합니다."],"cover_exhibit_id":"baal-ugarit"},{"slug":"hittite","name":"히타이트 신화","name_en":"Hittite","region":"아나톨리아","continent":"asia","earliest_source":"하투샤 점토판","era_label":"기원전 16세기경","era_year":-1600,"summary":"폭풍의 신 테슈브가 뱀 일루얀카와 싸우고, ‘천 명의 신’을 섬긴 아나톨리아 히타이트 왕국의 신화입니다.","description":["히타이트 사람들은 정복한 지역의 신들을 받아들여 스스로 ‘하티의 천 신’을 섬긴다고 했습니다. 특히 후르리인의 신들이 많이 들어왔습니다.","수도 하투샤(지금의 튀르키예 보아즈칼레)에서 나온 점토판에는 폭풍의 신이 뱀 일루얀카를 물리치는 이야기, 하늘의 왕권이 대를 이어 옮겨 가는 ‘쿠마르비 신화’ 등이 남아 있습니다."],"cover_exhibit_id":"teshub-yazilikaya"},{"slug":"arabian","name":"아랍 신화 (이슬람 이전)","name_en":"Pre-Islamic Arabian","region":"아라비아반도","continent":"asia","earliest_source":"남아라비아·나바테아 비문","era_label":"기원전 1천년기","era_year":-500,"summary":"이슬람 이전 아라비아에서 섬긴 알라트, 우짜, 마나트 같은 여신들과 나바테아의 신 두샤라의 신화입니다.","description":["이슬람이 생기기 전 아라비아반도의 사람들은 여러 신을 섬겼습니다. 메카 주변에서는 알라트, 알우짜, 마나트 세 여신이 특히 숭배되었습니다.","북쪽의 나바테아와 팔미라 같은 도시들은 이 신들을 그리스·로마의 신과 겹쳐 섬기며 신전과 부조를 남겼습니다."],"cover_exhibit_id":"dushara-nabataean"},{"slug":"slavic","name":"슬라브 신화","name_en":"Slavic","region":"동유럽","continent":"europe","earliest_source":"「원초 연대기」","era_label":"12세기 초","era_year":1113,"summary":"천둥의 신 페룬과 숲속 마녀 바바 야가가 등장하는, 동유럽 슬라브족의 신화입니다.","description":["슬라브 신화는 대부분 입으로 전해져 기록이 적습니다. 12세기 초 키이우에서 엮은 「원초 연대기」에는 블라디미르 대공이 언덕 위에 페룬 등 신들의 상을 세웠다가 기독교로 개종한 뒤 강에 던졌다는 기록이 있습니다.","옛 신들의 모습은 민담과 풍습 속에 남았고, 바바 야가 같은 인물은 러시아 민담에서 오늘날까지 사랑받습니다."],"cover_exhibit_id":"baba-yaga-bilibin"},{"slug":"baltic","name":"발트 신화","name_en":"Baltic","region":"리투아니아·라트비아","continent":"europe","earliest_source":"중세 연대기 · 민요 다이나","era_label":"13세기","era_year":1250,"summary":"천둥의 신 페르쿠나스와 운명의 여신 라이마를 섬긴, 유럽에서 가장 늦게까지 이어진 옛 신앙의 하나입니다.","description":["리투아니아와 라트비아의 발트족은 참나무를 신성하게 여기며 옛 신들을 섬겼습니다. 리투아니아는 14세기 말에야 기독교를 받아들여, 유럽에서 가장 늦게까지 옛 신앙이 남은 곳으로 꼽힙니다.","신들의 이야기는 중세 기사단과 선교사의 기록, 그리고 라트비아의 짧은 민요 ‘다이나’ 수만 편에 전합니다."],"cover_exhibit_id":"perkunas-baltic"},{"slug":"estonian","name":"에스토니아 신화","name_en":"Estonian","region":"에스토니아","continent":"europe","earliest_source":"「칼레비포에그」","era_label":"1857~1861년","era_year":1857,"summary":"거인 영웅 칼레비포에그가 지하 세계의 악마 바나파간과 겨루는, 에스토니아의 민족 서사시와 민간 신앙입니다.","description":["에스토니아의 옛 신앙은 교회 기록과 여행자의 글에 흩어져 있다가, 19세기에 민속을 모으는 움직임 속에서 정리되었습니다.","프리드리히 크로이츠발트는 민간 전승을 바탕으로 서사시 「칼레비포에그」(1857~1861)를 지었고, 이 작품은 에스토니아 민족 문화의 상징이 되었습니다."],"cover_exhibit_id":"kalevipoeg-raud"},{"slug":"etruscan","name":"에트루리아 신화","name_en":"Etruscan","region":"이탈리아 중부","continent":"europe","earliest_source":"청동 거울과 무덤 벽화의 명문","era_label":"기원전 7세기경","era_year":-650,"summary":"로마 이전 이탈리아 중부의 에트루리아인이 섬긴 신들로, 그리스 신화와 많은 이야기를 나눠 가졌습니다.","description":["에트루리아인은 로마가 커지기 전 이탈리아 중부에서 번성한 민족입니다. 하늘의 신 티니아, 그의 아내 우니, 지혜의 여신 멘르바가 대표적인 신입니다.","그리스 신화의 영향을 많이 받아, 청동 거울 뒷면에 신들의 이름을 에트루리아 문자로 새긴 그림이 많이 남았습니다. 죽은 이를 저승으로 데려가는 카룬 같은 고유한 존재도 있습니다."],"cover_exhibit_id":"tinia-etruscan"},{"slug":"minoan","name":"미노스 신화","name_en":"Minoan","region":"크레타","continent":"europe","earliest_source":"유물 (선형 문자 A는 미해독)","era_label":"기원전 17세기경","era_year":-1650,"summary":"청동기 시대 크레타의 미노스 문명에서 섬긴 여신들로, 글이 해독되지 않아 유물로만 짐작합니다.","description":["미노스 문명은 기원전 2천년기 크레타섬에서 크노소스 궁전을 중심으로 번성했습니다. 그들이 쓴 선형 문자 A는 아직 해독되지 않아, 신의 이름과 이야기는 알 수 없습니다.","남은 유물에는 양손에 뱀을 든 여신, 짐승들을 거느린 여신 같은 모습이 자주 보여, 여신 숭배가 중요했으리라 추측합니다. 미노타우로스 이야기는 훗날 그리스인이 전한 것입니다."],"cover_exhibit_id":"snake-goddess-minoan"},{"slug":"armenian","name":"아르메니아 신화","name_en":"Armenian","region":"아르메니아고원","continent":"europe","earliest_source":"모브세스 호레나치 「아르메니아 역사」","era_label":"5세기경","era_year":450,"summary":"용을 물리친 불과 번개의 신 바하근과 어머니 여신 아나히트를 섬긴 아르메니아의 옛 신화입니다.","description":["아르메니아의 옛 신앙은 인도유럽 공통의 신화 위에 이웃 이란의 신들과 그리스 문화가 더해진 것입니다. 301년 아르메니아가 세계 최초로 기독교를 국교로 삼으면서 신전과 기록이 많이 사라졌습니다.","남은 이야기는 5세기 무렵 역사가 모브세스 호레나치가 기록한 노래 조각 등에 전합니다."],"cover_exhibit_id":"anahit-satala"},{"slug":"hungarian","name":"헝가리 신화","name_en":"Hungarian","region":"카르파티아 분지","continent":"europe","earliest_source":"「게스타 훙가로룸」","era_label":"1200년경","era_year":1200,"summary":"신성한 새 투룰이 헝가리 왕가의 시작을 알렸다는 이야기가 전하는 마자르족의 신화입니다.","description":["헝가리인(마자르족)의 신화는 우랄계 신앙에 중앙아시아 유목민의 샤머니즘이 더해진 모습이었다고 봅니다. 기독교를 받아들인 뒤 기록이 많이 사라졌습니다.","1200년 무렵 쓰인 연대기 「게스타 훙가로룸」에는 투룰 새가 에메세의 꿈에 나타나 아들 알모시가 왕가를 열 것을 알렸다는 이야기가 실려 있습니다."],"cover_exhibit_id":"turul-hungarian"},{"slug":"anglo-saxon","name":"앵글로색슨 신화","name_en":"Anglo-Saxon","region":"잉글랜드","continent":"europe","earliest_source":"「베오울프」","era_label":"8세기경","era_year":750,"summary":"브리튼으로 건너간 게르만족 앵글로색슨인의 신화로, 영웅 서사시 「베오울프」와 대장장이 웨일랜드 이야기가 전합니다.","description":["앵글로색슨인은 5세기 무렵 브리튼으로 건너온 게르만족으로, 북유럽 신화와 같은 뿌리의 신들을 섬겼습니다. 영어 요일 이름 Wednesday(워든), Thursday(투노르)에 그 흔적이 남았습니다.","7~8세기에 기독교로 바뀌면서 옛 신앙은 대부분 잊혔지만, 고대 영어 서사시 「베오울프」와 공예품에 새겨진 이야기가 남았습니다."],"cover_exhibit_id":"weland-franks-casket"},{"slug":"thracian","name":"트라키아 신화","name_en":"Thracian","region":"발칸반도 동부","continent":"europe","earliest_source":"그리스 저술가의 기록 · 봉헌 부조","era_label":"기원전 5세기경","era_year":-450,"summary":"말을 탄 영웅신을 수천 개의 부조로 남긴, 발칸반도 동부 트라키아인의 신앙입니다.","description":["트라키아인은 지금의 불가리아와 그리스 북부, 튀르키예 유럽 쪽에 살던 사람들로, 스스로 글을 거의 남기지 않았습니다. 헤로도토스 같은 그리스 저술가들의 기록으로 신앙을 짐작합니다.","말을 탄 채 사냥하는 ‘트라키아의 기수’를 새긴 봉헌 부조가 발칸 곳곳에서 수천 점 발견되었습니다."],"cover_exhibit_id":"thracian-horseman"},{"slug":"yoruba","name":"요루바 신화","name_en":"Yoruba","region":"나이지리아 서남부","continent":"africa","earliest_source":"이파 점술 시가 (구전)","era_label":"구전 (19세기 기록)","era_year":1850,"summary":"최고신 올로두마레 아래 수많은 오리샤가 사람의 삶을 돌보는, 서아프리카 요루바족의 신화입니다.","description":["요루바 신화에서 최고신 올로두마레는 직접 나서지 않고, 오리샤라 불리는 신들이 사람과 세상의 일을 맡습니다. 천둥의 샹고, 길과 전언의 에슈, 지혜의 오룬밀라가 대표적입니다.","신화는 점술 체계 이파의 시가로 대대로 전해졌으며, 대서양 노예무역을 거쳐 쿠바의 산테리아, 브라질의 칸돔블레 같은 신앙으로도 이어졌습니다."],"cover_exhibit_id":"eshu-yoruba"},{"slug":"dogon","name":"도곤 신화","name_en":"Dogon","region":"말리 반디아가라 절벽","continent":"africa","earliest_source":"구전 (20세기 민족지)","era_label":"구전 (20세기 기록)","era_year":1930,"summary":"창조신 암마가 빚은 물의 정령 놈모가 세상에 질서를 가져왔다는 말리 도곤족의 신화입니다.","description":["도곤족은 말리의 반디아가라 절벽 일대에 사는 사람들로, 정교한 나무 조각과 가면 의식으로 유명합니다.","20세기 프랑스 민족학자 마르셀 그리올이 원로들의 이야기를 기록해 널리 알렸지만, 그 기록에는 해석이 많이 더해졌다는 비판도 있습니다."],"cover_exhibit_id":"nommo-dogon"},{"slug":"fon","name":"폰 신화 (다호메)","name_en":"Fon (Dahomey)","region":"베냉","continent":"africa","earliest_source":"구전 (19세기 기록)","era_label":"구전","era_year":1860,"summary":"달과 해의 쌍둥이 신 마우-리사와 쇠의 신 구가 등장하는, 옛 다호메 왕국 폰족의 신화입니다.","description":["지금의 베냉에 있던 다호메 왕국의 폰족은 ‘보둔’이라 부르는 신들을 섬겼습니다. 이 말은 훗날 아메리카의 부두 신앙이라는 이름의 뿌리가 되었습니다.","창조신 마우-리사는 달과 해, 여성과 남성이 한 몸인 신으로, 그 자식들이 세상의 여러 영역을 나눠 맡습니다."],"cover_exhibit_id":"gu-fon"},{"slug":"inca","name":"잉카 신화","name_en":"Inca","region":"안데스","continent":"americas","earliest_source":"에스파냐 연대기 · 파차쿠티 얌키의 그림","era_label":"16세기","era_year":1550,"summary":"창조신 비라코차, 왕가의 조상인 태양신 인티, 대지의 어머니 파차마마를 섬긴 안데스 잉카 제국의 신화입니다.","description":["잉카인은 자신들의 왕(사파 잉카)을 태양신 인티의 아들이라 여겼고, 수도 쿠스코의 코리칸차 신전을 금으로 꾸며 태양을 섬겼습니다.","문자 대신 매듭 끈 키푸를 썼기에, 신화는 에스파냐 정복 뒤 연대기 작가들과 원주민 출신 작가들의 기록으로 전합니다."],"cover_exhibit_id":"pachamama-inca"},{"slug":"haida","name":"하이다 신화","name_en":"Haida","region":"하이다 과이 (캐나다 서해안)","continent":"americas","earliest_source":"구전 (19세기 기록)","era_label":"구전","era_year":1880,"summary":"장난꾸러기이자 창조자인 까마귀가 세상에 빛과 사람을 가져왔다는 북서 해안 하이다족의 신화입니다.","description":["하이다족은 캐나다 서해안 하이다 과이 섬들에 사는 사람들로, 집 앞과 마을에 가문의 이야기를 새긴 기둥(토템 기둥)을 세웠습니다.","신화의 중심에는 까마귀가 있는데, 욕심 많고 장난스럽지만 그 행동 덕분에 세상에 해와 달, 물과 사람이 생겼다고 전합니다."],"cover_exhibit_id":"raven-haida"},{"slug":"olmec","name":"올멕 신화","name_en":"Olmec","region":"멕시코만 연안","continent":"americas","earliest_source":"조각과 유물 (문자 기록 없음)","era_label":"기원전 12세기경","era_year":-1200,"summary":"메소아메리카 최초의 문명으로 꼽히는 올멕의 신앙으로, 사람과 재규어가 섞인 모습이 자주 새겨졌습니다.","description":["올멕 문명은 기원전 1200년 무렵부터 멕시코만 연안에서 번성했으며, 거대한 돌 두상으로 유명합니다.","글 기록이 없어 신의 이름은 알 수 없지만, 유물에 자주 보이는 재규어와 사람이 섞인 얼굴, 깃털 달린 뱀 같은 모습은 뒤의 마야와 아즈텍 신앙으로 이어졌다고 봅니다."],"cover_exhibit_id":"were-jaguar-olmec"},{"slug":"zapotec","name":"사포텍 신화","name_en":"Zapotec","region":"오악사카 (멕시코)","continent":"americas","earliest_source":"몬테 알반 비문","era_label":"기원전 6세기경","era_year":-500,"summary":"산 위의 도시 몬테 알반을 세운 사포텍 사람들이 비와 번개의 신 코시호를 섬긴 신화입니다.","description":["사포텍 문명은 오악사카 계곡에서 기원전 500년 무렵부터 산꼭대기 도시 몬테 알반을 중심으로 번성했습니다.","무덤에 신의 얼굴을 새긴 토기 단지를 함께 묻었는데, 그 가운데 비와 번개의 신 코시호의 모습이 가장 많습니다."],"cover_exhibit_id":"cocijo-zapotec"},{"slug":"mixtec","name":"믹스텍 신화","name_en":"Mixtec","region":"오악사카 (멕시코)","continent":"americas","earliest_source":"그림 문서 (「주슈-너톨 코덱스」 등)","era_label":"14~15세기","era_year":1400,"summary":"사슴 가죽 그림 문서에 신들과 왕들의 계보를 그린 믹스텍 사람들의 신화와 전설입니다.","description":["믹스텍 사람들은 오악사카 서부에서 작은 왕국들을 이루었고, 접어서 펼치는 사슴 가죽 그림 문서에 조상과 왕들의 역사를 남겼습니다.","그 가운데 「주슈-너톨 코덱스」는 전설적인 왕 ‘8 사슴 재규어 발톱’의 일생을 자세히 그려, 신화와 역사가 섞인 이야기를 전합니다."],"cover_exhibit_id":"zouche-nuttall-75"},{"slug":"polynesian","name":"폴리네시아 신화","name_en":"Polynesian","region":"태평양 폴리네시아","continent":"oceania","earliest_source":"구전 (19세기 기록)","era_label":"구전","era_year":1840,"summary":"바다에서 섬을 낚아 올린 마우이, 바다의 신 탕가로아가 등장하는, 하와이에서 뉴질랜드까지 이어진 태평양의 신화입니다.","description":["폴리네시아 사람들은 카누로 넓은 태평양을 건너 하와이, 타히티, 뉴질랜드(아오테아로아) 등에 퍼졌고, 섬마다 비슷하면서도 조금씩 다른 신화를 전했습니다.","하늘의 아버지와 땅의 어머니가 갈라지며 세상이 열렸다는 이야기, 반신 마우이의 모험담이 널리 공통으로 전합니다."],"cover_exhibit_id":"maui-polynesian"},{"slug":"rapa-nui","name":"라파누이 신화","name_en":"Rapa Nui","region":"라파누이 (이스터섬)","continent":"oceania","earliest_source":"롱고롱고 (미해독) · 구전","era_label":"구전","era_year":1860,"summary":"창조신 마케마케와, 해마다 새알을 두고 겨룬 새 사람 의식이 전하는 이스터섬의 신화입니다.","description":["라파누이는 태평양 한가운데 홀로 떨어진 섬으로, 조상을 새긴 거대한 석상 모아이로 유명합니다. 섬의 문자 롱고롱고는 아직 해독되지 않았습니다.","모아이를 만드는 시대가 지난 뒤에는 창조신 마케마케를 섬기며, 해마다 바다 건너 바위섬에서 새알을 가져오는 사람을 뽑는 ‘새 사람’ 의식을 치렀습니다."],"cover_exhibit_id":"moai-rapanui"},{"slug":"ainu","name":"아이누 신화","name_en":"Ainu","region":"홋카이도·사할린","continent":"asia","earliest_source":"유카르 (구전 서사시)","era_label":"1923년 「아이누 신요집」","era_year":1923,"summary":"곰과 올빼미, 불과 바다 같은 자연의 모든 것을 신 ‘카무이’로 여긴 아이누 사람들의 신화입니다.","description":["아이누 사람들은 쓸모 있거나 힘센 모든 것에 카무이(신)가 깃든다고 여겼습니다. 곰은 산의 신이 사람 세상에 고기와 털가죽을 선물하러 온 모습이라고 믿었습니다.","신화는 ‘유카르’라 부르는 노래로 전해졌으며, 1923년 지리 유키에가 신들이 스스로 이야기하는 노래를 일본어로 옮겨 「아이누 신요집」을 펴냈습니다."],"cover_exhibit_id":"kim-un-kamuy-ainu"},{"slug":"tibetan","name":"티베트 신화","name_en":"Tibetan","region":"티베트고원","continent":"asia","earliest_source":"「게사르 왕 서사시」 · 뵌교 문헌","era_label":"11세기 이후","era_year":1050,"summary":"세계에서 가장 긴 서사시로 꼽히는 「게사르 왕」과, 불교와 뵌교가 섞인 수호신들의 신화입니다.","description":["티베트에는 불교 이전부터 이어진 뵌교의 신앙과, 불교가 받아들인 수많은 수호신의 이야기가 함께 전합니다.","링 왕국의 영웅 게사르의 이야기는 지금도 이야기꾼들이 노래로 전하는 살아 있는 서사시로, 유네스코 인류무형문화유산에 올라 있습니다."],"cover_exhibit_id":"palden-lhamo-tibet"},{"slug":"vietnamese","name":"베트남 신화","name_en":"Vietnamese","region":"베트남 북부","continent":"asia","earliest_source":"「영남척괴열전」","era_label":"15세기경","era_year":1490,"summary":"용의 아들과 선녀가 낳은 백 개의 알에서 베트남 사람들이 나왔다는 건국 신화와 영웅 전설입니다.","description":["베트남 사람들은 자신들을 용의 아들 락롱꾸언과 산의 선녀 어우꺼의 자손이라 여깁니다. 이 이야기는 15세기 무렵 엮은 설화집 「영남척괴열전」에 실려 있습니다.","외적을 물리치고 하늘로 올라간 영웅 타인지옹 같은 이야기는 동호 마을의 민화 판화로도 즐겨 그려졌습니다."],"cover_exhibit_id":"thanh-giong-vietnam"},{"slug":"thai","name":"타이 신화","name_en":"Thai","region":"타이","continent":"asia","earliest_source":"「라마끼안」","era_label":"1797년 (현존 판본)","era_year":1797,"summary":"인도의 「라마야나」를 타이식으로 다시 쓴 「라마끼안」과, 벼의 여신 매포솝 같은 민간 신앙이 함께 전합니다.","description":["타이의 「라마끼안」은 인도 서사시 「라마야나」를 바탕으로 하지만, 등장인물과 이야기가 타이식으로 바뀌었습니다. 지금 전하는 판본은 1797년 라마 1세 때 정리되었습니다.","방콕 왕궁의 왓 프라깨우 회랑에는 「라마끼안」 전체를 그린 긴 벽화가 있습니다. 농촌에서는 벼의 여신 매포솝에게 풍년을 빌었습니다."],"cover_exhibit_id":"tosakanth-thai"},{"slug":"burmese","name":"미얀마 신화","name_en":"Burmese","region":"미얀마","continent":"asia","earliest_source":"37 낫 목록","era_label":"11세기 (낫 신앙 정비)","era_year":1050,"summary":"불교와 함께 지금도 섬기는, ‘낫’이라 부르는 신령들의 신앙입니다.","description":["미얀마 사람들은 불교를 믿으면서도 ‘낫’이라 부르는 신령들을 함께 섬깁니다. 많은 낫은 억울하게 죽은 사람이 신이 된 존재로 전합니다.","11세기 바간의 아노라타 왕은 수많은 낫 가운데 37을 골라 공식 신령으로 정하고, 그 우두머리 자리에 불교의 수호신 따자민(인드라)을 두었다고 전합니다."],"cover_exhibit_id":"mahagiri-myanmar"},{"slug":"indonesian","name":"인도네시아 신화","name_en":"Indonesian","region":"자와·발리","continent":"asia","earliest_source":"「탄투 팡겔라란」 등 고대 자와 문헌","era_label":"15세기경","era_year":1450,"summary":"벼의 여신 데위 스리와, 선의 바롱과 악의 랑다가 끝없이 겨루는 자와와 발리의 신화입니다.","description":["인도네시아 섬들의 신화는 토착 신앙 위에 힌두교와 불교, 이슬람이 차례로 더해진 모습입니다. 자와에서는 벼의 여신 데위 스리를 집집마다 모셨습니다.","힌두 신앙이 이어지는 발리에서는 수호자 바롱과 마녀 랑다가 맞서는 춤극을 지금도 공연하는데, 둘 중 어느 쪽도 완전히 이기지 않습니다."],"cover_exhibit_id":"barong-bali"},{"slug":"arthurian","name":"아서왕 전설","name_en":"Arthurian","region":"브리튼","continent":"europe","earliest_source":"몬머스의 제프리 「브리튼 왕 열전」","era_label":"12세기경","era_year":1136,"summary":"브리튼의 왕 아서와 원탁의 기사들, 마법사 멀린과 성배 탐색을 그린 중세 유럽의 기사 전설입니다.","description":["몬머스의 제프리가 쓴 「브리튼 왕 열전」(1136년경)에서 틀을 갖추었고, 프랑스의 로망스와 토머스 맬러리의 「아서의 죽음」으로 이어지며 기사도 이야기의 중심이 되었습니다.","바위에서 뽑은 검과 호수의 여인이 준 엑스칼리버, 원탁, 성배 탐색, 캄란 전투와 아발론으로의 여행이 대표적인 이야기입니다."],"cover_exhibit_id":"king-arthur-butler"},{"slug":"carolingian","name":"샤를마뉴 전설","name_en":"Matter of France","region":"프랑크 왕국","continent":"europe","earliest_source":"「롤랑의 노래」","era_label":"11세기경","era_year":1100,"summary":"샤를마뉴 대제와 열두 기사(팔라딘)가 사라센과 싸우는 이야기로, 「롤랑의 노래」에서 시작된 무훈시 전통입니다.","description":["11세기 무렵의 「롤랑의 노래」는 론세스바예스 고개에서 후위를 맡아 싸우다 쓰러진 롤랑을 노래합니다.","이탈리아로 건너가 보이아르도의 「사랑에 빠진 오를란도」와 아리오스토의 「광란의 오를란도」에서 아스톨포, 브라다만테 같은 인물이 더해졌습니다."],"cover_exhibit_id":"roland-roncevaux-dore"},{"slug":"germanic","name":"게르만 영웅 전설","name_en":"Germanic heroic legend","region":"독일·라인강 유역","continent":"europe","earliest_source":"「니벨룽겐의 노래」","era_label":"13세기 초","era_year":1200,"summary":"「니벨룽겐의 노래」의 지크프리트와 크림힐트, 베른의 디트리히처럼 중세 독일어 서사시로 전해진 영웅 전설입니다.","description":["북유럽의 시구르드 전설과 뿌리가 같으며, 니벨룽족의 보물과 용의 피를 뒤집어쓴 지크프리트의 이야기를 담고 있습니다.","지크프리트가 하겐에게 살해된 뒤 크림힐트가 훈족의 왕 에첼과 결혼해 부르군트족에게 복수하는 비극으로 끝납니다."],"cover_exhibit_id":"siegfried-forge-hauschild"},{"slug":"roman","name":"로마 건국 전설","name_en":"Roman","region":"이탈리아 반도","continent":"europe","earliest_source":"리비우스 「로마사」","era_label":"기원전 1세기경","era_year":-30,"summary":"늑대가 기른 쌍둥이 로물루스와 레무스, 트로이에서 건너온 아이네이아스의 후예가 로마를 세웠다는 전설입니다.","description":["리비우스의 「로마사」와 베르길리우스의 「아이네이스」가 전하는 이야기로, 로마 사람들은 자신들의 기원을 트로이와 군신 마르스에 두었습니다.","로물루스는 팔라티누스 언덕에 도시를 세우고 첫 왕이 되었으며, 죽은 뒤 신 퀴리누스로 섬겨졌다고 전합니다."],"cover_exhibit_id":"romulus-remus-rubens"},{"slug":"european-folklore","name":"유럽 민담","name_en":"European folklore","region":"잉글랜드·스위스·프랑스","continent":"europe","earliest_source":"로빈 후드 발라드","era_label":"14세기 이후","era_year":1400,"summary":"셔우드 숲의 의적, 아들 머리 위의 사과를 쏜 명사수, 용을 물리친 성인처럼 유럽 곳곳에서 전해 온 민간 전설입니다.","description":["발라드와 연대기, 성인전, 동화 모음으로 전해진 이야기들로, 기록된 시기는 대부분 중세 후기 이후입니다.","로빈 후드와 빌헬름 텔은 압제에 맞선 민중의 영웅으로, 멜뤼진과 하베트롯은 요정 이야기로 오래 사랑받았습니다."],"cover_exhibit_id":"saint-george-uccello"},{"slug":"american-folklore","name":"북아메리카 민담","name_en":"American folklore","region":"북아메리카","continent":"americas","earliest_source":"신문 기사와 광고 소책자","era_label":"20세기 초","era_year":1910,"summary":"벌목꾼들이 모닥불 곁에서 주고받던 허풍담에서 태어난, 거인 벌목꾼 폴 버니언 같은 북아메리카의 민담입니다.","description":["과장과 익살로 가득한 이른바 '톨 테일'로, 개척 시대의 노동과 광활한 자연을 영웅의 몸집으로 그려 냈습니다.","20세기 초 신문과 광고 소책자를 통해 널리 퍼졌습니다."],"cover_exhibit_id":"paul-bunyan-bemidji"},{"slug":"turko-mongol","name":"몽골·알타이 신화","name_en":"Turko-Mongol","region":"몽골 초원·알타이산맥","continent":"asia","earliest_source":"구전 서사시 (19세기 채록)","era_label":"구전 (19세기 채록)","era_year":1870,"summary":"해를 쏜 명궁 에르히 메르겡, 저승을 다녀온 영웅 알립마나시처럼 초원과 산맥의 유목민이 구전으로 전한 신화와 영웅 서사시입니다.","description":["샤먼과 이야기꾼이 노래로 전해 온 서사시로, 19세기 이후 학자들이 채록해 기록으로 남았습니다.","하늘의 신 텡그리, 여러 개의 해, 말과 활을 다루는 영웅이 자주 등장합니다."],"cover_exhibit_id":"alpamysh-stamp"},{"slug":"arabian-nights","name":"천일야화","name_en":"One Thousand and One Nights","region":"페르시아·아라비아","continent":"asia","earliest_source":"「천일야화」 아랍어 필사본","era_label":"9세기경","era_year":850,"summary":"셰에라자드가 왕에게 밤마다 이야기를 들려주는 틀 속에 신드바드, 알라딘 같은 이야기가 담긴 중동의 설화 모음입니다.","description":["페르시아의 「천의 이야기」를 바탕으로 아랍어로 옮겨지며 인도·페르시아·아랍의 이야기가 더해졌습니다.","18세기 앙투안 갈랑의 프랑스어 번역으로 유럽에 알려졌고, 알라딘과 알리 바바처럼 이때 더해진 이야기도 있습니다."],"cover_exhibit_id":"scheherazade-anderson"},{"slug":"taino","name":"타이노 신화","name_en":"Taíno","region":"카리브해 대앤틸리스 제도","continent":"americas","earliest_source":"라몬 파네 「인디오의 옛일에 관한 보고서」","era_label":"1498년경","era_year":1498,"summary":"콜럼버스 일행을 처음 맞은 카리브해 원주민 타이노 사람들의 신앙으로, 정령이 깃든 신상 제미를 섬겼습니다.","description":["타이노 사람들은 히스파니올라, 쿠바, 푸에르토리코, 자메이카 같은 대앤틸리스 제도에서 카사바를 기르고 고기를 잡으며 살았습니다. 1492년 콜럼버스 일행을 처음 맞았지만, 정복과 전염병으로 수십 년 만에 인구가 크게 줄었습니다.","콜럼버스의 명으로 수도사 라몬 파네가 1498년 무렵 받아 적은 보고서가 이들의 신화를 전하는 가장 중요한 기록입니다. 원본은 사라졌고, 콜럼버스의 아들 페르난도가 쓴 전기의 이탈리아어 번역본(1571)에 실려 남았습니다."],"cover_exhibit_id":"zemi-met"},{"slug":"moche","name":"모체 신화","name_en":"Moche","region":"페루 북부 해안","continent":"americas","earliest_source":"토기·금속 공예·신전 벽화 (문자 기록 없음)","era_label":"1~8세기","era_year":100,"summary":"잉카보다 천 년쯤 앞서 페루 북부 해안에서 번성한 모체 사람들의 신앙으로, 송곳니 난 신과 희생 제의 장면을 토기와 금속 공예에 남겼습니다.","description":["모체 문화는 1세기 무렵부터 8세기 무렵까지 안데스산맥과 태평양 사이 사막의 강 골짜기에서 꽃피었으며, 물길을 낸 농사와 흙벽돌로 쌓은 거대한 신전으로 이름났습니다. 시판 왕의 무덤에서 나온 금은 장신구처럼 뛰어난 금속 공예도 남겼습니다.","문자 기록이 없어 신들의 본래 이름은 알 수 없지만, 그림 토기와 사람 얼굴 모양 토기에는 신들의 싸움과 포로를 바치는 의식 같은 장면이 자세히 그려졌습니다. 학자들은 이 그림들을 이어 맞추어 신화의 줄거리를 되짚고 있습니다."],"cover_exhibit_id":"ai-apaec-plaque"}]$seed$::jsonb)
on conflict (slug) do nothing;
insert into public.figures (slug, pantheon_slug, kind, grade, name, name_en, epithet, domains, summary, description, sort_order)
select slug, pantheon_slug, kind, grade, name, name_en, epithet, domains, summary, description, sort_order from jsonb_populate_recordset(null::public.figures, $seed$[{"slug":"zeus","pantheon_slug":"greek","kind":"god","grade":null,"name":"제우스","name_en":"Zeus","epithet":"하늘과 번개의 신","domains":["하늘","번개","법과 질서"],"summary":"아버지 크로노스를 몰아내고 올림포스의 신들을 다스리게 된 신들의 왕입니다.","description":["제우스는 형제들과 함께 티탄족과 싸워 이긴 뒤 하늘을 맡았고, 포세이돈은 바다를, 하데스는 저승을 맡았습니다.","번개를 무기로 쓰며 손님과 맹세를 지키는 신으로도 섬겨졌습니다. 로마에서는 유피테르와 동일시되었습니다."],"sort_order":1},{"slug":"athena","pantheon_slug":"greek","kind":"god","grade":null,"name":"아테나","name_en":"Athena","epithet":"지혜와 전략의 여신","domains":["지혜","전쟁의 전략","공예"],"summary":"제우스의 머리에서 완전 무장한 채 태어났다고 전하는 아테네의 수호 여신입니다.","description":["아테나는 무작정 싸우는 전쟁이 아니라 계획과 전략의 전쟁을 맡았고, 베 짜기와 같은 공예의 신이기도 했습니다.","아테네 사람들에게 올리브나무를 선물해 포세이돈을 이기고 도시의 수호신이 되었다는 이야기가 유명합니다."],"sort_order":2},{"slug":"apollo","pantheon_slug":"greek","kind":"god","grade":null,"name":"아폴론","name_en":"Apollo","epithet":"빛과 예언, 음악의 신","domains":["예언","음악","치유","궁술"],"summary":"델포이 신탁의 주인으로, 리라를 연주하는 젊은 신의 모습으로 자주 표현됩니다.","description":["아폴론은 제우스와 레토의 아들이자 아르테미스의 쌍둥이 형제입니다.","델포이에서 왕뱀 피톤을 물리치고 신탁소를 세웠다고 전하며, 사람들은 중요한 일을 앞두고 그곳에서 아폴론의 뜻을 물었습니다."],"sort_order":3},{"slug":"aphrodite","pantheon_slug":"greek","kind":"god","grade":null,"name":"아프로디테","name_en":"Aphrodite","epithet":"사랑과 아름다움의 여신","domains":["사랑","아름다움","욕망"],"summary":"바다 거품에서 태어났다고 전하는 사랑의 여신으로, 로마에서는 베누스라 불렸습니다.","description":["헤시오도스의 「신통기」는 아프로디테가 바다 거품에서 태어났다고 하고, 호메로스는 제우스와 디오네의 딸이라고 합니다.","트로이 전쟁의 발단이 된 ‘파리스의 심판’에서 가장 아름다운 여신으로 뽑혔습니다."],"sort_order":4},{"slug":"poseidon","pantheon_slug":"greek","kind":"god","grade":null,"name":"포세이돈","name_en":"Poseidon","epithet":"바다와 지진의 신","domains":["바다","지진","말"],"summary":"삼지창으로 바다를 다스리고 땅을 뒤흔드는 신입니다.","description":["포세이돈은 제우스의 형제로, 화가 나면 폭풍과 지진을 일으킨다고 여겨졌습니다.","「오디세이아」에서는 아들 폴리페모스의 눈을 멀게 한 오디세우스가 고향에 돌아가지 못하도록 오랫동안 방해합니다."],"sort_order":5},{"slug":"odin","pantheon_slug":"norse","kind":"god","grade":null,"name":"오딘","name_en":"Odin","epithet":"지혜와 죽음, 전쟁의 신","domains":["지혜","시","전쟁","죽음"],"summary":"지혜를 얻으려 한쪽 눈을 내놓은, 아스가르드의 주신입니다.","description":["오딘은 미미르의 샘물을 마시려고 한쪽 눈을 바쳤고, 룬 문자의 비밀을 얻으려 세계수 이그드라실에 아흐레 동안 매달렸다고 합니다.","여덟 다리를 가진 말 슬레이프니르를 타고 다니며, 라그나로크에서 늑대 펜리르에게 삼켜질 운명입니다."],"sort_order":1},{"slug":"thor","pantheon_slug":"norse","kind":"god","grade":null,"name":"토르","name_en":"Thor","epithet":"천둥의 신","domains":["천둥","힘","인간의 수호"],"summary":"망치 묠니르로 거인들과 싸우며 신과 사람의 세계를 지키는 신입니다.","description":["토르는 오딘의 아들로, 염소 두 마리가 끄는 수레를 타고 하늘을 달리면 천둥이 친다고 여겨졌습니다.","라그나로크에서 세계를 휘감은 뱀 요르문간드와 싸워 쓰러뜨리지만, 그 독에 쓰러진다고 전합니다."],"sort_order":2},{"slug":"freyja","pantheon_slug":"norse","kind":"god","grade":null,"name":"프레이야","name_en":"Freyja","epithet":"사랑과 풍요, 마법의 여신","domains":["사랑","풍요","세이드 마법"],"summary":"목걸이 브리싱가멘의 주인이자, 전사한 이들의 절반을 맞이하는 바니르 신족의 여신입니다.","description":["프레이야는 고양이가 끄는 수레를 탄다고 전하며, 전장에서 죽은 이들의 절반을 자신의 저택 폴크방으로 데려갑니다.","난쟁이들이 만든 목걸이 브리싱가멘을 로키가 훔치자 헤임달이 되찾아 돌려주었다는 이야기가 있습니다."],"sort_order":3},{"slug":"loki","pantheon_slug":"norse","kind":"god","grade":null,"name":"로키","name_en":"Loki","epithet":"꾀와 변신의 신","domains":["속임수","변신","혼란"],"summary":"신들을 돕기도, 곤경에 빠뜨리기도 하는 변신의 명수입니다.","description":["로키는 거인의 혈통이지만 아스가르드의 신들과 함께 지냈습니다. 펜리르, 요르문간드, 헬이 그의 자식입니다.","발드르의 죽음을 꾸민 대가로 결박당했다가 라그나로크에 풀려나 신들에게 맞선다고 전합니다."],"sort_order":4},{"slug":"osiris","pantheon_slug":"egyptian","kind":"god","grade":null,"name":"오시리스","name_en":"Osiris","epithet":"저승과 부활의 신","domains":["저승","부활","농경"],"summary":"동생 세트에게 죽임을 당했다가 되살아나 저승의 왕이 된 신입니다.","description":["오시리스는 세트에게 살해되어 몸이 흩어졌지만, 아내 이시스가 조각을 모아 되살렸다고 전합니다.","이후 저승을 다스리며 죽은 이들을 심판했고, 왕관과 갈고리 지팡이, 도리깨를 든 미라의 모습으로 표현됩니다."],"sort_order":1},{"slug":"isis","pantheon_slug":"egyptian","kind":"god","grade":null,"name":"이시스","name_en":"Isis","epithet":"마법과 모성의 여신","domains":["마법","모성","치유"],"summary":"죽은 남편 오시리스를 되살리고 아들 호루스를 지켜 낸 여신입니다.","description":["이시스는 강력한 마법으로 오시리스를 되살렸고, 늪지에 숨어 아들 호루스를 길렀습니다.","아기 호루스에게 젖을 먹이는 이시스의 모습은 이집트 전역에서 소상으로 만들어졌고, 그리스·로마 세계에서도 널리 숭배되었습니다."],"sort_order":2},{"slug":"anubis","pantheon_slug":"egyptian","kind":"god","grade":null,"name":"아누비스","name_en":"Anubis","epithet":"미라와 무덤의 신","domains":["장례","미라","저승 안내"],"summary":"자칼의 머리를 한 신으로, 죽은 이를 저승으로 이끌고 심장의 무게를 단다고 여겨졌습니다.","description":["아누비스는 미라를 만드는 의식을 지키는 신으로, 장례를 맡은 사제들은 그의 가면을 쓰고 의식을 치렀다고 합니다.","「사자의 서」의 심판 장면에서는 죽은 이의 심장을 진리의 깃털과 함께 저울에 올려 무게를 답니다."],"sort_order":3},{"slug":"gilgamesh","pantheon_slug":"mesopotamian","kind":"hero","grade":null,"name":"길가메시","name_en":"Gilgamesh","epithet":"우루크의 왕","domains":["영웅","왕권","죽음과 영생"],"summary":"친구 엔키두를 잃고 영원한 삶을 찾아 떠난 우루크의 영웅 왕입니다.","description":["길가메시는 삼분의 이는 신, 삼분의 일은 사람이라고 전하는 우루크의 왕입니다. 실제 왕이었을 가능성도 있습니다.","「길가메시 서사시」에서 그는 엔키두와 함께 괴물 훔바바를 물리치지만, 엔키두가 죽자 죽음을 피하는 길을 찾아 나섭니다."],"sort_order":1},{"slug":"ishtar","pantheon_slug":"mesopotamian","kind":"god","grade":null,"name":"이슈타르","name_en":"Ishtar","epithet":"사랑과 전쟁의 여신","domains":["사랑","전쟁","금성"],"summary":"수메르에서는 인안나라고 불린, 사랑과 전쟁을 함께 다스리는 여신입니다.","description":["이슈타르는 저녁과 새벽의 금성으로 상징되었고, 사자는 그녀의 신성한 동물이었습니다.","저승으로 내려갔다가 돌아오는 「인안나의 저승 하강」 이야기가 유명합니다. 바빌론의 이슈타르 문에는 사자를 새긴 유약 벽돌이 늘어서 있었습니다."],"sort_order":2},{"slug":"marduk","pantheon_slug":"mesopotamian","kind":"god","grade":null,"name":"마르두크","name_en":"Marduk","epithet":"바빌론의 수호신","domains":["창조","왕권","정의"],"summary":"혼돈의 여신 티아마트를 무찌르고 그 몸으로 하늘과 땅을 만든 바빌론의 주신입니다.","description":["창조 서사시 「에누마 엘리시」에서 마르두크는 신들의 왕이 되는 조건으로 티아마트와 싸우겠다고 나섭니다.","바빌론이 강해지면서 마르두크는 메소포타미아의 가장 높은 신이 되었고, 용 모양의 짐승 무슈후슈가 그를 상징합니다."],"sort_order":3},{"slug":"vishnu","pantheon_slug":"hindu","kind":"god","grade":null,"name":"비슈누","name_en":"Vishnu","epithet":"세계를 유지하는 신","domains":["유지","보호","화신(아바타라)"],"summary":"세상의 질서가 무너질 때마다 화신으로 내려와 세계를 지키는 신입니다.","description":["비슈누는 라마와 크리슈나를 비롯한 여러 화신(아바타라)으로 세상에 나타난다고 여겨집니다.","우주가 쉬는 동안 뱀 아난타(셰샤) 위에 누워 잠들어 있다가, 배꼽에서 피어난 연꽃에서 창조의 신 브라흐마가 태어난다고 합니다."],"sort_order":1},{"slug":"shiva","pantheon_slug":"hindu","kind":"god","grade":null,"name":"시바","name_en":"Shiva","epithet":"파괴와 재생의 신","domains":["파괴","재생","고행","춤"],"summary":"낡은 우주를 허물어 새 우주가 태어나게 하는 신으로, 춤의 왕 나타라자로도 표현됩니다.","description":["시바는 히말라야에서 명상하는 고행자이면서, 아내 파르바티와 아들 가네샤, 스칸다를 둔 가장이기도 합니다.","불꽃 고리 안에서 춤추는 나타라자 상은 우주의 창조와 파괴가 이어지는 리듬을 나타냅니다."],"sort_order":2},{"slug":"ganesha","pantheon_slug":"hindu","kind":"god","grade":null,"name":"가네샤","name_en":"Ganesha","epithet":"지혜와 시작의 신","domains":["지혜","시작","장애 제거"],"summary":"코끼리 머리를 한 시바와 파르바티의 아들로, 새로운 일을 시작할 때 먼저 찾는 신입니다.","description":["가네샤가 코끼리 머리를 갖게 된 사연은 여러 가지로 전하는데, 시바가 아들인 줄 모르고 목을 벤 뒤 코끼리 머리를 붙여 주었다는 이야기가 널리 알려져 있습니다.","장애를 없애 주는 신으로 여겨져, 의식이나 새로운 일을 시작할 때 가장 먼저 기도를 받습니다."],"sort_order":3},{"slug":"izanagi-izanami","pantheon_slug":"japanese","kind":"god","grade":null,"name":"이자나기와 이자나미","name_en":"Izanagi & Izanami","epithet":"국토를 낳은 부부 신","domains":["창조","국토","삶과 죽음"],"summary":"하늘의 창으로 바다를 휘저어 첫 섬을 만들고 일본의 섬들과 신들을 낳은 부부 신입니다.","description":["두 신은 하늘에 걸린 다리에 서서 창으로 바다를 휘저었고, 창끝에서 떨어진 소금물이 굳어 첫 섬이 되었다고 합니다.","불의 신을 낳다가 죽은 이자나미를 찾아 이자나기는 저승 요미로 내려가지만, 끝내 데려오지 못하고 돌아옵니다."],"sort_order":1},{"slug":"amaterasu","pantheon_slug":"japanese","kind":"god","grade":null,"name":"아마테라스","name_en":"Amaterasu","epithet":"태양의 여신","domains":["태양","다카마가하라 통치"],"summary":"동굴에 숨어 세상을 어둠에 빠뜨렸다가 신들의 꾀로 다시 나온 태양의 여신입니다.","description":["아마테라스는 이자나기가 저승에서 돌아와 몸을 씻을 때 왼쪽 눈에서 태어났다고 「고사기」는 전합니다.","동생 스사노오의 난폭함에 화가 나 바위 동굴 아마노이와토에 숨자 세상이 어두워졌고, 신들은 동굴 앞에서 춤판을 벌여 그녀를 밖으로 이끌어 냈습니다."],"sort_order":2},{"slug":"susanoo","pantheon_slug":"japanese","kind":"god","grade":null,"name":"스사노오","name_en":"Susanoo","epithet":"폭풍과 바다의 신","domains":["폭풍","바다"],"summary":"하늘에서 쫓겨난 뒤 이즈모에서 머리 여덟 개 달린 큰 뱀 야마타노오로치를 물리친 신입니다.","description":["스사노오는 이자나기의 코에서 태어났다고 전합니다. 다카마가하라에서 난동을 부리다 쫓겨났습니다.","이즈모에서 야마타노오로치에게 술을 먹여 잠재운 뒤 베었고, 그 꼬리에서 나온 검 구사나기를 아마테라스에게 바쳤습니다."],"sort_order":3},{"slug":"raijin","pantheon_slug":"japanese","kind":"god","grade":null,"name":"라이진","name_en":"Raijin","epithet":"번개와 천둥의 신","domains":["천둥","번개","비"],"summary":"북을 둥글게 두르고 두드려 천둥을 울린다고 여겨진 신으로, 바람의 신 후진과 짝을 이룹니다.","description":["라이진은 오니와 비슷한 모습에 북을 고리처럼 둘러멘 모습으로 그려집니다.","바람의 신 후진과 함께 사찰의 문이나 병풍 그림에 자주 등장합니다."],"sort_order":4},{"slug":"hera","pantheon_slug":"greek","kind":"god","grade":null,"name":"헤라","name_en":"Hera","epithet":"신들의 여왕","domains":["결혼","가정","여성"],"summary":"제우스의 아내이자 누나로, 결혼과 가정을 지키는 올림포스의 여왕입니다.","description":["헤라는 크로노스와 레아의 딸로, 제우스와 결혼해 신들의 여왕이 되었습니다. 공작과 석류, 왕관과 홀이 헤라의 상징입니다.","제우스가 다른 여신과 인간에게서 얻은 자식들을 미워해 괴롭힌 이야기가 많은데, 영웅 헤라클레스가 대표적입니다. 로마에서는 유노와 동일시되었습니다."],"sort_order":6},{"slug":"artemis","pantheon_slug":"greek","kind":"god","grade":null,"name":"아르테미스","name_en":"Artemis","epithet":"사냥과 달의 여신","domains":["사냥","야생","달","소녀의 수호"],"summary":"아폴론의 쌍둥이 누이로, 활을 들고 숲과 산의 짐승을 다스리는 처녀 여신입니다.","description":["아르테미스는 제우스와 레토의 딸로, 델로스섬에서 아폴론과 함께 태어났습니다.","사냥꾼과 소녀들의 수호신이었으며, 목욕하는 자신을 엿본 사냥꾼 악타이온을 사슴으로 바꾸어 버린 이야기처럼 범할 수 없는 순결의 신으로 그려집니다. 후대에는 달의 여신으로도 여겨졌습니다."],"sort_order":7},{"slug":"hermes","pantheon_slug":"greek","kind":"god","grade":null,"name":"헤르메스","name_en":"Hermes","epithet":"신들의 전령","domains":["전령","여행","상업","도둑"],"summary":"날개 달린 신발을 신고 신들의 말을 전하며, 죽은 이의 영혼을 저승으로 이끄는 신입니다.","description":["헤르메스는 제우스와 마이아의 아들로, 태어난 날 아폴론의 소 떼를 훔치고 거북 등딱지로 리라를 만들어 아폴론에게 주었다고 합니다.","여행자와 상인, 도둑의 수호신이며, 뱀 두 마리가 감긴 지팡이 케리케이온을 듭니다. 로마에서는 메르쿠리우스라 불렸습니다."],"sort_order":8},{"slug":"hades","pantheon_slug":"greek","kind":"god","grade":null,"name":"하데스","name_en":"Hades","epithet":"저승의 왕","domains":["저승","죽은 이","땅속의 부"],"summary":"제우스·포세이돈과 세계를 나눠 저승을 맡은 신으로, 올림포스 열두 신에는 들지 않습니다.","description":["하데스는 크로노스와 레아의 아들로, 티탄족과의 싸움이 끝난 뒤 제비를 뽑아 저승을 맡았습니다. 이름은 ‘보이지 않는 자’라는 뜻으로 풀이됩니다.","데메테르의 딸 페르세포네를 데려가 아내로 삼았고, 그녀가 저승의 석류를 먹은 탓에 한 해의 일부를 저승에서 지내게 되면서 계절이 생겼다고 전합니다. 땅속의 부를 다스린다 하여 플루톤이라고도 불렸습니다."],"sort_order":9},{"slug":"baldr","pantheon_slug":"norse","kind":"god","grade":null,"name":"발드르","name_en":"Baldr","epithet":"빛과 순수의 신","domains":["빛","정의","아름다움"],"summary":"모든 것에게서 사랑받았지만 겨우살이에 맞아 죽은 오딘의 아들입니다.","description":["발드르는 오딘과 프리그의 아들로, 가장 아름답고 현명한 신이었습니다. 그가 죽는 꿈을 꾸자 프리그는 세상 모든 것에게 그를 해치지 않겠다는 맹세를 받았지만, 어리다고 여긴 겨우살이만은 빠뜨렸습니다.","로키가 이를 알아내 눈먼 신 회드에게 겨우살이를 던지게 했고, 발드르는 죽었습니다. 그의 죽음은 라그나로크로 이어지는 불행의 시작이 되며, 라그나로크 뒤 새 세상에서 되살아난다고 전합니다."],"sort_order":5},{"slug":"heimdall","pantheon_slug":"norse","kind":"god","grade":null,"name":"헤임달","name_en":"Heimdall","epithet":"신들의 파수꾼","domains":["경계","파수"],"summary":"무지개다리 비프로스트를 지키며, 라그나로크가 오면 뿔피리 걀라르호른을 불어 알리는 신입니다.","description":["헤임달은 아홉 어머니에게서 태어났다고 전하며, 새보다 잠을 적게 자고 풀과 양털이 자라는 소리까지 듣는다고 합니다.","아스가르드로 이어지는 비프로스트 곁에서 거인들을 지키다가, 라그나로크에는 걀라르호른을 불어 신들을 깨우고 로키와 싸워 함께 쓰러진다고 「산문 에다」는 전합니다."],"sort_order":6},{"slug":"ra","pantheon_slug":"egyptian","kind":"god","grade":null,"name":"라","name_en":"Ra","epithet":"태양신","domains":["태양","창조","왕권"],"summary":"태양의 배를 타고 낮에는 하늘을, 밤에는 저승을 건너는 이집트의 최고신입니다.","description":["라는 제5왕조 무렵부터 이집트의 최고신으로 섬겨졌고, 헬리오폴리스가 신앙의 중심이었습니다. 아침 해는 케프리, 저녁 해는 아툼으로 불리기도 했습니다.","밤마다 저승을 지나는 라의 배를 거대한 뱀 아포피스가 공격하지만, 라는 매번 이겨 다시 떠오른다고 여겨졌습니다. 매의 머리 위에 해 원반을 인 라-호라크티의 모습으로도 그려집니다."],"sort_order":4},{"slug":"horus","pantheon_slug":"egyptian","kind":"god","grade":null,"name":"호루스","name_en":"Horus","epithet":"하늘과 왕권의 신","domains":["하늘","왕권","수호"],"summary":"오시리스와 이시스의 아들로, 아버지를 죽인 세트와 싸워 이집트의 왕위를 되찾은 매의 신입니다.","description":["호루스는 매 또는 매의 머리를 한 사람으로 표현되며, 살아 있는 파라오는 호루스의 화신으로 여겨졌습니다.","세트와 싸우다 다친 눈은 토트가 고쳐 주었다고 하는데, 이 ‘호루스의 눈’은 온전함과 보호를 뜻하는 부적으로 널리 쓰였습니다. 에드푸 신전이 호루스를 모신 대표적인 신전입니다."],"sort_order":5},{"slug":"thoth","pantheon_slug":"egyptian","kind":"god","grade":null,"name":"토트","name_en":"Thoth","epithet":"지혜와 문자의 신","domains":["문자","지혜","기록","달"],"summary":"따오기 또는 개코원숭이의 모습으로 그려지는, 문자를 만든 지혜의 신입니다.","description":["토트는 신성문자를 만들고 신들의 서기 노릇을 했다고 여겨졌으며, 헤르모폴리스가 신앙의 중심이었습니다.","죽은 이의 심장을 다는 심판에서 결과를 기록하는 것도 토트의 일이었습니다. 그리스인들은 토트를 헤르메스와 동일시했습니다."],"sort_order":6},{"slug":"enki","pantheon_slug":"mesopotamian","kind":"god","grade":null,"name":"엔키","name_en":"Enki","epithet":"물과 지혜의 신","domains":["민물","지혜","마법","창조"],"summary":"수메르에서는 엔키, 아카드에서는 에아라 불린, 땅속 민물과 지혜를 다스리는 신입니다.","description":["엔키는 하늘의 신 안의 아들로, 땅 밑 민물의 바다 압수에 산다고 여겨졌습니다. 에리두가 신앙의 중심이었습니다.","사람을 만들고 문명의 기술을 전한 신으로 그려지며, 대홍수 이야기에서는 신들의 결정을 몰래 알려 한 사람이 배를 지어 살아남게 합니다."],"sort_order":4},{"slug":"tiamat","pantheon_slug":"mesopotamian","kind":"god","grade":null,"name":"티아마트","name_en":"Tiamat","epithet":"원초의 바다","domains":["바닷물","혼돈"],"summary":"민물의 신 압수와 함께 처음의 신들을 낳았고, 끝내 마르두크에게 쓰러진 바다의 여신입니다.","description":["창조 서사시 「에누마 엘리시」에서 티아마트는 바닷물을, 남편 압수는 민물을 나타내며, 둘의 물이 섞여 신들이 태어났다고 합니다.","압수가 젊은 신들에게 죽자 티아마트는 괴물들을 만들어 복수에 나섰지만 마르두크에게 쓰러졌고, 마르두크는 그 몸을 둘로 갈라 하늘과 땅을 만들었습니다."],"sort_order":5},{"slug":"brahma","pantheon_slug":"hindu","kind":"god","grade":null,"name":"브라흐마","name_en":"Brahma","epithet":"창조의 신","domains":["창조","베다","지혜"],"summary":"네 얼굴로 사방을 보는 창조의 신으로, 비슈누·시바와 함께 세 주신(트리무르티)을 이룹니다.","description":["브라흐마는 비슈누의 배꼽에서 피어난 연꽃에서 태어났다는 이야기와 스스로 태어났다는 이야기가 함께 전합니다. 아내는 학문과 예술의 여신 사라스바티입니다.","창조의 신이지만 오늘날 브라흐마만을 모시는 사원은 드뭅니다. 불교에서는 범천으로 받아들여졌습니다."],"sort_order":4},{"slug":"krishna","pantheon_slug":"hindu","kind":"god","grade":null,"name":"크리슈나","name_en":"Krishna","epithet":"비슈누의 여덟 번째 화신","domains":["사랑","보호","가르침"],"summary":"목동들 사이에서 자란 비슈누의 화신으로, 「바가바드 기타」에서 아르주나에게 가르침을 주는 신입니다.","description":["크리슈나는 ‘검은’ 또는 ‘검푸른’이라는 뜻으로, 그림에서는 흔히 푸른 피부에 피리를 든 모습으로 그려집니다. 어린 시절 마을 사람들을 폭우에서 지키려고 고바르다나산을 들어 올렸다는 이야기가 유명합니다.","「마하바라타」의 전쟁에서는 아르주나의 마부가 되어 의무와 헌신에 대해 가르치는데, 이 대화가 「바가바드 기타」입니다."],"sort_order":5},{"slug":"fujin","pantheon_slug":"japanese","kind":"god","grade":null,"name":"후진","name_en":"Fujin","epithet":"바람의 신","domains":["바람"],"summary":"바람이 든 자루를 메고 하늘을 달리는 신으로, 천둥의 신 라이진과 짝을 이룹니다.","description":["후진은 오니처럼 생긴 몸에 바람 자루를 두르고, 그 자루를 열어 바람을 일으킨다고 여겨졌습니다.","17세기 화가 다와라야 소타쓰가 금박 바탕에 후진과 라이진을 그린 「풍신뇌신도」 병풍은 일본의 국보입니다."],"sort_order":5},{"slug":"inari","pantheon_slug":"japanese","kind":"god","grade":null,"name":"이나리","name_en":"Inari","epithet":"벼와 풍요의 신","domains":["벼농사","풍요","장사의 번성"],"summary":"여우를 사자로 부리는 곡식의 신으로, 붉은 도리이가 늘어선 이나리 신사에서 모십니다.","description":["이나리라는 이름은 ‘벼가 자란다’는 말에서 왔다는 설이 있으며, 남신·여신 등 여러 모습으로 그려집니다. 교토의 후시미 이나리 신사가 대표적입니다.","여우는 이나리의 사자로 여겨져 신사 곳곳에 여우 석상이 놓입니다. 섣달그믐 밤 오지 이나리 신사 근처에 여우들이 모인다는 전설은 우타가와 히로시게의 판화로도 그려졌습니다."],"sort_order":6},{"slug":"pangu","pantheon_slug":"chinese","kind":"god","grade":null,"name":"반고","name_en":"Pangu","epithet":"천지를 연 거인","domains":["창조","하늘과 땅"],"summary":"혼돈의 알에서 깨어나 하늘과 땅을 갈라놓고, 죽은 뒤 몸이 세상 만물이 된 거인입니다.","description":["반고는 알처럼 뒤섞인 혼돈 속에서 태어나 하늘과 땅을 갈랐고, 하늘이 내려앉지 않도록 1만 8천 년 동안 떠받쳤다고 합니다.","그가 죽자 숨은 바람과 구름, 두 눈은 해와 달, 피는 강이 되었다고 전합니다. 이 이야기는 3세기 삼국 시대 오나라의 기록에 처음 보여, 다른 중국 신화보다 늦게 자리 잡았습니다."],"sort_order":1},{"slug":"nuwa","pantheon_slug":"chinese","kind":"god","grade":null,"name":"여와","name_en":"Nüwa","epithet":"사람을 빚은 여신","domains":["인류 창조","혼인","하늘을 기움"],"summary":"황토로 사람을 빚고, 무너진 하늘을 오색 돌로 기운 뱀 몸의 여신입니다.","description":["여와는 사람의 윗몸에 뱀의 몸을 한 모습으로 그려지며, 황토를 빚어 사람을 만들었다고 합니다. 복희와 남매 또는 부부로 짝지어지는 것은 한나라 무렵부터입니다.","「회남자」에 따르면 하늘을 받치던 기둥이 부러져 세상이 불과 물에 휩싸이자, 여와가 오색 돌을 녹여 하늘의 구멍을 메웠다고 합니다."],"sort_order":2},{"slug":"xiwangmu","pantheon_slug":"chinese","kind":"god","grade":null,"name":"서왕모","name_en":"Xiwangmu","epithet":"곤륜산의 여신","domains":["불사","신선"],"summary":"곤륜산에 살며 먹으면 늙지 않는 복숭아를 기르는, 도교 신선들의 여왕입니다.","description":["「산해경」의 서왕모는 표범 꼬리와 호랑이 이빨을 가진 무서운 모습이었지만, 시간이 지나며 아름다운 여신으로 바뀌었습니다.","도교에서는 곤륜산의 연못 요지 곁에 살며 불로장생의 복숭아 반도가 열리면 잔치를 연다고 여겨, 장수를 비는 그림의 주제가 되었습니다."],"sort_order":3},{"slug":"change","pantheon_slug":"chinese","kind":"god","grade":null,"name":"항아","name_en":"Chang'e","epithet":"달의 여신","domains":["달"],"summary":"불사의 약을 먹고 달로 올라가 월궁에 살게 된 여신으로, 상아라고도 부릅니다.","description":["항아는 활의 명수 예의 아내로, 예가 서왕모에게 받은 불사의 약을 먹고 몸이 가벼워져 달로 날아갔다고 합니다.","한나라 문제의 이름 글자를 피해 ‘상아’로 바꿔 부르게 되었으며, 중국의 달 탐사선 이름도 여기서 따왔습니다."],"sort_order":4},{"slug":"cernunnos","pantheon_slug":"celtic","kind":"god","grade":null,"name":"케르눈노스","name_en":"Cernunnos","epithet":"뿔 달린 신","domains":["동물","풍요","숲"],"summary":"사슴뿔을 단 채 다리를 꼬고 앉은 모습으로 켈트 유물에 남은, 이름조차 확실하지 않은 신입니다.","description":["‘케르눈노스’라는 이름은 1세기 파리의 ‘뱃사공의 기둥’에 새겨진 글자에서 왔으며, 켈트 유물의 뿔 달린 신을 통틀어 이렇게 부릅니다.","덴마크에서 나온 군데스트루프 솥에는 사슴뿔을 단 신이 한 손에 목걸이(토크)를, 다른 손에 뱀을 쥐고 짐승들에 둘러싸여 앉아 있습니다."],"sort_order":1},{"slug":"cuchulainn","pantheon_slug":"celtic","kind":"hero","grade":null,"name":"쿠 훌린","name_en":"Cú Chulainn","epithet":"얼스터의 영웅","domains":["영웅","전쟁"],"summary":"어린 나이에 홀로 얼스터를 지킨, 아일랜드 신화에서 가장 이름난 영웅입니다.","description":["본래 이름은 세탄타였지만, 대장장이 쿨란의 사나운 개를 죽인 뒤 그 개 대신 집을 지키겠다고 하여 ‘쿨란의 개’라는 뜻의 쿠 훌린이 되었습니다.","「쿨리의 소 약탈」에서 코노트의 군대가 쳐들어오자 홀로 여울을 지키며 적의 용사들과 차례로 싸웠습니다. 전쟁의 여신 모리안과 얽힌 이야기도 많습니다."],"sort_order":2},{"slug":"brigid","pantheon_slug":"celtic","kind":"god","grade":null,"name":"브리지트","name_en":"Brigid","epithet":"불과 시, 치유의 여신","domains":["불","시","치유","대장장이 기술"],"summary":"시인과 치유사, 대장장이를 돕는 여신으로, 같은 이름의 성녀 브리지다와 겹쳐 전해집니다.","description":["브리지트(브리드)는 다그다의 딸로 전하며, 봄의 시작을 알리는 임볼크 축제와 이어집니다.","아일랜드가 기독교로 바뀐 뒤에는 킬데어의 성녀 브리지다와 겹쳐졌고, 성녀의 축일도 임볼크와 같은 2월 1일입니다."],"sort_order":3},{"slug":"morrigan","pantheon_slug":"celtic","kind":"god","grade":null,"name":"모리안","name_en":"The Morrígan","epithet":"전쟁과 운명의 여신","domains":["전쟁","운명","예언"],"summary":"까마귀로 변해 전장을 날며 승패와 죽음을 예고하는 아일랜드의 여신입니다.","description":["모리안은 ‘위대한 여왕’ 또는 ‘공포의 여왕’이라는 뜻으로 풀이되며, 자매들과 함께 세 여신으로 이야기되기도 합니다.","쿠 훌린에게 사랑을 구했다가 거절당한 뒤 그를 방해했다고 전합니다. 쿠 훌린이 죽을 때 그의 어깨에 까마귀가 내려앉았는데, 이 까마귀를 모리안으로 보기도 합니다."],"sort_order":4},{"slug":"quetzalcoatl","pantheon_slug":"aztec","kind":"god","grade":null,"name":"케찰코아틀","name_en":"Quetzalcoatl","epithet":"깃털 달린 뱀","domains":["바람","지혜","문명"],"summary":"‘깃털 달린 뱀’이라는 이름의, 메소아메리카 전역에서 숭배된 바람과 지혜의 신입니다.","description":["깃털 달린 뱀의 모습은 테오티우아칸 시대부터 나타나며, 아즈텍에서는 바람의 신 에에카틀의 모습으로도 섬겨졌습니다.","저승에서 옛 인류의 뼈를 가져와 자신의 피를 뿌려 지금의 인류를 만들었다고 전하며, 형제이자 맞수인 테스카틀리포카와 함께 세상을 만들고 무너뜨렸습니다."],"sort_order":1},{"slug":"tezcatlipoca","pantheon_slug":"aztec","kind":"god","grade":null,"name":"테스카틀리포카","name_en":"Tezcatlipoca","epithet":"연기 나는 거울","domains":["밤","운명","권력","마법"],"summary":"흑요석 거울로 세상을 보는 밤과 운명의 신으로, 케찰코아틀의 맞수입니다.","description":["이름은 나와틀어로 ‘연기 나는 거울’이라는 뜻이며, 잃어버린 한쪽 발 자리에 흑요석 거울을 단 모습으로 그려집니다.","첫 번째 태양인 재규어의 시대를 다스렸다고 전하며, 툴라의 왕이던 케찰코아틀을 속여 나라를 떠나게 만든 이야기가 유명합니다."],"sort_order":2},{"slug":"huitzilopochtli","pantheon_slug":"aztec","kind":"god","grade":null,"name":"우이칠로포치틀리","name_en":"Huitzilopochtli","epithet":"태양과 전쟁의 신","domains":["태양","전쟁"],"summary":"멕시카(아즈텍) 사람들을 이끌어 테노치티틀란을 세우게 한 태양과 전쟁의 신입니다.","description":["이름은 ‘남쪽의 벌새’라는 뜻으로 풀이되며, 어머니 코아틀리쿠에를 해치려던 누이 코욜샤우키와 형제들을 불의 뱀 시우코아틀로 물리쳤다고 합니다.","틀랄록과 함께 테노치티틀란의 큰 신전(템플로 마요르) 꼭대기에 나란히 선 두 사당에 모셔졌습니다."],"sort_order":3},{"slug":"tlaloc","pantheon_slug":"aztec","kind":"god","grade":null,"name":"틀랄록","name_en":"Tlaloc","epithet":"비와 번개의 신","domains":["비","번개","농사"],"summary":"고글 같은 눈 테와 송곳니로 알아볼 수 있는, 비와 농사를 다스리는 신입니다.","description":["틀랄록은 메소아메리카에서 오래전부터 섬긴 비의 신으로, 비를 내려 농사를 살리기도 하고 홍수와 가뭄을 부르기도 했습니다.","세 번째 태양의 시대를 다스렸다고 전하며, 우이칠로포치틀리와 함께 템플로 마요르 꼭대기의 두 사당에 모셔졌습니다."],"sort_order":4},{"slug":"mictlantecuhtli","pantheon_slug":"aztec","kind":"god","grade":null,"name":"믹틀란테쿠틀리","name_en":"Mictlantecuhtli","epithet":"죽은 이들의 나라 믹틀란의 주인","domains":["죽음","저승"],"summary":"해골 얼굴을 한 아즈텍의 저승 신으로, 아내 믹테카시우아틀과 함께 가장 깊은 저승 믹틀란을 다스립니다.","description":["아즈텍 사람들은 전쟁이나 물, 출산과 관계없이 평범하게 죽은 이들이 네 해 동안 아홉 층의 저승을 지나 마침내 믹틀란에 이른다고 믿었습니다. 믹틀란테쿠틀리는 뼈가 드러난 몸에 올빼미 깃털과 종이 장식을 단 모습으로 그려지며, 올빼미와 거미, 박쥐가 그를 따릅니다.","16세기 기록 「태양의 전설」에 따르면 케찰코아틀이 새 사람을 만들려고 앞 시대 사람들의 뼈를 얻으러 오자, 그는 구멍 없는 소라를 불어 보라는 어려운 과제를 냈습니다. 케찰코아틀은 벌레에게 구멍을 뚫게 하고 벌을 넣어 소리를 낸 뒤 뼈를 얻었지만, 달아나다 넘어져 뼈가 부러지는 바람에 사람들의 키가 제각각이 되었다고 합니다."],"sort_order":5},{"slug":"coatlicue","pantheon_slug":"aztec","kind":"god","grade":null,"name":"코아틀리쿠에","name_en":"Coatlicue","epithet":"뱀 치마를 두른 대지의 어머니","domains":["대지","탄생","죽음"],"summary":"뱀을 엮은 치마를 두른 대지의 여신으로, 전쟁의 신 우이칠로포치틀리와 그 누이 코욜사우키의 어머니입니다.","description":["「피렌체 코덱스」에 따르면 코아테펙산에서 비질을 하던 코아틀리쿠에는 하늘에서 떨어진 깃털 뭉치를 품에 넣었다가 아이를 배었습니다. 이를 부끄러운 일로 여긴 딸 코욜사우키와 아들 400명이 어머니를 죽이러 몰려오자, 갓 태어난 우이칠로포치틀리가 무장한 채 나와 그들을 물리쳤습니다.","1790년 멕시코시티 중앙 광장에서 나온 높이 2.5미터가 넘는 석상은 목이 잘린 자리에서 솟은 두 뱀이 얼굴을 이루고, 사람의 손과 심장을 엮은 목걸이를 걸었습니다. 생명을 낳으면서 거두기도 하는 대지의 두 얼굴을 나타냈다고 풀이합니다."],"sort_order":6},{"slug":"chalchiuhtlicue","pantheon_slug":"aztec","kind":"god","grade":null,"name":"찰치우틀리쿠에","name_en":"Chalchiuhtlicue","epithet":"옥 치마를 두른 물의 여신","domains":["강과 호수","출산","물"],"summary":"강과 호수, 샘처럼 땅 위를 흐르는 물을 다스리는 아즈텍의 여신으로, 비의 신 틀랄록의 아내 또는 누이라고 합니다.","description":["이름은 '옥 치마를 두른 여인'이라는 뜻으로, 옥빛처럼 푸른 물을 나타냅니다. 산파는 아기를 받은 뒤 그녀에게 기도하며 아기를 물로 씻겼고, 물을 길어 파는 사람과 배를 부리는 사람들도 그녀를 섬겼습니다.","「태양의 전설」에서는 그녀가 다스린 넷째 태양의 시대가 큰 홍수로 끝났고, 그때 사람들은 물고기가 되었다고 합니다. 아즈텍 사람들은 무릎을 꿇고 앉아 술 장식이 달린 머리띠를 두른 모습으로 그녀의 석상을 새겼습니다."],"sort_order":7},{"slug":"coyolxauhqui","pantheon_slug":"aztec","kind":"god","grade":null,"name":"코욜사우키","name_en":"Coyolxauhqui","epithet":"방울로 얼굴을 꾸민 여신","domains":["달","밤하늘"],"summary":"어머니 코아틀리쿠에를 죽이려다 갓 태어난 동생 우이칠로포치틀리에게 죽임을 당한 여신으로, 흔히 달의 여신으로 봅니다.","description":["이름은 '방울로 얼굴을 꾸민 이'라는 뜻이며, 남쪽 하늘의 별들인 400명의 형제를 이끌고 코아테펙산으로 쳐들어갔습니다. 「피렌체 코덱스」에 따르면 우이칠로포치틀리는 불뱀 시우코아틀로 그녀를 베었고, 그 몸은 산 아래로 굴러떨어지며 흩어졌습니다.","1978년 멕시코시티에서 전기 공사를 하던 노동자들이 그녀를 새긴 커다란 돌 원반을 찾아내면서 땅속에 묻혀 있던 아즈텍 대신전 발굴이 시작되었습니다. 그녀를 달로 보는 해석이 널리 퍼져 있지만, 옛 기록에는 달이라는 말이 없다는 반론도 있습니다."],"sort_order":8},{"slug":"xipe-totec","pantheon_slug":"aztec","kind":"god","grade":null,"name":"시페 토텍","name_en":"Xipe Totec","epithet":"벗긴 가죽을 걸친 봄과 새싹의 신","domains":["봄","새싹","금세공"],"summary":"제물의 벗긴 가죽을 옷처럼 걸친 모습으로 그려지는 아즈텍의 신으로, 낡은 껍질을 벗고 새싹이 돋는 봄을 나타낸다고 봅니다.","description":["이름은 '가죽을 벗긴 우리 주인'이라는 뜻입니다. 둘째 달의 틀라카시페우알리스틀리 축제에서 사제가 제물의 가죽을 스무 날 동안 입었는데, 옥수수가 껍질을 벗고 싹을 틔우듯 새 생명이 돋는 것을 나타냈다고 풀이합니다.","16세기 기록 「멕시코인의 역사」에서는 창조의 신 부부가 낳은 네 아들 가운데 맏이인 붉은 테스카틀리포카를 시페 토텍과 같은 신으로 봅니다. 금세공인들의 수호신이기도 했으며, 사포텍 등 멕시코 여러 지역에서 섬겼습니다."],"sort_order":9},{"slug":"dangun","pantheon_slug":"korean","kind":"hero","grade":null,"name":"단군","name_en":"Dangun","epithet":"고조선을 세운 시조","domains":["건국","시조"],"summary":"하늘에서 내려온 환웅과 곰에서 사람이 된 웅녀 사이에서 태어나 고조선을 세웠다고 전하는 시조입니다.","description":["「삼국유사」에 따르면 하늘신 환인의 아들 환웅이 무리 3천을 이끌고 태백산 신단수 아래로 내려왔습니다. 쑥과 마늘을 먹으며 동굴에서 견딘 곰이 여인 웅녀가 되어 환웅과 혼인해 단군왕검을 낳았습니다.","단군왕검은 아사달에 도읍해 고조선을 세웠고, 1,500년 동안 나라를 다스린 뒤 산신이 되었다고 전합니다. ‘단군’은 제사장, ‘왕검’은 임금을 뜻하는 말로 보는 견해가 많습니다."],"sort_order":1},{"slug":"bari","pantheon_slug":"korean","kind":"god","grade":null,"name":"바리공주","name_en":"Princess Bari","epithet":"무당의 조상신","domains":["저승 안내","무속","치유"],"summary":"일곱째 딸이라 버려졌지만, 저승에서 약물을 구해 와 부모를 살려 낸 무당들의 조상신입니다.","description":["오구대왕의 일곱째 딸로 태어나 버려졌기에 ‘버려진 공주’라는 뜻의 바리공주, 바리데기라고 불립니다.","부모가 병들어 목숨이 다하자 저승까지 가서 생명의 약물을 구해 와 부모를 살렸고, 그 뒤 죽은 이의 넋을 저승으로 이끄는 신이 되었습니다. 죽은 이를 보내는 오구굿에서 무당이 이 이야기를 노래합니다."],"sort_order":2},{"slug":"sansin","pantheon_slug":"korean","kind":"god","grade":null,"name":"산신","name_en":"Sansin","epithet":"산을 다스리는 신","domains":["산","마을의 수호","장수"],"summary":"범을 거느린 노인의 모습으로 그려지는, 산과 마을을 지키는 신입니다.","description":["산신은 산마다 깃든 신으로, 마을 사람들은 산신제를 지내며 풍년과 안녕을 빌었습니다. 흔히 노인이 범을 곁에 두고 앉은 모습으로 그려집니다.","불교가 이 믿음을 받아들이면서 절 안에 산신을 모시는 산신각이 생겼고, 그 안에 산신도를 걸어 모십니다. 「삼국유사」에는 단군이 나라를 다스린 뒤 산신이 되었다는 이야기도 있습니다."],"sort_order":3},{"slug":"jeseok","pantheon_slug":"korean","kind":"god","grade":null,"name":"제석","name_en":"Jeseok","epithet":"자손과 수명의 신","domains":["자손","수명","풍요"],"summary":"불교의 제석천(인드라)에서 이름을 얻은, 자손과 수명, 곡식을 내려 준다고 믿은 무속의 신입니다.","description":["제석이라는 이름은 불교의 하늘 신 제석천에서 왔으며, 제석천은 인도 신화의 인드라입니다.","무속의 제석굿에서는 당금애기가 스님과 인연을 맺어 세 아들을 낳고, 그 아들들이 제석신이 되는 이야기를 노래합니다. 그래서 무신도에는 고깔을 쓴 세 제석이 나란히 그려지곤 합니다."],"sort_order":4},{"slug":"vainamoinen","pantheon_slug":"finnish","kind":"hero","grade":null,"name":"베이네뫼이넨","name_en":"Väinämöinen","epithet":"노래하는 현자","domains":["노래","지혜","주술"],"summary":"공기의 여신 일마타르의 아들로, 노래와 주문으로 세상을 움직이는 「칼레발라」의 늙은 현자입니다.","description":["베이네뫼이넨은 어머니 뱃속에서 서른 해를 보낸 뒤 늙은 모습으로 태어났다고 하며, 노래로 사람과 자연을 움직이는 힘을 지녔습니다. 큰 강꼬치고기의 턱뼈로 현악기 칸텔레를 만들었습니다.","「칼레발라」의 마지막에서 그는 새 시대가 온 것을 알고 구리 배를 타고 바다 너머로 떠나며, 언젠가 다시 돌아오겠다고 말합니다."],"sort_order":1},{"slug":"ilmarinen","pantheon_slug":"finnish","kind":"hero","grade":null,"name":"일마리넨","name_en":"Ilmarinen","epithet":"하늘을 두드린 대장장이","domains":["대장장이","하늘"],"summary":"하늘의 둥근 지붕을 두드려 만들었다는 대장장이로, 행운을 낳는 보물 삼포를 벼려 냈습니다.","description":["일마리넨은 쇠를 다루는 솜씨가 뛰어나 하늘의 둥근 지붕까지 두드려 만들었다고 전합니다.","포흐욜라의 여주인 로우히의 딸과 혼인하려고, 곡식과 소금, 돈을 끝없이 만들어 내는 신비한 맷돌 삼포를 벼려 바쳤습니다."],"sort_order":2},{"slug":"louhi","pantheon_slug":"finnish","kind":"other","grade":null,"name":"로우히","name_en":"Louhi","epithet":"포흐욜라의 여주인","domains":["북쪽 땅","주술","역병"],"summary":"북쪽 나라 포흐욜라를 다스리는 강력한 마녀로, 삼포를 되찾으려 거대한 독수리로 변해 영웅들과 싸웁니다.","description":["로우히는 어둡고 추운 북쪽 땅 포흐욜라의 여주인으로, 딸을 신부로 내주는 대가로 영웅들에게 어려운 일을 맡깁니다.","베이네뫼이넨 일행이 삼포를 훔쳐 달아나자, 로우히는 날개에 군사를 태운 거대한 독수리로 변해 뒤쫓았고, 싸움 끝에 삼포는 바다에서 부서졌습니다."],"sort_order":3},{"slug":"lemminkainen","pantheon_slug":"finnish","kind":"hero","grade":null,"name":"레민케이넨","name_en":"Lemminkäinen","epithet":"무모한 영웅","domains":["모험","사랑"],"summary":"북쪽 나라의 처녀를 얻으려다 죽었지만, 어머니가 조각난 몸을 모아 되살린 영웅입니다.","description":["레민케이넨은 잘생기고 대담하지만 무모한 영웅으로, 로우히의 딸에게 청혼하러 갔다가 저승 투오넬라의 백조를 잡아 오라는 과제를 받습니다.","그는 투오넬라 강에서 죽어 몸이 조각난 채 강에 던져졌지만, 어머니가 긴 갈퀴로 조각을 건져 이어 붙이고 주문과 약으로 되살렸습니다."],"sort_order":4},{"slug":"kullervo","pantheon_slug":"finnish","kind":"hero","grade":null,"name":"쿨레르보","name_en":"Kullervo","epithet":"비극의 영웅","domains":["복수","비극"],"summary":"집안이 몰살당한 뒤 노예로 자라 복수를 이루었지만 끝내 스스로 목숨을 끊은 「칼레발라」의 비극적인 영웅입니다.","description":["삼촌 운타모가 아버지 칼레르보의 집안을 몰살할 때 살아남은 쿨레르보는 노예로 자라 대장장이 일마리넨의 집에 팔려 갔습니다. 일마리넨의 아내가 빵 속에 돌을 넣어 아버지의 유품인 칼이 부러지자, 그는 소 떼 대신 늑대와 곰을 몰고 와 그녀를 죽게 했습니다.","살아 있던 부모를 찾았지만, 길에서 만난 처녀가 잃어버린 누이였음을 뒤늦게 알게 되고 누이는 강물에 몸을 던졌습니다. 쿨레르보는 운타모의 집안을 쳐서 복수한 뒤, 누이를 만났던 숲에서 자기 칼에 몸을 던져 죽었습니다."],"sort_order":5},{"slug":"aino","pantheon_slug":"finnish","kind":"hero","grade":null,"name":"아이노","name_en":"Aino","epithet":"물고기가 된 처녀","domains":["비극","물"],"summary":"늙은 베이네뫼이넨에게 시집보내질 처지가 되자 바다로 걸어 들어가 물고기가 된 「칼레발라」의 처녀입니다.","description":["오빠 요우카하이넨은 베이네뫼이넨과의 노래 겨루기에서 져 늪에 빠지자, 목숨을 건지려고 누이 아이노를 그에게 주겠다고 약속했습니다. 어머니는 그 혼인을 기뻐했지만 아이노는 늙은 노인의 아내가 되기를 원하지 않았습니다.","슬픔에 잠겨 헤매던 아이노는 바닷가 바위에 올랐다가 물에 빠져 죽었고, 물고기가 되었다고 합니다. 뒤에 베이네뫼이넨이 그 물고기를 낚았으나 알아보지 못하고 칼로 손질하려 하자, 물고기는 그를 꾸짖고 물속으로 사라졌습니다."],"sort_order":6},{"slug":"joukahainen","pantheon_slug":"finnish","kind":"hero","grade":null,"name":"요우카하이넨","name_en":"Joukahainen","epithet":"노래 겨루기에 진 젊은이","domains":["노래 겨루기","복수"],"summary":"베이네뫼이넨에게 노래 겨루기를 걸었다가 져서 누이 아이노를 내주기로 한 「칼레발라」의 라플란드 젊은이입니다.","description":["자신의 지혜를 뽐내던 요우카하이넨은 길에서 베이네뫼이넨과 마주치자 노래 겨루기를 걸었습니다. 베이네뫼이넨이 노래를 부르자 그는 늪에 점점 빠져들었고, 살려 달라며 누이 아이노를 아내로 주겠다고 약속했습니다.","누이를 잃은 뒤 앙심을 품은 그는 석궁을 들고 기다리다, 말을 타고 물을 건너던 베이네뫼이넨을 쏘았습니다. 화살은 말을 맞혔고, 바다에 떨어진 베이네뫼이넨은 여러 날을 떠다니다 독수리에 실려 북쪽 땅 포욜라에 닿았습니다."],"sort_order":7},{"slug":"itzamna","pantheon_slug":"maya","kind":"god","grade":null,"name":"이참나","name_en":"Itzamna","epithet":"하늘과 지혜의 늙은 신","domains":["하늘","지혜","문자","치유"],"summary":"‘이구아나의 집’이라는 뜻으로 풀이되는, 문자와 달력을 전했다고 여겨진 늙은 창조신입니다.","description":["이참나는 이가 빠진 늙은 남자로 그려지며, 사제와 서기의 수호신으로 여겨졌습니다. 마야 사람들에게 문자와 달력을 가르쳤다고 전합니다.","마야 사람들은 하늘을 머리 둘 달린 뱀이나 이구아나의 모습으로 나타내기도 했는데, 이참나는 그 하늘의 집에 사는 신으로 해석됩니다."],"sort_order":1},{"slug":"kukulkan","pantheon_slug":"maya","kind":"god","grade":null,"name":"쿠쿨칸","name_en":"Kukulkan","epithet":"깃털 달린 뱀","domains":["바람","비","권력"],"summary":"아즈텍의 케찰코아틀에 해당하는, 마야 유카탄의 깃털 달린 뱀 신입니다.","description":["쿠쿨칸은 유카텍 마야어로 ‘깃털 달린 뱀’이라는 뜻이며, 10세기 무렵부터 치첸이차를 중심으로 크게 숭배되었습니다.","치첸이차의 엘 카스티요 피라미드는 쿠쿨칸의 신전으로, 춘분과 추분 해 질 녘이면 계단 난간에 비친 그림자가 뱀이 내려오는 모습처럼 보입니다."],"sort_order":2},{"slug":"chaac","pantheon_slug":"maya","kind":"god","grade":null,"name":"차크","name_en":"Chaac","epithet":"비의 신","domains":["비","번개","농사"],"summary":"도끼로 구름을 내리쳐 번개와 비를 부른다고 여겨진, 긴 코를 가진 비의 신입니다.","description":["차크는 아래로 휜 긴 코와 이빨을 가진 모습으로 그려지며, 번개를 상징하는 도끼를 들고 다닙니다.","동서남북 네 방향에 각각 차크가 있다고 믿었고, 유카탄의 건물 벽에는 차크의 얼굴 가면이 겹겹이 새겨졌습니다. 「드레스덴 코덱스」에 가장 자주 나오는 신입니다."],"sort_order":3},{"slug":"maize-god","pantheon_slug":"maya","kind":"god","grade":null,"name":"옥수수 신","name_en":"Maize God","epithet":"옥수수와 다시 태어남의 신","domains":["옥수수","풍요","부활"],"summary":"해마다 베어지고 다시 자라는 옥수수처럼, 죽었다가 다시 살아나는 젊고 아름다운 신입니다.","description":["옥수수 신은 옥수수 이삭처럼 길게 늘인 머리를 한 젊은 남자로 그려지며, 마야 사람들이 생각한 아름다움의 기준이었습니다.","「포폴 부」에서 영웅 쌍둥이의 아버지 훈 후나푸는 저승의 신들에게 죽임을 당하지만, 쌍둥이가 저승의 신들을 꺾은 뒤 되살아납니다. 이 이야기는 옥수수 신의 죽음과 부활과 이어진다고 봅니다."],"sort_order":4},{"slug":"ix-chel","pantheon_slug":"maya","kind":"god","grade":null,"name":"이슈 첼","name_en":"Ix Chel","epithet":"출산과 약, 베 짜기의 여신","domains":["출산","약","베 짜기","달"],"summary":"에스파냐 정복 무렵 유카탄의 마야 사람들이 출산과 약, 베 짜기의 여신으로 섬긴 신으로, 코수멜섬의 성지에 순례가 이어졌습니다.","description":["16세기 디에고 데 란다의 기록에 따르면 유카탄의 여인들은 아이를 낳을 때 이슈 첼에게 빌었고, 코수멜섬의 신전에는 먼 곳에서도 순례자가 찾아왔습니다. 후대에는 달의 여신으로도 널리 알려졌습니다.","마야 그림 문서에는 젊은 달의 여신(여신 I)과 물 항아리를 기울이는 늙은 여신(여신 O)이 따로 나오는데, 어느 쪽이 이슈 첼인지는 학자마다 견해가 다릅니다. 늙은 여신의 이름은 고전기 글자로 '차크 첼'이라고 읽기도 합니다."],"sort_order":5},{"slug":"hero-twins","pantheon_slug":"maya","kind":"hero","grade":null,"name":"우나푸와 슈발랑케","name_en":"Hunahpu and Xbalanque","epithet":"저승의 신들을 이긴 쌍둥이 영웅","domains":["공놀이","지혜","해와 달"],"summary":"「포폴 부」의 쌍둥이 영웅으로, 아버지를 죽인 저승 시발바의 신들을 꾀와 공놀이로 이기고 해와 달이 되어 하늘에 올랐습니다.","description":["쌍둥이는 시발바의 신들에게 죽임을 당한 운 우나푸의 머리가 침을 뱉어 저승 신의 딸 슈키크를 잉태시켜 태어났습니다. 자라서는 해와 달인 척 뽐내던 큰 새 부쿱 카킥스를 바람총으로 쏘아 쓰러뜨리고, 그의 아들들인 시파크나와 카브라칸도 꾀로 물리쳤습니다.","아버지처럼 시발바에 불려 간 쌍둥이는 어둠의 집, 칼날의 집, 박쥐의 집 같은 시련을 견디며 저승 신들과 공놀이를 했습니다. 스스로 불에 뛰어들었다가 되살아난 뒤 죽은 이를 살리는 재주를 부려, 자신들도 그렇게 해 달라는 저승의 우두머리 훈 카메와 부쿱 카메를 죽였고, 끝내 해와 달이 되었다고 합니다."],"sort_order":6},{"slug":"vucub-caquix","pantheon_slug":"maya","kind":"monster","grade":"spirit","name":"부쿱 카킥스","name_en":"Vucub Caquix","epithet":"해라고 뽐낸 일곱 마코앵무새","domains":["교만"],"summary":"해와 달이 생기기 전, 보석 이와 금속 눈의 빛을 뽐내며 자신이 해이자 달이라고 했던 큰 새로, 쌍둥이 영웅의 바람총에 쓰러졌습니다.","description":["「포폴 부」에 따르면 아직 해가 뜨지 않았던 때 부쿱 카킥스('일곱 마코앵무새')는 은빛 눈과 보석 이를 번쩍이며 자신이 해이고 달이라고 뽐냈습니다. 쌍둥이 영웅은 열매를 따 먹으러 나무에 오른 그의 턱을 바람총으로 맞혔고, 그는 다친 채 우나푸의 팔을 뜯어 달아났습니다.","쌍둥이는 할머니와 할아버지를 치료사로 꾸며 보내, 아픈 이를 고쳐 준다며 보석 이를 하얀 옥수수 알로 바꾸고 눈의 빛을 벗겨 냈습니다. 빛을 잃은 부쿱 카킥스는 죽었고, 쌍둥이는 우나푸의 팔을 되찾아 다시 붙였습니다."],"sort_order":7},{"slug":"dionysus","pantheon_slug":"greek","kind":"god","grade":null,"name":"디오니소스","name_en":"Dionysus","epithet":"포도주와 축제의 신","domains":["포도주","축제","연극"],"summary":"인간 어머니에게서 태어나 신이 된 포도주의 신으로, 축제와 연극의 수호신입니다.","description":["디오니소스는 제우스와 인간 세멜레의 아들입니다. 세멜레가 죽자 제우스는 아기를 자기 넓적다리에 넣어 길러 태어나게 했다고 합니다.","포도 재배와 포도주를 사람들에게 전했으며, 그를 기리는 아테네의 축제에서 비극과 희극이 생겨났습니다. 로마에서는 바쿠스라 불렸습니다."],"sort_order":10},{"slug":"hephaestus","pantheon_slug":"greek","kind":"god","grade":null,"name":"헤파이스토스","name_en":"Hephaestus","epithet":"불과 대장장이의 신","domains":["불","대장장이","공예"],"summary":"신들의 무기와 궁전을 만든 대장장이 신으로, 아프로디테의 남편입니다.","description":["헤파이스토스는 제우스의 번개와 아킬레우스의 방패 같은 신과 영웅의 무기를 만들었고, 화산 아래에 대장간이 있다고 여겨졌습니다.","다리가 불편했는데, 헤라가 갓난 그를 올림포스에서 던져 버렸다는 이야기와 제우스가 던졌다는 이야기가 함께 전합니다. 로마에서는 불카누스라 불렸습니다."],"sort_order":11},{"slug":"heracles","pantheon_slug":"greek","kind":"hero","grade":null,"name":"헤라클레스","name_en":"Heracles","epithet":"열두 과업의 영웅","domains":["영웅","힘"],"summary":"헤라의 미움을 받아 열두 가지 과업을 해낸 끝에 신이 된 그리스 최고의 영웅입니다.","description":["헤라클레스는 제우스와 인간 알크메네의 아들로, 갓난아기 때 헤라가 보낸 뱀 두 마리를 맨손으로 죽였다고 합니다.","헤라 때문에 광기에 빠져 가족을 죽인 죄를 씻으려 네메아의 사자 사냥, 히드라 퇴치 등 열두 과업을 해냈고, 죽은 뒤 올림포스에 올라 신이 되었습니다."],"sort_order":12},{"slug":"medusa","pantheon_slug":"greek","kind":"monster","grade":"spirit","name":"메두사","name_en":"Medusa","epithet":"고르곤 세 자매의 막내","domains":["괴물","보호의 상징"],"summary":"눈을 마주친 이를 돌로 바꾼다는 고르곤으로, 영웅 페르세우스에게 목이 베였습니다.","description":["메두사는 고르곤 세 자매 가운데 유일하게 죽는 몸이었습니다. 원래 아름다운 여인이었다가 저주로 괴물이 되었다는 이야기는 로마 시인 오비디우스가 전한 후대의 이야기입니다.","페르세우스는 방패에 비친 모습만 보며 다가가 메두사의 목을 베었고, 그 머리는 아테나의 방패에 붙어 적을 막는 상징이 되었습니다. 카라바조의 「메두사」도 방패에 그린 그림입니다."],"sort_order":13},{"slug":"set","pantheon_slug":"egyptian","kind":"god","grade":null,"name":"세트","name_en":"Set","epithet":"사막과 폭풍의 신","domains":["사막","폭풍","혼돈"],"summary":"형 오시리스를 죽이고 왕위를 빼앗았지만, 라의 배를 지켜 뱀 아포피스와 싸우기도 한 신입니다.","description":["세트는 게브와 누트의 아들로, 정체를 알 수 없는 동물의 머리를 한 모습으로 그려집니다. 오시리스를 죽인 뒤 호루스와 오랫동안 왕위를 두고 다퉜습니다.","악한 신으로만 여겨진 것은 아니어서, 밤마다 라의 배를 공격하는 뱀 아포피스를 물리치는 수호자이기도 했고, 세티 1세처럼 파라오의 이름에도 쓰였습니다."],"sort_order":7},{"slug":"hathor","pantheon_slug":"egyptian","kind":"god","grade":null,"name":"하토르","name_en":"Hathor","epithet":"사랑과 음악의 여신","domains":["사랑","음악","출산","저승 안내"],"summary":"암소의 귀를 가진 여인이나 암소로 그려지는, 사랑과 음악, 기쁨의 여신입니다.","description":["하토르는 라의 딸 또는 호루스의 아내로 전하며, 하늘의 암소로 여겨졌습니다. 신전 기둥머리에는 암소 귀를 한 하토르의 얼굴이 새겨지곤 했습니다.","춤과 음악, 술의 여신이었고, 악기 시스트럼이 하토르의 상징입니다. 죽은 이를 저승으로 맞이하는 여신이기도 했습니다."],"sort_order":8},{"slug":"bastet","pantheon_slug":"egyptian","kind":"god","grade":null,"name":"바스테트","name_en":"Bastet","epithet":"고양이의 여신","domains":["가정","보호","즐거움"],"summary":"처음에는 사나운 암사자의 여신이었다가, 점차 집과 아이를 지키는 고양이의 여신이 되었습니다.","description":["바스테트는 이른 시기에는 암사자 머리의 사나운 여신이었지만, 기원전 1천 년대 무렵부터 고양이 또는 고양이 머리를 한 여인으로 그려졌습니다.","하이집트의 부바스티스가 신앙의 중심이었고, 그곳에는 많은 고양이 미라가 바쳐졌습니다. 그리스인들은 바스테트를 아르테미스와 동일시했습니다."],"sort_order":9},{"slug":"lakshmi","pantheon_slug":"hindu","kind":"god","grade":null,"name":"락슈미","name_en":"Lakshmi","epithet":"부와 행운의 여신","domains":["부","행운","아름다움"],"summary":"우유 바다를 휘저을 때 연꽃 위로 나타났다는, 비슈누의 아내이자 부와 행운의 여신입니다.","description":["락슈미는 신들과 아수라가 불사의 감로를 얻으려 우유 바다를 휘저을 때 바다에서 나타나 비슈누를 남편으로 골랐다고 합니다.","연꽃 위에 선 모습으로 그려지며, 빛의 축제 디왈리에 집집마다 등불을 밝혀 락슈미를 맞이합니다."],"sort_order":6},{"slug":"hanuman","pantheon_slug":"hindu","kind":"hero","grade":null,"name":"하누만","name_en":"Hanuman","epithet":"원숭이 영웅","domains":["힘","헌신","용기"],"summary":"「라마야나」에서 라마를 도와 납치된 시타를 찾아낸 원숭이 장군으로, 지금은 널리 섬기는 신입니다.","description":["하누만은 바람의 신 바유의 아들로 전하며, 바다를 단숨에 뛰어넘어 랑카섬에 갇힌 시타를 찾아냈습니다.","전쟁 중 다친 락슈마나를 살릴 약초를 구하려 히말라야의 산을 통째로 들고 왔다는 이야기가 유명하며, 라마에 대한 헌신의 상징으로 섬겨집니다."],"sort_order":7},{"slug":"durga","pantheon_slug":"hindu","kind":"god","grade":null,"name":"두르가","name_en":"Durga","epithet":"악을 무찌르는 여신","domains":["전쟁","보호","악을 물리침"],"summary":"신들이 이기지 못한 물소 악마 마히샤를 여러 팔로 무찌른, 사자를 탄 전쟁의 여신입니다.","description":["신들의 분노에서 태어난 두르가는 신들에게서 무기를 하나씩 받아 여러 팔에 들고, 사자를 타고 물소 악마 마히샤와 싸워 이겼습니다. 그래서 ‘마히샤를 죽인 여신’이라는 뜻의 마히샤수라마르디니라고도 불립니다.","벵골 지방에서는 해마다 가을에 두르가 푸자 축제를 크게 엽니다."],"sort_order":8},{"slug":"frigg","pantheon_slug":"norse","kind":"god","grade":null,"name":"프리그","name_en":"Frigg","epithet":"신들의 여왕","domains":["결혼","가정","예지"],"summary":"오딘의 아내이자 발드르의 어머니로, 모든 운명을 알지만 말하지 않는다는 여신입니다.","description":["프리그는 오딘과 함께 높은 자리에서 세상을 내려다보며, 사람들의 운명을 알지만 입 밖에 내지 않는다고 「산문 에다」는 전합니다.","아들 발드르를 지키려 세상 모든 것에게 맹세를 받았지만, 겨우살이를 빠뜨린 탓에 그를 잃었습니다."],"sort_order":7},{"slug":"tyr","pantheon_slug":"norse","kind":"god","grade":null,"name":"티르","name_en":"Tyr","epithet":"전쟁과 맹세의 신","domains":["전쟁","법","맹세","용기"],"summary":"늑대 펜리르를 묶기 위해 한 손을 그 입에 넣었다가 잃은 용감한 신입니다.","description":["신들이 펜리르를 마법의 끈 글레이프니르로 묶으려 하자, 펜리르는 속임수가 아니라는 증거로 누군가의 손을 입에 넣으라고 했습니다. 티르만이 나섰고, 끈이 풀리지 않자 펜리르는 그의 손을 물어뜯었습니다.","게르만 사람들이 오래전부터 섬긴 신으로, 영어의 화요일(Tuesday)이 티르의 이름에서 나왔습니다. 라그나로크에서는 개 가름과 싸워 함께 쓰러진다고 전합니다."],"sort_order":8},{"slug":"ahura-mazda","pantheon_slug":"iranian","kind":"god","grade":null,"name":"아후라 마즈다","name_en":"Ahura Mazda","epithet":"지혜의 주","domains":["선","지혜","창조"],"summary":"조로아스터교의 최고신으로, 빛과 진리의 편에서 악과 싸우는 창조주입니다.","description":["아후라 마즈다는 ‘지혜의 주’라는 뜻으로, 예언자 조로아스터가 유일한 최고신으로 섬기게 한 신입니다. 악의 영 앙그라 마이뉴(아리만)와 맞서 세상을 선으로 이끈다고 여겼습니다.","페르시아 왕들은 비문에서 아후라 마즈다의 뜻으로 왕이 되었다고 밝혔습니다. 날개 달린 원반 문양 파라바하르를 아후라 마즈다로 보기도 하지만, 사람의 수호령으로 보는 견해도 있습니다."],"sort_order":1},{"slug":"mithra","pantheon_slug":"iranian","kind":"god","grade":null,"name":"미트라","name_en":"Mithra","epithet":"계약과 빛의 신","domains":["계약","맹세","빛","태양"],"summary":"약속과 맹세를 지키는 빛의 신으로, 로마 제국에서는 미트라스 신앙으로 퍼졌습니다.","description":["미트라는 인도·이란 사람들이 함께 섬긴 오래된 신으로, 인도의 미트라와 뿌리가 같습니다. 사람 사이의 계약을 지키고, 거짓말하는 자를 벌한다고 여겨졌습니다.","햇살을 두른 모습으로 그려지며, 로마 제국에서는 황소를 죽이는 미트라스를 섬기는 비밀 종교가 군인들 사이에 널리 퍼졌습니다."],"sort_order":2},{"slug":"anahita","pantheon_slug":"iranian","kind":"god","grade":null,"name":"아나히타","name_en":"Anahita","epithet":"물과 생명의 여신","domains":["물","풍요","출산"],"summary":"모든 물과 생명을 맑게 하는 여신으로, 페르시아 왕들이 왕권을 내려 주는 신으로 새겼습니다.","description":["아나히타의 본디 이름은 아르드비 수라 아나히타로, ‘물기 많고 강하며 순결한 이’라는 뜻입니다. 강과 비, 출산과 풍요를 맡았습니다.","사산 왕조의 왕들은 아나히타를 깊이 섬겨, 타크에 보스탄 동굴 부조에는 아후라 마즈다와 아나히타 사이에서 왕이 왕권을 받는 장면이 새겨져 있습니다."],"sort_order":3},{"slug":"baal","pantheon_slug":"canaanite","kind":"god","grade":null,"name":"바알","name_en":"Baal","epithet":"폭풍과 비의 신","domains":["폭풍","비","풍요","왕권"],"summary":"번개를 창처럼 들고 바다와 죽음의 신에 맞선, 가나안의 폭풍과 풍요의 신입니다.","description":["바알은 ‘주인’이라는 뜻의 칭호로, 본디 이름은 하다드라고 봅니다. 비를 내려 땅을 기름지게 하는 신이었습니다.","우가리트 점토판에서 바알은 바다의 신 얌을 물리치고, 죽음의 신 모트에게 삼켜졌다가 누이 아나트의 도움으로 되살아납니다. 이 순환은 마른 계절과 비 오는 계절의 바뀜과 이어진다고 봅니다."],"sort_order":1},{"slug":"astarte","pantheon_slug":"canaanite","kind":"god","grade":null,"name":"아스타르테","name_en":"Astarte","epithet":"사랑과 전쟁의 여신","domains":["사랑","풍요","전쟁"],"summary":"메소포타미아의 이슈타르와 뿌리가 같은, 페니키아와 가나안의 사랑과 전쟁의 여신입니다.","description":["아스타르테는 가나안에서는 아스타르트, 페니키아에서는 아쉬타르트라 불렸고, 메소포타미아의 이슈타르와 같은 계통의 여신입니다.","페니키아 상인들을 따라 키프로스와 카르타고까지 신앙이 퍼졌고, 그리스인들은 아스타르테를 아프로디테와 동일시했습니다."],"sort_order":2},{"slug":"teshub","pantheon_slug":"hittite","kind":"god","grade":null,"name":"테슈브","name_en":"Teshub","epithet":"폭풍의 신","domains":["폭풍","하늘","왕권"],"summary":"황소가 끄는 수레를 타고 번개를 든, 후르리와 히타이트 신들의 왕입니다.","description":["테슈브는 본디 후르리인의 폭풍의 신으로, 히타이트에 들어와 신들의 왕이 되었습니다. 아내는 여신 헤바트입니다.","‘쿠마르비 신화’에서 테슈브는 아버지 세대의 신 쿠마르비를 몰아내고 왕권을 차지하는데, 이 이야기는 그리스 신화의 크로노스와 제우스 이야기와 닮았습니다. 하투샤 근처 야즐르카야 바위 성소에 테슈브와 헤바트가 마주 선 부조가 있습니다."],"sort_order":1},{"slug":"illuyanka","pantheon_slug":"hittite","kind":"monster","grade":"divine","name":"일루얀카","name_en":"Illuyanka","epithet":"폭풍의 신과 싸운 뱀","domains":["혼돈","뱀"],"summary":"폭풍의 신을 한때 이겼지만, 꾀에 빠져 결국 죽임을 당한 거대한 뱀입니다.","description":["히타이트의 새해 축제에서 읊은 이야기에 따르면, 뱀 일루얀카는 폭풍의 신과 싸워 이겼습니다.","폭풍의 신은 여신 이나라의 꾀로 잔치를 열어 일루얀카가 배불리 먹고 굴에 돌아가지 못하게 한 뒤, 사람 후파시야가 뱀을 묶자 마침내 죽였습니다. 이 이야기에는 여러 판본이 있습니다."],"sort_order":2},{"slug":"kumarbi","pantheon_slug":"hittite","kind":"god","grade":null,"name":"쿠마르비","name_en":"Kumarbi","epithet":"하늘의 왕위를 다툰 신들의 아버지","domains":["왕권","곡식"],"summary":"후르리인의 신으로, 하늘의 왕 아누를 몰아냈지만 자기 몸에서 태어난 폭풍의 신 테슈브에게 왕위를 빼앗기고 되찾으려 애쓴 신입니다.","description":["히타이트 점토판으로 전하는 「쿠마르비의 노래」(「하늘의 왕권」)에 따르면 하늘의 왕은 알랄루, 아누, 쿠마르비로 차례로 바뀌었습니다. 쿠마르비는 달아나는 아누를 붙잡아 그 생식기를 물어뜯어 삼켰고, 그 때문에 몸속에 테슈브를 비롯한 신들을 배게 되었습니다.","그렇게 태어난 테슈브가 그를 몰아내자, 쿠마르비는 커다란 바위와 짝지어 돌 괴물 울리쿰미를 낳아 테슈브와 맞서게 했습니다. 아버지를 몰아낸 신이 다시 자식에게 왕위를 잃는 이 이야기는 헤시오도스의 크로노스 이야기와 닮아, 그리스 신화의 뿌리 가운데 하나로 연구됩니다."],"sort_order":3},{"slug":"telipinu","pantheon_slug":"hittite","kind":"god","grade":null,"name":"텔리피누","name_en":"Telipinu","epithet":"사라졌다 돌아온 농사의 신","domains":["농사","풍요"],"summary":"화가 나서 자취를 감추자 곡식과 가축이 자라지 않게 되었다가, 벌에게 쏘이고 의식으로 노여움을 푼 뒤 돌아온 히타이트의 농사의 신입니다.","description":["「텔리피누 신화」에 따르면 텔리피누는 무엇에 노했는지 신발을 바꿔 신은 채 떠나 버렸습니다. 그러자 창에는 안개가 끼고 아궁이의 장작이 꺼졌으며, 곡식은 자라지 않고 소와 양은 새끼를 돌보지 않아 사람과 신들이 모두 굶주렸습니다.","독수리도 폭풍의 신도 그를 찾지 못했지만, 어머니 여신 한나한나가 보낸 벌이 들판에서 잠든 그를 찾아 쏘아 깨웠습니다. 더 노한 텔리피누를 여신 캄루세파가 의식으로 달래 돌아오게 했고, 세상은 다시 풍요로워졌습니다."],"sort_order":4},{"slug":"ullikummi","pantheon_slug":"hittite","kind":"monster","grade":"divine","name":"울리쿰미","name_en":"Ullikummi","epithet":"하늘까지 자란 돌 거인","domains":["돌","파괴"],"summary":"쿠마르비가 테슈브를 무너뜨리려고 바위와 짝지어 낳은 돌 괴물로, 바다 밑 거인의 어깨 위에서 하늘에 닿을 만큼 자랐습니다.","description":["「울리쿰미의 노래」에 따르면 쿠마르비는 갓 태어난 돌 아이를 신들 몰래 바다 밑 거인 우펠루리의 오른쪽 어깨에 올려 두었고, 아이는 하루에 한 규빗씩 자라 끝내 하늘에 닿았습니다. 보지도 듣지도 못해 여신 샤우슈카의 노래에도 넘어가지 않은 이 거인 앞에서 테슈브는 첫 싸움에 졌습니다.","지혜의 신 에아는 옛날 하늘과 땅을 갈라놓은 구리 칼을 꺼내 와 울리쿰미의 발을 우펠루리의 어깨에서 잘라 내게 했고, 힘을 잃은 그에게 테슈브가 다시 싸움을 걸었습니다. 마지막 대목은 점토판이 깨져 온전히 전하지 않습니다."],"sort_order":5},{"slug":"allat","pantheon_slug":"arabian","kind":"god","grade":null,"name":"알라트","name_en":"Allat","epithet":"여신","domains":["대지","보호"],"summary":"‘여신’이라는 뜻의 이름을 가진, 이슬람 이전 아라비아에서 가장 널리 섬긴 여신의 하나입니다.","description":["알라트는 알우짜, 마나트와 함께 메카 사람들이 섬긴 세 여신이며, 타이프에 큰 신전이 있었습니다.","시리아의 팔미라에서는 알라트를 그리스의 아테나와 겹쳐 섬겼고, 그 신전 터에서 사자 조각 등이 발견되었습니다."],"sort_order":1},{"slug":"dushara","pantheon_slug":"arabian","kind":"god","grade":null,"name":"두샤라","name_en":"Dushara","epithet":"나바테아의 주신","domains":["산","왕권","포도"],"summary":"페트라를 세운 나바테아 왕국의 최고신으로, 흔히 네모난 돌 기둥으로 표현되었습니다.","description":["두샤라는 ‘샤라산의 그분’이라는 뜻으로, 페트라 근처 산과 이어진 나바테아의 최고신입니다.","처음에는 사람 모습 대신 네모난 돌(베틸)로 섬겼지만, 로마 시대에는 그리스의 제우스나 디오니소스처럼 수염 난 신의 모습으로도 새겨졌습니다."],"sort_order":2},{"slug":"perun","pantheon_slug":"slavic","kind":"god","grade":null,"name":"페룬","name_en":"Perun","epithet":"천둥의 신","domains":["천둥","번개","전쟁"],"summary":"참나무와 높은 언덕에서 섬긴, 슬라브 신들의 왕이자 천둥의 신입니다.","description":["페룬이라는 이름은 ‘번개’ 또는 ‘치는 자’라는 뜻으로 풀이되며, 발트의 페르쿠나스와 뿌리가 같습니다.","「원초 연대기」에는 키이우의 블라디미르 대공이 980년 무렵 언덕 위에 은 머리와 금 수염을 단 페룬의 나무 신상을 세웠다고 적혀 있습니다."],"sort_order":1},{"slug":"svetovid","pantheon_slug":"slavic","kind":"god","grade":null,"name":"스뱌토비트","name_en":"Svetovid","epithet":"네 얼굴의 신","domains":["전쟁","풍요","예언"],"summary":"네 얼굴로 사방을 본다고 전하는 서슬라브의 신으로, 발트해 연안 아르코나에 큰 신전이 있었습니다.","description":["12세기 덴마크 역사가 삭소 그라마티쿠스는 뤼겐섬 아르코나 신전에 네 머리를 가진 스뱌토비트의 거대한 상이 있었고, 1168년 덴마크군이 이를 무너뜨렸다고 기록했습니다.","1848년 우크라이나 즈브루치강에서 발견된, 네 면에 얼굴을 새긴 돌기둥은 흔히 스뱌토비트와 이어서 소개됩니다."],"sort_order":2},{"slug":"baba-yaga","pantheon_slug":"slavic","kind":"other","grade":null,"name":"바바 야가","name_en":"Baba Yaga","epithet":"숲속의 마녀","domains":["숲","죽음과 시험","지혜"],"summary":"닭다리 위에 선 오두막에 살며 절구를 타고 나는, 슬라브 민담의 무서운 마녀입니다.","description":["바바 야가는 ‘할멈’과 ‘공포’를 뜻하는 말이 합쳐진 이름으로, 깊은 숲 속 닭다리 위의 오두막에 산다고 전합니다.","찾아온 주인공을 잡아먹으려 하기도 하고, 시험을 견딘 이에게는 도움을 주기도 하는 두 얼굴의 존재입니다. 절구를 타고 절굿공이로 노를 저으며 빗자루로 흔적을 지운다고 합니다."],"sort_order":3},{"slug":"perkunas","pantheon_slug":"baltic","kind":"god","grade":null,"name":"페르쿠나스","name_en":"Perkūnas","epithet":"천둥의 신","domains":["천둥","하늘","정의"],"summary":"참나무를 신성하게 여긴 발트족의 천둥의 신으로, 악을 쫓고 비를 내린다고 믿었습니다.","description":["페르쿠나스는 하늘을 수레로 달리며 도끼로 번개를 던지고, 악한 존재를 쫓는다고 여겨졌습니다. 참나무가 그의 나무입니다.","리투아니아의 빌뉴스에는 그를 모시던 성소가 있었다고 전하며, 라트비아에서는 페르콘스라고 불렀습니다."],"sort_order":1},{"slug":"laima","pantheon_slug":"baltic","kind":"god","grade":null,"name":"라이마","name_en":"Laima","epithet":"운명의 여신","domains":["운명","출산","행운"],"summary":"아기가 태어날 때 그 삶의 운명을 정한다는 발트의 운명의 여신입니다.","description":["라이마는 출산을 돕고, 갓 태어난 아이의 수명과 행복을 정한다고 믿었습니다.","라트비아 민요 다이나에는 라이마가 사람의 앞날을 노래하는 구절이 많으며, 혼인과 행운의 여신으로도 섬겼습니다."],"sort_order":2},{"slug":"kalevipoeg","pantheon_slug":"estonian","kind":"hero","grade":null,"name":"칼레비포에그","name_en":"Kalevipoeg","epithet":"칼레브의 아들","domains":["영웅","힘"],"summary":"에스토니아 땅을 지키며 거인의 힘으로 바위를 던지고 숲을 갈았다는 민족 서사시의 영웅입니다.","description":["칼레비포에그는 ‘칼레브의 아들’이라는 뜻으로, 에스토니아 곳곳의 큰 바위와 언덕이 그가 던지거나 쌓은 것이라는 전설이 있습니다.","서사시에서 그는 지하 세계로 내려가 악마 바나파간과 싸워 이기지만, 끝내 저주받은 칼에 다리를 잃고 저승의 문을 지키게 됩니다."],"sort_order":1},{"slug":"vanapagan","pantheon_slug":"estonian","kind":"other","grade":null,"name":"바나파간","name_en":"Vanapagan","epithet":"옛 이교도","domains":["지하 세계","속임수"],"summary":"에스토니아 민담에서 꾀에 자주 넘어가는 어리숙한 악마로, 칼레비포에그의 맞수입니다.","description":["바나파간은 ‘옛 이교도’라는 뜻으로, 기독교가 들어온 뒤 옛 신앙의 존재가 악마로 바뀐 모습입니다.","민담에서는 힘은 세지만 어리숙해 농부에게 번번이 속아 넘어가고, 서사시에서는 지하 세계의 주인으로 칼레비포에그와 겨룹니다."],"sort_order":2},{"slug":"tinia","pantheon_slug":"etruscan","kind":"god","grade":null,"name":"티니아","name_en":"Tinia","epithet":"하늘의 신","domains":["하늘","번개","신들의 왕"],"summary":"번개를 던지는 에트루리아 신들의 왕으로, 그리스의 제우스, 로마의 유피테르와 겹쳐집니다.","description":["티니아는 하늘과 번개의 신으로, 에트루리아 사람들은 번개가 어느 쪽 하늘에서 치는지로 신의 뜻을 읽었습니다.","아내 우니(로마의 유노), 딸 멘르바(미네르바)와 함께 섬겨졌는데, 이 세 신은 훗날 로마 카피톨리노 언덕의 세 주신으로 이어졌습니다."],"sort_order":1},{"slug":"charun","pantheon_slug":"etruscan","kind":"other","grade":null,"name":"카룬","name_en":"Charun","epithet":"저승의 안내자","domains":["죽음","저승"],"summary":"망치를 든 푸른 피부의 존재로, 죽은 이를 저승으로 데려가는 에트루리아의 저승 안내자입니다.","description":["카룬은 그리스의 뱃사공 카론에게서 이름을 얻었지만, 매부리코에 푸르스름한 피부를 하고 큰 망치를 든 무서운 모습으로 그려집니다.","무덤 벽화에서 그는 죽은 이 곁에 서서 저승으로 이끄는데, 망치는 죽음의 일격 또는 저승의 문을 지키는 도구로 풀이됩니다."],"sort_order":2},{"slug":"menrva","pantheon_slug":"etruscan","kind":"god","grade":null,"name":"멘르바","name_en":"Menrva","epithet":"지혜와 전쟁의 여신","domains":["지혜","전쟁","예술"],"summary":"투구와 방패를 갖춘 지혜의 여신으로, 로마의 미네르바가 이 이름에서 나왔습니다.","description":["멘르바는 그리스의 아테나와 겹쳐지는 여신으로, 투구를 쓰고 방패를 든 모습으로 거울 그림에 자주 나옵니다.","티니아의 머리에서 태어났다는 그리스 신화도 에트루리아 거울에 그려졌으며, 로마인은 이 여신을 미네르바라는 이름으로 받아들였습니다."],"sort_order":3},{"slug":"snake-goddess","pantheon_slug":"minoan","kind":"god","grade":null,"name":"뱀의 여신","name_en":"Minoan Snake Goddess","epithet":"뱀을 든 여신","domains":["대지","가정의 수호","재생"],"summary":"크노소스 궁전 터에서 나온, 양손에 뱀을 든 여인 소상으로 알려진 미노스의 여신입니다.","description":["1903년 아서 에번스가 크노소스 궁전의 저장고에서 발견한 소상으로, 가슴을 드러낸 옷을 입고 양손에 뱀을 든 여인의 모습입니다.","여신인지 여사제인지는 확실하지 않으며, 발견 당시 부서진 조각을 이어 붙이며 일부가 복원되었다는 점도 알려져 있습니다."],"sort_order":1},{"slug":"mistress-of-animals","pantheon_slug":"minoan","kind":"god","grade":null,"name":"동물의 여주인","name_en":"Mistress of Animals","epithet":"짐승을 거느린 여신","domains":["야생","짐승"],"summary":"양옆에 사자나 새 같은 짐승을 거느린 여신의 모습으로, 지중해 곳곳에서 보이는 오래된 도상입니다.","description":["미노스의 인장과 반지에는 짐승들 사이에 선 여신이 자주 새겨져 있으며, 이를 흔히 ‘동물의 여주인’이라 부릅니다.","같은 도상은 그리스의 아르테미스로 이어졌다고 보며, 그리스어로는 ‘포트니아 테론(짐승들의 여주인)’이라 불렀습니다."],"sort_order":2},{"slug":"anahit","pantheon_slug":"armenian","kind":"god","grade":null,"name":"아나히트","name_en":"Anahit","epithet":"어머니 여신","domains":["풍요","지혜","출산"],"summary":"이란의 아나히타에서 비롯한 아르메니아의 어머니 여신으로, 금으로 만든 신상이 있었다고 전합니다.","description":["아나히트는 ‘위대한 여인’으로 불리며 풍요와 출산, 지혜를 맡은 아르메니아의 주요 여신이었습니다.","그리스 지리학자 스트라본은 에레즈의 아나히트 신전에 금으로 만든 신상이 있었다고 기록했습니다. 아르메니아 사탈라에서 나온 청동 두상을 아나히트로 보기도 합니다."],"sort_order":1},{"slug":"vahagn","pantheon_slug":"armenian","kind":"god","grade":null,"name":"바하근","name_en":"Vahagn","epithet":"용을 물리친 신","domains":["불","번개","용기"],"summary":"갈대 줄기 속에서 불꽃으로 태어나 용을 물리쳤다는 아르메니아의 불과 번개의 신입니다.","description":["모브세스 호레나치가 전한 옛 노래에 따르면, 하늘과 땅과 바다가 산고를 겪을 때 붉은 갈대에서 연기와 불이 피어오르고, 그 불꽃 속에서 불의 머리털과 해 같은 눈을 가진 바하근이 태어났습니다.","용을 물리친 영웅으로 섬겨졌고, 이란의 승리의 신 베레트라그나와 뿌리가 같다고 봅니다."],"sort_order":2},{"slug":"hayk","pantheon_slug":"armenian","kind":"hero","grade":null,"name":"하이크","name_en":"Hayk","epithet":"아르메니아 민족의 시조","domains":["건국","활","자유"],"summary":"바빌론의 폭군 벨에 맞서 아르메니아 고원으로 떠나, 활로 벨을 쓰러뜨렸다는 아르메니아 민족의 시조입니다.","description":["모브세스 호레나치의 「아르메니아 역사」에 따르면 하이크는 노아의 아들 야벳의 후손인 거인 장수로, 바빌론의 벨이 모두를 다스리려 하자 굴복하지 않고 자기 사람들을 이끌고 북쪽 아라라트 땅으로 떠났습니다.","벨이 대군을 이끌고 쫓아오자 하이크는 반 호수 근처에서 맞서 싸워, 세 날개 화살로 벨의 가슴을 꿰뚫었습니다. 아르메니아 사람들이 스스로를 '하이', 나라를 '하야스탄'이라고 부르는 것은 그의 이름에서 나왔다고 합니다."],"sort_order":3},{"slug":"ara","pantheon_slug":"armenian","kind":"hero","grade":null,"name":"아름다운 아라","name_en":"Ara the Beautiful","epithet":"세미라미스가 탐낸 왕","domains":["아름다움","충절"],"summary":"아시리아 여왕 세미라미스의 구애를 거절하다 전쟁에서 목숨을 잃은 아르메니아의 전설적인 왕입니다.","description":["모브세스 호레나치의 「아르메니아 역사」에 따르면 아라의 아름다움을 전해 들은 세미라미스는 사신을 보내 결혼을 청했지만 아라는 거절했습니다. 여왕은 군대를 이끌고 쳐들어와 아라를 산 채로 데려오라 했으나, 아라는 싸움터에서 죽고 말았습니다.","세미라미스는 개의 모습을 한 정령 아랄레즈들이 상처를 핥아 그를 되살려 내게 하겠다고 했다고 전합니다. 이 이야기는 죽었다 살아나는 신에 관한 옛 신앙의 흔적으로 풀이되기도 합니다."],"sort_order":4},{"slug":"turul","pantheon_slug":"hungarian","kind":"monster","grade":"spirit","name":"투룰","name_en":"Turul","epithet":"신성한 새","domains":["왕가의 시작","하늘"],"summary":"헝가리 왕가의 시작을 알렸다는 신화 속 맹금으로, 오늘날까지 헝가리의 상징으로 쓰입니다.","description":["연대기에 따르면 투룰은 에메세의 꿈에 나타나 그녀에게서 위대한 왕들이 나올 것을 알렸고, 그 아들 알모시가 아르파드 왕가의 시조가 되었습니다.","매나 송골매 같은 맹금으로 그려지며, 부다 성과 타타바냐 언덕 등 헝가리 곳곳에 투룰 조각이 세워져 있습니다."],"sort_order":1},{"slug":"emese","pantheon_slug":"hungarian","kind":"hero","grade":null,"name":"에메세","name_en":"Emese","epithet":"왕가의 어머니","domains":["어머니","예지몽"],"summary":"투룰 새의 꿈을 꾸고 아르파드 왕가의 시조 알모시를 낳았다는 전설 속 어머니입니다.","description":["에메세는 임신했을 때 투룰 새가 내려와 그녀의 몸에서 강물이 흘러 나가는 꿈을 꾸었고, 이는 위대한 왕들이 그녀에게서 나온다는 뜻으로 풀이되었습니다.","그래서 아들의 이름을 ‘꿈’과 이어지는 말인 알모시라고 지었다고 연대기는 전합니다."],"sort_order":2},{"slug":"weland","pantheon_slug":"anglo-saxon","kind":"hero","grade":null,"name":"웨일랜드","name_en":"Weland","epithet":"대장장이","domains":["대장장이","복수"],"summary":"붙잡혀 다리 힘줄이 잘린 채 일하다가 왕에게 복수하고 날개를 만들어 달아난 전설의 대장장이입니다.","description":["웨일랜드는 북유럽의 뵐룬드와 같은 인물로, 게르만 여러 민족에 이야기가 전합니다.","니두드 왕에게 붙잡혀 섬에 갇힌 채 보물을 만들던 그는 왕의 아들들을 죽이고 딸을 욕보여 복수한 뒤, 손수 만든 날개로 날아 달아났습니다. 8세기의 프랭크스 상자에도 이 장면이 새겨져 있습니다."],"sort_order":1},{"slug":"beowulf","pantheon_slug":"anglo-saxon","kind":"hero","grade":null,"name":"베오울프","name_en":"Beowulf","epithet":"괴물을 물리친 영웅","domains":["영웅","용기"],"summary":"괴물 그렌델과 그 어미, 그리고 늙어서는 용과 싸운 고대 영어 서사시의 영웅입니다.","description":["예아트족의 용사 베오울프는 덴마크 흐로드가르 왕의 궁전을 습격하던 괴물 그렌델을 맨손으로 물리치고, 복수하러 온 그렌델의 어미도 물속 동굴에서 쓰러뜨립니다.","왕이 된 뒤 노년에 보물을 지키는 용과 싸워 이기지만 그 자신도 목숨을 잃습니다. 이 서사시는 1000년 무렵의 필사본 하나로만 전합니다."],"sort_order":2},{"slug":"grendel","pantheon_slug":"anglo-saxon","kind":"monster","grade":"spirit","name":"그렌델","name_en":"Grendel","epithet":"헤오로트를 습격한 늪의 괴물","domains":["어둠","늪","증오"],"summary":"「베오울프」에서 덴마크 흐로드가르 왕의 궁전 헤오로트를 열두 해 동안 밤마다 습격한 괴물입니다.","description":["시는 그를 아우를 죽인 카인의 후손으로, 늪과 황야를 떠도는 존재로 그립니다. 궁전에서 흘러나오는 잔치 소리와 노래에 분노해 밤마다 쳐들어와 잠든 전사들을 잡아먹었습니다.","그의 몸에는 어떤 칼도 들지 않았지만, 베오울프가 맨손으로 붙잡아 어깨째 팔을 뜯어내자 늪의 소굴로 달아나 죽었습니다. 이튿날 밤에는 그 어미가 아들의 원수를 갚으러 궁전을 찾아옵니다."],"sort_order":3},{"slug":"thracian-heros","pantheon_slug":"thracian","kind":"hero","grade":null,"name":"트라키아의 기수","name_en":"Thracian Heros","epithet":"말을 탄 영웅신","domains":["수호","사냥","저승"],"summary":"말을 타고 사냥하는 모습으로 수천 점의 봉헌 부조에 새겨진, 이름이 확실하지 않은 트라키아의 신입니다.","description":["트라키아의 기수는 흔히 망토를 휘날리며 말을 달려 멧돼지 등을 사냥하는 모습으로 새겨집니다. 이름은 확실하지 않아 ‘헤로스(영웅)’라고 부르는 경우가 많습니다.","로마 시대에 특히 많이 만들어졌으며, 무덤과 성소에 봉헌되어 죽은 이와 집을 지키는 수호신으로 여겨졌다고 봅니다."],"sort_order":1},{"slug":"zalmoxis","pantheon_slug":"thracian","kind":"god","grade":null,"name":"잘목시스","name_en":"Zalmoxis","epithet":"게타이족의 신","domains":["불멸","저승"],"summary":"헤로도토스가 전한, 죽은 이를 불멸의 세계로 맞이한다는 트라키아 게타이족의 신입니다.","description":["헤로도토스에 따르면 게타이족은 자신들이 죽지 않고 잘목시스에게 간다고 믿었으며, 5년마다 사자를 뽑아 그에게 보냈습니다.","그리스인들은 잘목시스가 본래 피타고라스의 노예였다가 고향에 가르침을 전한 사람이라는 이야기도 전했는데, 헤로도토스 자신도 이를 의심했습니다."],"sort_order":2},{"slug":"shango","pantheon_slug":"yoruba","kind":"god","grade":null,"name":"샹고","name_en":"Shango","epithet":"천둥과 번개의 오리샤","domains":["천둥","번개","정의","춤"],"summary":"옛 오요 왕국의 왕이었다가 신이 되었다고 전하는, 양날 도끼를 든 천둥의 오리샤입니다.","description":["샹고는 오요 왕국의 네 번째 왕이었다고 전하며, 죽은 뒤 천둥과 번개의 신으로 섬겨졌습니다.","양쪽에 날이 달린 도끼가 그의 상징으로, 샹고를 섬기는 이들은 춤출 때 이 도끼 모양 지팡이 ‘오셰 샹고’를 듭니다."],"sort_order":1},{"slug":"eshu","pantheon_slug":"yoruba","kind":"god","grade":null,"name":"에슈","name_en":"Eshu","epithet":"길과 전언의 오리샤","domains":["길","전언","장난","운명의 갈림길"],"summary":"사람과 신 사이에서 말과 제물을 전하는, 장난스럽고 예측할 수 없는 갈림길의 오리샤입니다.","description":["에슈는 신들에게 바치는 제물과 기도를 전하는 심부름꾼으로, 의식에서 가장 먼저 대접받습니다.","한쪽은 빨갛고 한쪽은 검은 모자를 쓰고 걸어가, 길 양쪽 사람들이 서로 다른 색을 봤다고 다투게 만들었다는 장난 이야기가 유명합니다."],"sort_order":2},{"slug":"orunmila","pantheon_slug":"yoruba","kind":"god","grade":null,"name":"오룬밀라","name_en":"Orunmila","epithet":"지혜와 점술의 오리샤","domains":["지혜","점술","운명"],"summary":"모든 사람의 운명을 알고 있다는 지혜의 오리샤로, 이파 점술의 수호신입니다.","description":["오룬밀라는 사람이 태어나기 전에 고른 운명을 지켜본 증인으로 여겨집니다.","이파 점술사 바발라워는 나무 쟁반 오폰 이파 위에 가루를 뿌리고 표시를 그려, 오룬밀라의 지혜가 담긴 시구를 찾아 풀이합니다."],"sort_order":3},{"slug":"ogun","pantheon_slug":"yoruba","kind":"god","grade":null,"name":"오군","name_en":"Ogun","epithet":"쇠와 대장장이, 길을 여는 신","domains":["쇠","전쟁","사냥","기술"],"summary":"쇠와 대장장이, 사냥과 전쟁의 오리샤로, 처음 땅에 내려온 신들이 빽빽한 숲에 막혔을 때 쇠칼로 길을 열었다고 합니다.","description":["요루바 전승에 따르면 신들이 땅으로 내려왔을 때 앞을 가로막은 숲을 아무도 뚫지 못했지만, 쇠를 다룰 줄 아는 오군이 칼로 길을 냈습니다. 그래서 대장장이와 사냥꾼, 오늘날에는 쇠붙이를 다루는 운전사와 기술자들도 그를 수호신으로 섬깁니다.","이레의 왕이 된 오군이 오랜 싸움 끝에 돌아왔을 때 마침 의식 때문에 침묵하던 사람들이 인사하지 않자, 노해서 많은 이를 베었다가 뒤늦게 뉘우치고 땅속으로 사라졌다는 이야기가 전합니다. 쇠붙이에 대고 맹세하는 관습도 오군에게서 나왔습니다."],"sort_order":4},{"slug":"obatala","pantheon_slug":"yoruba","kind":"god","grade":null,"name":"오바탈라","name_en":"Obatala","epithet":"흰 천의 주인, 사람의 몸을 빚은 신","domains":["창조","순결","지혜"],"summary":"흰 천을 두른 깨끗함과 지혜의 오리샤로, 최고신 올로두마레의 명을 받아 진흙으로 사람의 몸을 빚었다고 합니다.","description":["요루바 전승에 따르면 올로두마레는 오바탈라에게 물로 덮인 세상에 땅을 만들라고 맡겼지만, 그는 가는 길에 야자술에 취해 잠들어 버렸습니다. 그 사이 오두두와가 흙과 닭을 가지고 내려가 일레이페에 땅을 펼쳤다고 하며, 두 신의 역할은 지역마다 달리 전합니다.","오바탈라는 사람의 몸을 빚는 일을 맡았는데, 술에 취한 채 빚은 탓에 몸이 불편한 사람들이 생겨났다고 합니다. 그래서 그는 그런 이들을 지키는 신으로 여겨지고, 그를 섬기는 이들은 야자술을 마시지 않으며 흰옷을 입습니다."],"sort_order":5},{"slug":"oshun","pantheon_slug":"yoruba","kind":"god","grade":null,"name":"오순","name_en":"Oshun","epithet":"단물과 사랑의 강 여신","domains":["강","사랑","출산"],"summary":"나이지리아 오순강의 여신으로, 사랑과 아름다움, 아이를 낳는 일과 단물을 다스리는 오리샤입니다.","description":["이파 시가에 따르면 세상을 만들던 남신들이 오순을 따돌리자 아무 일도 이루어지지 않았고, 신들이 그녀를 다시 받아들인 뒤에야 일이 풀렸다고 합니다. 꿀과 놋쇠 장신구, 노란빛이 그녀를 상징합니다.","오소그보의 오순강 가에 있는 성스러운 숲(오순-오소그보 성림)은 2005년 유네스코 세계유산에 올랐고, 해마다 많은 사람이 모이는 오순 축제가 열립니다. 전승에 따라 샹고의 아내로 나오기도 합니다."],"sort_order":6},{"slug":"yemoja","pantheon_slug":"yoruba","kind":"god","grade":null,"name":"예모자","name_en":"Yemoja","epithet":"물고기 아이들의 어머니","domains":["물","모성","출산"],"summary":"오군강에서 섬기는 물과 어머니의 오리샤로, 대서양을 건너간 아프리카 사람들의 신앙에서는 바다의 여신 예마야·이에만자가 되었습니다.","description":["이름은 요루바어로 '물고기를 자식으로 둔 어머니'라는 뜻으로 풀이합니다. 나이지리아 오군강의 여신으로 섬겨졌으며, 여러 오리샤를 낳은 어머니로 전하고, 아이를 바라는 여인들이 그녀에게 빕니다.","노예무역으로 아메리카에 끌려간 요루바 사람들의 신앙 속에서 그녀는 바다의 여신이 되었습니다. 브라질 바이아의 사우바도르에서는 2월 2일에 사람들이 꽃과 선물을 배에 실어 바다로 보내는 이에만자 축제가 열립니다."],"sort_order":7},{"slug":"nommo","pantheon_slug":"dogon","kind":"other","grade":null,"name":"놈모","name_en":"Nommo","epithet":"물의 정령","domains":["물","질서","가르침"],"summary":"창조신 암마가 처음 만든 물고기 같은 몸의 쌍둥이 정령으로, 사람에게 말과 질서를 전했다고 합니다.","description":["도곤 신화에서 놈모는 창조신 암마의 자식인 쌍둥이 정령으로, 물과 비, 말을 다스립니다.","놈모의 모습은 흔히 두 팔을 든 조각으로 표현된다고 소개되지만, 어떤 조각이 놈모인지는 해석이 갈립니다."],"sort_order":1},{"slug":"amma","pantheon_slug":"dogon","kind":"god","grade":null,"name":"암마","name_en":"Amma","epithet":"창조신","domains":["창조","하늘"],"summary":"우주의 알 속에서 세상을 계획하고 만들었다는 도곤족의 최고신입니다.","description":["암마는 세상을 만들기 전 모든 것을 씨앗처럼 담은 우주의 알을 품었고, 그 속에서 놈모가 태어났다고 전합니다.","도곤 사람들은 마을의 제단에서 암마에게 비와 풍년을 빌었습니다."],"sort_order":2},{"slug":"gu","pantheon_slug":"fon","kind":"god","grade":null,"name":"구","name_en":"Gu","epithet":"쇠와 전쟁의 신","domains":["쇠","대장장이","전쟁"],"summary":"사람에게 쇠를 다루는 기술을 주고 숲을 개간하게 한, 폰족의 쇠와 전쟁의 신입니다.","description":["구는 창조신 마우-리사의 자식으로, 세상을 사람이 살 만하게 다듬는 도구이자 무기였다고 전합니다.","19세기 다호메의 대장장이 아카티 에클레켄도가 고철로 만든 구의 신상은, 지금 파리 루브르 박물관에 전시되어 있습니다."],"sort_order":1},{"slug":"mawu-lisa","pantheon_slug":"fon","kind":"god","grade":null,"name":"마우-리사","name_en":"Mawu-Lisa","epithet":"달과 해의 창조신","domains":["창조","달","해"],"summary":"달의 여신 마우와 해의 신 리사가 한 몸을 이룬, 폰족의 창조신입니다.","description":["마우는 서쪽에서 밤과 서늘함, 지혜를 맡고, 리사는 동쪽에서 낮과 힘을 맡는다고 합니다.","둘이 함께 세상을 만들고, 그 자식들인 여러 보둔이 하늘, 바다, 땅을 나눠 다스린다고 전합니다."],"sort_order":2},{"slug":"inti","pantheon_slug":"inca","kind":"god","grade":null,"name":"인티","name_en":"Inti","epithet":"태양신","domains":["태양","왕권","농사"],"summary":"잉카 왕가의 조상으로 여겨진 태양신으로, 쿠스코의 황금 신전 코리칸차에서 섬겼습니다.","description":["잉카의 왕은 인티의 아들로 여겨졌고, 인티는 사람 얼굴을 한 황금 해 원반으로 표현되었습니다.","해마다 동지 무렵 열린 태양 축제 인티 라이미는 지금도 쿠스코에서 재현됩니다."],"sort_order":1},{"slug":"viracocha","pantheon_slug":"inca","kind":"god","grade":null,"name":"비라코차","name_en":"Viracocha","epithet":"창조신","domains":["창조","바다","문명"],"summary":"티티카카호에서 나타나 해와 달, 사람을 만들고 바다 너머로 떠났다는 안데스의 창조신입니다.","description":["비라코차는 티티카카호에서 나와 해와 달, 별을 만들고, 돌로 사람을 빚은 뒤 각지로 보냈다고 전합니다.","일을 마친 뒤에는 바다 위를 걸어 서쪽으로 떠났다고 합니다. 잉카 이전 티와나쿠 문명의 ‘태양의 문’에 새겨진 지팡이 든 신을 비라코차로 보기도 합니다."],"sort_order":2},{"slug":"pachamama","pantheon_slug":"inca","kind":"god","grade":null,"name":"파차마마","name_en":"Pachamama","epithet":"대지의 어머니","domains":["대지","풍요","농사"],"summary":"곡식을 키우고 산과 땅을 품은 안데스의 대지 여신으로, 오늘날에도 제물을 바쳐 섬깁니다.","description":["파차마마는 ‘세계의 어머니’ 또는 ‘대지의 어머니’라는 뜻으로, 씨 뿌리기와 수확을 돌본다고 여겨집니다.","에스파냐 정복 뒤에는 성모 마리아와 겹쳐졌고, 포토시의 은광 산 세로 리코를 성모의 몸으로 그린 식민지 시대 그림이 그 예입니다. 안데스 사람들은 지금도 8월에 파차마마에게 제물을 바칩니다."],"sort_order":3},{"slug":"manco-capac","pantheon_slug":"inca","kind":"hero","grade":null,"name":"망코 카팍","name_en":"Manco Cápac","epithet":"쿠스코를 세운 첫 잉카","domains":["건국","농사"],"summary":"해의 신 인티의 아들로 티티카카호에서 나와, 황금 지팡이가 땅속으로 들어가는 곳을 찾아 쿠스코를 세웠다는 잉카의 첫 임금입니다.","description":["잉카 가르실라소 데 라 베가의 「잉카 왕실사」(1609)에 따르면 해는 아들 망코 카팍과 딸 마마 오클료를 티티카카호로 내려보내며 황금 지팡이를 주었습니다. 두 사람은 지팡이가 단번에 땅속으로 들어가는 곳을 찾아 북쪽으로 걸었고, 우아나카우리 언덕 아래 골짜기에 쿠스코를 세운 뒤 남자들에게 농사를 가르쳤습니다.","다른 기록에서는 아야르 형제 넷과 누이 넷이 파카리탐보의 동굴에서 나왔고, 형제들이 동굴에 갇히거나 돌로 변한 끝에 아야르 망코가 쿠스코에 이르러 망코 카팍이 되었다고 합니다."],"sort_order":4},{"slug":"mama-ocllo","pantheon_slug":"inca","kind":"hero","grade":null,"name":"마마 오클료","name_en":"Mama Ocllo","epithet":"베 짜기를 가르친 첫 왕비","domains":["베 짜기","건국"],"summary":"망코 카팍의 누이이자 아내로, 함께 쿠스코를 세우고 여인들에게 실 잣기와 베 짜기를 가르쳤다는 잉카의 첫 왕비입니다.","description":["「잉카 왕실사」에서 마마 오클료는 해와 달의 딸로, 오빠 망코 카팍과 함께 티티카카호에서 나와 쿠스코를 세웠습니다. 망코 카팍이 남자들에게 농사를 가르치는 동안 그녀는 여자들에게 실을 잣고 천을 짜서 옷을 짓는 법을 가르쳤습니다.","잉카 사람들은 그녀를 왕비 '코야'의 시조로 받들었습니다. 식민지 시대 쿠스코의 화가들은 잉카 왕과 왕비의 초상 연작을 그리며 그녀를 첫 코야로 즐겨 그렸습니다."],"sort_order":5},{"slug":"mama-quilla","pantheon_slug":"inca","kind":"god","grade":null,"name":"마마 킬랴","name_en":"Mama Quilla","epithet":"은빛 달의 어머니","domains":["달","혼인","달력"],"summary":"해의 신 인티의 아내이자 누이인 달의 여신으로, 혼인과 여인들을 지키고 의식의 날을 정하는 달력을 다스렸습니다.","description":["잉카 사람들은 은을 달의 눈물로 여겼고, 쿠스코의 코리칸차 신전에는 은으로 꾸민 마마 킬랴의 방이 있었다고 합니다. 달이 차고 기우는 것으로 달을 셈했기 때문에 의식과 잔치의 날도 그녀가 정한다고 여겼습니다.","월식이 일어나면 달이 병들거나 짐승에게 공격당한다고 여겨, 사람들은 소리를 지르고 무기를 휘두르며 개를 때려 짖게 해 달을 깨우려 했다고 연대기 작가들은 전합니다."],"sort_order":6},{"slug":"illapa","pantheon_slug":"inca","kind":"god","grade":null,"name":"이야파","name_en":"Illapa","epithet":"무릿매로 천둥을 울리는 날씨의 신","domains":["천둥","번개","비"],"summary":"번개와 천둥, 비를 다스린 잉카의 신으로, 무릿매를 돌려 천둥을 치고 하늘 강의 물을 쏟아 비를 내린다고 여겼습니다.","description":["잉카 사람들은 번쩍이는 옷을 입은 이야파가 무릿매를 돌리면 그 소리가 천둥이 되고 무릿매의 번쩍임이 번개가 된다고 여겼습니다. 하늘의 강인 은하수에서 물을 길어 누이가 든 항아리에 담아 두었다가, 그 항아리를 깨뜨려 비를 내린다는 이야기도 전합니다.","비에 농사를 기대야 했던 안데스에서 매우 중요한 신이라 가뭄이 들면 그에게 제물을 바쳤습니다. 번개를 맞고 살아남은 사람은 그에게 뽑힌 이로 여겨 사제가 되기도 했습니다."],"sort_order":7},{"slug":"pachacamac","pantheon_slug":"inca","kind":"god","grade":null,"name":"파차카막","name_en":"Pachacamac","epithet":"땅을 흔드는 해안의 창조신","domains":["창조","지진","신탁"],"summary":"페루 중부 해안에서 잉카 이전부터 섬긴 창조의 신으로, 리마 남쪽의 큰 성소는 안데스 곳곳에서 신탁을 들으러 오는 순례지였습니다.","description":["이름은 케추아어로 '세상을 움직이는 이' 또는 '세상을 만든 이'로 풀이하며, 화가 나면 땅을 흔든다고 여겼습니다. 잉카는 이 지역을 다스리게 되자 파차카막의 성소를 그대로 두고 그 곁에 해의 신전을 세워 함께 섬겼습니다.","17세기 에스파냐 수도사가 적은 해안의 전승에서 그는 첫 사람들을 만들었으나 먹을 것이 없어 굶주리자 한 아이의 몸에서 옥수수와 열매가 돋게 했다고 합니다. 1533년 에르난도 피사로가 이 성소에 들어와 신상을 부수고 보물을 가져갔습니다."],"sort_order":8},{"slug":"raven","pantheon_slug":"haida","kind":"god","grade":null,"name":"까마귀","name_en":"Raven","epithet":"장난꾸러기 창조자","domains":["창조","장난","변신"],"summary":"조개껍데기 속 첫 사람들을 꾀어내고, 상자에 갇힌 해와 달을 훔쳐 세상에 빛을 가져온 까마귀입니다.","description":["하이다 이야기에서 까마귀는 욕심 많고 장난스럽지만, 그 행동 덕분에 세상이 지금 모습이 되었습니다.","하늘의 추장이 상자에 감춰 둔 해와 달, 별을 꾀로 훔쳐 하늘에 걸었고, 바닷가 조개껍데기 속에 숨어 있던 첫 사람들을 불러냈다고 전합니다."],"sort_order":1},{"slug":"were-jaguar","pantheon_slug":"olmec","kind":"monster","grade":"spirit","name":"재규어 인간","name_en":"Olmec Were-Jaguar","epithet":"재규어와 사람이 섞인 존재","domains":["비","풍요","권력"],"summary":"찡그린 입과 송곳니를 가진 아기 같은 얼굴로 새겨진, 올멕 유물의 사람과 재규어가 섞인 존재입니다.","description":["올멕 조각에는 아래로 처진 입과 송곳니, 갈라진 머리를 가진 아기 같은 얼굴이 자주 보이며, 이를 ‘재규어 인간’이라 부릅니다.","비와 풍요, 지배자의 권력과 관련된 존재로 보지만, 이름과 이야기는 전하지 않습니다."],"sort_order":1},{"slug":"cocijo","pantheon_slug":"zapotec","kind":"god","grade":null,"name":"코시호","name_en":"Cocijo","epithet":"비와 번개의 신","domains":["비","번개","농사"],"summary":"갈라진 혀와 화려한 머리 장식으로 표현된 사포텍의 비와 번개의 신입니다.","description":["코시호는 비와 번개를 내려 옥수수 농사를 돌본다고 여겨졌으며, 아즈텍의 틀랄록, 마야의 차크와 비슷한 신입니다.","사포텍 사람들은 코시호의 얼굴을 새긴 토기 단지를 무덤과 제단에 바쳤습니다."],"sort_order":1},{"slug":"eight-deer","pantheon_slug":"mixtec","kind":"hero","grade":null,"name":"8 사슴 재규어 발톱","name_en":"Eight Deer Jaguar Claw","epithet":"전설적인 정복 왕","domains":["왕권","정복"],"summary":"11세기 무렵 믹스텍의 여러 왕국을 하나로 묶었다고 그림 문서가 전하는 전설적인 왕입니다.","description":["믹스텍 사람들은 태어난 날의 이름으로 사람을 불렀는데, ‘8 사슴’은 그의 날 이름이고 ‘재규어 발톱’은 별명입니다.","「주슈-너톨 코덱스」 뒷면에는 그가 전쟁과 동맹으로 세력을 넓히고, 결국 처형되기까지의 일생이 그림으로 그려져 있습니다."],"sort_order":1},{"slug":"maui","pantheon_slug":"polynesian","kind":"hero","grade":null,"name":"마우이","name_en":"Māui","epithet":"꾀 많은 반신","domains":["모험","꾀","불"],"summary":"낚싯바늘로 바다에서 섬을 낚아 올리고, 밧줄로 해를 붙잡아 느리게 가게 했다는 폴리네시아의 반신입니다.","description":["마우이는 마법의 낚싯바늘로 바다 밑에서 섬들을 끌어 올렸다고 전하는데, 뉴질랜드 북섬은 그가 낚은 물고기라는 이야기가 있습니다.","해가 너무 빨리 지나가 하루가 짧자, 밧줄로 해를 붙잡아 천천히 가겠다는 약속을 받아 냈습니다. 사람에게 불을 가져다준 이야기도 전합니다."],"sort_order":1},{"slug":"tangaroa","pantheon_slug":"polynesian","kind":"god","grade":null,"name":"탕가로아","name_en":"Tangaroa","epithet":"바다의 신","domains":["바다","물고기","창조"],"summary":"바다와 물고기를 다스리는 신으로, 섬에 따라 세상을 만든 창조신으로도 섬겨졌습니다.","description":["뉴질랜드 마오리에게 탕가로아는 하늘과 땅의 자식이자 바다와 물고기의 신이며, 타히티 등에서는 탕가로아(타아로아)를 세상을 만든 창조신으로 여겼습니다.","오스트랄 제도 루루투에서 나온 나무 신상 ‘아아’는 온몸에 작은 신들이 붙어 나오는 모습으로, 신들의 창조를 나타낸다고 풀이됩니다."],"sort_order":2},{"slug":"ku","pantheon_slug":"polynesian","kind":"god","grade":null,"name":"쿠","name_en":"Kū","epithet":"전쟁의 신","domains":["전쟁","정치","수호"],"summary":"하와이의 네 주신 가운데 하나로, 깃털로 만든 무서운 얼굴의 신상으로 섬긴 전쟁의 신입니다.","description":["하와이에서 쿠는 카네, 로노, 카날로아와 함께 네 주신을 이루며, 전쟁과 정치를 맡았습니다.","카메하메하 1세는 전쟁의 신 쿠카일리모쿠를 섬기며 하와이 섬들을 통일했다고 전합니다. 붉고 노란 깃털로 덮인 쿠의 신상은 커다란 입에 개의 이빨이 박혀 있습니다."],"sort_order":3},{"slug":"hina","pantheon_slug":"polynesian","kind":"god","grade":null,"name":"히나","name_en":"Hina","epithet":"달에 사는 여신","domains":["달","여성","나무껍질 천"],"summary":"폴리네시아 곳곳에서 여러 모습으로 전하는 여신으로, 흔히 달과 여성의 일을 맡으며 마우이의 어머니나 누이, 아내로 등장합니다.","description":["하와이에서는 마우이의 어머니로, 나무껍질 천을 두드리는 일에 지쳐 달로 올라가 지금도 그곳에서 천을 두드린다고 합니다. 마오리 전승에서는 마우이의 누이로 나오는데, 마우이가 남편을 개로 만들어 버리자 슬픔에 바다로 몸을 던졌다고도 합니다.","타히티 전승에서 히나는 땅의 신 파투에게 죽은 사람을 다시 살려 달라고 청했다가 거절당하자, 그렇다면 자신은 달을 다시 살아나게 하겠다고 말했습니다. 그래서 달은 이지러졌다가 다시 차오르지만 사람은 죽으면 돌아오지 못한다고 하며, 이 이야기는 폴 고갱의 그림 「히나 테파투」의 소재가 되었습니다."],"sort_order":4},{"slug":"tane","pantheon_slug":"polynesian","kind":"god","grade":null,"name":"타네","name_en":"Tāne","epithet":"하늘과 땅을 떼어 놓은 숲의 신","domains":["숲","새","사람의 창조"],"summary":"하늘 아버지 랑기누이와 땅 어머니 파파투아누쿠를 떼어 놓아 세상에 빛을 들인 마오리의 숲과 새의 신으로, 첫 여인을 흙으로 빚었다고 합니다.","description":["마오리 전승에서 하늘과 땅은 처음에 꼭 껴안고 있어 그 사이에서 태어난 자식들은 어둠 속에서 살았습니다. 형제들이 차례로 실패한 끝에 타네가 땅에 등을 대고 두 발로 하늘을 밀어 올려 부모를 떼어 놓았고, 그제야 세상에 빛이 들었습니다.","타네는 쿠라와카의 붉은 흙으로 첫 여인 히네아후오네를 빚어 숨을 불어넣었고, 하늘에서 지식이 담긴 바구니 세 개를 가져왔다고도 합니다. 숲의 나무와 새는 모두 그의 자손으로 여겨, 뉴질랜드에서 가장 큰 카우리나무에도 '타네 마후타'라는 이름이 붙었습니다."],"sort_order":5},{"slug":"rangi-and-papa","pantheon_slug":"polynesian","kind":"god","grade":null,"name":"랑기와 파파","name_en":"Rangi and Papa","epithet":"서로 껴안은 하늘과 땅","domains":["하늘","땅","창조"],"summary":"하늘 아버지 랑기누이와 땅 어머니 파파투아누쿠로, 꼭 껴안은 채 여러 신을 낳았다가 아들 타네에게 떼어진 마오리 신화의 첫 부부입니다.","description":["부모 사이의 좁은 어둠에 갇혀 지내던 자식 신들은 의논 끝에 부모를 떼어 놓기로 했고, 전쟁의 신 투마타우엥가는 아예 죽이자고까지 했습니다. 바람의 신 타휘리마테아만이 반대하며 하늘 아버지 편에 섰고, 부모가 떼어진 뒤에는 형제들에게 폭풍으로 앙갚음했습니다.","떨어진 뒤에도 랑기누이는 아내를 그리워해 눈물을 흘리는데 그것이 비와 이슬이 되었고, 파파투아누쿠의 한숨은 땅에서 피어오르는 안개가 되었다고 합니다. 이 이야기는 19세기 조지 그레이 등이 엮은 마오리 전승 기록에 남았습니다."],"sort_order":6},{"slug":"pele","pantheon_slug":"polynesian","kind":"god","grade":null,"name":"펠레","name_en":"Pele","epithet":"킬라우에아 화산의 불의 여신","domains":["화산","불","땅의 창조"],"summary":"하와이 킬라우에아 화산의 할레마우마우 분화구에 산다는 불과 화산의 여신으로, 지금도 하와이 사람들이 깊이 받드는 신입니다.","description":["하와이 전승에 따르면 펠레는 먼 고향 카히키에서 카누를 타고 와, 바다의 여신인 언니 나마카오카하이의 노여움을 피해 섬을 옮겨 다니며 불을 지필 구덩이를 팠습니다. 북서쪽 섬에서 남동쪽 섬으로 옮겨 가며 판 구덩이마다 언니의 물이 덮쳐, 끝내 하와이섬 킬라우에아에 자리를 잡았다고 합니다. 이 순서는 섬들이 생겨난 지질학적 순서와도 닮았습니다.","막내 여동생 히이아카가 펠레의 연인 로히아우를 데려오는 긴 여정을 노래한 이야기가 유명합니다. 화산에서 바람에 날려 실처럼 굳은 유리는 '펠레의 머리카락', 물방울처럼 굳은 것은 '펠레의 눈물'이라고 부릅니다."],"sort_order":7},{"slug":"makemake","pantheon_slug":"rapa-nui","kind":"god","grade":null,"name":"마케마케","name_en":"Makemake","epithet":"창조신","domains":["창조","풍요","새"],"summary":"새의 머리를 한 사람의 모습으로 바위에 새겨진, 라파누이의 창조신입니다.","description":["마케마케는 세상과 사람을 만들었다고 전하는 라파누이의 주신으로, 새와 깊은 관련이 있습니다.","오롱고 바위 마을 곳곳에는 새 머리를 한 사람의 모습이 새겨져 있으며, 새 사람 의식도 마케마케를 섬기는 의례였습니다."],"sort_order":1},{"slug":"moai","pantheon_slug":"rapa-nui","kind":"other","grade":null,"name":"모아이","name_en":"Moai","epithet":"신이 된 조상","domains":["조상","수호"],"summary":"섬을 바라보며 마을을 지키도록 세운, 신격화된 조상의 거대한 석상입니다.","description":["모아이는 라파누이 사람들이 화산암을 깎아 만든 석상으로, 신이 된 조상의 힘(마나)을 담아 마을을 지킨다고 여겼습니다.","대부분 바다를 등지고 섬 안쪽 마을을 바라보도록 세웠습니다. 아후 통가리키에는 열다섯 개의 모아이가 나란히 서 있습니다."],"sort_order":2},{"slug":"kimun-kamuy","pantheon_slug":"ainu","kind":"god","grade":null,"name":"키무은 카무이","name_en":"Kimun Kamuy","epithet":"산의 신 (곰)","domains":["산","사냥","선물"],"summary":"곰의 모습으로 사람 세상을 찾아와 고기와 털가죽을 선물한다는 아이누의 산의 신입니다.","description":["아이누 사람들은 곰을 산의 신이 사람 세상에 올 때 입는 옷이라 여겼습니다.","아기 곰을 마을에서 정성껏 기른 뒤 의식을 치러 신의 나라로 돌려보내는 ‘이오만테(곰 보내기)’에서는, 곰의 영혼이 선물을 안고 돌아가 다시 찾아오도록 빌었습니다."],"sort_order":1},{"slug":"gesar","pantheon_slug":"tibetan","kind":"hero","grade":null,"name":"게사르 왕","name_en":"King Gesar","epithet":"링 왕국의 영웅 왕","domains":["영웅","정의","악귀 퇴치"],"summary":"하늘에서 내려와 악한 왕과 마귀들을 물리친, 티베트 서사시 속 링 왕국의 왕입니다.","description":["게사르는 하늘 신의 아들로 사람 세상에 태어나, 어린 시절의 시련을 이기고 경마에서 이겨 링 왕국의 왕이 되었다고 전합니다.","사방의 악한 왕들을 물리치는 그의 이야기는 수많은 판본으로 전하며, 이야기꾼이 꿈에서 이야기를 받아 노래한다고 합니다."],"sort_order":1},{"slug":"palden-lhamo","pantheon_slug":"tibetan","kind":"god","grade":null,"name":"팔덴 라모","name_en":"Palden Lhamo","epithet":"티베트의 수호 여신","domains":["수호","분노","정의"],"summary":"노새를 타고 피의 바다를 건너는 무서운 모습의, 티베트와 달라이 라마의 수호 여신입니다.","description":["팔덴 라모는 불교를 지키는 분노의 수호신으로, 검푸른 몸에 노새를 타고 피의 바다를 건너는 모습으로 그려집니다.","라싸와 달라이 라마의 수호신으로 섬겨지며, 티베트 사람들은 그녀가 나라를 지킨다고 믿었습니다."],"sort_order":2},{"slug":"thanh-giong","pantheon_slug":"vietnamese","kind":"hero","grade":null,"name":"타인지옹","name_en":"Thánh Gióng","epithet":"하늘로 올라간 소년 영웅","domains":["영웅","나라 지키기"],"summary":"세 살까지 말도 못 하다가 외적이 쳐들어오자 거인이 되어 쇠 말을 타고 싸운 베트남의 영웅입니다.","description":["지옹은 세 살이 되도록 말하지도 걷지도 못했지만, 은나라 군대가 쳐들어오자 처음 입을 열어 쇠 말과 쇠 채찍, 쇠 갑옷을 달라고 했습니다.","순식간에 거인으로 자란 그는 쇠 말을 타고 적을 물리쳤고, 채찍이 부러지자 대나무를 뽑아 싸운 뒤 산꼭대기에서 하늘로 올라갔다고 전합니다."],"sort_order":1},{"slug":"lac-long-quan","pantheon_slug":"vietnamese","kind":"hero","grade":null,"name":"락롱꾸언","name_en":"Lạc Long Quân","epithet":"용의 군주","domains":["건국","바다","조상"],"summary":"산의 선녀 어우꺼와 혼인해 백 개의 알에서 백 명의 아들을 얻었다는 베트남 사람들의 조상입니다.","description":["바다의 용족인 락롱꾸언은 산의 선녀 어우꺼와 혼인했고, 어우꺼는 알 백 개가 든 주머니를 낳아 백 명의 아들이 태어났습니다.","둘은 사는 곳이 달라 헤어지며 아들 쉰은 아버지를 따라 바다로, 쉰은 어머니를 따라 산으로 갔고, 산으로 간 맏아들이 첫 왕조 홍방의 훙왕이 되었다고 전합니다."],"sort_order":2},{"slug":"an-duong-vuong","pantheon_slug":"vietnamese","kind":"hero","grade":null,"name":"안즈엉 왕","name_en":"An Dương Vương","epithet":"신기 쇠뇌로 어울락을 지킨 왕","domains":["건국","전쟁"],"summary":"기원전 3세기 어울락을 세우고 꼬로아 성을 쌓은 왕으로, 금거북이 준 발톱으로 만든 쇠뇌를 잃어 나라를 잃었다는 전설의 주인공입니다.","description":["15세기 말에 엮은 「영남척괴」에 따르면 안즈엉 왕이 꼬로아에 성을 쌓을 때마다 무너졌는데, 강의 사자인 금거북 낌꾸이가 나타나 도와 성이 완성되었습니다. 떠나는 금거북은 발톱 하나를 남겼고, 왕은 이것을 쇠뇌의 방아쇠로 삼아 한 번에 수많은 적을 쓰러뜨렸습니다.","남월의 조타는 쇠뇌를 당해 내지 못하자 아들 쫑투이를 왕의 딸 미쩌우와 혼인시켰고, 쫑투이는 몰래 발톱을 바꿔치기해 돌아갔습니다. 다시 쳐들어온 적을 막지 못한 왕은 금거북의 말로 딸이 적을 이끌었다는 것을 알고 미쩌우를 벤 뒤 바다로 걸어 들어갔다고 합니다."],"sort_order":3},{"slug":"kim-quy","pantheon_slug":"vietnamese","kind":"monster","grade":"spirit","name":"금거북 낌꾸이","name_en":"Kim Quy","epithet":"나라를 돕는 황금 거북","domains":["수호","물"],"summary":"베트남 전설에서 나라가 위태로울 때 나타나 임금을 돕는 황금 거북으로, 안즈엉 왕에게 발톱을 주고 레러이 왕에게서는 신검을 돌려받았다고 합니다.","description":["「영남척괴」에서 낌꾸이는 강의 사자로 나타나 안즈엉 왕이 꼬로아 성을 쌓도록 돕고, 쇠뇌에 쓸 발톱을 남겼습니다. 나라를 잃고 쫓기던 왕에게 '등 뒤에 탄 이가 적'이라고 일러 준 것도 금거북이었습니다.","15세기 레러이 왕의 전설에서는 명나라 군대를 몰아낸 왕이 탕롱의 호수에서 배를 타고 있을 때 금거북이 떠올라, 하늘이 빌려준 칼을 돌려 달라고 하여 칼을 물고 물속으로 사라졌습니다. 그 호수가 '칼을 돌려준 호수'라는 뜻의 하노이 호안끼엠 호수입니다."],"sort_order":4},{"slug":"thotsakan","pantheon_slug":"thai","kind":"monster","grade":"spirit","name":"톳사깐","name_en":"Thotsakan","epithet":"열 머리의 마왕","domains":["마귀","욕망"],"summary":"「라마끼안」에서 프라 람의 아내 시다를 납치한 열 머리의 마왕으로, 「라마야나」의 라바나입니다.","description":["톳사깐은 랑카의 왕으로, 프라 람(라마)의 아내 시다를 납치해 큰 전쟁을 일으킵니다.","방콕 왕궁의 수호 거인상과 가면극 콘에서도 자주 볼 수 있는, 타이에서 가장 유명한 악역입니다."],"sort_order":1},{"slug":"mae-phosop","pantheon_slug":"thai","kind":"god","grade":null,"name":"매포솝","name_en":"Mae Phosop","epithet":"벼의 여신","domains":["벼","풍요"],"summary":"벼의 영혼으로 여겨진 타이의 여신으로, 농부들이 모내기와 수확 때 정성껏 모셨습니다.","description":["매포솝은 벼 자체에 깃든 영혼으로, 소홀히 대하면 떠나 버려 흉년이 든다고 믿었습니다.","농부들은 벼가 이삭을 밸 때 임신한 여인을 대하듯 과일과 화장품을 바치며 그녀를 위로했습니다."],"sort_order":2},{"slug":"mahagiri","pantheon_slug":"burmese","kind":"god","grade":null,"name":"마하기리","name_en":"Mahagiri","epithet":"집의 수호 낫","domains":["집","가정의 수호"],"summary":"불에 타 죽은 대장장이가 신이 되었다는, 미얀마 집집마다 모시는 집의 수호 낫입니다.","description":["대장장이 응아띤데는 힘이 너무 세서 왕의 의심을 사 불에 타 죽었고, 그 영혼이 누이와 함께 낫이 되었다고 전합니다.","포파산에 모셔졌으며, 집 안 기둥에 코코넛을 매달아 마하기리를 섬기는 풍습이 이어집니다."],"sort_order":1},{"slug":"thagyamin","pantheon_slug":"burmese","kind":"god","grade":null,"name":"따자민","name_en":"Thagyamin","epithet":"낫들의 왕","domains":["하늘","수호","불교"],"summary":"불교의 제석천(인드라)이 미얀마의 신령 신앙에 들어와 37 낫의 우두머리가 된 신입니다.","description":["따자민은 인도의 인드라, 불교의 제석천과 같은 신으로, 미얀마에서는 낫들의 왕으로 섬깁니다.","미얀마의 새해 축제 띤잔은 따자민이 하늘에서 내려와 머무는 기간이라 여깁니다."],"sort_order":2},{"slug":"barong","pantheon_slug":"indonesian","kind":"monster","grade":"spirit","name":"바롱","name_en":"Barong","epithet":"선한 수호자","domains":["수호","선"],"summary":"사자와 개를 닮은 거대한 가면과 옷으로 표현되는, 발리 마을을 지키는 선의 수호자입니다.","description":["바롱은 두 사람이 들어가 움직이는 거대한 짐승 모습으로 표현되며, 마을을 병과 악에서 지킨다고 여깁니다.","춤극에서 바롱은 마녀 랑다와 싸우는데, 둘의 싸움은 어느 한쪽이 이기지 않고 균형을 이루며 끝납니다."],"sort_order":1},{"slug":"rangda","pantheon_slug":"indonesian","kind":"monster","grade":"spirit","name":"랑다","name_en":"Rangda","epithet":"마녀의 여왕","domains":["악","주술","죽음"],"summary":"긴 흰 머리와 혀, 송곳니를 가진 발리의 마녀 여왕으로, 바롱의 영원한 맞수입니다.","description":["랑다는 ‘과부’라는 뜻으로, 11세기 발리 왕의 어머니가 저주를 내린 이야기에서 비롯했다고 전합니다.","무서운 얼굴의 가면으로 표현되지만, 신전에서는 보호의 힘을 가진 존재로 모셔지기도 합니다."],"sort_order":2},{"slug":"dewi-sri","pantheon_slug":"indonesian","kind":"god","grade":null,"name":"데위 스리","name_en":"Dewi Sri","epithet":"벼의 여신","domains":["벼","풍요","생명"],"summary":"죽은 몸에서 벼와 여러 작물이 자라났다고 전하는 자와와 발리의 벼의 여신입니다.","description":["자와의 이야기에 따르면 데위 스리는 신들의 세계에서 죽었고, 그 몸을 묻은 자리에서 벼와 코코넛, 여러 작물이 자라났다고 합니다.","농부들은 논에 그녀의 작은 사당을 세우고, 집 안 곳간에 데위 스리를 모셔 풍년을 빌었습니다."],"sort_order":3},{"slug":"semar","pantheon_slug":"indonesian","kind":"god","grade":null,"name":"스마르","name_en":"Semar","epithet":"광대 하인으로 내려온 신","domains":["지혜","웃음","보살핌"],"summary":"자와섬 와양 그림자극에서 영웅들을 모시는 뚱뚱한 광대 하인이지만, 실은 신 상향 이스마야가 사람 모습으로 내려온 존재로 여겨지는 인물입니다.","description":["스마르는 판다와 형제 같은 영웅들 곁을 따르며 웃음을 주는 광대 무리 푸나카완의 우두머리로, 아들 가렝, 프트룩, 바공과 함께 무대에 오릅니다. 둥근 몸에 웃는 입과 눈물 고인 눈을 함께 지녀 기쁨과 슬픔을 한 얼굴에 담았다고 합니다.","인도의 「마하바라타」에는 없는 자와 고유의 인물로, 신들의 왕 바타라 구루의 형이라고 전합니다. 영웅들이 길을 잃으면 바른 길을 일러 주고 때로는 신들까지 꾸짖어, 자와의 수호령으로 받들어지기도 합니다."],"sort_order":4},{"slug":"gatotkaca","pantheon_slug":"indonesian","kind":"hero","grade":null,"name":"가토트카차","name_en":"Gatotkaca","epithet":"하늘을 나는 쇠뼈의 용사","domains":["용맹","하늘을 나는 힘"],"summary":"자와 와양 그림자극에서 사랑받는 영웅으로, 비마의 아들이며 '쇠줄 같은 힘줄과 쇠 같은 뼈'를 지니고 하늘을 날아다닙니다.","description":["「마하바라타」에서 비마와 락샤사 여인 히딤비 사이에 태어난 가토트카차가 자와에서 새롭게 그려진 인물입니다. 와양에서는 아기 때 탯줄이 어떤 칼로도 잘리지 않아 신들의 창 콘타의 칼집으로 자르자 그 칼집이 배꼽 속으로 들어갔고, 신들이 그를 불타는 찬드라디무카 분화구에 넣어 단련하자 쇠 같은 몸과 하늘을 나는 힘을 얻었다고 합니다.","큰 전쟁 바라타유다에서 카우라바 군을 휩쓸던 그는 카르나가 던진 창 콘타에 맞아 쓰러졌는데, 창이 제 칼집이 있는 배꼽으로 돌아갔기 때문이라고 합니다. 인도네시아에서는 나라를 지키는 영웅으로 여겨 그 이름을 비행기와 동상에도 붙였습니다."],"sort_order":5},{"slug":"hwanin","pantheon_slug":"korean","kind":"god","grade":null,"name":"환인","name_en":"Hwanin","epithet":"하늘의 임금","domains":["하늘","주재"],"summary":"「삼국유사」 단군 이야기에서 아들 환웅을 사람 세상에 내려보낸 하늘의 임금입니다.","description":["「삼국유사」는 환인을 하늘의 임금으로 적고, 그 아래 ‘제석을 이른다’는 주를 달았습니다. 불교의 제석천(인드라)과 같은 신으로 본 것입니다.","환인은 아들 환웅이 사람 세상에 뜻을 두자 세상을 내려다보고, 사람을 널리 이롭게 할 만하다며 천부인 세 개를 주어 내려보냈다고 전합니다. 이 밖에 환인만의 이야기는 거의 전하지 않습니다."],"sort_order":5},{"slug":"hwanung","pantheon_slug":"korean","kind":"god","grade":null,"name":"환웅","name_en":"Hwanung","epithet":"신시를 연 하늘의 아들","domains":["하늘","다스림","농사"],"summary":"무리 3천을 이끌고 태백산 신단수 아래로 내려와 신시를 열고, 사람 세상의 360여 가지 일을 맡았다는 하늘의 아들입니다.","description":["환웅은 바람의 신 풍백, 비의 신 우사, 구름의 신 운사를 거느리고 곡식, 목숨, 병, 형벌, 선악 같은 사람 세상의 일을 다스렸다고 「삼국유사」는 전합니다.","사람이 되기를 바라는 곰과 범에게 쑥 한 줌과 마늘 스무 개를 주며 백 일 동안 햇빛을 보지 말라고 했고, 금기를 지켜 여인이 된 웅녀와 혼인해 단군왕검을 낳았습니다."],"sort_order":6},{"slug":"ungnyeo","pantheon_slug":"korean","kind":"hero","grade":null,"name":"웅녀","name_en":"Ungnyeo","epithet":"곰에서 사람이 된 여인","domains":["인내","출산","조상"],"summary":"쑥과 마늘을 먹으며 굴속에서 견뎌 사람이 되고, 환웅과 혼인해 단군을 낳은 여인입니다.","description":["곰과 범은 함께 굴에 살며 사람이 되기를 빌었습니다. 범은 금기를 지키지 못했지만, 곰은 스무하루 만에 여인이 되었다고 「삼국유사」는 전합니다.","혼인할 사람이 없던 웅녀가 신단수 아래에서 아이를 갖게 해 달라고 빌자, 환웅이 잠시 사람으로 변해 혼인했고 웅녀는 단군왕검을 낳았습니다. 곰을 조상으로 섬긴 집단의 기억으로 보는 해석이 있습니다."],"sort_order":7},{"slug":"haemosu","pantheon_slug":"korean","kind":"god","grade":null,"name":"해모수","name_en":"Haemosu","epithet":"하늘에서 내려온 해의 아들","domains":["하늘","해","왕권"],"summary":"다섯 마리 용이 끄는 수레를 타고 하늘에서 내려와 북부여를 세웠다는 천제의 아들입니다.","description":["「삼국유사」와 이규보의 「동명왕편」에 따르면 해모수는 아침이면 하늘에서 내려와 나라를 다스리고 저녁이면 하늘로 올라가, 사람들이 ‘하늘의 왕자’라 불렀습니다.","물의 신 하백의 딸 유화와 정을 맺었는데, 하백이 그를 시험하려 잉어, 사슴, 꿩으로 변하자 해모수는 수달, 승냥이, 매로 변해 차례로 잡았다고 「동명왕편」은 전합니다."],"sort_order":8},{"slug":"yuhwa","pantheon_slug":"korean","kind":"hero","grade":null,"name":"유화","name_en":"Yuhwa","epithet":"고구려 건국 신화의 어머니 영웅","domains":["물","곡식","어머니"],"summary":"물의 신 하백의 딸로, 알을 낳아 주몽을 기른 고구려 건국 신화의 영웅입니다. 고구려에서는 뒤에 ‘부여신’으로 모셨습니다.","description":["유화는 해모수와 정을 맺은 일로 아버지에게 쫓겨났고, 동부여의 금와왕이 그를 거두었습니다. 햇빛이 몸을 따라 비춘 뒤 큰 알을 낳았고, 그 알에서 주몽이 태어났습니다.","주몽이 부여를 떠날 때 다섯 가지 곡식의 씨앗을 싸 주었다고 전해 곡식의 신으로도 봅니다. 중국 역사서는 고구려가 나무로 깎은 부인상을 ‘부여신’이라 부르며 섬겼다고 적었습니다."],"sort_order":9},{"slug":"dongmyeong","pantheon_slug":"korean","kind":"hero","grade":null,"name":"동명성왕","name_en":"King Dongmyeong (Jumong)","epithet":"고구려를 세운 건국 영웅","domains":["건국","활쏘기"],"summary":"알에서 태어나 활을 잘 쏘아 ‘주몽’이라 불렸고, 부여를 떠나 고구려를 세운 건국 영웅입니다.","description":["주몽은 금와왕의 아들들이 시기해 목숨을 노리자 부여를 떠났습니다. 큰 강에 가로막히자 ‘나는 천제의 아들이자 하백의 외손자’라고 외쳤고, 물고기와 자라가 떠올라 다리를 놓아 주었다고 전합니다.","414년에 세운 광개토왕릉비는 첫머리에서 시조 추모왕(주몽)을 ‘천제의 아들이자 하백의 딸의 아들’로 기록해, 한국 건국 신화를 전하는 가장 이른 글로 꼽힙니다."],"sort_order":10},{"slug":"hyeokgeose","pantheon_slug":"korean","kind":"hero","grade":null,"name":"박혁거세","name_en":"Bak Hyeokgeose","epithet":"신라를 세운 건국 영웅","domains":["건국","빛"],"summary":"나정 옆 자줏빛 알에서 태어나 몸에서 빛을 냈다는, 신라를 세운 건국 영웅입니다.","description":["여섯 마을의 우두머리들이 임금을 모시자고 의논할 때, 나정이라는 우물 옆에서 흰 말이 절하는 곳에 자줏빛 알이 있었고 그 알에서 사내아이가 태어났다고 「삼국유사」는 전합니다.","예순한 해를 다스린 뒤 하늘로 올라갔다가 이레 뒤 몸이 흩어져 땅에 떨어졌습니다. 사람들이 합쳐 묻으려 하자 큰 뱀이 막아 다섯 곳에 따로 묻었다는 이야기가 경주 오릉의 내력으로 전합니다."],"sort_order":11},{"slug":"suro","pantheon_slug":"korean","kind":"hero","grade":null,"name":"수로왕","name_en":"King Suro","epithet":"가락국을 세운 건국 영웅","domains":["건국","하늘"],"summary":"구지봉에서 사람들이 노래하며 춤추자 하늘에서 내려온 황금 알에서 태어나 가락국을 세운 건국 영웅입니다.","description":["「삼국유사」에 실린 「가락국기」에 따르면, 하늘의 소리를 따라 아홉 우두머리와 백성이 ‘거북아 거북아 머리를 내어라’ 하는 노래를 부르자 자줏빛 줄에 매달린 금빛 상자가 내려왔고, 그 안의 황금 알 여섯에서 여섯 가야의 왕이 태어났습니다.","가장 먼저 나온 수로는 가락국(금관가야)의 왕이 되었고, 바다 건너 아유타국에서 온 허황옥을 왕비로 맞았다고 전합니다."],"sort_order":12},{"slug":"seolmundae","pantheon_slug":"korean","kind":"god","grade":null,"name":"설문대할망","name_en":"Seolmundae Halmang","epithet":"제주를 만든 거인 여신","domains":["창조","섬","대지"],"summary":"치마폭에 흙을 날라 한라산을 쌓고 제주섬을 만들었다는 거인 여신입니다.","description":["제주 사람들은 설문대할망이 치마로 흙을 날라 한라산을 쌓았고, 그때 치마의 터진 구멍으로 흘린 흙이 섬 곳곳의 오름이 되었다고 전합니다.","제주 사람들에게 명주 속옷 한 벌을 지어 주면 육지까지 다리를 놓아 주겠다고 했지만, 명주가 조금 모자라 다리를 끝내지 못했다는 이야기가 유명합니다. 깊은 물에 들어갔다가 빠져 죽었다는 이야기 등 여러 결말이 전합니다."],"sort_order":13},{"slug":"samsin","pantheon_slug":"korean","kind":"god","grade":null,"name":"삼신할미","name_en":"Samsin Halmi","epithet":"아기를 점지하는 여신","domains":["출산","아기","생명"],"summary":"아기를 점지하고 태어난 아이와 산모를 돌본다는 출산의 여신입니다.","description":["사람들은 아이를 낳으면 삼신상에 밥과 미역국, 맑은 물을 올려 삼신할미에게 감사했습니다. 아기 엉덩이의 푸른 점은 삼신할미가 어서 나가라고 때린 자국이라는 속설도 있습니다.","제주의 「삼승할망본풀이」에서는 명진국 따님애기가 동해용왕 따님애기와 꽃 피우기를 겨루어 이긴 뒤, 아기를 점지하는 삼승할망이 되었다고 노래합니다."],"sort_order":14},{"slug":"jacheongbi","pantheon_slug":"korean","kind":"god","grade":null,"name":"자청비","name_en":"Jacheongbi","epithet":"농사의 여신","domains":["농사","사랑","씨앗"],"summary":"사랑을 찾아 하늘까지 오르고, 다섯 곡식의 씨앗을 받아 내려와 농사의 신이 된 제주 「세경본풀이」의 주인공입니다.","description":["자청비는 남장을 하고 하늘나라 문도령과 함께 글공부를 하다 사랑에 빠집니다. 숱한 시련 끝에 하늘에 올라 문도령과 혼인했고, 하늘에서 난리가 나자 이를 가라앉혔습니다.","그 공으로 다섯 가지 곡식의 씨앗을 받아 사람 세상에 내려와 농사를 맡는 ‘중세경’이 되었습니다. 문도령은 ‘상세경’, 머슴 정수남은 소와 말을 돌보는 ‘하세경’이 되었다고 합니다."],"sort_order":15},{"slug":"gangnim","pantheon_slug":"korean","kind":"hero","grade":null,"name":"강림도령","name_en":"Gangnim Doryeong","epithet":"저승에서 염라대왕을 잡아 온 차사","domains":["저승","죽음","심부름"],"summary":"원님의 명으로 저승에 가서 염라대왕을 잡아 오고, 그 재주로 사람의 혼을 데려가는 저승차사가 되었다는 제주 「차사본풀이」의 주인공입니다.","description":["강림은 억울하게 죽은 삼형제의 일을 풀려는 원님의 명을 받아 산 몸으로 저승길에 올랐습니다. 큰부인이 정성껏 차려 준 떡과 길에서 만난 집안 신들의 도움으로 저승에 이르러 염라대왕을 데려왔습니다.","염라대왕은 그 재주를 탐내 강림의 혼을 데려가 저승차사로 삼았습니다. 그 뒤 강림은 이름을 적은 붉은 적배지를 들고 사람의 혼을 데려가는 일을 맡았다고 전합니다."],"sort_order":16},{"slug":"siwang","pantheon_slug":"korean","kind":"god","grade":null,"name":"시왕","name_en":"Ten Kings of the Underworld","epithet":"저승의 열 대왕","domains":["저승","심판"],"summary":"죽은 사람을 차례로 심판하는 저승의 열 대왕으로, 다섯째가 염라대왕입니다.","description":["불교와 함께 들어온 시왕 신앙은 죽은 이가 이레마다 한 대왕씩 일곱 대왕을 거쳐 마흔아흐레를 지나고, 백 일, 한 해, 세 해 째에 나머지 대왕을 만나 심판받는다고 봅니다. 사십구재는 이 믿음에서 비롯했습니다.","절의 명부전에는 시왕을 그린 시왕도를 걸고, 굿에서는 망자를 시왕에게 잘 보내는 ‘시왕맞이’를 합니다."],"sort_order":17},{"slug":"cheoyong","pantheon_slug":"korean","kind":"god","grade":null,"name":"처용","name_en":"Cheoyong","epithet":"역신을 물리친 용의 아들","domains":["병 막이","춤","노래"],"summary":"아내를 범한 역신 앞에서 노래하고 춤추며 물러나, 역신을 스스로 굴복시킨 동해 용왕의 아들입니다.","description":["「삼국유사」에 따르면 신라 헌강왕이 개운포에 나들이했을 때 동해 용이 일곱 아들을 데리고 나타났고, 그 가운데 처용이 왕을 따라 서울로 와 벼슬을 받고 아내를 맞았습니다.","역신이 처용의 아내를 범하자 처용은 노래를 부르고 춤을 추며 물러났습니다. 감복한 역신은 처용의 얼굴만 보아도 그 집에 들지 않겠다고 맹세해, 사람들은 문에 처용의 얼굴을 붙여 병을 막았습니다. 처용 탈을 쓰고 추는 처용무는 유네스코 인류무형문화유산입니다."],"sort_order":18},{"slug":"ilwol","pantheon_slug":"korean","kind":"god","grade":null,"name":"일월성신","name_en":"Sun and Moon Gods","epithet":"해와 달, 별의 신","domains":["해","달","별"],"summary":"해와 달, 별을 신으로 모신 무속의 하늘 신으로, 무신도에서는 해와 달을 머리에 인 두 신으로 그립니다.","description":["무당들은 해와 달, 별을 ‘일월성신’이라 부르며 굿에서 모셨습니다. 무신도에서는 흔히 해와 달 장식을 머리에 얹은 두 신이 나란히 선 모습으로 그립니다.","호랑이를 피해 하늘에 오른 오누이가 해와 달이 되었다는 옛이야기 「해와 달이 된 오누이」도 해와 달의 내력을 전하는 이야기로 널리 알려져 있습니다."],"sort_order":19},{"slug":"choeyeong","pantheon_slug":"korean","kind":"hero","grade":null,"name":"최영","name_en":"Choe Yeong","epithet":"왜구를 물리친 고려의 영웅","domains":["장수","청렴","수호"],"summary":"왜구와 홍건적을 물리친 고려 말의 명장으로, 억울하게 죽은 뒤 무속에서 장군으로 모셔진 영웅입니다.","description":["최영(1316~1388)은 왜구와 홍건적을 물리친 고려 말의 명장으로, ‘황금 보기를 돌같이 하라’는 아버지의 말을 지킨 청렴함으로 유명합니다. 위화도 회군 뒤 이성계 세력에게 죽임을 당했습니다.","억울한 죽음 때문에 무당들은 장군당에 그를 모시고 집안과 마을을 지켜 주기를 빌었습니다. 그의 무덤에는 원한 때문에 풀이 나지 않는다는 전설이 있습니다."],"sort_order":20},{"slug":"jangseung","pantheon_slug":"korean","kind":"other","grade":null,"name":"장승","name_en":"Jangseung","epithet":"마을 어귀의 수호신","domains":["마을 수호","길","액막이"],"summary":"마을 어귀나 길가에 세워 나쁜 기운을 막은 나무나 돌 기둥으로, 흔히 천하대장군과 지하여장군이 짝을 이룹니다.","description":["장승은 부릅뜬 눈과 큰 코를 새긴 얼굴 아래 ‘천하대장군’, ‘지하여장군’ 같은 이름을 적어 세웠습니다. 마을로 들어오는 병과 나쁜 기운을 막는 수호신이자, 마을 사이의 거리를 알려 주는 이정표 구실도 했습니다.","마을 사람들은 정월에 장승제를 지내며 새 장승을 세우고 한 해의 평안을 빌었습니다. 장대 끝에 새를 깎아 올린 솟대와 함께 세우는 경우가 많았습니다."],"sort_order":21},{"slug":"chiyou","pantheon_slug":"korean","kind":"god","grade":null,"name":"치우","name_en":"Chiyou","epithet":"황제와 싸운 전쟁의 신","domains":["전쟁","무기","비바람"],"summary":"구리 머리에 쇠 이마를 가졌다는 전쟁의 신으로, 옛 기록에서 황제와 탁록에서 싸웠다고 전하며 한국에서는 붉은악마의 상징으로 널리 알려졌습니다.","description":["「산해경」에 따르면 치우는 무기를 만들어 황제에게 맞섰고, 「사기」는 둘이 탁록의 들판에서 싸웠다고 적었습니다. 후대 기록은 그에게 구리 머리와 쇠 이마를 가진 형제가 여든하나 있었다고 전합니다. 바람의 신 풍백과 비의 신 우사를 불러 큰 비바람을 일으켰지만, 황제가 내려보낸 가뭄의 여신 발이 비를 그치게 해 결국 사로잡혀 죽었다고 합니다.","패한 뒤에도 전쟁의 신 ‘병주’로 제사를 받았습니다. 20세기에 나온 「환단고기」는 그를 배달국의 임금 ‘치우천왕’으로 그렸는데, 학계는 이 책을 위서로 봅니다. 2002년 월드컵 때 응원단 붉은악마가 그의 얼굴을 상징으로 쓰면서 한국에서 널리 알려졌습니다."],"sort_order":22},{"slug":"poiyaunpe","pantheon_slug":"ainu","kind":"hero","grade":null,"name":"포이야운페","name_en":"Poiyaunpe","epithet":"아이누 서사시의 소년 영웅","domains":["영웅","전쟁"],"summary":"아이누의 영웅 서사시 유카르에서 갑옷을 입고 하늘을 날며 싸우는 소년 영웅입니다.","description":["누나에게 길러져 자라 원수를 갚으러 떠납니다.","구전 서사시로, 20세기에 채록되었습니다."],"sort_order":2},{"slug":"shitonai","pantheon_slug":"ainu","kind":"hero","grade":null,"name":"시토나이","name_en":"Shitonai","epithet":"유카르의 소년","domains":["모험","용기"],"summary":"아이누 옛이야기에 나오는 소년으로, 사람을 해치는 괴물과 맞서는 이야기로 전합니다.","description":["유카르와 옛이야기로 구전되었습니다.","이야기마다 모습이 조금씩 다르게 전합니다."],"sort_order":3},{"slug":"paul-bunyan","pantheon_slug":"american-folklore","kind":"hero","grade":null,"name":"폴 버니언","name_en":"Paul Bunyan","epithet":"거인 벌목꾼","domains":["힘","숲","대지"],"summary":"푸른 황소 베이브와 함께 다니는 거인 벌목꾼입니다.","description":["발자국에 물이 고여 미네소타의 호수들이 생겼다는 허풍담이 전합니다.","도끼를 끌고 간 자국이 그랜드 캐니언이 되었다고도 합니다."],"sort_order":1},{"slug":"john-henry","pantheon_slug":"american-folklore","kind":"hero","grade":null,"name":"존 헨리","name_en":"John Henry","epithet":"증기 드릴과 겨룬 사나이","domains":["힘","헌신"],"summary":"증기 드릴과 바위 뚫기 시합을 해 이기고 숨을 거둔 철도 노동자입니다.","description":["19세기 말 철도 터널 공사에서 전해진 노래로 퍼졌습니다.","기계에 맞선 노동의 상징이 되었습니다."],"sort_order":2},{"slug":"scheherazade","pantheon_slug":"arabian-nights","kind":"hero","grade":null,"name":"셰에라자드","name_en":"Scheherazade","epithet":"천 하룻밤의 이야기꾼","domains":["지혜","속임수","이야기"],"summary":"날마다 신부를 죽이던 샤리아르 왕에게 밤마다 이야기를 들려주어 살아남은 왕비입니다.","description":["이야기를 가장 흥미로운 대목에서 끊어 왕이 다음 날 밤을 기다리게 했습니다.","천 하룻밤이 지나 왕은 마음을 고쳐먹었다고 합니다."],"sort_order":1},{"slug":"sinbad","pantheon_slug":"arabian-nights","kind":"hero","grade":null,"name":"신드바드","name_en":"Sinbad the Sailor","epithet":"일곱 번 항해한 뱃사람","domains":["모험","바다","행운"],"summary":"일곱 번의 항해에서 고래 섬과 거대한 새 로크를 만난 바그다드의 상인입니다.","description":["가난한 짐꾼 신드바드에게 자신의 항해담을 들려주는 틀로 이야기가 펼쳐집니다.","로크의 다리에 몸을 묶어 섬을 빠져나온 이야기가 유명합니다."],"sort_order":2},{"slug":"aladdin","pantheon_slug":"arabian-nights","kind":"hero","grade":null,"name":"알라딘","name_en":"Aladdin","epithet":"램프의 주인","domains":["행운","꾀","모험"],"summary":"요술 램프의 정령을 부려 공주와 결혼한 가난한 소년입니다.","description":["앙투안 갈랑이 18세기에 「천일야화」 번역에 더한 이야기입니다.","마법사에게 속아 동굴에 갇혔다가 반지와 램프의 정령에게 도움을 받습니다."],"sort_order":3},{"slug":"ali-baba","pantheon_slug":"arabian-nights","kind":"hero","grade":null,"name":"알리바바","name_en":"Ali Baba","epithet":"열려라 참깨","domains":["행운","꾀","부"],"summary":"'열려라 참깨'라는 주문으로 도적의 동굴을 연 나무꾼입니다.","description":["앙투안 갈랑이 「천일야화」 번역에 더한 이야기입니다.","영리한 하녀 마르자나가 기름 항아리 속에 숨은 도적들을 물리쳤습니다."],"sort_order":4},{"slug":"roc","pantheon_slug":"arabian-nights","kind":"monster","grade":"common","name":"로크","name_en":"Roc","epithet":"코끼리를 채 가는 거대한 새","domains":["하늘","거대함"],"summary":"날개로 해를 가릴 만큼 거대한 새로, 「천일야화」 신드바드의 항해에서 코끼리를 채 가고 바위를 떨어뜨려 배를 부숩니다.","description":["두 번째 항해에서 섬에 홀로 남은 신드바드는 하얀 둥근 지붕처럼 보이는 로크의 알을 발견하고, 내려앉은 로크의 다리에 몸을 묶어 섬을 빠져나왔습니다. 로크는 새끼에게 코끼리를 먹인다고 합니다.","다섯 번째 항해에서는 상인들이 로크의 알을 깨뜨려 새끼를 먹자, 어미 새들이 커다란 바위를 떨어뜨려 배를 부수었습니다. 마르코 폴로도 마다가스카르 쪽 섬에 코끼리를 들어 올리는 거대한 새가 산다고 적었습니다."],"sort_order":5},{"slug":"king-arthur","pantheon_slug":"arthurian","kind":"hero","grade":null,"name":"아서 왕","name_en":"King Arthur","epithet":"브리튼의 왕","domains":["왕권","영웅","정의"],"summary":"바위에 꽂힌 검을 뽑아 왕이 되었다는 브리튼의 전설적인 왕입니다.","description":["우서 펜드래곤의 아들로, 마법사 멀린의 도움을 받아 왕위에 올랐고 원탁의 기사들을 거느렸습니다.","호수의 여인에게서 엑스칼리버를 받았으며, 조카 모드레드와의 캄란 전투에서 치명상을 입고 아발론으로 떠났다고 전합니다."],"sort_order":1},{"slug":"merlin","pantheon_slug":"arthurian","kind":"other","grade":null,"name":"멀린","name_en":"Merlin","epithet":"왕을 만든 마법사","domains":["마법","예언","지혜"],"summary":"아서를 왕으로 이끈 예언자이자 마법사입니다.","description":["몬머스의 제프리는 멀린이 스톤헨지를 아일랜드에서 옮겨 왔다고 적었습니다.","아서의 탄생과 즉위를 예언하고 도왔으나, 호수의 여인 니무에에게 마법을 배워 준 뒤 그녀에게 갇혔다고 합니다."],"sort_order":2},{"slug":"lancelot","pantheon_slug":"arthurian","kind":"hero","grade":null,"name":"랜슬롯","name_en":"Lancelot","epithet":"호수의 기사","domains":["전쟁","용기","사랑"],"summary":"원탁에서 가장 뛰어난 기사로 꼽히지만 왕비 귀네비어와의 사랑으로 원탁을 무너뜨린 기사입니다.","description":["호수의 여인에게 길러져 '호수의 랜슬롯'이라 불렸습니다.","귀네비어와의 관계가 드러나며 아서와 갈라섰고, 이 분열이 원탁 몰락의 시작이 되었습니다."],"sort_order":3},{"slug":"gawain","pantheon_slug":"arthurian","kind":"hero","grade":null,"name":"가웨인","name_en":"Gawain","epithet":"태양의 기사","domains":["용기","맹세","태양"],"summary":"아서의 조카로, 「가웨인 경과 녹색 기사」의 주인공입니다.","description":["녹색 기사의 목을 벤 대가로 1년 뒤 같은 일격을 받겠다는 약속을 지키러 떠나는 이야기가 유명합니다.","정오까지 힘이 세 배로 늘어난다는 전승이 있어 태양과 엮여 이야기됩니다."],"sort_order":4},{"slug":"tristan","pantheon_slug":"arthurian","kind":"hero","grade":null,"name":"트리스탄","name_en":"Tristan","epithet":"비련의 기사","domains":["사랑","음악","전쟁"],"summary":"콘월의 기사로, 이졸데와의 비극적인 사랑으로 유명합니다.","description":["숙부 마크 왕의 신부가 될 이졸데와 사랑의 묘약을 함께 마시며 비극이 시작되었습니다.","하프를 잘 타는 음악가로도 그려집니다."],"sort_order":5},{"slug":"bedivere","pantheon_slug":"arthurian","kind":"hero","grade":null,"name":"베디비어","name_en":"Bedivere","epithet":"마지막 기사","domains":["맹세","수호"],"summary":"캄란 전투 뒤 엑스칼리버를 호수에 돌려준 기사입니다.","description":["가장 오래된 아서 전설에도 등장하는 기사로, 맬러리의 「아서의 죽음」에서는 마지막까지 아서 곁을 지킵니다.","두 번 망설인 끝에 세 번째에 검을 호수에 던지자 물속에서 손이 나와 받았다고 합니다."],"sort_order":6},{"slug":"percival","pantheon_slug":"arthurian","kind":"hero","grade":null,"name":"퍼시벌","name_en":"Percival","epithet":"성배를 찾은 기사","domains":["모험","운명"],"summary":"성배 탐색 이야기의 주인공으로 처음 등장한 순박한 기사입니다.","description":["크레티앵 드 트루아의 「페르스발 또는 성배 이야기」에서 숲에서 자란 소년이 기사가 됩니다.","어부왕의 성에서 성배를 보지만 질문하지 않아 기회를 놓치는 장면이 유명합니다."],"sort_order":7},{"slug":"mordred","pantheon_slug":"arthurian","kind":"hero","grade":null,"name":"모드레드","name_en":"Mordred","epithet":"반역의 기사","domains":["전쟁","복수","혼돈"],"summary":"아서에게 반역해 캄란 전투에서 아서와 함께 쓰러진 기사입니다.","description":["판본에 따라 아서의 조카 또는 아들로 나옵니다.","아서가 원정을 떠난 사이 왕위를 빼앗았고, 마지막 전투에서 서로를 치명적으로 찔렀습니다."],"sort_order":8},{"slug":"morgan-le-fay","pantheon_slug":"arthurian","kind":"other","grade":null,"name":"모르간 르 페이","name_en":"Morgan le Fay","epithet":"아발론의 마녀","domains":["마법","치유","변신"],"summary":"아서의 이부 누이로, 치유자이자 아서를 괴롭히는 마녀로 그려지는 인물입니다.","description":["몬머스의 제프리는 아발론 섬을 다스리는 치유의 여인으로 소개했습니다.","후대의 이야기에서는 엑스칼리버의 칼집을 훔치는 등 아서와 대립하지만, 마지막에는 그를 아발론으로 데려갑니다."],"sort_order":9},{"slug":"gareth","pantheon_slug":"arthurian","kind":"hero","grade":null,"name":"가레스","name_en":"Gareth","epithet":"부엌의 기사","domains":["용기","수호"],"summary":"신분을 숨기고 부엌일을 하다 기사가 된 가웨인의 동생입니다.","description":["맬러리의 이야기에서 '보마인(고운 손)'이라는 별명으로 놀림받다가 공을 세워 기사로 인정받습니다.","랜슬롯을 존경했지만 왕비를 구하러 온 랜슬롯에게 뜻하지 않게 죽임을 당했습니다."],"sort_order":10},{"slug":"galahad","pantheon_slug":"arthurian","kind":"hero","grade":null,"name":"갤러해드","name_en":"Galahad","epithet":"성배를 이룬 기사","domains":["정의","맹세","운명"],"summary":"랜슬롯의 아들로, 위험한 자리에 앉아 성배 탐색을 완수한 가장 순결한 기사입니다.","description":["바위에 꽂힌 검을 뽑고 하얀 방패를 얻었습니다.","성배를 본 뒤 하늘로 들려 올라갔다고 맬러리가 전합니다."],"sort_order":11},{"slug":"lohengrin","pantheon_slug":"arthurian","kind":"hero","grade":null,"name":"로엔그린","name_en":"Lohengrin","epithet":"백조의 기사","domains":["맹세","수호"],"summary":"백조가 끄는 배를 타고 와 공주를 지킨 성배의 기사입니다.","description":["볼프람 폰 에셴바흐의 「파르치발」에서 퍼시벌의 아들로 나옵니다.","이름을 묻지 말라는 약속이 깨지자 떠났다고 합니다."],"sort_order":12},{"slug":"guinevere","pantheon_slug":"arthurian","kind":"hero","grade":null,"name":"귀네비어","name_en":"Guinevere","epithet":"아서 왕의 왕비","domains":["왕비","궁정의 사랑"],"summary":"아서 왕의 왕비로, 랜슬롯과의 사랑이 드러나 원탁의 기사단이 무너지는 계기가 되었습니다.","description":["몬머스의 제프리가 쓴 「브리튼 왕 열전」에서는 아서가 원정을 떠난 사이 모드레드와 혼인한 왕비로 나오고, 12세기 크레티앵 드 트루아의 「수레의 기사」부터 랜슬롯과 사랑하는 사이로 그려졌습니다.","맬러리의 「아서의 죽음」에서는 두 사람의 관계가 드러나 화형을 선고받은 그녀를 랜슬롯이 구해 내고, 이 일로 기사들이 갈라서 왕국이 무너집니다. 아서가 죽은 뒤 그녀는 에임즈베리의 수녀원에 들어가 생을 마쳤습니다."],"sort_order":13},{"slug":"isolde","pantheon_slug":"arthurian","kind":"hero","grade":null,"name":"이졸데","name_en":"Isolde","epithet":"사랑의 묘약을 마신 아일랜드 공주","domains":["사랑","치유"],"summary":"콘월의 마크 왕에게 시집가던 길에 트리스탄과 사랑의 묘약을 마셔 비극적인 사랑에 빠진 아일랜드의 공주입니다.","description":["약초에 밝은 아일랜드 왕비와 그 딸 이졸데는 독 묻은 상처를 입은 트리스탄을 고쳐 주었습니다. 뒤에 트리스탄이 숙부 마크 왕의 신부로 그녀를 데리러 오고, 콘월로 가는 배 위에서 두 사람은 어머니가 왕과의 혼인을 위해 지어 둔 사랑의 묘약을 함께 마셔 버립니다.","왕비가 된 뒤에도 두 사람의 사랑은 이어졌고, 트리스탄은 쫓겨나 브르타뉴에서 흰 손의 이졸데와 결혼합니다. 죽어 가던 트리스탄이 그녀를 불렀으나 검은 돛이 보인다는 거짓말에 숨을 거두었고, 뒤늦게 도착한 이졸데도 그를 껴안고 숨졌습니다."],"sort_order":14},{"slug":"uther-pendragon","pantheon_slug":"arthurian","kind":"hero","grade":null,"name":"우서 펜드래건","name_en":"Uther Pendragon","epithet":"아서 왕의 아버지","domains":["왕권","브리튼"],"summary":"브리튼의 왕으로, 멀린의 마법을 빌려 이그레인과의 사이에서 아서를 낳은 아서 왕의 아버지입니다.","description":["몬머스의 제프리가 쓴 「브리튼 왕 열전」에 따르면 그는 형 아우렐리우스 암브로시우스의 뒤를 이어 왕이 되었고, 하늘에 나타난 용 모양의 혜성을 따라 '용의 머리'라는 뜻의 펜드래건을 이름으로 삼았습니다.","콘월 공작 고를로이스의 아내 이그레인에게 반한 그는 멀린의 마법으로 공작의 모습을 하고 틴타젤 성에 들어가 아서를 잉태하게 했습니다. 공작이 싸움에서 죽은 뒤 이그레인과 결혼했고, 훗날 적이 샘물에 탄 독에 목숨을 잃었습니다."],"sort_order":15},{"slug":"green-knight","pantheon_slug":"arthurian","kind":"other","grade":null,"name":"녹색 기사","name_en":"Green Knight","epithet":"목 베기 내기를 청한 초록빛 기사","domains":["시험","명예"],"summary":"크리스마스에 아서 왕의 궁정에 나타나 목 베기 내기를 청한, 온몸이 초록빛인 거인 기사입니다.","description":["14세기 영어 시 「가웨인 경과 녹색 기사」에서 그는 초록 말을 타고 도끼를 든 채 나타나, 자기 목을 한 번 내리치게 해 주는 대신 1년 뒤 같은 일격을 받으라고 제안합니다. 가웨인이 그의 목을 베자 기사는 떨어진 머리를 집어 들고, 약속을 지키라는 말을 남기고 떠났습니다.","약속한 날 가웨인이 녹색 예배당을 찾아가자 기사는 세 번 도끼를 휘둘러 목에 작은 상처만 냈습니다. 그는 가웨인이 묵었던 성의 주인 베르틸락이었고, 이 모든 일은 아서의 궁정을 시험하려는 모르간 르 페이의 마법이었다고 밝힙니다."],"sort_order":16},{"slug":"lady-of-the-lake","pantheon_slug":"arthurian","kind":"other","grade":null,"name":"호수의 여인","name_en":"Lady of the Lake","epithet":"엑스칼리버를 건넨 호수의 요정","domains":["호수","마법"],"summary":"아서 왕에게 엑스칼리버를 건네고 어린 랜슬롯을 길러 낸 호수의 요정입니다.","description":["맬러리의 「아서의 죽음」에서 아서는 멀린의 안내로 호숫가에 가서, 물 위로 솟은 팔이 든 엑스칼리버를 호수의 여인에게서 받습니다. 아서가 죽음을 앞두고 베디비어에게 칼을 호수에 던지게 하자, 물속에서 다시 손이 나와 칼을 받아 갔습니다.","13세기 산문 「랜슬롯」에서는 아기 랜슬롯을 호수 속 나라로 데려가 기른 이로 나옵니다. 이름은 니무에, 비비안 등 문헌마다 다르며, 멀린에게서 마법을 배운 뒤 그를 가두었다고도 합니다."],"sort_order":17},{"slug":"kirta","pantheon_slug":"canaanite","kind":"hero","grade":null,"name":"키르타","name_en":"Kirta","epithet":"자손을 얻은 왕","domains":["왕권","자손"],"summary":"우가리트의 서사시에서 신의 꿈에 따라 원정해 새 왕비와 자손을 얻은 왕입니다.","description":["기원전 14세기 무렵의 우가리트 점토판에 남았습니다.","엘 신의 축복으로 병에서 회복했다는 이야기도 이어집니다."],"sort_order":3},{"slug":"el","pantheon_slug":"canaanite","kind":"god","grade":null,"name":"엘","name_en":"El","epithet":"신들의 아버지","domains":["창조","지혜","신들의 회의"],"summary":"우가리트 신화에서 신들의 회의를 이끈 늙은 아버지 신으로, '황소 엘', '세월의 아버지'라 불렸습니다.","description":["엘은 셈어로 '신'을 뜻하는 말이기도 합니다. 우가리트 점토판에서 그는 흰 수염을 기른 지혜로운 왕으로, 두 강이 흘러나오는 샘가의 장막에 살며 아내 아세라와 함께 '일흔 아들'로 불린 신들을 낳았습니다.","바다의 신 얌과 폭풍의 신 바알이 왕위를 다툴 때 엘은 처음에 얌의 편을 들었고, 바알이 궁전을 지으려면 그의 허락이 필요했습니다. 「키르타 이야기」에서는 아내와 자식을 잃은 왕 키르타의 꿈에 나타나 길을 일러 줍니다."],"sort_order":4},{"slug":"anat","pantheon_slug":"canaanite","kind":"god","grade":null,"name":"아낫","name_en":"Anat","epithet":"바알의 누이인 사나운 전쟁의 여신","domains":["전쟁","사냥"],"summary":"우가리트 신화에서 바알의 누이로 나오는 전쟁과 사냥의 여신으로, 바알을 죽인 죽음의 신 모트를 칼로 베고 키질해 들판에 뿌렸습니다.","description":["「바알 신화」에서 아낫은 적들의 머리와 손을 허리에 매달고 무릎까지 차오른 피를 헤치며 싸우는 사나운 여신으로 그려집니다. 바알이 궁전을 지을 수 있도록 아버지 신 엘을 위협해 허락을 받아 내려고도 합니다.","바알이 죽음의 신 모트에게 삼켜지자 아낫은 모트를 붙잡아 칼로 베고, 키로 까부르고, 불에 태우고, 맷돌에 갈아 들판에 뿌렸으며, 이야기는 그 뒤 바알이 되살아나는 것으로 이어집니다. 「아크하트 이야기」에서는 영웅 아크하트의 활을 탐내다 그를 죽게 만듭니다."],"sort_order":5},{"slug":"charlemagne","pantheon_slug":"carolingian","kind":"hero","grade":null,"name":"샤를마뉴","name_en":"Charlemagne","epithet":"열두 기사의 황제","domains":["왕권","정의","정복"],"summary":"무훈시 속에서 열두 기사를 거느리고 사라센과 싸우는 전설의 황제입니다.","description":["역사 속 프랑크 왕국의 왕이 전설 속에서 이백 살의 흰 수염 황제로 그려졌습니다.","보검 주아외즈를 지녔다고 전합니다."],"sort_order":1},{"slug":"roland","pantheon_slug":"carolingian","kind":"hero","grade":null,"name":"롤랑","name_en":"Roland","epithet":"론세스바예스의 기사","domains":["영웅","맹세","용기"],"summary":"「롤랑의 노래」의 주인공으로, 끝까지 뿔피리를 불지 않고 싸운 샤를마뉴의 조카입니다.","description":["론세스바예스 고개에서 후위를 맡아 사라센군과 싸우다 숨졌습니다.","검 뒤랑달이 적의 손에 들어가지 않도록 바위에 내려쳤으나 부러지지 않았다고 합니다."],"sort_order":2},{"slug":"astolfo","pantheon_slug":"carolingian","kind":"hero","grade":null,"name":"아스톨포","name_en":"Astolfo","epithet":"달까지 간 기사","domains":["모험","마법"],"summary":"히포그리프를 타고 달까지 날아가 롤랑의 잃어버린 정신을 찾아온 잉글랜드의 기사입니다.","description":["「광란의 오를란도」에서 마법의 창과 뿔피리, 마법서를 지닌 기사로 나옵니다.","잃어버린 것들이 모두 모인다는 달에서 병에 담긴 롤랑의 정신을 가져왔습니다."],"sort_order":3},{"slug":"bradamante","pantheon_slug":"carolingian","kind":"hero","grade":null,"name":"브라다만테","name_en":"Bradamante","epithet":"흰 깃털의 여기사","domains":["전쟁","사랑"],"summary":"「광란의 오를란도」에 나오는 샤를마뉴의 여기사입니다.","description":["사라센의 기사 루지에로와 사랑에 빠져 갖은 모험 끝에 결혼합니다.","닿기만 해도 상대를 말에서 떨어뜨리는 황금 창을 썼다고 합니다."],"sort_order":4},{"slug":"mandricardo","pantheon_slug":"carolingian","kind":"hero","grade":null,"name":"만드리카르도","name_en":"Mandricardo","epithet":"타타르의 왕","domains":["전쟁","분노"],"summary":"「광란의 오를란도」에서 헥토르의 갑옷을 얻은 타타르의 왕입니다.","description":["헥토르의 검 두린다나(뒤랑달)를 차지하려 롤랑과 다투었습니다.","루지에로와 겨루다 죽었습니다."],"sort_order":5},{"slug":"ogier","pantheon_slug":"carolingian","kind":"hero","grade":null,"name":"오지에 르 다누아","name_en":"Ogier the Dane","epithet":"잠든 덴마크의 기사","domains":["영웅","수호"],"summary":"샤를마뉴의 열두 기사 가운데 하나로, 덴마크가 위험할 때 깨어난다는 기사입니다.","description":["모르간 르 페이와 아발론에서 지냈다는 이야기도 있습니다.","크론보르성 지하에 잠든 석상으로 전해집니다."],"sort_order":6},{"slug":"renaud","pantheon_slug":"carolingian","kind":"hero","grade":null,"name":"르노 드 몽토방","name_en":"Renaud de Montauban","epithet":"아이몽의 아들","domains":["모험","용기"],"summary":"명마 바야르를 타고 샤를마뉴와 맞선 아이몽의 네 아들 가운데 맏이입니다.","description":["「아이몽의 네 아들」이라는 무훈시가 그 이야기를 전합니다.","바야르는 네 형제를 한꺼번에 태울 수 있었다고 합니다."],"sort_order":7},{"slug":"angelica","pantheon_slug":"carolingian","kind":"hero","grade":null,"name":"안젤리카","name_en":"Angelica","epithet":"기사들의 마음을 빼앗은 카타이의 공주","domains":["아름다움","마법 반지"],"summary":"보이아르도와 아리오스토의 서사시에서 롤랑을 비롯한 수많은 기사의 마음을 빼앗은 카타이(중국)의 공주입니다.","description":["보이아르도의 「사랑에 빠진 오를란도」에서 샤를마뉴의 궁정에 나타난 안젤리카는 기사들의 마음을 흔들어 놓고, 아리오스토의 「광란의 오를란도」에서는 그녀를 쫓는 기사들을 피해 계속 달아납니다. 입에 물면 몸이 사라지는 마법 반지를 지녔습니다.","에부다섬에서 바다 괴물의 제물이 될 뻔했다가 히포그리프를 탄 루지에로에게 구출되었습니다. 끝내 다친 사라센 병사 메도로를 돌보다 사랑에 빠져 결혼했고, 나무에 새긴 두 사람의 이름을 본 롤랑은 미쳐 버립니다."],"sort_order":8},{"slug":"ruggiero","pantheon_slug":"carolingian","kind":"hero","grade":null,"name":"루지에로","name_en":"Ruggiero","epithet":"히포그리프를 탄 사라센 기사","domains":["기사도","가문의 시조"],"summary":"「광란의 오를란도」에서 히포그리프를 타고 모험하다 브라다만테와 결혼해 에스테 가문의 시조가 된 사라센 기사입니다.","description":["트로이아의 영웅 헥토르의 후손으로, 그가 일찍 죽으리라는 예언 때문에 마법사 아틀란테가 오랫동안 숨겨 길렀습니다. 히포그리프에 실려 마녀 알치나의 섬에 갔다가 풀려난 뒤, 돌아오는 길에 바다 괴물에게 바쳐진 안젤리카를 구했습니다.","그리스도교의 여기사 브라다만테와 사랑에 빠져 마침내 세례를 받고 그녀와 결혼했고, 마지막 노래에서 로도몬테를 쓰러뜨립니다. 아리오스토는 두 사람을 자신이 섬기던 에스테 가문의 조상으로 그렸습니다."],"sort_order":9},{"slug":"hippogriff","pantheon_slug":"carolingian","kind":"monster","grade":"spirit","name":"히포그리프","name_en":"Hippogriff","epithet":"그리핀과 말 사이에서 난 날짐승","domains":["비행","탈것"],"summary":"앞은 독수리, 뒤는 말의 모습을 한 날짐승으로, 「광란의 오를란도」에서 기사들을 태우고 하늘을 날았습니다.","description":["아리오스토는 히포그리프를 그리핀 수컷과 암말 사이에서 태어난 짐승으로, 얼음 바다 너머 리페이산맥에서 드물게 난다고 설명합니다. 마법사 아틀란테가 길들여 타던 것을 기사 루지에로가 얻어 마녀 알치나의 섬까지 날아갔습니다.","뒤에 아스톨포가 이를 타고 에티오피아를 거쳐 지상 낙원까지 날아갔고, 그곳에서 성 요한과 함께 달에 올라 롤랑의 잃어버린 정신을 찾아왔습니다. 그리핀과 말이 짝을 짓는다는 것은 베르길리우스가 '있을 수 없는 일'의 예로 든 구절이기도 합니다."],"sort_order":10},{"slug":"scathach","pantheon_slug":"celtic","kind":"hero","grade":null,"name":"스카하크","name_en":"Scáthach","epithet":"그림자 섬의 여전사","domains":["전쟁","가르침"],"summary":"쿠 훌린에게 무예를 가르친 스코틀랜드 그림자 섬의 여전사입니다.","description":["울스터 이야기에서 영웅들에게 무술을 가르치는 스승으로 나옵니다.","쿠 훌린에게 바다 괴물의 뼈로 만든 창 게 볼그를 주었다고 전합니다."],"sort_order":5},{"slug":"diarmuid","pantheon_slug":"celtic","kind":"hero","grade":null,"name":"디어무드","name_en":"Diarmuid Ua Duibhne","epithet":"사랑의 점을 지닌 전사","domains":["전쟁","사랑"],"summary":"피아나 기사단의 전사로, 핀의 약혼녀 그라냐와 도망친 이야기로 유명합니다.","description":["이마의 '사랑의 점'을 본 여인은 모두 그를 사랑하게 되었다고 합니다.","붉은 창과 노란 창, 두 자루의 창과 두 자루의 검을 지녔다고 전합니다."],"sort_order":6},{"slug":"fergus","pantheon_slug":"celtic","kind":"hero","grade":null,"name":"퍼거스","name_en":"Fergus mac Róich","epithet":"옛 울스터의 왕","domains":["전쟁","왕권","힘"],"summary":"울스터의 옛 왕이자 쿠 훌린의 양부 같은 전사입니다.","description":["왕위를 잃은 뒤 코노트의 여왕 메이브 편에 서서 울스터와 싸웠습니다.","칼라드볼그라는 검으로 언덕 셋의 꼭대기를 베어 냈다고 전합니다."],"sort_order":7},{"slug":"fionn","pantheon_slug":"celtic","kind":"hero","grade":null,"name":"핀 막 쿨","name_en":"Fionn mac Cumhaill","epithet":"피아나의 수장","domains":["영웅","지혜","사냥"],"summary":"지혜의 연어를 먹고 지혜를 얻은 피아나 기사단의 수장입니다.","description":["연어를 굽다 덴 엄지를 입에 넣은 뒤로, 엄지를 깨물면 지혜가 떠올랐다고 합니다.","아일랜드와 스코틀랜드에 거인 핀 맥쿨의 이야기로도 전해집니다."],"sort_order":8},{"slug":"medb","pantheon_slug":"celtic","kind":"hero","grade":null,"name":"메이브","name_en":"Medb","epithet":"코노트의 여왕","domains":["왕권","전쟁","욕망"],"summary":"울스터의 갈색 황소를 빼앗으려 전쟁을 일으킨 코노트의 여왕입니다.","description":["「쿨리의 소 습격」에서 남편과 재산을 견주다 황소 한 마리가 모자라자 전쟁을 일으켰습니다.","주권의 여신에게서 온 인물로 보기도 합니다."],"sort_order":9},{"slug":"manannan","pantheon_slug":"celtic","kind":"god","grade":null,"name":"마나난 막 리르","name_en":"Manannán mac Lir","epithet":"바다의 신","domains":["바다","마법","여행"],"summary":"바다를 땅처럼 마차로 달린다는 아일랜드의 바다 신입니다.","description":["저세상으로 건너가는 길을 지키는 신으로, 안개 망토로 모습을 감춥니다.","어떤 갑옷도 꿰뚫는 검 프라가라흐를 지녔다고 전합니다."],"sort_order":10},{"slug":"oisin","pantheon_slug":"celtic","kind":"hero","grade":null,"name":"오신","name_en":"Oisín","epithet":"청춘의 나라에 간 시인","domains":["시","사랑","여행"],"summary":"요정 니아브를 따라 청춘의 나라 티르 너 노그에 갔던 핀의 아들입니다.","description":["그곳에서 세 해를 보냈다고 생각했으나 돌아와 보니 삼백 년이 흘렀습니다.","말에서 내려 땅을 밟자 한꺼번에 늙어 버렸다고 합니다."],"sort_order":11},{"slug":"lugh","pantheon_slug":"celtic","kind":"god","grade":null,"name":"루","name_en":"Lugh","epithet":"모든 재주를 갖춘 신","domains":["기술과 재주","왕권","전쟁"],"summary":"모든 재주에 능한 투어허 데 다넌의 신으로, 외할아버지인 포모르족의 우두머리 발로르를 쓰러뜨렸습니다.","description":["「마그 투이레드의 둘째 전투」에서 루는 타라의 궁전 문지기에게 대장장이, 장수, 하프 연주자, 시인, 의사 같은 재주를 하나씩 대지만, 그때마다 이미 그 재주를 지닌 이가 있다는 대답을 듣습니다. 이 모든 재주를 한 몸에 지닌 이는 없지 않으냐고 되묻고서야 궁전에 들어갔고, 누아다 왕은 그에게 왕좌를 내주며 포모르족과의 싸움을 맡겼습니다.","포모르족과의 싸움에서 그는 외할아버지 발로르의 독기 서린 눈을 무릿매 돌로 꿰뚫어 쓰러뜨렸습니다. 8월 1일의 수확 축제 루너사가 그의 이름에서 나왔고, 영웅 쿠 훌린의 아버지로도 전해집니다."],"sort_order":12},{"slug":"rhiannon","pantheon_slug":"celtic","kind":"god","grade":null,"name":"리안논","name_en":"Rhiannon","epithet":"흰 말을 탄 다른 세상의 여인","domains":["말","다른 세상","인내"],"summary":"웨일스의 「마비노기」에 나오는 다른 세상의 여인으로, 흰 말을 타고 나타나 영주 푸일과 결혼했습니다.","description":["푸일의 부하들은 흰 말을 타고 천천히 지나가는 그녀를 아무리 달려도 따라잡지 못했지만, 푸일이 멈춰 달라고 부르자 그녀는 곧바로 말을 세웠습니다. 뒤에 갓난아들 프리데리가 사라지자 아이를 죽였다는 누명을 쓰고, 7년 동안 성문 앞에서 손님을 등에 태워 나르는 벌을 받았습니다.","아들이 돌아와 누명을 벗었고, 「마비노기」 셋째 가지에서는 마나위단과 다시 결혼한 뒤 아들과 함께 마법의 성에 붙잡히기도 합니다. 노래로 죽은 이를 깨우고 산 이를 잠재운다는 '리안논의 새'가 함께 전하며, 갈리아의 말 여신 에포나와 견주어 옛 여신의 모습으로 보기도 합니다."],"sort_order":13},{"slug":"aengus","pantheon_slug":"celtic","kind":"god","grade":null,"name":"앵거스 오그","name_en":"Aengus Óg","epithet":"사랑과 젊음의 신","domains":["사랑","젊음","꿈"],"summary":"다그다와 강의 여신 보안의 아들로, 꿈에서 본 처녀를 찾아 백조가 되어 함께 날아간 사랑과 젊음의 신입니다.","description":["다그다는 보안과의 사이에서 아이를 몰래 얻으려고 해를 아홉 달 동안 하늘에 멈춰 두어, 앵거스는 하루 만에 잉태되어 태어났다고 합니다. 자란 뒤에는 '하루 낮과 하룻밤'만 머물게 해 달라는 꾀로 보인강 가의 궁전(뉴그레인지)을 영영 차지했습니다.","「앵거스의 꿈」에서 그는 꿈에 나타난 처녀 카에르를 그리워하다 병이 들었고, 한 해씩 걸러 백조가 되는 그녀를 찾아내 자신도 백조가 되어 함께 날아갔습니다. 수양아들 디어무드가 그라냐와 달아날 때 두 사람을 지켜 주었습니다."],"sort_order":14},{"slug":"deirdre","pantheon_slug":"celtic","kind":"hero","grade":null,"name":"데어드레","name_en":"Deirdre","epithet":"슬픔의 데어드레","domains":["사랑","슬픔","예언"],"summary":"태어나기 전부터 얼스터에 화를 부른다는 예언을 받은 미녀로, 콘코바르 왕을 피해 연인 노이시와 달아났다가 비극을 맞은 여인입니다.","description":["얼스터의 왕 콘코바르는 그녀가 큰 화를 부르리라는 드루이드의 예언에도 아내로 삼으려고 그녀를 외딴곳에서 길렀습니다. 그러나 데어드레는 젊은 전사 노이시를 사랑해 그의 두 형제와 함께 스코틀랜드로 달아났습니다.","왕은 퍼거스를 보내 용서를 약속하고 그들을 불러들였지만, 돌아온 노이시 형제를 죽여 버렸습니다. 데어드레는 한 해를 슬픔 속에 보내다 수레에서 몸을 던져 바위에 머리를 부딪쳐 죽었다고 합니다."],"sort_order":15},{"slug":"ceridwen","pantheon_slug":"celtic","kind":"other","grade":null,"name":"케리드웬","name_en":"Ceridwen","epithet":"영감의 가마솥을 끓인 마녀","domains":["마법","영감","변신"],"summary":"아들에게 줄 지혜의 약을 가마솥에 끓였다가, 그것을 가로챈 소년을 삼켜 시인 탈리에신으로 다시 낳은 웨일스 전설의 마녀입니다.","description":["16세기의 「탈리에신 이야기」에 따르면 케리드웬은 못생긴 아들 모르브란에게 지혜를 주려고 한 해하고 하루 동안 가마솥에 약을 끓였습니다. 그런데 솥을 젓던 소년 귀온 바흐의 손가락에 끓어 넘친 세 방울이 튀었고, 그가 손가락을 입에 넣는 순간 모든 지혜가 그에게 넘어갔습니다.","케리드웬은 달아나는 귀온을 쫓아 사냥개, 수달, 매, 암탉으로 차례로 모습을 바꾸었고, 밀알로 변한 그를 삼켜 아홉 달 뒤 아이로 낳았습니다. 차마 죽이지 못해 가죽 자루에 넣어 바다에 띄운 그 아이가 위대한 시인 탈리에신이 되었습니다."],"sort_order":16},{"slug":"dagda","pantheon_slug":"celtic","kind":"god","grade":null,"name":"다그다","name_en":"The Dagda","epithet":"모든 일에 능한 '좋은 신'","domains":["풍요","지혜","마법"],"summary":"투어허 데 다넌의 아버지 같은 신으로, 바닥나지 않는 가마솥과 스스로 날아오는 하프를 지녔습니다.","description":["이름은 '좋은 신'이라는 뜻으로, 무엇이든 잘해서 붙은 이름이라고 풉니다. '모두의 아버지'(에오하드 올라하르), '큰 지혜의 주인'이라고도 불렸으며, 「마그 투이레드의 둘째 전투」에서는 투어허 데 다넌을 이끄는 우두머리 가운데 하나로 나옵니다.","같은 이야기에서 포모르족은 그를 놀리려고 땅에 판 구덩이 가득 우유와 곡식, 고기를 넣어 죽을 쑤고 다 먹지 못하면 죽이겠다고 했지만, 다그다는 사람이 누울 만한 국자로 모두 먹어 치웠습니다. 후대 이야기에서는 그의 곤봉이 한쪽 끝으로 아홉 명을 죽이고 다른 쪽 끝으로 되살렸다고 하며, 브리지트와 앵거스 오그가 그의 자식으로 전합니다."],"sort_order":17},{"slug":"nuada","pantheon_slug":"celtic","kind":"god","grade":null,"name":"누아다","name_en":"Nuada Airgetlám","epithet":"은팔의 왕","domains":["왕권","전쟁"],"summary":"투어허 데 다넌의 첫 왕으로, 싸움에서 팔을 잃어 왕위를 내놓았다가 은으로 만든 팔을 달고 다시 왕이 되었습니다.","description":["투어허 데 다넌이 아일랜드에 와서 피르 볼그와 싸운 첫째 마그 투이레드 전투에서, 누아다는 스렝의 칼에 팔을 잃었습니다. 몸에 흠이 있는 이는 왕이 될 수 없어 왕위는 반은 포모르인 브레스에게 넘어갔고, 인색한 브레스의 다스림에 사람들은 괴로워했습니다.","의술의 신 디안 케흐트가 장인 크레드네와 함께 은팔을 만들어 주어 '은팔'(아르게틀람)이라 불렸고, 그 아들 미아흐는 살과 핏줄까지 되살렸다고 합니다. 다시 왕이 된 누아다는 루의 재주를 알아보고 포모르족과의 싸움을 그에게 맡겼지만, 그 싸움에서 발로르에게 쓰러졌습니다."],"sort_order":18},{"slug":"taliesin","pantheon_slug":"celtic","kind":"hero","grade":null,"name":"탈리에신","name_en":"Taliesin","epithet":"빛나는 이마의 시인","domains":["시","예언","지혜"],"summary":"6세기에 실제로 활동한 웨일스의 시인으로, 후대 전설에서는 케리드웬의 가마솥 약을 맛본 소년 귀온 바흐가 다시 태어난 존재로 그려집니다.","description":["탈리에신은 브리튼 북부의 왕 우리엔 레게드를 기린 시들로 이름이 전하는 시인이며, 14세기 필사본 「탈리에신의 책」에 그의 이름이 붙은 시들이 모였습니다.","16세기의 「탈리에신 이야기」에서 케리드웬에게 삼켜졌다 다시 태어난 아이는 가죽 자루에 담겨 바다에 띄워졌고, 물고기를 잡던 엘핀이 둑에서 건져 '빛나는 이마'라는 뜻의 탈리에신이라 불렀습니다. 자라서는 마엘군 귀네드 왕의 궁정에서 시인들을 노래로 이기고 사로잡힌 엘핀을 풀어냈다고 합니다."],"sort_order":19},{"slug":"balor","pantheon_slug":"celtic","kind":"monster","grade":"divine","name":"발로르","name_en":"Balor","epithet":"죽음의 눈을 가진 포모르족의 우두머리","domains":["죽음","파괴"],"summary":"한 번 뜨면 군대를 쓰러뜨리는 눈을 가진 포모르족의 우두머리로, 손자 루가 던진 돌에 그 눈을 맞고 죽었습니다.","description":["「마그 투이레드의 둘째 전투」에 따르면 발로르의 눈은 싸움터에서만 떴는데, 무거운 눈꺼풀을 네 사람이 손잡이로 들어 올려야 했고 그 눈이 바라본 군대는 수가 아무리 많아도 맞서지 못했습니다. 아버지의 드루이드들이 마법 약을 끓이던 방을 창으로 들여다보다 약 기운이 눈에 스며 그렇게 되었다고 합니다.","둘째 전투에서 눈꺼풀이 열리자 루가 무릿매로 돌을 던져 눈을 꿰뚫었고, 눈은 머리 뒤로 빠져나가 그 뒤에 있던 포모르 군사들을 쓰러뜨렸습니다. 손자에게 죽는다는 예언 때문에 딸 에흐니우를 탑에 가두었다는 이야기는 후대 민담에 전합니다."],"sort_order":20},{"slug":"nezha","pantheon_slug":"chinese","kind":"god","grade":null,"name":"나타","name_en":"Nezha","epithet":"바람불 바퀴의 소년","domains":["전쟁","재생","악귀 퇴치"],"summary":"「봉신연의」와 「서유기」에 나오는 소년 신으로, 바람불 바퀴를 타고 싸웁니다.","description":["동해 용왕의 아들을 죽인 일로 스스로 목숨을 끊었고, 스승 태을진인이 연꽃으로 몸을 되살렸습니다.","건곤권과 혼천릉, 화첨창을 무기로 씁니다."],"sort_order":5},{"slug":"jiang-ziya","pantheon_slug":"chinese","kind":"hero","grade":null,"name":"강태공","name_en":"Jiang Ziya","epithet":"봉신의 군사","domains":["지혜","왕권"],"summary":"주나라 문왕을 도운 군사로, 「봉신연의」에서 신들의 자리를 정했습니다.","description":["곧은 낚싯바늘로 낚시하며 때를 기다렸다는 이야기에서 '강태공'이 낚시꾼을 뜻하게 되었습니다.","「봉신연의」에서는 상나라와의 전쟁에서 죽은 이들을 신으로 봉합니다."],"sort_order":6},{"slug":"huang-feihu","pantheon_slug":"chinese","kind":"hero","grade":null,"name":"황비호","name_en":"Huang Feihu","epithet":"오색 신우를 탄 장수","domains":["전쟁","용기"],"summary":"「봉신연의」에서 상나라를 떠나 주나라에 가담한 장수입니다.","description":["주왕의 폭정에 맞서 반기를 들었습니다.","뒤에 동악 태산의 신으로 봉해졌습니다."],"sort_order":7},{"slug":"huyan-zhuo","pantheon_slug":"chinese","kind":"hero","grade":null,"name":"호연작","name_en":"Huyan Zhuo","epithet":"쌍채찍 장수","domains":["전쟁","용기"],"summary":"「수호전」 양산박 108 호걸 가운데 하나로, 두 자루 쇠채찍을 쓰는 장수입니다.","description":["처음에는 관군을 이끌고 양산박을 쳤으나 뒤에 호걸들과 뜻을 함께했습니다.","쇠사슬로 말을 엮은 연환마 진법으로 이름났습니다."],"sort_order":8},{"slug":"jade-rabbit","pantheon_slug":"chinese","kind":"monster","grade":"spirit","name":"옥토끼","name_en":"Moon Rabbit","epithet":"달의 토끼","domains":["달","치유"],"summary":"달에서 불사의 약을 찧는다는 토끼입니다.","description":["동아시아에서는 달의 무늬를 절구질하는 토끼로 보았습니다.","항아와 함께 달에 산다는 이야기로 이어집니다."],"sort_order":9},{"slug":"sun-wukong","pantheon_slug":"chinese","kind":"hero","grade":null,"name":"손오공","name_en":"Sun Wukong","epithet":"제천대성","domains":["변신","힘","속임수"],"summary":"돌에서 태어나 하늘을 어지럽힌 원숭이 왕으로, 삼장법사를 지켜 서천으로 간 「서유기」의 주인공입니다.","description":["일흔두 가지 변신술과 근두운, 크기를 마음대로 바꾸는 여의봉을 다룹니다.","천궁을 소란스럽게 한 벌로 오행산에 눌렸다가 삼장법사를 만나 풀려났습니다."],"sort_order":10},{"slug":"hou-yi","pantheon_slug":"chinese","kind":"hero","grade":null,"name":"후예","name_en":"Hou Yi","epithet":"열 개의 해를 쏜 궁수","domains":["궁술","영웅","태양"],"summary":"하늘에 뜬 열 개의 해 가운데 아홉을 쏘아 떨어뜨린 명궁입니다.","description":["요 임금 때 해 열 개가 한꺼번에 떠 땅이 타자 활로 세상을 구했습니다.","서왕모에게 받은 불사약을 아내 항아가 먹고 달로 올라갔다고 전합니다."],"sort_order":11},{"slug":"hua-mulan","pantheon_slug":"chinese","kind":"hero","grade":null,"name":"화목란","name_en":"Hua Mulan","epithet":"아버지 대신 나선 여전사","domains":["헌신","전쟁","용기"],"summary":"늙은 아버지 대신 남장을 하고 전쟁에 나간 여인입니다.","description":["북조의 민가 「목란시」가 전하는 이야기입니다.","열두 해를 싸우고 돌아오기까지 동료들은 그녀가 여인인 줄 몰랐다고 합니다."],"sort_order":12},{"slug":"yellow-emperor","pantheon_slug":"chinese","kind":"hero","grade":null,"name":"황제","name_en":"Yellow Emperor","epithet":"중화의 시조","domains":["왕권","문명","전쟁"],"summary":"치우와 탁록에서 싸워 이긴 중국 전설의 제왕입니다.","description":["수레와 옷, 문자와 의술 등 여러 문물을 만들었다고 전합니다.","탁록 전투에서 치우가 일으킨 안개를 지남거로 뚫었다는 이야기가 있습니다."],"sort_order":13},{"slug":"fuxi","pantheon_slug":"chinese","kind":"god","grade":null,"name":"복희","name_en":"Fuxi","epithet":"팔괘를 처음 그린 신","domains":["팔괘","문명","혼인"],"summary":"여와와 함께 사람의 조상으로 꼽히며, 팔괘를 처음 그리고 그물로 사냥과 고기잡이를 가르쳤다는 중국 신화의 첫 임금입니다.","description":["「주역」 계사전에 따르면 복희는 하늘의 모양과 땅의 법칙, 새와 짐승의 무늬를 살펴 팔괘를 처음 그렸고, 그물을 엮어 사냥과 고기잡이를 가르쳤습니다. 혼인의 예법을 정했다는 이야기도 전합니다.","한나라 무덤 그림에서는 윗몸은 사람, 아랫몸은 뱀인 모습으로 여와와 꼬리를 꼰 채 그려졌습니다. 후대에는 삼황의 첫째로 받들어 태호 복희씨라고도 불렀습니다."],"sort_order":14},{"slug":"shennong","pantheon_slug":"chinese","kind":"god","grade":null,"name":"신농","name_en":"Shennong","epithet":"온갖 풀을 맛본 농사의 신","domains":["농사","의약","시장"],"summary":"쟁기를 만들어 농사를 가르치고, 온갖 풀을 직접 맛보아 약초와 독초를 가렸다는 중국 신화의 임금입니다.","description":["「주역」 계사전에 따르면 신농은 나무를 깎아 보습과 쟁기를 만들어 농사를 가르치고, 한낮에 시장을 열어 물건을 바꾸게 했습니다. 「회남자」에는 온갖 풀을 맛보다가 하루에 일흔 번이나 독을 만났다는 이야기가 전합니다.","약초 책 「신농본초경」이 그의 이름을 빌렸고, 후대에는 불의 임금 염제와 같은 인물로 보아 염제 신농씨라고 불렀습니다. 일본에서도 의약의 신으로 섬겨 초상이 많이 그려졌습니다."],"sort_order":15},{"slug":"zhong-kui","pantheon_slug":"chinese","kind":"god","grade":null,"name":"종규","name_en":"Zhong Kui","epithet":"귀신을 잡는 신","domains":["귀신 쫓기","액막이"],"summary":"당나라 현종의 꿈에 나타나 작은 귀신을 잡아먹었다는 큰 귀신으로, 새해와 단오에 문에 붙여 액을 막는 그림의 주인공입니다.","description":["북송 심괄의 「몽계필담」에 따르면 학질을 앓던 당나라 현종의 꿈에 찢어진 모자를 쓴 큰 귀신이 나타나, 물건을 훔쳐 달아나던 작은 귀신을 붙잡아 먹었습니다. 그는 과거에 떨어진 뒤 궁궐 섬돌에 머리를 찧어 죽은 종남산의 선비 종규라며, 천하의 요괴를 없애겠다고 맹세했습니다.","꿈에서 깬 현종이 병이 낫자 화가 오도자에게 그 모습을 그리게 했다고 합니다. 그 뒤로 부릅뜬 눈에 덥수룩한 수염, 관복 차림의 종규 그림은 중국과 한국, 일본에서 귀신을 쫓는 부적처럼 쓰였습니다."],"sort_order":16},{"slug":"erlang-shen","pantheon_slug":"chinese","kind":"god","grade":null,"name":"이랑신","name_en":"Erlang Shen","epithet":"이마에 눈이 하나 더 있는 신장","domains":["물 다스리기","사냥","요괴 퇴치"],"summary":"이마의 세 번째 눈과 삼첨양인도, 사냥개 효천견으로 이름난 신으로, 「서유기」에서 하늘을 어지럽힌 손오공을 사로잡았습니다.","description":["쓰촨 관구 지방에서 물을 다스린 신으로 섬기던 데서 비롯했으며, 진나라 때 도강언을 쌓은 이빙의 둘째 아들이라는 전승과 수나라 때 강의 교룡을 벤 조욱이라는 전승 등이 겹쳐 있습니다. 「서유기」에서는 옥황상제의 누이가 인간 양씨와 낳은 아들로, 「봉신연의」에서는 양전이라는 장수로 나옵니다.","「서유기」에서 이랑신은 손오공과 300합 넘게 싸우고 서로 온갖 짐승으로 모습을 바꾸며 쫓고 쫓겼습니다. 태상노군이 던진 금강탁에 손오공이 쓰러지자 효천견이 다리를 물었고, 이랑신은 마침내 손오공을 붙잡았습니다."],"sort_order":17},{"slug":"jade-emperor","pantheon_slug":"chinese","kind":"god","grade":null,"name":"옥황상제","name_en":"Jade Emperor","epithet":"하늘 궁궐의 임금","domains":["하늘","통치","신들의 질서"],"summary":"하늘의 궁궐에서 신과 신선, 사람의 일을 다스린다는 도교와 민간 신앙의 하늘 임금으로, 「서유기」에서 손오공에게 벼슬을 내린 신입니다.","description":["도교 경전 「고상옥황본행집경」에 따르면 그는 광엄묘락국의 태자로 태어났으나 왕위를 버리고 오랜 수행 끝에 옥황이 되었습니다. 이 경전에 따라 음력 정월 초아흐렛날을 그의 생일로 기립니다.","송나라 진종과 휘종이 잇따라 존호를 올리면서 나라에서 받드는 신이 되었고, 한국의 무속과 옛이야기에서도 하늘의 임금으로 자주 나옵니다. 「서유기」에서는 손오공에게 필마온과 제천대성 벼슬을 주었다가 천궁 소동을 겪고 석가여래에게 도움을 청합니다."],"sort_order":18},{"slug":"yu-the-great","pantheon_slug":"chinese","kind":"hero","grade":null,"name":"우 임금","name_en":"Yu the Great","epithet":"홍수를 다스린 하나라의 시조","domains":["치수","건국"],"summary":"아버지 곤이 실패한 홍수 다스리기를 이어받아 물길을 터서 마무리하고, 하나라를 세웠다는 전설의 임금입니다.","description":["「산해경」에 따르면 곤은 천제의 흙 식양을 몰래 가져다 홍수를 막다가 죽임을 당했고, 그 몸에서 우가 태어났습니다. 우는 물을 막는 대신 물길을 터서 바다로 흘려보내는 방법으로 홍수를 다스렸습니다.","치수에 힘쓰느라 자기 집 앞을 세 번 지나면서도 들어가지 않았다고 「맹자」에 전합니다. 천하를 아홉 주로 나누고 순 임금에게서 왕위를 물려받아 하나라를 열었다고 합니다."],"sort_order":19},{"slug":"zhu-bajie","pantheon_slug":"chinese","kind":"other","grade":null,"name":"저팔계","name_en":"Zhu Bajie","epithet":"돼지 몸으로 태어난 천봉원수","domains":["물싸움","변신","식탐"],"summary":"하늘의 수군을 이끌던 천봉원수가 죄를 짓고 돼지 모습으로 태어난 존재로, 삼장법사의 둘째 제자가 되어 서천으로 간 「서유기」의 인물입니다.","description":["「서유기」에 따르면 그는 은하의 수군 8만을 거느리던 천봉원수였으나, 반도회에서 술에 취해 항아를 희롱한 벌로 인간 세상에 쫓겨나다가 돼지의 태에 잘못 들어갔습니다. 복릉산 운잔동에 살다가 관음보살의 권유로 저오능이라는 법명을 받았습니다.","고로장에서 손오공에게 붙잡힌 뒤 삼장법사의 제자가 되어 팔계라는 이름을 얻었습니다. 게으르고 먹을 것과 여색을 밝혀 일행을 자주 곤란하게 했지만 물속 싸움에는 손오공보다 뛰어났으며, 여정을 마친 뒤 정단사자에 봉해졌습니다."],"sort_order":20},{"slug":"qilin","pantheon_slug":"chinese","kind":"monster","grade":"spirit","name":"기린","name_en":"Qilin","epithet":"어진 임금의 시대에 나타나는 상서로운 짐승","domains":["상서","어짊","태평"],"summary":"사슴의 몸에 소의 꼬리, 말의 발굽을 하고 이마에 뿔이 하나 났다고 그려지는 상서로운 짐승으로, 어진 임금이 다스릴 때 나타난다고 여겼습니다.","description":["기린은 살아 있는 풀을 밟지 않고 살아 있는 벌레를 먹지 않는 어진 짐승이라 하며, 「예기」에서 봉황·거북·용과 함께 사령으로 꼽혔습니다. 공자가 태어나기 전 기린이 나타나 옥으로 된 글을 토해 냈다는 전설이 있고, 노나라 애공 때 사냥에서 기린이 잡히자 공자가 「춘추」 쓰기를 멈췄다고 합니다.","명나라 영락제 때 벵골과 아프리카에서 지라프가 바쳐지자 궁정은 이를 전설의 기린으로 반겼습니다. 한국어와 일본어에서 지라프를 기린이라 부르는 것도 이 상서로운 짐승의 이름을 빌린 것입니다."],"sort_order":21},{"slug":"fenghuang","pantheon_slug":"chinese","kind":"monster","grade":"spirit","name":"봉황","name_en":"Fenghuang","epithet":"새들의 왕이라 불리는 상서로운 새","domains":["상서","태평","덕"],"summary":"닭의 머리와 뱀의 목, 제비의 턱, 거북의 등, 물고기의 꼬리에 오색 깃을 지녔다는 상서로운 새로, 천하가 태평할 때 나타난다고 여겼습니다.","description":["수컷을 봉, 암컷을 황이라 하며, 오동나무가 아니면 깃들지 않고 대나무 열매가 아니면 먹지 않는 고결한 새로 그려졌습니다. 「서경」에는 순 임금의 음악 소소를 아홉 번 연주하자 봉황이 날아와 춤추었다고 합니다.","용이 황제를 나타내는 것과 짝을 이루어 봉황은 황후를 상징했고, 한국에서는 대통령을 상징하는 무늬로도 쓰였습니다. 일본에서는 호오라고 부르며, 교토 뵤도인 봉황당 지붕에 금동 봉황 한 쌍을 올렸습니다."],"sort_order":22},{"slug":"gonggong","pantheon_slug":"chinese","kind":"god","grade":null,"name":"공공","name_en":"Gonggong","epithet":"부주산을 들이받은 물의 신","domains":["물","홍수"],"summary":"사람의 얼굴에 뱀의 몸, 붉은 머리카락을 했다는 물의 신으로, 천하를 다투다 지자 하늘을 떠받치는 부주산을 들이받아 하늘과 땅을 기울게 했습니다.","description":["「회남자」 천문훈에 따르면 공공은 전욱과 임금 자리를 다투다 지자 노해서 부주산을 머리로 들이받았습니다. 하늘을 받치던 기둥이 부러져 하늘은 서북쪽으로 기울어 해와 달, 별이 그쪽으로 옮겨 가고, 땅은 동남쪽이 꺼져 강물이 모두 동쪽으로 흐르게 되었다고 합니다.","다른 전승에서는 불의 신 축융과 싸웠다고 하며, 후대에는 이때 무너진 하늘을 여와가 오색 돌로 기웠다는 이야기와 이어졌습니다. 「산해경」에는 그의 신하로 머리가 아홉 달린 뱀 상류가 나옵니다."],"sort_order":23},{"slug":"nitocris","pantheon_slug":"egyptian","kind":"hero","grade":null,"name":"니토크리스","name_en":"Nitocris","epithet":"전설의 여왕","domains":["왕권","복수"],"summary":"헤로도토스가 전한 이집트의 전설적인 여왕입니다.","description":["오빠를 죽인 자들을 지하 방의 연회에 불러 강물을 끌어들여 복수했다고 합니다.","실존 여부는 확실하지 않습니다."],"sort_order":10},{"slug":"robin-hood","pantheon_slug":"european-folklore","kind":"hero","grade":null,"name":"로빈 후드","name_en":"Robin Hood","epithet":"셔우드의 의적","domains":["궁술","정의","숲"],"summary":"셔우드 숲에서 부자의 재물을 빼앗아 가난한 이에게 나눈 잉글랜드의 의적입니다.","description":["14세기 무렵부터 발라드로 전해졌습니다.","리틀 존, 터크 수사, 메리언과 함께 노팅엄의 장관에 맞섭니다."],"sort_order":1},{"slug":"william-tell","pantheon_slug":"european-folklore","kind":"hero","grade":null,"name":"빌헬름 텔","name_en":"William Tell","epithet":"사과를 쏜 명사수","domains":["궁술","정의","용기"],"summary":"아들 머리 위의 사과를 쏘아 맞힌 스위스의 명사수입니다.","description":["총독 게슬러의 모자에 절하지 않아 벌로 사과를 쏘게 되었다고 전합니다.","뒤에 게슬러를 쏘아 스위스 독립의 상징이 되었습니다."],"sort_order":2},{"slug":"saint-george","pantheon_slug":"european-folklore","kind":"hero","grade":null,"name":"성 게오르기우스","name_en":"Saint George","epithet":"용을 물리친 기사","domains":["악귀 퇴치","용기","수호"],"summary":"제물로 바쳐질 공주를 구하려 용을 물리쳤다는 전설의 기사입니다.","description":["「황금 전설」에 실린 리비아의 용 이야기가 널리 알려졌습니다.","잉글랜드를 비롯한 여러 나라와 도시의 수호성인으로 섬겨집니다."],"sort_order":3},{"slug":"melusine","pantheon_slug":"european-folklore","kind":"other","grade":null,"name":"멜뤼진","name_en":"Melusine","epithet":"물의 요정","domains":["물","변신","뱀"],"summary":"토요일마다 허리 아래가 뱀(또는 물고기)이 된다는 프랑스 전설의 요정입니다.","description":["남편에게 토요일에는 자신을 보지 말라고 했으나 그가 약속을 어기자 용이 되어 떠났습니다.","뤼지냥 가문의 시조로 전합니다."],"sort_order":4},{"slug":"habetrot","pantheon_slug":"european-folklore","kind":"other","grade":null,"name":"하베트롯","name_en":"Habetrot","epithet":"실 잣는 요정","domains":["공예","치유"],"summary":"실을 잣는 일을 도와주는 스코틀랜드 국경 지방의 요정입니다.","description":["게으른 소녀 대신 실을 자아 주고, 너무 오래 실을 자으면 입술이 늘어진다고 남편을 일깨웠다는 이야기가 있습니다.","그녀가 짠 셔츠를 입으면 병이 낫는다고 합니다."],"sort_order":5},{"slug":"oberon","pantheon_slug":"european-folklore","kind":"other","grade":null,"name":"오베론","name_en":"Oberon","epithet":"요정의 왕","domains":["마법","숲"],"summary":"중세 프랑스 로망스와 셰익스피어의 「한여름 밤의 꿈」에 나오는 요정의 왕입니다.","description":["「보르도의 위옹」에서 기사 위옹을 돕는 난쟁이 요정 왕으로 처음 등장합니다.","「한여름 밤의 꿈」에서는 왕비 티타니아와 다투며 숲의 연인들을 꼬이게 만듭니다."],"sort_order":6},{"slug":"britomart","pantheon_slug":"european-folklore","kind":"hero","grade":null,"name":"브리토마트","name_en":"Britomart","epithet":"정절의 여기사","domains":["맹세","전쟁"],"summary":"스펜서의 서사시 「요정 여왕」에 나오는 정절의 여기사입니다.","description":["마법 거울로 본 기사 아테걸을 찾아 길을 떠납니다.","어떤 기사도 떨어뜨리는 마법의 창을 들었습니다."],"sort_order":7},{"slug":"el-cid","pantheon_slug":"european-folklore","kind":"hero","grade":null,"name":"엘 시드","name_en":"El Cid","epithet":"캄페아도르","domains":["전쟁","영웅"],"summary":"「엘 시드의 노래」에서 추방당한 뒤 발렌시아를 정복한 카스티야의 기사입니다.","description":["역사 인물이 서사시 속에서 전설이 되었습니다.","죽은 뒤에도 말에 묶여 적을 물리쳤다는 후대 전설이 있습니다."],"sort_order":8},{"slug":"prester-john","pantheon_slug":"european-folklore","kind":"hero","grade":null,"name":"사제왕 요한","name_en":"Prester John","epithet":"동방의 전설적인 왕","domains":["왕권","부"],"summary":"먼 동방에 기독교 왕국을 다스린다고 중세 유럽이 믿은 전설의 왕입니다.","description":["12세기에 그가 썼다는 편지가 유럽에 퍼졌습니다.","뒤에는 에티오피아의 왕으로 여겨지기도 했습니다."],"sort_order":9},{"slug":"saint-margaret","pantheon_slug":"european-folklore","kind":"hero","grade":null,"name":"안티오키아의 마르가리타","name_en":"Margaret the Virgin","epithet":"용의 배를 가른 성녀","domains":["악귀 퇴치","맹세"],"summary":"용에게 삼켜졌다가 십자가로 배를 가르고 나왔다는 성녀입니다.","description":["「황금 전설」에 실린 이야기입니다.","출산하는 여인을 지키는 성녀로 섬겨졌습니다."],"sort_order":10},{"slug":"siegfried","pantheon_slug":"germanic","kind":"hero","grade":null,"name":"지크프리트","name_en":"Siegfried","epithet":"용의 피를 뒤집어쓴 영웅","domains":["영웅","힘","불사"],"summary":"용을 죽이고 그 피로 목욕해 칼이 들지 않게 된 「니벨룽겐의 노래」의 영웅입니다.","description":["니벨룽족의 보물과 몸을 감추는 망토를 얻었습니다.","목욕할 때 등에 붙은 보리수 잎 자리만 약점으로 남았고, 하겐이 그곳을 찔러 죽였습니다."],"sort_order":1},{"slug":"kriemhild","pantheon_slug":"germanic","kind":"hero","grade":null,"name":"크림힐트","name_en":"Kriemhild","epithet":"복수의 왕비","domains":["복수","사랑"],"summary":"지크프리트의 아내로, 남편을 죽인 이들에게 처절하게 복수한 부르군트의 공주입니다.","description":["남편의 약점을 하겐에게 알려 주고 만 것을 평생 원망했습니다.","훈족의 왕 에첼과 결혼한 뒤 오빠들과 하겐을 불러 복수를 이루지만 자신도 죽임을 당합니다."],"sort_order":2},{"slug":"dietrich","pantheon_slug":"germanic","kind":"hero","grade":null,"name":"베른의 디트리히","name_en":"Dietrich von Bern","epithet":"망명한 왕","domains":["영웅","왕권","불"],"summary":"왕국을 빼앗기고 훈족의 궁정에서 오래 망명한 게르만 전설의 왕입니다.","description":["역사 속 동고트 왕 테오도리쿠스가 바탕이 되었습니다.","분노하면 입에서 불을 뿜었다는 이야기가 있습니다."],"sort_order":3},{"slug":"hildebrand","pantheon_slug":"germanic","kind":"hero","grade":null,"name":"힐데브란트","name_en":"Hildebrand","epithet":"디트리히의 스승","domains":["가르침","전쟁"],"summary":"디트리히를 섬긴 노장으로, 「힐데브란트의 노래」에서 아들과 마주친 비극으로 알려졌습니다.","description":["9세기에 기록된 고고지 독일어 영웅시가 그의 이야기를 전합니다.","망명에서 돌아오다 아들 하두브란트와 싸우게 됩니다."],"sort_order":4},{"slug":"walter-of-aquitaine","pantheon_slug":"germanic","kind":"hero","grade":null,"name":"아키텐의 발터","name_en":"Walter of Aquitaine","epithet":"훈족에게서 탈출한 영웅","domains":["모험","용기"],"summary":"훈족의 볼모였다가 연인 힐데군트와 함께 보물을 들고 탈출한 영웅입니다.","description":["라틴어 서사시 「발타리우스」가 그의 이야기를 전합니다.","보름스의 왕 군터의 기사들과 산길에서 싸웠습니다."],"sort_order":5},{"slug":"hagen","pantheon_slug":"germanic","kind":"hero","grade":null,"name":"하겐","name_en":"Hagen von Tronje","epithet":"니벨룽의 보물을 숨긴 기사","domains":["충성","배신","니벨룽의 보물"],"summary":"부르군트 왕 군터의 충신으로, 지크프리트를 죽이고 니벨룽의 보물을 라인강에 가라앉힌 기사입니다.","description":["「니벨룽의 노래」에서 하겐은 크림힐트를 속여 지크프리트의 유일한 약점이 두 어깨 사이에 있다는 것을 알아낸 뒤, 사냥터의 샘가에서 물을 마시던 그를 창으로 찔러 죽였습니다. 그 뒤 크림힐트가 보물을 나누어 주며 사람들을 모으자 보물을 빼앗아 라인강에 가라앉혔습니다.","훗날 훈족의 왕 에첼과 재혼한 크림힐트가 부르군트 사람들을 초대하자, 하겐은 함정임을 알면서도 왕들을 따라 길을 떠났습니다. 끝까지 보물이 있는 곳을 말하지 않은 그는 크림힐트가 지크프리트의 칼 발뭉으로 직접 목을 베어 죽였습니다."],"sort_order":6},{"slug":"achilles","pantheon_slug":"greek","kind":"hero","grade":null,"name":"아킬레우스","name_en":"Achilles","epithet":"트로이 전쟁의 영웅","domains":["영웅","전쟁","분노"],"summary":"「일리아스」의 주인공으로, 그리스군에서 가장 뛰어난 전사입니다.","description":["바다의 여신 테티스와 펠레우스의 아들로, 어머니가 스틱스강에 담가 발뒤꿈치 말고는 다치지 않게 되었다는 후대 전승이 있습니다.","친구 파트로클로스를 잃은 분노로 헥토르를 쓰러뜨렸고, 파리스의 화살에 발뒤꿈치를 맞아 죽었습니다."],"sort_order":14},{"slug":"hector","pantheon_slug":"greek","kind":"hero","grade":null,"name":"헥토르","name_en":"Hector","epithet":"트로이의 방패","domains":["수호","용기","전쟁"],"summary":"트로이의 왕자이자 가장 뛰어난 장수입니다.","description":["프리아모스 왕의 맏아들로 트로이를 지키는 기둥이었습니다.","아킬레우스와 맞서다 쓰러졌고, 아버지가 몸값을 치르고 시신을 되찾아 장례를 치르며 「일리아스」가 끝납니다."],"sort_order":15},{"slug":"odysseus","pantheon_slug":"greek","kind":"hero","grade":null,"name":"오디세우스","name_en":"Odysseus","epithet":"꾀 많은 영웅","domains":["꾀","모험","궁술"],"summary":"트로이 목마를 고안하고 10년 동안 바다를 떠돈 이타카의 왕입니다.","description":["「오디세이아」는 귀향길에 키클롭스와 세이렌, 키르케를 만나는 모험을 노래합니다.","집에 돌아와 아무도 당기지 못한 자신의 활로 구혼자들을 물리쳤습니다."],"sort_order":16},{"slug":"jason","pantheon_slug":"greek","kind":"hero","grade":null,"name":"이아손","name_en":"Jason","epithet":"아르고호의 선장","domains":["모험","왕권"],"summary":"아르고호 원정대를 이끌고 황금 양털을 찾아 나선 영웅입니다.","description":["숙부 펠리아스에게서 왕위를 되찾기 위해 콜키스의 황금 양털을 가져와야 했습니다.","콜키스의 공주 메데이아의 도움으로 양털을 얻었으나 훗날 그녀를 배신해 비극을 맞습니다."],"sort_order":17},{"slug":"medea","pantheon_slug":"greek","kind":"other","grade":null,"name":"메데이아","name_en":"Medea","epithet":"콜키스의 마녀","domains":["마법","복수"],"summary":"이아손을 도와 황금 양털을 얻게 한 콜키스의 공주이자 마녀입니다.","description":["태양신 헬리오스의 손녀로, 약초와 주술에 뛰어났습니다.","에우리피데스의 비극에서는 이아손에게 버림받은 뒤 끔찍한 복수를 합니다."],"sort_order":18},{"slug":"atalanta","pantheon_slug":"greek","kind":"hero","grade":null,"name":"아탈란테","name_en":"Atalanta","epithet":"발 빠른 사냥꾼","domains":["사냥","궁술","야생"],"summary":"곰이 길렀다는 사냥꾼으로, 칼리돈의 멧돼지 사냥에서 처음 화살을 맞혔습니다.","description":["아르테미스를 섬기며 숲에서 자랐습니다.","달리기에서 이기는 남자와 결혼하겠다고 했으나, 히포메네스가 굴린 황금 사과를 줍다 경주에서 졌습니다."],"sort_order":19},{"slug":"asclepius","pantheon_slug":"greek","kind":"god","grade":null,"name":"아스클레피오스","name_en":"Asclepius","epithet":"의술의 신","domains":["치유","생명"],"summary":"죽은 사람까지 살려 냈다는 의술의 신입니다.","description":["아폴론의 아들로 켄타우로스 케이론에게 의술을 배웠습니다.","죽은 자를 되살려 저승의 질서를 어지럽혔기에 제우스의 벼락을 맞았고, 뒤에 별자리 뱀주인자리가 되었다고 합니다."],"sort_order":20},{"slug":"chiron","pantheon_slug":"greek","kind":"monster","grade":"spirit","name":"케이론","name_en":"Chiron","epithet":"현명한 켄타우로스","domains":["가르침","지혜","치유"],"summary":"아킬레우스, 이아손, 아스클레피오스를 가르친 현명한 켄타우로스입니다.","description":["거친 다른 켄타우로스와 달리 의술과 음악, 사냥에 밝았습니다.","헤라클레스의 독화살에 맞아 낫지 않는 고통 속에 불사를 내려놓았고, 궁수자리가 되었다고 전합니다."],"sort_order":21},{"slug":"orion","pantheon_slug":"greek","kind":"hero","grade":null,"name":"오리온","name_en":"Orion","epithet":"거인 사냥꾼","domains":["사냥","힘"],"summary":"포세이돈의 아들이라 전하는 거인 사냥꾼으로, 밤하늘의 오리온자리가 되었습니다.","description":["바다 위를 걸을 수 있었다는 이야기가 있습니다.","죽음에 관해서는 전갈에 쏘였다는 이야기, 아르테미스의 화살에 맞았다는 이야기 등 여러 판본이 있습니다."],"sort_order":22},{"slug":"europa","pantheon_slug":"greek","kind":"hero","grade":null,"name":"에우로페","name_en":"Europa","epithet":"황소가 데려간 공주","domains":["대지","왕권"],"summary":"흰 황소로 변한 제우스가 크레타로 데려간 페니키아의 공주입니다.","description":["유럽이라는 이름이 그녀에게서 왔다고 이야기됩니다.","크레타에서 미노스 왕을 낳았습니다."],"sort_order":23},{"slug":"dioscuri","pantheon_slug":"greek","kind":"hero","grade":null,"name":"디오스쿠로이","name_en":"Dioscuri","epithet":"쌍둥이 형제","domains":["수호","바다","말"],"summary":"카스토르와 폴리데우케스 쌍둥이로, 뱃사람을 지키는 별자리 쌍둥이자리가 되었습니다.","description":["한 명은 신의 아들, 한 명은 사람의 아들이라 하나는 불사, 하나는 죽을 운명이었습니다.","카스토르가 죽자 폴리데우케스는 불사를 나누어 둘이 하루씩 하늘과 저승에 머물게 되었습니다."],"sort_order":24},{"slug":"paris","pantheon_slug":"greek","kind":"hero","grade":null,"name":"파리스","name_en":"Paris","epithet":"트로이의 왕자","domains":["사랑","궁술"],"summary":"헬레네를 데려와 트로이 전쟁을 일으킨 트로이의 왕자입니다.","description":["세 여신 가운데 가장 아름다운 이에게 황금 사과를 주는 '파리스의 심판'에서 아프로디테를 골랐습니다.","아폴론의 도움으로 쏜 화살로 아킬레우스를 쓰러뜨렸습니다."],"sort_order":25},{"slug":"theseus","pantheon_slug":"greek","kind":"hero","grade":null,"name":"테세우스","name_en":"Theseus","epithet":"미궁의 영웅","domains":["영웅","건국","용기"],"summary":"크레타의 미궁에서 미노타우로스를 물리친 아테네의 영웅입니다.","description":["아리아드네가 건넨 실을 따라 미궁을 빠져나왔습니다.","아테네의 왕이 되어 흩어진 마을들을 하나의 도시로 묶었다고 전합니다."],"sort_order":26},{"slug":"andromeda","pantheon_slug":"greek","kind":"hero","grade":null,"name":"안드로메다","name_en":"Andromeda","epithet":"바다 괴물의 제물","domains":["운명","바다"],"summary":"바다 괴물에게 바쳐졌다가 페르세우스에게 구출된 에티오피아의 공주입니다.","description":["어머니 카시오페이아가 바다 님프보다 아름답다고 자랑해 포세이돈의 노여움을 샀습니다.","죽은 뒤 별자리가 되었습니다."],"sort_order":27},{"slug":"hippolyta","pantheon_slug":"greek","kind":"hero","grade":null,"name":"히폴리테","name_en":"Hippolyta","epithet":"아마조네스의 여왕","domains":["전쟁","왕권"],"summary":"여성 전사 부족 아마조네스의 여왕입니다.","description":["아레스에게 받은 허리띠를 지니고 있었습니다.","헤라클레스의 아홉 번째 과업은 이 허리띠를 가져오는 것이었습니다."],"sort_order":28},{"slug":"daedalus","pantheon_slug":"greek","kind":"hero","grade":null,"name":"다이달로스","name_en":"Daedalus","epithet":"미궁을 지은 장인","domains":["공예","지혜"],"summary":"크레타의 미궁을 설계한 전설적인 장인이자 발명가입니다.","description":["미노스 왕에게 갇히자 밀랍과 깃털로 날개를 만들어 아들 이카로스와 함께 탈출했습니다.","태양에 너무 가까이 날아간 이카로스는 날개가 녹아 바다에 떨어졌습니다."],"sort_order":29},{"slug":"demeter","pantheon_slug":"greek","kind":"god","grade":null,"name":"데메테르","name_en":"Demeter","epithet":"곡물의 여신","domains":["농사","풍요","어머니"],"summary":"곡물과 수확을 다스리는 올림포스의 여신입니다.","description":["딸 페르세포네가 하데스에게 끌려가자 슬픔에 잠겨 땅에 곡식이 자라지 않게 되었습니다.","딸이 한 해의 일부를 저승에서 보내게 되며 계절이 생겼다고 전합니다."],"sort_order":30},{"slug":"astraea","pantheon_slug":"greek","kind":"god","grade":null,"name":"아스트라이아","name_en":"Astraea","epithet":"별의 처녀","domains":["정의","하늘"],"summary":"황금시대가 끝나자 마지막으로 땅을 떠난 정의의 여신입니다.","description":["사람들의 타락을 보고 하늘로 올라가 처녀자리가 되었다고 합니다.","그녀가 든 저울은 천칭자리로 이어진다고 이야기됩니다."],"sort_order":31},{"slug":"galatea","pantheon_slug":"greek","kind":"other","grade":null,"name":"갈라테이아","name_en":"Galatea","epithet":"살아난 조각상","domains":["사랑","생명"],"summary":"조각가 피그말리온이 사랑한 상아 조각상이 아프로디테의 은총으로 사람이 되었다는 이야기의 주인공입니다.","description":["오비디우스의 「변신 이야기」가 전하며, 갈라테이아라는 이름은 후대에 붙었습니다.","피그말리온 효과라는 말이 이 이야기에서 나왔습니다."],"sort_order":32},{"slug":"caeneus","pantheon_slug":"greek","kind":"hero","grade":null,"name":"카이네우스","name_en":"Caeneus","epithet":"칼이 들지 않는 전사","domains":["전쟁","변신"],"summary":"포세이돈의 힘으로 몸에 칼이 들지 않게 된 라피타이족의 전사입니다.","description":["본래 여성 카이니스였으나 포세이돈에게 남자가 되기를 청해 변했다고 오비디우스가 전합니다.","켄타우로스와의 싸움에서 칼로 쓰러뜨릴 수 없자 켄타우로스들이 나무로 덮어 눌렀다고 합니다."],"sort_order":33},{"slug":"euryale","pantheon_slug":"greek","kind":"monster","grade":"spirit","name":"에우리알레","name_en":"Euryale","epithet":"고르곤의 둘째","domains":["괴물","불사"],"summary":"메두사의 언니로, 죽지 않는 고르곤 자매 가운데 하나입니다.","description":["세 자매 가운데 메두사만 죽을 운명이었습니다.","메두사가 페르세우스에게 죽자 비명을 지르며 그를 쫓았다고 합니다."],"sort_order":34},{"slug":"ascalaphus","pantheon_slug":"greek","kind":"other","grade":null,"name":"아스칼라포스","name_en":"Ascalaphus","epithet":"저승 정원지기","domains":["저승","속임수"],"summary":"페르세포네가 저승의 석류를 먹었다고 일러바친 저승의 정원지기입니다.","description":["이 증언 때문에 페르세포네는 해마다 일부를 저승에서 지내게 되었습니다.","데메테르의 벌로 올빼미가 되었다고 오비디우스가 전합니다."],"sort_order":35},{"slug":"perseus","pantheon_slug":"greek","kind":"hero","grade":null,"name":"페르세우스","name_en":"Perseus","epithet":"메두사를 벤 영웅","domains":["영웅","모험","괴물"],"summary":"신들에게 빌린 하르페와 방패로 메두사의 목을 벤 영웅입니다.","description":["제우스와 다나에의 아들로, 헤르메스의 날개 신발과 하데스의 투구를 빌려 고르곤에게 다가갔습니다.","돌아오는 길에 바다 괴물에게 바쳐진 안드로메다를 구해 아내로 맞았습니다."],"sort_order":36},{"slug":"bellerophon","pantheon_slug":"greek","kind":"hero","grade":null,"name":"벨레로폰","name_en":"Bellerophon","epithet":"페가수스의 기수","domains":["영웅","괴물","하늘"],"summary":"날개 달린 말 페가수스를 타고 괴물 키마이라를 물리친 영웅입니다.","description":["아테나가 준 황금 고삐로 페가수스를 길들였습니다.","교만해져 올림포스까지 날아오르려 하다 떨어졌다고 전합니다."],"sort_order":37},{"slug":"orpheus","pantheon_slug":"greek","kind":"hero","grade":null,"name":"오르페우스","name_en":"Orpheus","epithet":"저승을 노래로 연 시인","domains":["음악","저승","사랑"],"summary":"노래로 짐승과 바위까지 움직였다는 트라키아의 시인입니다.","description":["아내 에우리디케를 되찾으러 저승에 내려가 하데스를 노래로 감동시켰습니다.","지상에 닿기 전에 뒤를 돌아보지 말라는 약속을 어겨 아내를 영영 잃었습니다."],"sort_order":38},{"slug":"diomedes","pantheon_slug":"greek","kind":"hero","grade":null,"name":"디오메데스","name_en":"Diomedes","epithet":"신에게 상처를 입힌 영웅","domains":["전쟁","용기"],"summary":"트로이 전쟁에서 아테나의 도움으로 아레스와 아프로디테에게 상처를 입힌 아르고스의 왕입니다.","description":["「일리아스」 5권은 그의 활약을 길게 노래합니다.","오디세우스와 함께 밤에 트로이 진영을 정탐하는 이야기도 있습니다."],"sort_order":39},{"slug":"meleager","pantheon_slug":"greek","kind":"hero","grade":null,"name":"멜레아그로스","name_en":"Meleager","epithet":"칼리돈의 사냥꾼","domains":["사냥","운명"],"summary":"칼리돈의 멧돼지 사냥을 이끈 영웅으로, 장작 한 토막에 목숨이 묶여 있었습니다.","description":["운명의 여신들이 화로의 장작이 다 타면 아이도 죽는다고 하자, 어머니는 장작을 꺼내 숨겼습니다.","훗날 어머니가 분노해 장작을 불에 던지자 숨을 거두었습니다."],"sort_order":40},{"slug":"ajax","pantheon_slug":"greek","kind":"hero","grade":null,"name":"대 아이아스","name_en":"Ajax the Great","epithet":"그리스군의 성벽","domains":["수호","힘","전쟁"],"summary":"커다란 탑 같은 방패를 든, 아킬레우스 다음가는 그리스의 장수입니다.","description":["헥토르와 하루 종일 맞서 싸웠습니다.","아킬레우스의 무구를 오디세우스에게 빼앗기자 스스로 목숨을 끊었습니다."],"sort_order":41},{"slug":"cadmus","pantheon_slug":"greek","kind":"hero","grade":null,"name":"카드모스","name_en":"Cadmus","epithet":"테바이의 건국자","domains":["건국","문자","괴물"],"summary":"용의 이빨을 뿌려 전사들을 길러 내고 테바이를 세운 영웅입니다.","description":["누이 에우로페를 찾아 떠났다가 신탁에 따라 도시를 세웠습니다.","그리스에 페니키아 문자를 전했다고 헤로도토스가 전합니다."],"sort_order":42},{"slug":"cyrene","pantheon_slug":"greek","kind":"other","grade":null,"name":"키레네","name_en":"Cyrene","epithet":"사자와 씨름한 님프","domains":["사냥","용기"],"summary":"맨손으로 사자와 싸우다 아폴론의 눈에 든 라피타이족의 공주입니다.","description":["아폴론이 그녀를 리비아로 데려가 그 땅을 다스리게 했습니다.","리비아의 도시 키레네의 이름이 그녀에게서 왔다고 합니다."],"sort_order":43},{"slug":"psyche","pantheon_slug":"greek","kind":"god","grade":null,"name":"프시케","name_en":"Psyche","epithet":"사랑을 찾은 영혼","domains":["사랑","모험","불사"],"summary":"에로스와 사랑에 빠져 아프로디테의 시련을 견딘 끝에 신이 된 공주입니다.","description":["아풀레이우스의 「황금 당나귀」에 실린 이야기입니다.","프시케라는 이름은 그리스어로 '영혼'을 뜻합니다."],"sort_order":44},{"slug":"penthesilea","pantheon_slug":"greek","kind":"hero","grade":null,"name":"펜테실레이아","name_en":"Penthesilea","epithet":"트로이에 온 아마조네스 여왕","domains":["전쟁","용기"],"summary":"트로이를 돕다가 아킬레우스와 싸워 쓰러진 아마조네스의 여왕입니다.","description":["아레스의 딸로 전합니다.","아킬레우스가 쓰러뜨린 뒤 그녀의 아름다움에 슬퍼했다는 이야기가 있습니다."],"sort_order":45},{"slug":"antiope","pantheon_slug":"greek","kind":"hero","grade":null,"name":"안티오페","name_en":"Antiope","epithet":"아마조네스의 전사","domains":["전쟁","사랑"],"summary":"테세우스에게 끌려가 그의 아내가 되었다는 아마조네스의 전사입니다.","description":["판본에 따라 히폴리테의 자매로 전합니다.","아마조네스가 아테네를 공격한 전쟁에서 목숨을 잃었다고 합니다."],"sort_order":46},{"slug":"britomartis","pantheon_slug":"greek","kind":"god","grade":null,"name":"브리토마르티스","name_en":"Britomartis","epithet":"크레타의 그물 여신","domains":["사냥","바다"],"summary":"미노스 왕을 피해 바다로 뛰어들었다가 어부의 그물에 건져졌다는 크레타의 여신입니다.","description":["'달콤한 처녀'라는 뜻의 이름을 가졌습니다.","아르테미스와 함께 사냥하는 님프로 그려집니다."],"sort_order":47},{"slug":"arjuna","pantheon_slug":"hindu","kind":"hero","grade":null,"name":"아르주나","name_en":"Arjuna","epithet":"판다바의 궁수","domains":["궁술","영웅","전쟁"],"summary":"「마하바라타」의 판다바 형제 가운데 셋째로, 비할 데 없는 궁수입니다.","description":["크루크셰트라 전쟁을 앞두고 망설이던 그에게 크리슈나가 들려준 가르침이 「바가바드 기타」입니다.","아그니에게서 받은 활 간디바를 들었습니다."],"sort_order":9},{"slug":"karna","pantheon_slug":"hindu","kind":"hero","grade":null,"name":"카르나","name_en":"Karna","epithet":"태양의 아들","domains":["궁술","맹세","선물"],"summary":"태양신 수리야의 아들로, 갑옷과 귀걸이를 지니고 태어난 「마하바라타」의 비극적 영웅입니다.","description":["판다바의 형이었지만 버려져 마부의 아들로 자랐고, 두료다나의 편에서 싸웠습니다.","인드라에게 몸의 갑옷을 내주고 그 대가로 한 번만 쓸 수 있는 창 바사비 샥티를 받았습니다."],"sort_order":10},{"slug":"rama","pantheon_slug":"hindu","kind":"hero","grade":null,"name":"라마","name_en":"Rama","epithet":"「라마야나」의 왕자","domains":["영웅","정의","궁술"],"summary":"비슈누의 일곱 번째 화신으로, 납치된 아내 시타를 되찾으려 락샤사의 왕 라바나와 싸운 왕자입니다.","description":["하누만과 원숭이 군대의 도움으로 랑카에 건너가 라바나를 쓰러뜨렸습니다.","아요디야로 돌아와 다스린 시대가 이상적인 통치로 이야기됩니다."],"sort_order":11},{"slug":"indra","pantheon_slug":"hindu","kind":"god","grade":null,"name":"인드라","name_en":"Indra","epithet":"신들의 왕","domains":["번개","비","신들의 왕"],"summary":"「리그베다」에서 가장 많이 찬양된 천둥과 비의 신이자 신들의 왕입니다.","description":["벼락 바즈라로 물을 가둔 뱀 브리트라를 죽여 세상에 물을 풀어 주었습니다.","흰 코끼리 아이라바타를 타고 다닙니다."],"sort_order":12},{"slug":"parvati","pantheon_slug":"hindu","kind":"god","grade":null,"name":"파르바티","name_en":"Parvati","epithet":"산의 딸","domains":["사랑","어머니","산"],"summary":"히말라야의 딸이자 시바의 아내이며 가네샤의 어머니입니다.","description":["고행 끝에 시바의 마음을 얻었습니다.","두르가와 칼리 같은 강한 여신의 모습으로도 나타난다고 여겨집니다."],"sort_order":13},{"slug":"kama","pantheon_slug":"hindu","kind":"god","grade":null,"name":"카마","name_en":"Kama","epithet":"사랑의 신","domains":["사랑","욕망"],"summary":"사탕수수 활과 꽃 화살을 든 사랑과 욕망의 신입니다.","description":["고행하던 시바에게 화살을 쏘았다가 시바의 셋째 눈에서 나온 불에 재가 되었습니다.","그래서 몸이 없는 자 '아낭가'라고도 불립니다."],"sort_order":14},{"slug":"ashwatthama","pantheon_slug":"hindu","kind":"hero","grade":null,"name":"아슈바타만","name_en":"Ashwatthama","epithet":"죽지 않는 전사","domains":["분노","불사","전쟁"],"summary":"이마에 보석을 지니고 태어난 「마하바라타」의 전사로, 불사의 저주를 받았습니다.","description":["아버지 드로나가 속임수로 죽자 분노해 판다바의 진영을 밤에 습격했습니다.","그 벌로 크리슈나에게 세상이 끝날 때까지 떠도는 저주를 받았다고 합니다."],"sort_order":15},{"slug":"bhima","pantheon_slug":"hindu","kind":"hero","grade":null,"name":"비마","name_en":"Bhima","epithet":"곤봉의 장사","domains":["힘","분노","전쟁"],"summary":"바람의 신 바유의 아들로, 판다바 형제 가운데 가장 힘이 센 둘째입니다.","description":["곤봉 싸움의 달인으로, 마지막에 두료다나의 허벅지를 쳐 쓰러뜨렸습니다.","어려서부터 엄청난 식욕과 힘으로 이름났습니다."],"sort_order":16},{"slug":"duryodhana","pantheon_slug":"hindu","kind":"hero","grade":null,"name":"두료다나","name_en":"Duryodhana","epithet":"카우라바의 맏이","domains":["왕권","권력","전쟁"],"summary":"판다바와 왕국을 두고 크루크셰트라 전쟁을 벌인 카우라바 백 형제의 맏이입니다.","description":["주사위 노름으로 판다바의 왕국을 빼앗았습니다.","카르나를 친구로 받아들인 의리로도 이야기됩니다."],"sort_order":17},{"slug":"vritra","pantheon_slug":"hindu","kind":"monster","grade":"divine","name":"브리트라","name_en":"Vritra","epithet":"물을 가둔 뱀","domains":["혼돈","뱀","물"],"summary":"세상의 물을 가두어 가뭄을 일으킨 거대한 뱀 또는 아수라입니다.","description":["「리그베다」에서 인드라가 바즈라로 브리트라를 쳐 강물을 풀어 주었습니다.","어떤 무기로도 죽지 않는다는 축복을 받았다는 후대 이야기도 있습니다."],"sort_order":18},{"slug":"parashurama","pantheon_slug":"hindu","kind":"hero","grade":null,"name":"파라슈라마","name_en":"Parashurama","epithet":"도끼를 든 화신","domains":["분노","전쟁","복수"],"summary":"시바에게 받은 도끼 파라슈를 든 비슈누의 여섯 번째 화신입니다.","description":["아버지를 죽인 크샤트리아들을 스물한 번이나 쓸어버렸다고 합니다.","「마하바라타」에서는 카르나와 비슈마의 스승으로 나옵니다."],"sort_order":19},{"slug":"saraswati","pantheon_slug":"hindu","kind":"god","grade":null,"name":"사라스바티","name_en":"Saraswati","epithet":"지혜와 학문, 음악의 여신","domains":["지혜","학문","음악","말"],"summary":"흰옷을 입고 현악기 비나를 든 지혜와 학문, 예술의 여신으로, 창조신 브라흐마의 짝으로 섬겨집니다.","description":["사라스바티는 「리그베다」에서 먼저 큰 강의 여신으로 찬양되었고, 뒤에 말과 지혜, 학문의 여신이 되었습니다. 흰 연꽃 위에 앉아 비나를 타고, 백조나 공작을 곁에 둔 모습으로 그려집니다.","브라흐마의 짝으로, 브라흐마가 세상을 지을 때 지식을 주었다고 합니다. 락슈미, 파르바티와 함께 세 여신으로 꼽히며, 학생과 예술가들이 봄 축제 바산트 판차미에 그녀를 기립니다."],"sort_order":20},{"slug":"kali","pantheon_slug":"hindu","kind":"god","grade":null,"name":"칼리","name_en":"Kali","epithet":"시간과 죽음의 검은 여신","domains":["시간","죽음","파괴","해방"],"summary":"검푸른 몸에 혀를 내밀고 칼을 든 무서운 여신으로, 악마를 무찌르고 시간과 죽음을 넘어선 힘을 나타냅니다.","description":["「데비 마하트미야」에서 칼리는 싸움에 나선 두르가의 이마에서 뛰쳐나와 악마 찬다와 문다를 무찔렀습니다. 피 한 방울마다 새 몸이 생겨나는 악마 락타비자와 싸울 때는 그 피를 남김없이 마셔 쓰러뜨렸다고 합니다.","싸움에 취한 칼리가 멈추지 않자 시바가 그 발밑에 누웠고, 남편을 밟은 것을 깨닫고서야 혀를 내밀며 멈추었다는 이야기가 전합니다. 무섭게 생겼지만 탄트라 전통과 벵골 지방에서는 자식을 지키는 어머니 여신으로 깊이 섬깁니다."],"sort_order":21},{"slug":"yama","pantheon_slug":"hindu","kind":"god","grade":null,"name":"야마","name_en":"Yama","epithet":"죽음과 정의의 왕","domains":["죽음","저승","정의"],"summary":"처음으로 죽어 저승의 길을 연 존재로, 물소를 타고 올가미로 죽은 이의 넋을 거두어 심판하는 죽음의 신입니다.","description":["「리그베다」에서 야마는 처음으로 죽은 인간으로, 뒤따르는 이들을 위해 저승으로 가는 길을 찾아 그 왕이 되었다고 합니다. 태양신 수리야의 아들이며 쌍둥이 누이 야미와 함께 태어났습니다.","뒤의 문헌에서 그는 정의의 왕 다르마라자로서 서기 치트라굽타가 적은 행적에 따라 죽은 이를 심판합니다. 남편 사티아반의 넋을 데려가는 야마를 끝까지 따라가 지혜로운 말로 남편을 되살린 사비트리 이야기가 유명하며, 불교를 따라 동아시아에 전해져 염라대왕이 되었습니다."],"sort_order":22},{"slug":"agni","pantheon_slug":"hindu","kind":"god","grade":null,"name":"아그니","name_en":"Agni","epithet":"제물을 신들에게 나르는 불의 신","domains":["불","제사","전령"],"summary":"제단의 불 속에 깃든 신으로, 사람이 바친 제물을 신들에게 날라 주는 하늘과 땅 사이의 전령입니다.","description":["「리그베다」는 아그니를 찬양하는 노래로 시작하며, 인드라 다음으로 많은 찬가를 받은 신입니다. 하늘에서는 해로, 구름 속에서는 번개로, 땅에서는 불로 나타난다고 여겼습니다.","제사의 불에 바친 공물은 아그니가 연기로 바꾸어 신들에게 전한다고 믿었고, 집집의 아궁이와 혼례, 장례의 불에도 그가 있습니다. 붉은 몸에 머리가 둘이고 숫양을 탄 모습으로 그려지는 일이 많습니다."],"sort_order":23},{"slug":"surya","pantheon_slug":"hindu","kind":"god","grade":null,"name":"수리야","name_en":"Surya","epithet":"일곱 말의 수레를 모는 태양신","domains":["태양","빛","하늘"],"summary":"일곱 마리 말이 끄는 수레를 타고 날마다 하늘을 가로지르는 태양신으로, 모든 것을 비추고 보는 신들의 눈으로 여겨졌습니다.","description":["「리그베다」에서 수리야는 신들의 눈이자 어둠과 병을 몰아내는 빛으로 찬양되며, 마부 아루나가 모는 일곱 말의 수레를 탑니다. 조각에서는 두 손에 활짝 핀 연꽃을 든 모습으로 나타나며, 인도 북서부에서는 긴 겉옷에 장화를 신은 모습으로도 새겼습니다.","죽음의 신 야마와 강의 여신 야무나의 아버지이며, 「마하바라타」의 영웅 카르나도 그의 아들입니다. 13세기에 세운 코나라크의 태양 신전은 거대한 수레 모양으로 지어졌습니다."],"sort_order":24},{"slug":"kartikeya","pantheon_slug":"hindu","kind":"god","grade":null,"name":"카르티케야","name_en":"Kartikeya","epithet":"신들의 군대를 이끄는 장군","domains":["전쟁","용기","지혜"],"summary":"시바의 아들이자 신들의 군대를 이끄는 장군으로, 여섯 얼굴에 공작을 타고 악마 타라카를 무찔렀습니다.","description":["악마 타라카는 시바의 아들에게만 죽는다는 은혜를 받아 세상을 괴롭혔고, 신들은 시바의 아들이 태어나기를 기다렸습니다. 시바의 불씨에서 태어난 아이를 크리티카라 불리는 여섯 별의 여신이 길렀기에 카르티케야라 하며, 여섯 어머니의 젖을 먹느라 얼굴이 여섯이 되었다고 합니다.","그는 신들의 장군이 되어 창을 들고 타라카를 무찔렀습니다. 남인도 타밀 지방에서는 무루간이라는 이름으로 지금도 가장 사랑받는 신 가운데 하나이며, 스칸다라는 이름으로도 불립니다."],"sort_order":25},{"slug":"sita","pantheon_slug":"hindu","kind":"hero","grade":null,"name":"시타","name_en":"Sita","epithet":"「라마야나」의 왕비","domains":["인내","정절","대지"],"summary":"밭고랑에서 발견된 대지의 딸로, 라마의 아내가 되었다가 라바나에게 납치되어 랑카에 갇혔던 「라마야나」의 여주인공입니다.","description":["미틸라의 자나카 왕이 밭을 갈다 고랑에서 찾아낸 아이로, 시타라는 이름은 '밭고랑'이라는 뜻입니다. 시바의 활을 들어 올려 꺾은 라마의 아내가 되었고, 라마가 숲으로 쫓겨나자 함께 떠났습니다.","황금 사슴에 홀린 사이 라바나에게 납치되어 랑카의 아쇼카 숲에 갇혔지만 끝까지 굴복하지 않았습니다. 돌아온 뒤에도 정절을 의심받아 불의 시험을 치렀고, 끝내 어머니인 대지가 갈라져 그녀를 품어 갔다고 전합니다."],"sort_order":26},{"slug":"draupadi","pantheon_slug":"hindu","kind":"hero","grade":null,"name":"드라우파디","name_en":"Draupadi","epithet":"판다바 다섯 형제의 아내","domains":["정의","인내","명예"],"summary":"제사의 불 속에서 태어난 판찰라의 공주로, 판다바 다섯 형제의 아내가 되어 「마하바라타」의 큰 전쟁을 부른 모욕과 복수의 한가운데에 섰습니다.","description":["드루파다 왕이 제사의 불 속에서 얻은 딸로, 신랑 고르기에서 아르주나가 활쏘기 시험을 통과해 그녀를 얻었습니다. 어머니 쿤티의 말 때문에 판다바 다섯 형제의 공동 아내가 되었습니다.","유디슈티라가 노름에서 모든 것을 잃자 두료다나의 궁정에 끌려 나와 옷이 벗겨질 위기에 놓였지만, 크리슈나의 도움으로 사리가 끝없이 이어졌다고 전합니다. 숲에서 떠돌던 시절과 비라타 왕궁에 숨어 지낼 때에도 모욕을 견디며 복수를 다짐했고, 그 다짐은 쿠루크셰트라 전쟁으로 이어졌습니다."],"sort_order":27},{"slug":"bhishma","pantheon_slug":"hindu","kind":"hero","grade":null,"name":"비슈마","name_en":"Bhishma","epithet":"무거운 맹세를 지킨 쿠루의 큰어른","domains":["맹세","충성","전쟁"],"summary":"아버지의 혼인을 위해 왕위와 혼인을 버리겠다고 맹세한 쿠루 왕가의 큰어른으로, 「마하바라타」 전쟁에서 카우라바 군을 이끌었습니다.","description":["샨타누 왕과 강의 여신 강가의 아들로, 본래 이름은 데바브라타입니다. 아버지가 어부 우두머리의 딸 사티아바티와 혼인할 수 있도록 왕위를 잇지 않고 평생 혼인하지 않겠다고 맹세했고, 그 맹세가 너무나 무거워 '무서운 이'라는 뜻의 비슈마라 불렸습니다.","그 대가로 아버지에게서 스스로 죽을 때를 고를 수 있는 은혜를 받았습니다. 쿠루크셰트라 전쟁에서 카우라바 군의 총사령관으로 싸우다 시칸디를 앞세운 아르주나의 화살에 쓰러졌고, 화살 침대에 누운 채 해가 북쪽으로 돌아설 때까지 기다렸다가 숨을 거두었습니다."],"sort_order":28},{"slug":"ravana","pantheon_slug":"hindu","kind":"other","grade":null,"name":"라바나","name_en":"Ravana","epithet":"열 머리의 락샤사 왕","domains":["랑카","힘","오만"],"summary":"열 개의 머리와 스무 개의 팔을 한 랑카의 락샤사 왕으로, 시타를 납치했다가 라마에게 쓰러졌습니다.","description":["라바나는 오랜 고행 끝에 브라흐마에게서 신과 악마, 하늘의 존재들 누구에게도 죽지 않는다는 은혜를 받았지만, 사람을 하찮게 여겨 사람만은 빼놓았습니다. 그는 이복형 쿠베라를 몰아내고 랑카와 하늘을 나는 수레 푸시파카를 빼앗았습니다.","라마의 아내 시타를 납치해 랑카로 데려갔다가, 원숭이 군대와 함께 바다를 건너온 라마와 싸워 죽었습니다. 시바를 깊이 섬긴 학자이자 비나의 명수로도 전해져, 지역에 따라서는 그를 높이 기리기도 합니다."],"sort_order":29},{"slug":"garuda","pantheon_slug":"hindu","kind":"monster","grade":"divine","name":"가루다","name_en":"Garuda","epithet":"비슈누를 태우는 새들의 왕","domains":["하늘","속도","뱀의 천적"],"summary":"독수리의 머리와 날개에 사람의 몸을 한 새들의 왕으로, 비슈누를 태우고 다니며 뱀들의 적으로 여겨집니다.","description":["가루다는 현자 카샤파와 비나타의 아들입니다. 어머니가 내기에 져 뱀들의 어머니 카드루의 종이 되자, 뱀들이 몸값으로 내건 불사의 감로 암리타를 구하러 하늘로 올라가 신들을 물리치고 그것을 가져왔습니다.","그 힘에 감탄한 비슈누가 그에게 죽지 않는 몸을 주고 자신을 태우는 탈것으로 삼았으며, 인드라와도 벗이 되었습니다. 이 일 뒤로 가루다는 뱀들을 먹이로 삼았다고 하며, 오늘날 인도네시아와 타이의 나라 문장에도 그려져 있습니다."],"sort_order":30},{"slug":"nandi","pantheon_slug":"hindu","kind":"monster","grade":"spirit","name":"난디","name_en":"Nandi","epithet":"시바를 태우는 흰 황소","domains":["수호","헌신"],"summary":"시바가 타고 다니는 흰 황소이자 카일라스산의 문을 지키는 시종으로, 시바 신전마다 신을 마주 보고 앉은 모습으로 모셔집니다.","description":["난디는 시바의 탈것이면서 시바를 따르는 무리 가나의 우두머리로, 시바가 사는 카일라스산의 문지기로도 그려집니다. 이름은 '기쁨을 주는 이'라는 뜻입니다.","시바 신전 앞에는 대개 성소 쪽을 바라보며 엎드린 난디 상이 놓이고, 참배하는 이들은 그의 귀에 소원을 속삭여 시바에게 전해 달라고 빕니다. 탄자부르의 브리하디스와라 신전에 있는 커다란 난디 상이 유명합니다."],"sort_order":31},{"slug":"shesha","pantheon_slug":"hindu","kind":"monster","grade":"divine","name":"셰샤","name_en":"Shesha","epithet":"비슈누가 잠드는 천 개의 머리 뱀","domains":["우주","시간"],"summary":"머리가 천 개인 뱀들의 왕으로, 우주의 바다 위에서 비슈누가 그 몸 위에 누워 쉬며, 머리로 온 세상을 떠받친다고 합니다.","description":["아난타('끝없는 이')라고도 불리며, 세상이 끝나 모든 것이 사라져도 홀로 남는다고 하여 '남은 것'이라는 뜻의 셰샤라는 이름이 붙었다고 풉니다. 비슈누는 젖의 바다에서 똬리를 튼 셰샤 위에 누워 있고, 그 배꼽에서 피어난 연꽃에서 창조신 브라흐마가 태어납니다.","머리를 들어 땅을 떠받치고 있어 그가 하품하면 땅이 흔들린다고도 합니다. 「라마야나」의 락슈마나와 크리슈나의 형 발라라마가 셰샤의 화신으로 여겨집니다."],"sort_order":32},{"slug":"arash","pantheon_slug":"iranian","kind":"hero","grade":null,"name":"아라시","name_en":"Arash the Archer","epithet":"국경을 정한 궁수","domains":["궁술","헌신","나라 지키기"],"summary":"목숨을 바친 화살 한 발로 이란과 투란의 국경을 정했다는 전설의 궁수입니다.","description":["화살이 떨어진 곳까지를 이란 땅으로 하기로 하자, 산꼭대기에서 온 힘을 다해 쏘았습니다.","화살은 해 뜰 때부터 해 질 때까지 날아갔고 아라시는 그 자리에서 숨졌다고 합니다."],"sort_order":4},{"slug":"rostam","pantheon_slug":"iranian","kind":"hero","grade":null,"name":"루스탐","name_en":"Rostam","epithet":"「샤나메」의 영웅","domains":["영웅","힘","전쟁"],"summary":"애마 락시를 타고 일곱 시련을 넘은 페르시아 최고의 영웅입니다.","description":["피르다우시의 「샤나메」에서 이란의 왕들을 여러 대에 걸쳐 지켰습니다.","모르고 싸운 상대가 아들 소랍이었음을 알게 되는 비극이 유명합니다."],"sort_order":5},{"slug":"fereydun","pantheon_slug":"iranian","kind":"hero","grade":null,"name":"페레이둔","name_en":"Fereydun","epithet":"폭군을 묶은 왕","domains":["왕권","정의"],"summary":"뱀 어깨의 폭군 자하크를 쓰러뜨리고 다마반드산에 묶은 왕입니다.","description":["대장장이 카베가 일으킨 봉기에 힘입어 왕위에 올랐습니다.","소머리 철퇴를 무기로 썼다고 전합니다."],"sort_order":6},{"slug":"kaveh","pantheon_slug":"iranian","kind":"hero","grade":null,"name":"카베","name_en":"Kaveh the Blacksmith","epithet":"가죽 앞치마의 대장장이","domains":["대장장이","정의","용기"],"summary":"폭군 자하크에게 아들들을 잃고 가죽 앞치마를 깃발로 삼아 봉기한 대장장이입니다.","description":["그의 앞치마는 왕실의 깃발 '카비아니 기'가 되었다고 합니다.","「샤나메」에서 민중 봉기의 상징으로 그려집니다."],"sort_order":7},{"slug":"garshasp","pantheon_slug":"iranian","kind":"hero","grade":null,"name":"케레사스파","name_en":"Garshasp","epithet":"용을 죽인 영웅","domains":["영웅","괴물"],"summary":"「아베스타」에 나오는 용 퇴치의 영웅입니다.","description":["뿔 달린 용 스루바라를 죽였는데, 그 등에서 불을 피워 요리하다 용이 깨어났다는 이야기가 있습니다.","세상의 끝날에 다시 일어나 악을 친다고 전합니다."],"sort_order":8},{"slug":"zal","pantheon_slug":"iranian","kind":"hero","grade":null,"name":"잘","name_en":"Zal","epithet":"시무르그가 기른 흰머리 영웅","domains":["영웅","지혜","궁술"],"summary":"흰머리로 태어나 버려졌다가 시무르그의 손에 자라, 루스탐의 아버지가 된 자불리스탄의 영웅입니다.","description":["잘은 영웅 삼의 아들로 태어났지만, 머리카락이 노인처럼 하얗다는 이유로 알보르즈산에 버려졌습니다. 시무르그가 그를 데려다 길렀고, 꿈에서 잘못을 깨달은 삼이 산을 찾아오자 깃털을 받아 들고 아버지에게 돌아갔습니다.","카불 왕의 딸 루다베와 사랑에 빠졌는데, 루다베가 탑 위에서 긴 머리채를 늘어뜨려 그를 올라오게 하려 했다는 이야기가 유명합니다. 두 사람 사이에서 루스탐이 태어났고, 잘은 이란 왕들을 대대로 섬긴 현명한 조언자가 되었습니다."],"sort_order":9},{"slug":"jamshid","pantheon_slug":"iranian","kind":"hero","grade":null,"name":"잠시드","name_en":"Jamshid","epithet":"황금시대를 연 왕","domains":["왕권","문명","오만"],"summary":"사람들에게 갖가지 기술을 가르치고 황금시대를 연 전설의 왕으로, 스스로를 신처럼 여긴 오만 때문에 왕좌를 잃었습니다.","description":["「샤나메」에서 잠시드는 700년을 다스리며 무기와 옷을 만드는 법, 집 짓는 법을 가르치고 사람들을 네 계층으로 나누었습니다. 악마들을 시켜 하늘을 나는 왕좌를 만들게 했고, 그가 왕좌를 타고 하늘에 오른 날이 새해 첫날 노루즈의 시작이라고 전합니다.","그러나 세상의 모든 것이 자기 덕이라고 자랑하자 신의 은총(파르)이 떠났고, 자하크에게 쫓겨 떠돌다 끝내 죽임을 당했습니다. 「아베스타」에서는 이마라는 이름으로, 큰 겨울을 앞두고 울타리 '바라'를 지어 사람과 짐승을 지킨 왕으로 나옵니다."],"sort_order":10},{"slug":"sohrab","pantheon_slug":"iranian","kind":"hero","grade":null,"name":"소흐랍","name_en":"Sohrab","epithet":"아버지 손에 쓰러진 젊은 영웅","domains":["영웅","비극","부자의 인연"],"summary":"루스탐과 사만간 공주 타흐미네의 아들로, 아버지를 찾아 나섰다가 서로를 알아보지 못한 채 루스탐과 싸워 죽었습니다.","description":["루스탐은 잃어버린 말 락시를 찾아 사만간에 들렀다가 공주 타흐미네와 혼인했고, 떠나며 아이에게 줄 팔찌를 남겼습니다. 그렇게 태어난 소흐랍은 어려서부터 힘이 남달랐고, 아버지를 찾아 이란의 왕좌에 앉히려고 투란의 군대를 이끌고 왔습니다.","루스탐은 이름을 숨긴 채 소흐랍과 사흘을 싸웠고, 마지막 날 그를 쓰러뜨린 뒤에야 팔에 감긴 팔찌를 보고 아들임을 알았습니다. 루스탐이 왕 카우스에게 아들을 살릴 약을 청했지만 왕이 내주지 않아 소흐랍은 숨을 거두었습니다."],"sort_order":11},{"slug":"siavash","pantheon_slug":"iranian","kind":"hero","grade":null,"name":"시야바시","name_en":"Siavash","epithet":"불길을 지나온 결백한 왕자","domains":["순결","희생","영웅"],"summary":"왕 카우스의 아들로, 불길을 지나 결백을 증명했지만 투란 땅에서 억울하게 죽임을 당한 「샤나메」의 왕자입니다.","description":["시야바시는 루스탐의 손에 자란 왕자로, 계모 수다베의 유혹을 물리쳤다가 도리어 모함을 받았습니다. 그는 결백을 밝히려고 검은 말을 타고 산더미처럼 쌓은 장작불 사이를 지나갔고, 털끝 하나 다치지 않고 나왔습니다.","그 뒤 아버지와 뜻이 맞지 않아 적국 투란으로 건너가 왕 아프라시아브의 딸 파랑기스와 혼인하고 도시를 세웠지만, 시기하는 이들의 모함으로 죽임을 당했습니다. 그가 흘린 피에서 풀이 돋았다고 전하며, 그의 죽음은 이란과 투란의 긴 복수전으로 이어져 아들 카이 호스로가 원수를 갚았습니다."],"sort_order":12},{"slug":"esfandiyar","pantheon_slug":"iranian","kind":"hero","grade":null,"name":"에스판디야르","name_en":"Esfandiyar","epithet":"몸에 상처가 나지 않는 왕자","domains":["영웅","신앙","무적"],"summary":"조로아스터의 가르침을 지킨 이란의 왕자로, 몸이 청동처럼 단단했지만 눈에 위성류 화살을 맞고 루스탐에게 쓰러졌습니다.","description":["에스판디야르는 왕 고슈타스프의 아들로, 조로아스터의 가르침을 퍼뜨리며 싸웠고 붙잡힌 누이들을 구하러 가는 길에 일곱 시련을 넘었습니다. 조로아스터의 축복으로 몸에 상처가 나지 않았다고 전합니다.","왕위를 넘기기 싫었던 아버지가 루스탐을 사슬에 묶어 데려오라고 명하자, 둘은 피할 수 없는 싸움을 벌였습니다. 시무르그의 가르침으로 위성류 가지로 만든 화살을 쏜 루스탐에게 눈을 맞고 쓰러졌으며, 그를 죽인 루스탐도 끝내 불행을 피하지 못했다고 합니다."],"sort_order":13},{"slug":"zahhak","pantheon_slug":"iranian","kind":"other","grade":null,"name":"자하크","name_en":"Zahhak","epithet":"어깨에 뱀이 돋은 폭군","domains":["폭정","악","뱀"],"summary":"악마 아흐리만의 꾐에 넘어가 어깨에서 뱀 두 마리가 돋아난 폭군으로, 천 년 동안 이란을 다스리다 페레이둔에게 붙잡혔습니다.","description":["아랍 왕 메르다스의 아들 자하크는 아흐리만의 꾐에 넘어가 아버지를 죽이고 왕위에 올랐습니다. 요리사로 꾸민 아흐리만이 그의 두 어깨에 입을 맞추자 뱀 두 마리가 돋아났고, 뱀을 달래려고 날마다 젊은이 둘의 뇌를 먹였다고 합니다.","잠시드를 몰아내고 천 년 동안 다스렸지만, 대장장이 카베가 일으킨 반란과 함께 나타난 페레이둔에게 사로잡혀 다마반드산의 동굴에 묶였습니다. 「아베스타」에 나오는 세 머리 용 아지 다하카가 그 원형으로 여겨집니다."],"sort_order":14},{"slug":"simurgh","pantheon_slug":"iranian","kind":"monster","grade":"spirit","name":"시무르그","name_en":"Simurgh","epithet":"알보르즈산의 지혜로운 신조","domains":["지혜","치유","보호"],"summary":"알보르즈산에 둥지를 튼 거대하고 지혜로운 새로, 버려진 아기 잘을 길러 내고 그 집안을 대대로 도왔습니다.","description":["「샤나메」에서 시무르그는 흰머리로 태어나 버려진 아기 잘을 둥지로 데려가 자기 새끼들과 함께 키웠습니다. 잘이 아버지 삼에게 돌아갈 때 깃털을 건네며, 어려울 때 태우면 곧바로 오겠다고 약속했습니다.","뒤에 잘의 아내 루다베가 난산으로 위태로울 때 배를 갈라 아기 루스탐을 꺼내는 법을 알려 주었고, 에스판디야르와 싸워 다친 루스탐과 락시를 고쳐 주었습니다. 이슬람 이전의 전승에서는 온갖 씨앗을 품은 나무에 산다고 하며, 아타르의 「새들의 회의」에서는 신을 상징하는 새로 그려집니다."],"sort_order":15},{"slug":"rakhsh","pantheon_slug":"iranian","kind":"monster","grade":"spirit","name":"락시","name_en":"Rakhsh","epithet":"루스탐의 충직한 명마","domains":["충성","전쟁","명마"],"summary":"루스탐이 수많은 말 가운데 골라낸 붉은 얼룩말로, 사자와 용에 맞서 잠든 주인을 지켰습니다.","description":["루스탐은 어떤 말도 그의 무게를 견디지 못하자 수많은 말 가운데 붉은 바탕에 얼룩이 박힌 망아지 락시를 골랐습니다. 락시는 코끼리처럼 힘세고 낙타처럼 키가 컸다고 하며, 루스탐은 평생 이 말만 탔습니다.","일곱 시련의 첫째 날 밤 잠든 루스탐에게 사자가 덤비자 락시가 홀로 싸워 죽였고, 셋째 시련에서는 용이 다가올 때마다 발을 굴러 주인을 깨웠습니다. 루스탐이 이복동생 샤가드의 함정 구덩이에 빠져 죽을 때 락시도 함께 숨을 거두었습니다."],"sort_order":16},{"slug":"yamato-takeru","pantheon_slug":"japanese","kind":"hero","grade":null,"name":"야마토타케루","name_en":"Yamato Takeru","epithet":"동서를 평정한 왕자","domains":["영웅","전쟁","꾀"],"summary":"「고사기」와 「일본서기」에 나오는 게이코 천황의 아들로, 동서를 원정한 전설적인 왕자입니다.","description":["여장을 하고 구마소의 우두머리를 쓰러뜨린 이야기가 전합니다.","들판에서 불에 갇히자 쿠사나기의 검으로 풀을 베어 빠져나왔다고 합니다."],"sort_order":7},{"slug":"kiyohime","pantheon_slug":"japanese","kind":"monster","grade":"spirit","name":"키요히메","name_en":"Kiyohime","epithet":"큰 뱀이 된 여인","domains":["복수","변신","뱀"],"summary":"자신을 버린 승려 안친을 쫓다 큰 뱀이 된 여인으로, 도조지 전설의 주인공입니다.","description":["안친이 도조지의 종 속에 숨자 뱀이 된 키요히메가 종을 감고 불을 뿜어 그를 태웠습니다.","노와 가부키 「도조지」의 바탕이 되었습니다."],"sort_order":8},{"slug":"tamamo-no-mae","pantheon_slug":"japanese","kind":"monster","grade":"spirit","name":"다마모노마에","name_en":"Tamamo-no-Mae","epithet":"아홉 꼬리 여우","domains":["변신","속임수","혼돈"],"summary":"도바 상황을 홀린 미녀로, 정체는 아홉 꼬리 여우였다고 전합니다.","description":["음양사 아베노 야스나리에게 정체가 드러나 나스노로 달아났다가 토벌되었습니다.","죽어서 독을 뿜는 돌 셋쇼세키가 되었다고 합니다."],"sort_order":9},{"slug":"shuten-doji","pantheon_slug":"japanese","kind":"monster","grade":"spirit","name":"슈텐도지","name_en":"Shuten-dōji","epithet":"오에산의 귀신 왕","domains":["괴물","악","힘"],"summary":"오에산에 살며 도읍을 어지럽힌 오니들의 우두머리입니다.","description":["술을 좋아해 '술 마시는 아이'라는 이름이 붙었다고 합니다.","미나모토노 라이코와 사천왕이 독술을 먹인 뒤 목을 베었다고 전합니다."],"sort_order":10},{"slug":"ibaraki-doji","pantheon_slug":"japanese","kind":"monster","grade":"spirit","name":"이바라키도지","name_en":"Ibaraki-dōji","epithet":"라쇼몬의 오니","domains":["괴물","복수"],"summary":"슈텐도지를 따르던 오니로, 라쇼몬에서 와타나베노 쓰나에게 팔을 잘렸습니다.","description":["잘린 팔을 되찾으려 쓰나의 유모로 변장해 찾아왔다는 이야기가 있습니다.","에도 시대의 가부키와 그림에 자주 그려졌습니다."],"sort_order":11},{"slug":"ibuki-doji","pantheon_slug":"japanese","kind":"monster","grade":"spirit","name":"이부키도지","name_en":"Ibuki-dōji","epithet":"이부키산의 귀신","domains":["괴물","산"],"summary":"이부키산의 귀신으로, 슈텐도지와 같은 존재로도 전해집니다.","description":["야마타노오로치의 아들이라는 이야기가 있습니다.","술을 즐기는 산의 귀신으로 그려집니다."],"sort_order":12},{"slug":"minamoto-no-raiko","pantheon_slug":"japanese","kind":"hero","grade":null,"name":"미나모토노 라이코","name_en":"Minamoto no Raikō","epithet":"오니 퇴치의 무장","domains":["악귀 퇴치","영웅","전쟁"],"summary":"사천왕을 거느리고 슈텐도지와 거미 요괴를 물리친 헤이안 시대의 무장입니다.","description":["역사 속 미나모토노 요리미쓰가 전설 속 요괴 퇴치의 영웅이 되었습니다.","슈텐도지를 벤 검 도지기리 야스쓰나가 전합니다."],"sort_order":13},{"slug":"sakata-kintoki","pantheon_slug":"japanese","kind":"hero","grade":null,"name":"사카타노 긴토키","name_en":"Sakata no Kintoki","epithet":"금태랑","domains":["힘","악귀 퇴치"],"summary":"산속에서 곰과 씨름하며 자란 괴력의 소년 '긴타로'가 자라 라이코의 사천왕이 된 무사입니다.","description":["도끼를 메고 곰을 탄 긴타로는 단오의 인형으로 사랑받습니다.","슈텐도지 퇴치에 함께했습니다."],"sort_order":14},{"slug":"watanabe-no-tsuna","pantheon_slug":"japanese","kind":"hero","grade":null,"name":"와타나베노 쓰나","name_en":"Watanabe no Tsuna","epithet":"오니의 팔을 벤 무사","domains":["악귀 퇴치","용기"],"summary":"라이코의 사천왕 가운데 하나로, 이바라키도지의 팔을 벤 무사입니다.","description":["그 검은 '오니마루' 또는 '히게키리'로 전합니다.","모도리바시 다리와 라쇼몬의 이야기가 유명합니다."],"sort_order":15},{"slug":"tawara-toda","pantheon_slug":"japanese","kind":"hero","grade":null,"name":"다와라 도타","name_en":"Tawara Tōda","epithet":"큰 지네를 쏜 무사","domains":["궁술","악귀 퇴치"],"summary":"용궁의 부탁으로 미카미산의 큰 지네를 활로 쏘아 죽인 무사입니다.","description":["역사 속 후지와라노 히데사토가 전설의 주인공이 되었습니다.","용왕에게서 먹어도 줄지 않는 쌀가마를 받아 '쌀가마 도타'라고 불렸습니다."],"sort_order":16},{"slug":"suzuka-gozen","pantheon_slug":"japanese","kind":"other","grade":null,"name":"스즈카고젠","name_en":"Suzuka Gozen","epithet":"스즈카산의 천녀","domains":["마법","전쟁","사랑"],"summary":"스즈카산의 도적 또는 천녀로, 사카노우에노 다무라마로와 얽힌 전설의 여인입니다.","description":["판본에 따라 도적, 귀녀, 천녀 등으로 다르게 전합니다.","세 자루의 신검을 지녔다는 이야기가 있습니다."],"sort_order":17},{"slug":"benkei","pantheon_slug":"japanese","kind":"hero","grade":null,"name":"벤케이","name_en":"Benkei","epithet":"선 채로 죽은 승병","domains":["힘","헌신","수호"],"summary":"요시쓰네를 끝까지 지킨 승병으로, 고조 대교에서 천 번째 칼을 노리다 요시쓰네에게 진 이야기로 유명합니다.","description":["고로모가와 전투에서 화살을 맞으며 주군을 지키다 선 채로 숨졌다고 합니다.","역사 인물이지만 「기케이키」와 노·가부키로 전설이 크게 불어났습니다."],"sort_order":18},{"slug":"daikokuten","pantheon_slug":"japanese","kind":"god","grade":null,"name":"다이코쿠텐","name_en":"Daikokuten","epithet":"부엌과 풍요의 신","domains":["부","풍요","행운"],"summary":"쌀가마 위에서 망치를 든 칠복신의 하나입니다.","description":["인도의 마하칼라가 불교와 함께 전해져 일본의 오쿠니누시와 겹쳐졌습니다.","도깨비방망이처럼 흔들면 재물이 나오는 망치를 듭니다."],"sort_order":19},{"slug":"hanasaka-jiisan","pantheon_slug":"japanese","kind":"hero","grade":null,"name":"꽃 피우는 할아버지","name_en":"Hanasaka Jiisan","epithet":"마른 나무에 꽃을 피운 노인","domains":["선","풍요"],"summary":"재를 뿌려 마른 나무에 꽃을 피웠다는 일본 옛이야기의 착한 할아버지입니다.","description":["기르던 개 덕분에 보물을 얻고, 개를 기리며 만든 절구의 재로 기적을 일으킵니다.","욕심 많은 이웃 노인은 같은 일을 따라 하다 벌을 받습니다."],"sort_order":20},{"slug":"koga-saburo","pantheon_slug":"japanese","kind":"hero","grade":null,"name":"고가 사부로","name_en":"Kōga Saburō","epithet":"땅속 나라를 떠돈 무사","domains":["모험","변신","뱀"],"summary":"사라진 공주를 찾아 땅속 나라를 떠돌다 큰 뱀이 되었다는 무사입니다.","description":["무로마치 시대 「신도집」의 스와 신사 연기담에 나오는 이야기입니다.","돌아와 스와 신사의 신으로 모셔졌다고 합니다."],"sort_order":21},{"slug":"okuninushi","pantheon_slug":"japanese","kind":"god","grade":null,"name":"오쿠니누시","name_en":"Ōkuninushi","epithet":"땅 위의 나라를 일군 이즈모의 신","domains":["나라 만들기","인연","의술"],"summary":"털을 잃은 이나바의 흰 토끼를 고쳐 주고, 갖은 시련 끝에 땅 위의 나라를 일군 뒤 아마테라스의 자손에게 넘겨준 이즈모의 신입니다.","description":["「고사기」에 따르면 젊은 시절 이름은 오나무지로, 형제 신들의 짐을 지고 가다가 털을 잃고 우는 이나바의 흰 토끼에게 낫는 법을 알려 주었습니다. 형제들에게 두 번이나 죽임을 당했다가 살아났고, 스사노오가 다스리는 네노쿠니로 피해 뱀과 지네, 들불의 시련을 이겨 냈습니다.","스사노오의 딸 스세리비메와 함께 달아나 형제들을 물리치고, 작은 신 스쿠나비코나와 힘을 합쳐 나라를 만들었습니다. 훗날 아마테라스의 사자에게 나라를 넘겨주는 대신 큰 신전을 지어 받았는데, 이것이 이즈모 다이샤의 기원이라고 합니다."],"sort_order":22},{"slug":"benzaiten","pantheon_slug":"japanese","kind":"god","grade":null,"name":"벤자이텐","name_en":"Benzaiten","epithet":"비파를 타는 물과 음악의 여신","domains":["음악","말재주","재물","물"],"summary":"인도의 강 여신 사라스바티가 불교와 함께 건너와 일본의 신이 된 여신으로, 비파를 타며 음악과 말재주, 재물을 주는 칠복신의 하나입니다.","description":["불경 「금광명경」에서 지혜와 말재주를 주는 변재천으로 소개되었고, 일본에서는 뱀 몸에 노인 머리를 한 곡식의 신 우가진과 합쳐지며 물과 재물의 신이 되었습니다. 그래서 이름의 '재(才)' 자를 재물을 뜻하는 '재(財)'로 바꿔 쓰기도 합니다.","물과 인연이 깊어 섬이나 연못가에 모시는 일이 많으며, 에노시마와 지쿠부시마, 이쓰쿠시마가 3대 벤자이텐으로 꼽힙니다. 무로마치 시대 무렵 칠복신이 한데 묶이면서 그 가운데 홍일점이 되었습니다."],"sort_order":23},{"slug":"ebisu","pantheon_slug":"japanese","kind":"god","grade":null,"name":"에비스","name_en":"Ebisu","epithet":"도미를 안은 고기잡이와 장사의 신","domains":["풍어","장사","복"],"summary":"낚싯대를 메고 도미를 안은 웃는 얼굴로 그려지는 고기잡이와 장사의 신으로, 칠복신 가운데 유일하게 일본에서 비롯한 신이라고 합니다.","description":["바닷가 마을에서 바다 건너 찾아오는 복의 신으로 섬기던 데서 비롯했으며, 이자나기와 이자나미가 처음 낳아 갈대배에 실어 떠나보낸 히루코와 같은 신이라는 이야기가 있습니다. 오쿠니누시의 아들 고토시로누시와 같은 신으로 보기도 합니다.","중세 이후 상인들이 장사가 잘되기를 빌며 섬기기 시작했고, 다이코쿠텐과 짝을 이뤄 부엌과 가게에 모셔졌습니다. 효고현의 니시노미야 신사가 에비스 신앙의 중심으로 꼽힙니다."],"sort_order":24},{"slug":"momotaro","pantheon_slug":"japanese","kind":"hero","grade":null,"name":"모모타로","name_en":"Momotarō","epithet":"복숭아에서 태어난 아이","domains":["용기","오니 퇴치"],"summary":"강물에 떠내려온 커다란 복숭아에서 태어나, 기장 경단을 나눠 준 개와 원숭이, 꿩을 데리고 오니가시마의 오니를 물리친 일본 옛이야기의 주인공입니다.","description":["빨래하던 할머니가 강에서 건져 온 복숭아를 가르자 사내아이가 나왔고, 노부부는 그를 모모타로라 부르며 길렀습니다. 자라서 오니를 물리치러 떠난 모모타로는 길에서 만난 개, 원숭이, 꿩에게 기장 경단을 나눠 주고 함께 오니가시마로 가서 보물을 가지고 돌아왔습니다.","글로 남은 가장 오래된 판본은 1723년에 찍은 작은 그림책이며, 에도 시대 책에서는 복숭아를 먹고 젊어진 노부부가 아이를 낳았다는 줄거리가 많았습니다. 복숭아에서 바로 태어나는 오늘날의 줄거리는 메이지 시대 이후 교과서와 그림책을 거치며 널리 퍼졌습니다."],"sort_order":25},{"slug":"urashima-taro","pantheon_slug":"japanese","kind":"hero","grade":null,"name":"우라시마 다로","name_en":"Urashima Tarō","epithet":"용궁에 다녀온 어부","domains":["바다","시간"],"summary":"거북을 구해 준 답례로 바닷속 용궁에 다녀왔다가, 고향에서 열지 말라던 상자를 열고 한순간에 늙어 버린 어부입니다.","description":["널리 알려진 이야기에서 어부 우라시마 다로는 아이들에게 괴롭힘당하던 거북을 살려 주고, 그 거북을 타고 용궁에 가서 오토히메의 대접을 받았습니다. 몇 해를 지내다 고향에 돌아와 보니 이미 수백 년이 흘러 아는 사람이 아무도 없었습니다.","오토히메가 준 다마테바코를 열자 흰 연기가 피어올라 그는 백발노인이 되었습니다. 이야기의 원형은 「일본서기」와 「단고국 풍토기」 일문에 나오는 우라시마노코 전설로, 그곳에서는 거북이 여인으로 변해 그를 바다 저편 신선의 나라로 데려갑니다."],"sort_order":26},{"slug":"kaguya-hime","pantheon_slug":"japanese","kind":"other","grade":null,"name":"가구야 공주","name_en":"Princess Kaguya","epithet":"달에서 내려온 공주","domains":["달","아름다움"],"summary":"빛나는 대나무 속에서 발견되어 아름답게 자랐지만, 구혼자들에게 불가능한 과제를 내고 끝내 달나라로 돌아간 「다케토리 이야기」의 주인공입니다.","description":["대나무를 베는 노인이 빛나는 대나무 속에서 세 치쯤 되는 여자아이를 찾아 길렀는데, 아이는 석 달 만에 아름다운 여인이 되었습니다. 그녀는 청혼한 귀족 다섯에게 부처의 돌 바리때, 불쥐 가죽옷, 용의 목에 달린 구슬 같은 보물을 구해 오라 했고 아무도 해내지 못했습니다.","천황의 청혼도 거절한 그녀는 자신이 달나라 사람이라 밝히고, 팔월 보름밤 하늘에서 내려온 사자들과 함께 떠났습니다. 천황은 그녀가 남긴 불사약을 하늘에 가장 가까운 산꼭대기에서 태우게 했는데, 그 산이 후지산이라고 합니다. 「다케토리 이야기」는 9~10세기에 쓰여 일본에서 가장 오래된 이야기책으로 꼽힙니다."],"sort_order":27},{"slug":"yamata-no-orochi","pantheon_slug":"japanese","kind":"monster","grade":"divine","name":"야마타노오로치","name_en":"Yamata no Orochi","epithet":"머리와 꼬리가 여덟인 큰 뱀","domains":["재앙","물"],"summary":"해마다 이즈모 노부부의 딸을 하나씩 잡아먹다가 스사노오가 빚은 독한 술에 취해 베인 큰 뱀으로, 그 꼬리에서 구사나기의 검이 나왔습니다.","description":["「고사기」는 머리와 꼬리가 여덟씩이고 눈은 꽈리처럼 붉으며, 몸에 이끼와 노송나무, 삼나무가 자라 여덟 골짜기와 여덟 봉우리에 걸칠 만큼 크다고 그립니다. 노부부 아시나즈치와 데나즈치의 여덟 딸 가운데 일곱이 해마다 하나씩 잡아먹혔습니다.","스사노오는 남은 딸 구시나다히메를 빗으로 바꿔 머리에 꽂고, 여덟 번 빚은 독한 술을 여덟 통에 담아 두었습니다. 오로치가 술을 마시고 잠들자 칼로 베었는데, 가운데 꼬리에서 칼날이 이가 빠져 갈라 보니 구사나기의 검이 들어 있었습니다. 해마다 넘치던 히이강을 오로치로 보는 해석도 있습니다."],"sort_order":28},{"slug":"tsuchigumo","pantheon_slug":"japanese","kind":"monster","grade":"common","name":"쓰치구모","name_en":"Tsuchigumo","epithet":"미나모토노 라이코가 벤 큰 거미","domains":["재앙","속임수"],"summary":"본래 「고사기」와 「일본서기」에서 조정에 따르지 않던 토착 세력을 낮춰 부르던 이름이었으나, 중세 이후에는 미나모토노 라이코에게 퇴치된 거대한 거미 요괴로 이야기되었습니다.","description":["「헤이케 이야기」의 「검의 권」에서는 학질을 앓던 라이코의 머리맡에 키가 일곱 자인 승려가 나타나 실을 던져 그를 옭아매려 했습니다. 라이코가 칼로 베고 핏자국을 따라가니 무덤 속에 큰 거미가 있었고, 그 칼은 이후 구모키리(거미 베기)라고 불렸습니다.","14세기 그림 두루마리 「쓰치구모 소시」에서는 라이코와 와타나베노 쓰나가 날아가는 해골을 쫓아 교토 교외의 낡은 저택에 이르러 갖가지 요괴를 만난 끝에, 산속 굴에 숨은 거대한 거미를 벱니다. 노와 가부키의 「쓰치구모」로도 공연되었습니다."],"sort_order":29},{"slug":"tengu","pantheon_slug":"japanese","kind":"monster","grade":"spirit","name":"덴구","name_en":"Tengu","epithet":"깊은 산에 사는 날개 달린 요괴","domains":["산","무예","교만"],"summary":"붉은 얼굴에 긴 코, 또는 까마귀 부리와 날개를 하고 산속 수행자 차림으로 깊은 산에 산다는 일본의 요괴로, 사람을 홀리기도 하고 무예를 가르치기도 합니다.","description":["이름은 본래 중국에서 하늘을 가로지르는 유성을 가리킨 '천구'에서 왔으며, 일본에서는 12세기 「곤자쿠 이야기집」 등에 승려를 홀리는 요괴로 등장합니다. 교만한 승려가 죽어 덴구가 된다는 믿음도 있었습니다.","구라마산의 대덴구 소조보가 어린 우시와카마루, 곧 훗날의 미나모토노 요시쓰네에게 검술을 가르쳤다는 전설이 노와 그림으로 널리 퍼졌습니다. 아이가 산에서 사라지면 덴구에게 홀렸다고 여겼고, 산의 신으로 모시는 곳도 있습니다."],"sort_order":30},{"slug":"nue","pantheon_slug":"japanese","kind":"monster","grade":"common","name":"누에","name_en":"Nue","epithet":"밤마다 궁궐 위에서 울던 괴수","domains":["재앙","병"],"summary":"원숭이 얼굴에 너구리 몸, 호랑이 다리, 뱀 꼬리를 하고 밤마다 검은 구름을 타고 와 천황을 앓게 했다는 괴수로, 미나모토노 요리마사의 화살에 떨어졌습니다.","description":["「헤이케 이야기」에 따르면 고노에 천황 때 한밤마다 도산조 숲 쪽에서 검은 구름이 몰려와 궁궐 지붕을 덮었고, 천황은 그때마다 겁에 질려 앓았습니다. 활의 명수 미나모토노 요리마사가 구름 속을 향해 쏜 화살에 괴물이 떨어지자, 부하 이노 하야타가 칼로 숨통을 끊었습니다.","본래 누에는 밤에 구슬프게 우는 새 호랑지빠귀를 가리키던 말로, 괴물의 울음소리가 이 새와 닮아 같은 이름으로 불렸습니다. 지금은 정체를 알 수 없는 것을 빗대는 말로도 씁니다."],"sort_order":31},{"slug":"tsukuyomi","pantheon_slug":"japanese","kind":"god","grade":null,"name":"쓰쿠요미","name_en":"Tsukuyomi","epithet":"밤을 다스리는 달의 신","domains":["달","밤"],"summary":"이자나기가 눈을 씻을 때 태어난 달의 신으로, 음식의 여신을 죽인 일로 해의 여신 아마테라스와 갈라져 낮과 밤이 나뉘었다고 합니다.","description":["「고사기」에 따르면 저승에서 돌아온 이자나기가 몸을 씻을 때 왼쪽 눈에서 아마테라스가, 오른쪽 눈에서 쓰쿠요미가, 코에서 스사노오가 태어났고, 쓰쿠요미는 밤의 나라를 맡았습니다. 귀한 세 신 가운데 하나이지만 그에 관한 이야기는 거의 전하지 않습니다.","「일본서기」의 한 전승에서 쓰쿠요미는 아마테라스의 명으로 음식의 여신 우케모치를 찾아갔다가, 여신이 입에서 음식을 토해 대접하자 더럽다며 칼로 베어 죽였습니다. 노한 아마테라스가 다시는 마주하지 않겠다고 하여 해와 달이 낮과 밤으로 나뉘어 뜨게 되었다고 합니다."],"sort_order":32},{"slug":"daebyeol-sobyeol","pantheon_slug":"korean","kind":"god","grade":null,"name":"대별왕과 소별왕","name_en":"Daebyeol and Sobyeol","epithet":"이승과 저승의 형제","domains":["궁술","저승","질서"],"summary":"해와 달이 둘씩 떠 혼란하던 세상에서 하나씩 활로 쏘아 질서를 세운 쌍둥이 형제입니다.","description":["제주 「천지왕본풀이」의 주인공으로, 천지왕과 총명부인의 아들입니다.","수수께끼 겨루기에서 꾀로 이긴 소별왕이 이승을, 대별왕이 저승을 맡았다고 합니다."],"sort_order":23},{"slug":"geotaji","pantheon_slug":"korean","kind":"hero","grade":null,"name":"거타지","name_en":"Geotaji","epithet":"늙은 여우를 쏜 궁사","domains":["궁술","악귀 퇴치"],"summary":"서해 용왕을 괴롭히던 늙은 여우를 활로 쏘아 죽인 신라의 궁사입니다.","description":["「삼국유사」에 실린 이야기로, 당나라로 가는 사신의 배에 탄 궁사였습니다.","용왕의 딸을 꽃으로 바꾸어 품에 넣고 돌아가 아내로 맞았습니다."],"sort_order":24},{"slug":"utturi","pantheon_slug":"korean","kind":"hero","grade":null,"name":"우투리","name_en":"Utturi","epithet":"날개 달린 아기 장수","domains":["영웅","운명"],"summary":"겨드랑이에 날개를 달고 태어났으나 뜻을 이루지 못한 지리산 전설의 아기 장수입니다.","description":["콩 한 말로 군사를 길러 새 세상을 열려 했으나 미리 들켜 죽임을 당했다고 합니다.","아기 장수 설화는 한국 곳곳에 비슷한 이야기로 전합니다."],"sort_order":25},{"slug":"jeon-u-chi","pantheon_slug":"korean","kind":"hero","grade":null,"name":"전우치","name_en":"Jeon Woo-chi","epithet":"도술을 부리는 선비","domains":["마법","속임수","정의"],"summary":"도술로 탐관오리를 골탕 먹이고 백성을 도운 「전우치전」의 주인공입니다.","description":["실존한 조선 중기의 도사가 바탕이 되었다고 합니다.","구름을 타고 다니며 그림 속으로 들어가 사라지는 이야기가 전합니다."],"sort_order":26},{"slug":"hong-gil-dong","pantheon_slug":"korean","kind":"hero","grade":null,"name":"홍길동","name_en":"Hong Gildong","epithet":"활빈당의 의적","domains":["정의","변신","속임수"],"summary":"서자로 태어나 활빈당을 이끌며 탐관오리의 재물을 빼앗아 백성에게 나눈 의적입니다.","description":["허균의 작품으로 전해지는 「홍길동전」의 주인공입니다.","여덟 명의 허수아비 분신을 만들어 조정을 놀라게 했고, 율도국의 왕이 되었다고 합니다."],"sort_order":27},{"slug":"seol-jukhwa","pantheon_slug":"korean","kind":"hero","grade":null,"name":"설죽화","name_en":"Seol Juk-hwa","epithet":"남장한 여장수","domains":["전쟁","용기","헌신"],"summary":"남장을 하고 거란군과 싸웠다는 고려의 여장수 전설입니다.","description":["귀주 대첩에 나가 싸우다 숨졌다는 이야기가 평안도 지방에 전합니다.","기록이 뒷날의 것이라 실존 여부는 확실하지 않습니다."],"sort_order":28},{"slug":"hyeonmu","pantheon_slug":"korean","kind":"monster","grade":"divine","name":"현무","name_en":"Hyeonmu","epithet":"북쪽을 지키는 거북과 뱀","domains":["북쪽","물","겨울"],"summary":"거북과 뱀이 한 몸으로 얽힌 신령한 짐승으로, 청룡·백호·주작과 함께 사방을 지키는 사신 가운데 북쪽을 맡습니다.","description":["사신은 하늘의 별자리를 동서남북으로 나누어 네 짐승으로 나타낸 것으로, 현무는 북쪽과 물, 겨울, 검은빛을 상징합니다. 중국 전국 시대 무렵부터 나타나 한나라 때 널리 퍼졌고, 무덤과 궁궐을 지키는 존재로 여겨졌습니다.","고구려 사람들은 무덤 방의 네 벽에 사신을 그려 죽은 이를 지키게 했는데, 7세기 무렵 강서대묘의 북벽에 그린 현무는 거북을 휘감은 뱀과 거북이 서로 마주 보는 모습으로 이름이 높습니다. 이 무덤들은 2004년 '고구려 고분군'으로 세계유산에 올랐습니다."],"sort_order":29},{"slug":"munmu","pantheon_slug":"korean","kind":"hero","grade":null,"name":"문무왕","name_en":"King Munmu","epithet":"바다의 용이 되어 나라를 지킨 왕","domains":["나라 지키기","바다"],"summary":"삼국 통일을 이룬 신라의 왕으로, 죽어서 바다의 용이 되어 나라를 지키겠다며 동해의 큰 바위에 묻혔다고 전합니다.","description":["「삼국사기」에 따르면 문무왕은 죽기 전에 자신을 화장해 동해에 장사 지내라고 유언했고, 신하들은 그 뜻대로 바다 어귀의 큰 바위에 장사 지냈습니다. 경주 앞바다의 대왕암이 그곳으로 전하며, 「삼국유사」는 왕이 용이 되어 왜병을 막겠다고 했다고 적었습니다.","아들 신문왕이 아버지를 위해 감은사를 완성한 뒤, 용이 된 문무왕과 하늘의 신이 된 김유신이 함께 보낸 대나무로 피리 만파식적을 만들었다는 이야기가 「삼국유사」에 전합니다."],"sort_order":30},{"slug":"hodong","pantheon_slug":"korean","kind":"hero","grade":null,"name":"호동왕자","name_en":"Prince Hodong","epithet":"자명고를 찢게 한 고구려의 왕자","domains":["사랑","전쟁"],"summary":"고구려 대무신왕의 아들로, 낙랑의 공주에게 적이 오면 저절로 울리는 북을 찢게 하여 낙랑을 무너뜨렸다고 「삼국사기」에 전하는 왕자입니다.","description":["「삼국사기」에 따르면 32년(대무신왕 15년) 옥저에 놀러 갔던 호동을 본 낙랑의 왕 최리는 그를 사위로 삼았습니다. 고구려로 돌아간 호동은 몰래 사람을 보내, 적이 오면 저절로 울리는 낙랑의 북과 나팔을 부수면 예를 갖추어 맞이하겠다고 공주에게 전했습니다.","공주가 북을 찢고 나팔을 부수자 고구려 군대가 들이닥쳤고, 낙랑은 항복했습니다. 그해 겨울 호동은 왕비의 모함을 받자 변명하지 않고 스스로 목숨을 끊었다고 합니다."],"sort_order":31},{"slug":"nangnang-princess","pantheon_slug":"korean","kind":"hero","grade":null,"name":"낙랑공주","name_en":"Princess of Nangnang","epithet":"자명고를 찢은 공주","domains":["사랑","희생"],"summary":"낙랑의 왕 최리의 딸로, 고구려 왕자 호동의 부탁을 받고 적이 오면 저절로 울리는 북을 찢었다가 아버지 손에 죽었다고 전합니다.","description":["「삼국사기」는 그녀의 이름을 전하지 않고 '최씨의 딸'이라고만 적었습니다. 남편 호동이 고구려로 돌아간 뒤 보낸 전갈을 받고, 그녀는 날카로운 칼을 들고 몰래 무기고에 들어가 북의 가죽을 찢고 나팔의 입을 부수었습니다.","북과 나팔이 울리지 않아 대비하지 못한 최리는 고구려 군대가 성 밑에 이른 뒤에야 그 까닭을 알았고, 딸을 죽인 뒤 나와 항복했습니다. 이 이야기는 뒷날 연극과 영화로 여러 번 다시 만들어졌습니다."],"sort_order":32},{"slug":"enkidu","pantheon_slug":"mesopotamian","kind":"hero","grade":null,"name":"엔키두","name_en":"Enkidu","epithet":"들판에서 빚어진 벗","domains":["야생","힘","짐승"],"summary":"신들이 길가메시와 맞서도록 진흙으로 빚은 야생의 사람으로, 길가메시의 둘도 없는 벗이 되었습니다.","description":["짐승들과 함께 살다가 사람의 세계로 들어와 길가메시와 겨룬 뒤 친구가 되었습니다.","함께 훔바바와 하늘의 황소를 쓰러뜨렸으나 신들의 벌로 병들어 죽었고, 이것이 길가메시를 불사의 탐색으로 이끌었습니다."],"sort_order":6},{"slug":"ereshkigal","pantheon_slug":"mesopotamian","kind":"god","grade":null,"name":"에레쉬키갈","name_en":"Ereshkigal","epithet":"저승의 여왕","domains":["저승","죽음"],"summary":"메소포타미아 저승 쿠르를 다스리는 여왕으로, 이슈타르의 언니입니다.","description":["「이난나의 저승 하강」에서 저승에 내려온 동생을 죽음에 이르게 합니다.","네르갈과 맺어져 함께 저승을 다스렸다는 이야기도 있습니다."],"sort_order":7},{"slug":"semiramis","pantheon_slug":"mesopotamian","kind":"hero","grade":null,"name":"세미라미스","name_en":"Semiramis","epithet":"전설의 여왕","domains":["왕권","정복"],"summary":"그리스 역사가들이 전한 아시리아의 전설적인 여왕입니다.","description":["비둘기가 길렀다는 출생 이야기와 바빌론을 세웠다는 이야기가 전합니다.","역사 속 섬무라마트 왕비가 바탕이 되었을 것으로 보기도 합니다."],"sort_order":8},{"slug":"shamash","pantheon_slug":"mesopotamian","kind":"god","grade":null,"name":"샤마시","name_en":"Shamash","epithet":"정의를 지키는 태양신","domains":["태양","정의","재판"],"summary":"날마다 하늘을 가로지르며 세상을 살피는 태양신으로, 정의와 법, 맹세와 재판을 맡았습니다.","description":["수메르어로는 우투, 아카드어로는 샤마시라 불렀습니다. 아침에 동쪽 산의 문을 열고 나와 하늘을 건너고 밤에는 저승을 지나 다시 동쪽으로 돌아온다고 여겼으며, 두 산 사이로 솟아오르며 톱니 칼을 든 모습으로 자주 새겨졌습니다.","모든 것을 보는 신이기에 재판과 점술을 맡았고, 함무라비 법전 비석 위쪽에도 왕이 이 신 앞에 선 모습이 새겨져 있습니다. 「길가메시 서사시」에서는 열세 바람을 보내 길가메시와 엔키두가 훔바바를 사로잡도록 돕습니다."],"sort_order":9},{"slug":"pazuzu","pantheon_slug":"mesopotamian","kind":"other","grade":null,"name":"파주주","name_en":"Pazuzu","epithet":"바람을 몰고 오는 악령의 왕","domains":["바람","역병","액막이"],"summary":"개 같은 얼굴에 네 날개와 새의 발톱, 전갈 꼬리를 한 바람의 악령으로, 그 무서운 힘 때문에 오히려 다른 악령을 쫓는 부적으로 쓰였습니다.","description":["파주주는 기원전 1천년기 아시리아와 바빌로니아의 주문과 부적에 나오는 악령으로, 악령 한비의 아들이자 바람 악령들의 왕이라고 합니다. 남서쪽에서 불어오는 바람을 타고 기근과 메뚜기 떼, 병을 몰고 온다고 여겼습니다.","같은 악한 힘으로 다른 악령을 막을 수 있다고 믿어, 산모와 갓난아이를 노리는 여악령 라마슈투를 쫓는 부적에 그 머리와 몸을 새겼습니다. 20세기에는 영화 「엑소시스트」에 나오면서 널리 알려졌습니다."],"sort_order":10},{"slug":"lamassu","pantheon_slug":"mesopotamian","kind":"other","grade":null,"name":"라마수","name_en":"Lamassu","epithet":"궁전 문을 지키는 날개 달린 수호신","domains":["수호","문","왕권"],"summary":"사람의 머리에 황소나 사자의 몸, 독수리의 날개를 한 아시리아의 수호신으로, 궁전과 성문 양쪽에 거대한 석상으로 세워졌습니다.","description":["라마수라는 이름은 사람을 곁에서 지켜 주는 수호령 '라마'에서 왔습니다. 기원전 9~7세기 아시리아 왕들은 님루드, 코르사바드, 니네베 궁전의 문마다 이 수호신을 한 쌍씩 세워 악한 기운이 들어오지 못하게 했습니다.","앞에서 보면 버티고 서 있고 옆에서 보면 걸어가는 것처럼 보이도록 다리를 다섯 개 새긴 것이 많습니다. 뿔 달린 관은 신성함을, 사람의 얼굴은 지혜를, 짐승의 몸은 힘을, 날개는 빠름을 나타낸다고 풉니다."],"sort_order":11},{"slug":"humbaba","pantheon_slug":"mesopotamian","kind":"monster","grade":"spirit","name":"훔바바","name_en":"Humbaba","epithet":"삼나무 숲의 파수꾼","domains":["삼나무 숲","수호","공포"],"summary":"엔릴이 삼나무 숲을 지키라고 세운 괴물로, 길가메시와 엔키두에게 목숨을 빌었지만 끝내 목이 베였습니다.","description":["훔바바(수메르어로 후와와)는 일곱 겹의 무서운 빛을 두른 삼나무 숲의 수호자입니다. 「길가메시 서사시」는 그의 외침은 홍수요, 입은 불이며, 숨결은 죽음이라고 묘사합니다.","샤마시가 보낸 바람에 붙들린 훔바바는 목숨을 빌었지만, 엔키두의 재촉에 길가메시가 목을 베었습니다. 신들은 훔바바와 하늘의 황소를 죽인 벌로 엔키두를 죽게 했다고 전하며, 창자처럼 주름진 그의 얼굴은 점술에 쓰는 가면과 부적으로도 만들어졌습니다."],"sort_order":12},{"slug":"anzu","pantheon_slug":"mesopotamian","kind":"monster","grade":"divine","name":"안주","name_en":"Anzu","epithet":"운명의 서판을 훔친 사자 머리 독수리","domains":["폭풍","하늘","새"],"summary":"사자 머리를 한 거대한 독수리로, 엔릴에게서 운명의 서판을 훔쳤다가 전쟁의 신 닌우르타에게 쓰러졌습니다.","description":["수메르에서는 임두구드라 불렀으며, 날개를 펴고 두 짐승을 움켜쥔 모습이 라가시의 신 닌기르수의 상징으로 쓰였습니다. 날갯짓으로 회오리바람과 폭풍을 일으킨다고 여겼습니다.","「안주 이야기」에 따르면 엔릴이 몸을 씻는 사이 안주가 운명의 서판을 훔쳐 산으로 달아났습니다. 서판의 힘에 신들의 무기가 모두 되돌아갔지만, 닌우르타가 에아의 꾀를 따라 날개를 꺾고 화살로 쏘아 서판을 되찾았습니다."],"sort_order":13},{"slug":"enlil","pantheon_slug":"mesopotamian","kind":"god","grade":null,"name":"엔릴","name_en":"Enlil","epithet":"바람과 대기의 주인","domains":["바람","대기","왕권"],"summary":"니푸르의 에쿠르 신전에서 섬긴 바람과 대기의 신으로, 오랫동안 신들 가운데 실제로 세상을 다스리는 왕으로 여겨졌습니다.","description":["이름은 수메르어로 '바람의 주인'이라는 뜻입니다. 하늘의 신 안의 아들로 하늘과 땅을 갈라놓았다고 하며, 운명의 서판을 지니고 왕권을 내려 주는 신으로 섬겨졌습니다. 그 서판을 사자 머리 독수리 안주가 훔쳐 달아난 이야기도 전합니다.","「아트라하시스」에서는 사람들이 내는 소음 때문에 잠을 이루지 못해 역병과 가뭄을 보내고 끝내 홍수로 인류를 쓸어버리려 했습니다. 바빌로니아가 커지면서 신들의 왕 자리는 차츰 마르두크에게 넘어갔습니다."],"sort_order":14},{"slug":"nergal","pantheon_slug":"mesopotamian","kind":"god","grade":null,"name":"네르갈","name_en":"Nergal","epithet":"역병과 전쟁, 저승의 신","domains":["저승","역병","전쟁"],"summary":"쿠타에서 섬긴 역병과 전쟁의 신으로, 저승의 여왕 에레쉬키갈의 남편이 되어 저승을 함께 다스렸습니다.","description":["「네르갈과 에레쉬키갈」에 따르면 신들의 잔치에 에레쉬키갈이 보낸 사자 남타르가 오자 다른 신들은 모두 일어섰지만 네르갈만 일어나지 않았습니다. 이 무례 때문에 저승으로 불려 간 네르갈은 에레쉬키갈의 남편이 되었는데, 판본에 따라 힘으로 그녀를 굴복시켰다고도 하고 여러 날 함께 지낸 끝에 저승에 남게 되었다고도 합니다.","한낮의 뜨거운 햇볕과 역병, 전쟁의 파괴를 다스린다고 여겼고, 바빌로니아 천문에서는 붉은 행성인 화성과 이어졌습니다. 「에라 서사시」의 역병 신 에라와도 같은 신으로 보았습니다."],"sort_order":15},{"slug":"ninurta","pantheon_slug":"mesopotamian","kind":"god","grade":null,"name":"닌우르타","name_en":"Ninurta","epithet":"괴물을 무찌르는 전쟁과 농사의 신","domains":["전쟁","농사","사냥"],"summary":"엔릴의 아들인 전쟁의 신으로, 말하는 철퇴 샤루르를 들고 돌 괴물 아사그와 사자 머리 독수리 안주를 무찔렀습니다.","description":["수메르 시 「루갈에」에서 닌우르타는 산에서 돌의 군대를 거느리고 일어난 괴물 아사그를 무찌르고, 그 돌들을 쌓아 티그리스강의 물을 들판으로 돌렸다고 합니다. 바빌로니아의 「안주 이야기」에서는 엔릴에게서 운명의 서판을 훔친 안주를 쏘아 떨어뜨려 서판을 되찾았습니다.","싸움의 신이면서 쟁기를 다루는 농사의 신이기도 했고, 니푸르에서 아버지 엔릴과 함께 섬겨졌습니다. 라가시의 신 닌기르수와 같은 신으로 여겨졌으며, 아시리아 왕들이 특히 높이 받들었습니다."],"sort_order":16},{"slug":"utnapishtim","pantheon_slug":"mesopotamian","kind":"hero","grade":null,"name":"우트나피시팀","name_en":"Utnapishtim","epithet":"홍수에서 살아남아 영생을 얻은 사람","domains":["홍수","영생"],"summary":"「길가메시 서사시」에서 신들이 보낸 큰 홍수를 배를 지어 견뎌 내고, 신들에게서 영원한 생명을 얻은 슈루팍의 왕입니다.","description":["신들이 홍수로 사람을 쓸어버리기로 하자, 지혜의 신 에아가 갈대 집 벽에 대고 말하는 꾀로 우트나피시팀에게 이를 알렸습니다. 그는 집을 허물어 큰 배를 짓고 가족과 장인들, 짐승들을 태웠으며, 엿새 낮과 이레 밤 동안 몰아친 폭풍이 그친 뒤 배는 니무시산에 걸렸습니다. 그는 비둘기와 제비, 까마귀를 차례로 날려 물이 빠졌는지 알아보았습니다.","신들은 그와 아내를 죽지 않게 하여 강들의 어귀 먼 곳에 살게 했습니다. 영생을 찾아온 길가메시에게 그는 엿새 낮과 이레 밤을 잠들지 말아 보라 했지만 길가메시는 곧 잠들어 버렸고, 떠나는 길가메시에게 바다 밑 젊음의 풀이 있는 곳을 알려 주었습니다."],"sort_order":17},{"slug":"sigurd","pantheon_slug":"norse","kind":"hero","grade":null,"name":"시구르드","name_en":"Sigurd","epithet":"용을 죽인 자","domains":["영웅","용기","운명"],"summary":"용 파프니르를 죽이고 그 피로 새의 말을 알아듣게 된 볼숭 가문의 영웅입니다.","description":["「볼숭가 사가」와 「에다」에 나오며, 부러진 아버지의 검을 다시 벼린 그람으로 파프니르를 쓰러뜨렸습니다.","발키리 브륀힐드와 사랑을 맹세했지만 망각의 약으로 그녀를 잊으며 비극을 맞았습니다."],"sort_order":9},{"slug":"brynhild","pantheon_slug":"norse","kind":"hero","grade":null,"name":"브륀힐드","name_en":"Brynhild","epithet":"불꽃 속의 발키리","domains":["전쟁","운명","복수"],"summary":"오딘의 뜻을 거슬러 불꽃 울타리 속에 잠든 발키리입니다.","description":["불꽃을 넘어온 시구르드와 사랑을 맹세했습니다.","속임수로 군나르와 결혼하게 되자 시구르드의 죽음을 꾀하고 스스로 장작더미에 올랐다고 합니다."],"sort_order":10},{"slug":"skadi","pantheon_slug":"norse","kind":"god","grade":null,"name":"스카디","name_en":"Skaði","epithet":"눈과 사냥의 여신","domains":["사냥","산","복수"],"summary":"아버지 티아지의 복수를 위해 아스가르드를 찾아온 거인 출신의 여신입니다.","description":["보상으로 신들 가운데 발만 보고 남편을 고르게 되어 바다의 신 뇨르드와 결혼했습니다.","스키를 타고 활을 쏘는 겨울 산의 사냥꾼으로 그려집니다."],"sort_order":11},{"slug":"tjalfi","pantheon_slug":"norse","kind":"hero","grade":null,"name":"티알피","name_en":"Þjálfi","epithet":"토르의 시종","domains":["여행","헌신"],"summary":"토르와 함께 거인들의 땅을 여행한 발 빠른 시종입니다.","description":["염소의 뼈를 부러뜨린 벌로 누이 뢰스크바와 함께 토르를 섬기게 되었습니다.","우트가르드에서 생각과 달리기 시합을 해 졌다는 이야기가 있습니다."],"sort_order":12},{"slug":"skirnir","pantheon_slug":"norse","kind":"hero","grade":null,"name":"스키르니르","name_en":"Skírnir","epithet":"프레이르의 사자","domains":["전령","여행"],"summary":"프레이르를 대신해 거인 게르드에게 청혼하러 간 사자입니다.","description":["프레이르의 검을 받고 불꽃을 넘어 게르드를 찾아갔습니다.","「스키르니르의 여행」이 그 이야기를 전합니다."],"sort_order":13},{"slug":"romulus","pantheon_slug":"roman","kind":"hero","grade":null,"name":"로물루스","name_en":"Romulus","epithet":"로마의 건국자","domains":["건국","전쟁","왕권"],"summary":"늑대가 젖을 먹여 기른 쌍둥이 가운데 하나로, 로마를 세운 첫 왕입니다.","description":["동생 레무스와 도시 세울 자리를 두고 다투다 그를 죽였습니다.","폭풍 속에 사라진 뒤 신 퀴리누스가 되었다고 리비우스가 전합니다."],"sort_order":1},{"slug":"camilla","pantheon_slug":"roman","kind":"hero","grade":null,"name":"카밀라","name_en":"Camilla","epithet":"볼스키의 여전사","domains":["전쟁","사냥"],"summary":"「아이네이스」에서 아이네이아스에 맞서 싸운 볼스키족의 여전사입니다.","description":["디아나에게 바쳐져 숲에서 자랐습니다.","곡식 이삭 위를 달려도 쓰러뜨리지 않을 만큼 빨랐다고 베르길리우스가 노래합니다."],"sort_order":2},{"slug":"aeneas","pantheon_slug":"roman","kind":"hero","grade":null,"name":"아이네이아스","name_en":"Aeneas","epithet":"트로이의 생존자","domains":["건국","운명","헌신"],"summary":"불타는 트로이에서 아버지를 업고 빠져나와 로마의 시조가 된 영웅입니다.","description":["베르길리우스의 「아이네이스」는 그의 방랑과 이탈리아 정착을 노래합니다.","카르타고의 여왕 디도와의 사랑을 뒤로하고 운명을 따랐습니다."],"sort_order":3},{"slug":"dobrynya","pantheon_slug":"slavic","kind":"hero","grade":null,"name":"도브리냐 니키티치","name_en":"Dobrynya Nikitich","epithet":"뱀을 물리친 용사","domains":["영웅","용기","악귀 퇴치"],"summary":"러시아 서사시 브일리나의 세 용사 가운데 하나로, 용 고리니치를 물리쳤습니다.","description":["키예프의 블라디미르 대공을 섬긴 용사로 노래됩니다.","일리야 무로메츠, 알료샤 포포비치와 함께 '세 용사'로 그려집니다."],"sort_order":4},{"slug":"ilya-muromets","pantheon_slug":"slavic","kind":"hero","grade":null,"name":"일리야 무로메츠","name_en":"Ilya Muromets","epithet":"서른셋에 일어선 용사","domains":["힘","영웅","수호"],"summary":"서른세 해 동안 걷지 못하다 순례자의 힘을 얻어 일어선 러시아 브일리나의 으뜸 용사입니다.","description":["도적 솔로베이 라즈보이니크를 사로잡아 키예프로 끌고 왔습니다.","세 용사 가운데 맏이로 그려집니다."],"sort_order":5},{"slug":"koschei","pantheon_slug":"slavic","kind":"other","grade":null,"name":"죽지 않는 코셰이","name_en":"Koschei the Deathless","epithet":"죽음을 숨긴 마법사","domains":["불사","마법","악"],"summary":"자신의 죽음을 바늘 끝에 숨겨 죽지 않는다는 러시아 옛이야기의 악당입니다.","description":["바늘은 알 속에, 알은 오리 속에, 오리는 토끼 속에 숨겨져 있다고 합니다.","공주를 납치하는 악당으로 자주 등장합니다."],"sort_order":6},{"slug":"marko-kraljevic","pantheon_slug":"slavic","kind":"hero","grade":null,"name":"마르코 크랄례비치","name_en":"Prince Marko","epithet":"세르비아 서사시의 왕자","domains":["영웅","힘","정의"],"summary":"얼룩말 샤라츠를 타고 다니는 세르비아 서사시의 영웅입니다.","description":["역사 속 14세기 왕자가 서사시 속에서 장사로 그려졌습니다.","요정 빌라와 의형제를 맺었다는 이야기가 있습니다."],"sort_order":7},{"slug":"bruncvik","pantheon_slug":"slavic","kind":"hero","grade":null,"name":"브룬츠비크","name_en":"Bruncvík","epithet":"사자를 데려온 기사","domains":["영웅","모험","짐승"],"summary":"사자를 구해 함께 돌아왔다는 체코 전설의 기사로, 프라하의 상징이 되었습니다.","description":["스스로 휘두르는 신비한 검을 지녔다고 전합니다.","카를교 아래 기둥에 그의 석상이 서 있습니다."],"sort_order":8},{"slug":"sadko","pantheon_slug":"slavic","kind":"hero","grade":null,"name":"사드코","name_en":"Sadko","epithet":"구슬리를 켜는 노브고로드의 상인","domains":["음악","상업","바다"],"summary":"구슬리 연주로 바다 왕의 마음을 얻어 큰 부자가 된 노브고로드의 상인입니다.","description":["노브고로드의 브일리나에 나오는 사드코는 연회에서 구슬리를 켜던 가난한 악사였습니다. 일멘 호숫가에서 그가 켠 노래에 기뻐한 바다 왕이 호수의 황금 지느러미 물고기를 두고 내기를 걸라고 일러 주었고, 내기에 이긴 사드코는 큰 부자 상인이 되었습니다.","뒷날 그의 배가 바다 한가운데서 꼼짝하지 않자, 사드코는 바다 왕에게 바쳐지려고 홀로 물속 궁전으로 내려갔습니다. 그가 구슬리를 켜자 바다 왕이 춤을 추어 폭풍이 일었고, 성 니콜라이의 말대로 줄을 끊어 춤을 멈추게 한 뒤 노브고로드로 돌아왔습니다."],"sort_order":9},{"slug":"vasilisa","pantheon_slug":"slavic","kind":"hero","grade":null,"name":"아름다운 바실리사","name_en":"Vasilisa the Beautiful","epithet":"바바 야가의 집에서 돌아온 소녀","domains":["지혜","어머니의 축복"],"summary":"어머니가 남긴 인형의 도움으로 바바 야가의 시험을 견디고 돌아온 러시아 민담의 소녀입니다.","description":["어머니는 죽으며 바실리사에게 작은 인형을 남겼는데, 먹을 것을 주면 인형이 그녀를 도와주었습니다. 계모와 의붓언니들이 일부러 불을 꺼뜨리고 그녀를 숲속 바바 야가의 집으로 불씨를 얻으러 보내자, 바실리사는 인형의 도움으로 바바 야가가 시킨 일을 모두 해냈습니다.","바바 야가는 눈에서 불이 타는 해골 등불을 주어 그녀를 돌려보냈고, 집에 돌아오자 그 불빛이 계모와 언니들을 태워 버렸습니다. 뒷날 그녀가 짠 고운 아마포가 차르의 눈에 들어 왕비가 되었다고 합니다(아파나시예프 민담집)."],"sort_order":10},{"slug":"alyosha-popovich","pantheon_slug":"slavic","kind":"hero","grade":null,"name":"알료샤 포포비치","name_en":"Alyosha Popovich","epithet":"꾀 많은 막내 용사","domains":["용맹","꾀"],"summary":"일리야 무로메츠, 도브리냐 니키티치와 함께 러시아의 세 용사로 꼽히는, 로스토프 사제의 아들인 젊은 용사입니다.","description":["이름은 '사제의 아들 알료샤'라는 뜻으로, 브일리나에서 그는 힘보다 재치와 꾀로 이기는 용사로 그려집니다. 가장 이름난 이야기에서 그는 키예프를 위협하던 괴물 투가린 즈메예비치를 꾀를 써서 쓰러뜨립니다.","허풍이 세고 여자를 좋아하는 모습도 함께 그려져, 도브리냐가 집을 비운 사이 그가 죽었다는 거짓 소식을 퍼뜨리고 그의 아내에게 청혼했다가 망신을 당하는 이야기도 전합니다."],"sort_order":11},{"slug":"rusalka","pantheon_slug":"slavic","kind":"other","grade":null,"name":"루살카","name_en":"Rusalka","epithet":"물가에 사는 처녀 혼령","domains":["물","숲과 들판","죽음"],"summary":"강과 호수에 산다는 젊은 여인의 혼령으로, 초여름 '루살카 주간'에 물 밖으로 나와 사람을 홀린다고 여겨졌습니다.","description":["19세기 민속 기록에서 루살카는 흔히 물에 빠져 죽었거나 혼인하지 못하고 일찍 죽은 처녀의 혼령으로, 긴 머리를 풀어 헤친 창백한 모습이라고 합니다.","성령강림절 무렵의 '루살카 주간'에 물에서 나와 숲과 들판에서 그네를 타고 춤추며, 지나가는 사람을 간지럼 태워 죽이거나 물속으로 끌어들인다고 여겨졌습니다. 드보르자크의 오페라 「루살카」(1901)는 이 정령을 사랑에 빠진 물의 요정으로 그렸습니다."],"sort_order":12},{"slug":"firebird","pantheon_slug":"slavic","kind":"monster","grade":"spirit","name":"불새","name_en":"Firebird","epithet":"황금 사과를 훔치는 빛나는 새","domains":["빛","탐색"],"summary":"깃털 하나로도 어둠을 밝힌다는 빛나는 새로, 러시아 민담에서 왕자들이 찾아 나서는 보물입니다.","description":["아파나시예프가 모은 「이반 왕자와 불새와 회색 늑대」에서 불새는 밤마다 왕의 정원에 날아와 황금 사과를 훔쳐 먹습니다. 막내 이반 왕자가 지키다 꼬리 깃털 하나를 뽑았는데, 그 깃털은 어두운 방을 환히 밝힐 만큼 빛났습니다.","왕이 새를 잡아 오라며 아들들을 떠나보내자, 이반은 회색 늑대의 도움으로 불새와 함께 황금 갈기의 말과 아름다운 공주까지 얻습니다. 불새를 찾는 일은 흔히 주인공을 시련으로 이끄는 시작이 되며, 스트라빈스키의 발레 「불새」(1910)로 널리 알려졌습니다."],"sort_order":13},{"slug":"zmey-gorynych","pantheon_slug":"slavic","kind":"monster","grade":"spirit","name":"즈메이 고리니치","name_en":"Zmey Gorynych","epithet":"머리 여럿 달린 산의 용","domains":["불","산","약탈"],"summary":"러시아 브일리나와 민담에 나오는 머리 여럿 달린 용으로, 불을 뿜으며 날아다니고 사람을 잡아갑니다.","description":["이름은 흔히 '산의 아들인 용'으로 풀이되며, 머리가 셋, 여섯, 열둘처럼 여럿인 모습으로 그려집니다. 브일리나 「도브리냐와 용」에서 도브리냐 니키티치는 푸차이강에서 헤엄치다 덮쳐 온 이 용을 꺾고, 다시는 러시아 땅에 오지 않겠다는 약속을 받아 냅니다.","그러나 용은 약속을 어기고 키예프 블라디미르 대공의 조카딸 자바바를 잡아갔고, 도브리냐는 용의 굴로 쳐들어가 그를 죽이고 붙잡혀 있던 사람들을 구해 냈습니다."],"sort_order":14},{"slug":"sirin-alkonost","pantheon_slug":"slavic","kind":"monster","grade":"spirit","name":"시린과 알코노스트","name_en":"Sirin and Alkonost","epithet":"여인의 얼굴을 한 낙원의 새","domains":["노래","기쁨과 슬픔","낙원"],"summary":"여인의 머리를 한 러시아 전설의 두 새로, 알코노스트는 기쁨을, 시린은 슬픔과 불행을 노래한다고 합니다.","description":["중세 러시아의 책과 민간 그림에서 둘은 낙원에 사는 새로 함께 그려졌습니다. 알코노스트의 노래를 들은 사람은 모든 것을 잊는다고 하며, 그녀가 알을 바다에 굴려 넣은 동안에는 폭풍이 일지 않는다고 합니다.","민간 전승에서는 사과 구세주 축일 아침에 시린이 과수원에 날아와 슬피 울고, 오후에는 알코노스트가 날아와 기뻐 웃으며 날개의 이슬로 열매에 병을 낫게 하는 힘을 준다고 합니다. 빅토르 바스네초프는 두 새를 「기쁨과 슬픔의 노래」라는 그림으로 남겼습니다."],"sort_order":15},{"slug":"erkhii-mergen","pantheon_slug":"turko-mongol","kind":"hero","grade":null,"name":"에르히 메르겡","name_en":"Erkhii Mergen","epithet":"해를 쏜 명궁","domains":["궁술","태양"],"summary":"하늘에 뜬 일곱 해 가운데 여섯을 쏘아 떨어뜨렸다는 몽골의 명궁입니다.","description":["마지막 해를 쏘지 못하면 엄지를 자르고 사람으로 살지 않겠다고 맹세했습니다.","제비가 화살 앞을 지나가 마지막 해를 놓쳤고, 그는 마멋이 되었다고 합니다."],"sort_order":1},{"slug":"alip-manash","pantheon_slug":"turko-mongol","kind":"hero","grade":null,"name":"알립마나시","name_en":"Alyp-Manash","epithet":"알타이의 용사","domains":["영웅","모험"],"summary":"알타이 서사시의 용사로, 오랜 포로 생활 끝에 고향으로 돌아와 배신자들을 벌했습니다.","description":["오디세우스의 귀향 이야기와 닮은 줄거리로 알려졌습니다.","충실한 말과 아내의 도움을 받습니다."],"sort_order":2},{"slug":"cerberus","pantheon_slug":"greek","kind":"monster","grade":"common","name":"케르베로스","name_en":"Cerberus","epithet":"저승 문을 지키는 개","domains":["저승","문지기"],"summary":"머리가 여럿 달린 몸으로 저승의 문을 지키며, 죽은 이가 빠져나가지 못하게 막는 하데스의 개입니다.","description":["헤시오도스는 케르베로스를 괴물 티폰과 에키드나의 자식으로 적었고, 대개 머리가 셋 달린 개로 그립니다. 산 사람이 들어오는 것은 막지 않지만, 죽은 이가 나가려 하면 붙잡았다고 합니다.","헤라클레스의 열두 과업 가운데 마지막이 케르베로스를 무기 없이 붙잡아 지상으로 끌고 오는 일이었습니다. 오르페우스는 리라 연주로, 아이네이아스 일행은 꿀 과자로 그를 잠재우고 저승을 지나갔습니다."],"sort_order":48},{"slug":"minotaur","pantheon_slug":"greek","kind":"monster","grade":"common","name":"미노타우로스","name_en":"Minotaur","epithet":"미궁의 황소 인간","domains":["미궁","제물"],"summary":"황소의 머리에 사람의 몸을 한 괴물로, 크레타의 미궁에 갇혀 아테네의 젊은이들을 제물로 받았습니다.","description":["크레타의 왕비 파시파에와 포세이돈이 보낸 흰 황소 사이에서 태어났다고 전합니다. 미노스 왕은 다이달로스에게 빠져나올 수 없는 미궁 라비린토스를 짓게 해 그를 가두었습니다.","아테네는 해마다 젊은 남녀를 제물로 보내야 했고, 영웅 테세우스가 그 가운데 끼어 미궁에 들어가 미노타우로스를 죽였습니다. 공주 아리아드네가 준 실타래를 따라 미궁을 빠져나왔습니다."],"sort_order":49},{"slug":"hydra","pantheon_slug":"greek","kind":"monster","grade":"common","name":"히드라","name_en":"Lernaean Hydra","epithet":"머리가 다시 자라는 물뱀","domains":["독","늪","재생"],"summary":"레르나의 늪에 살던 머리 여럿 달린 물뱀으로, 머리 하나를 자르면 두 개가 새로 자랐습니다.","description":["히드라는 티폰과 에키드나의 자식으로, 숨결과 피에 독이 있었다고 합니다. 헤라클레스의 두 번째 과업이 히드라를 물리치는 일이었습니다.","잘라도 다시 자라는 머리 때문에 애를 먹던 헤라클레스는 조카 이올라오스가 자른 자리를 횃불로 지지게 해 마침내 이겼습니다. 그 뒤 화살을 히드라의 독에 적셔 썼습니다."],"sort_order":50},{"slug":"chimera","pantheon_slug":"greek","kind":"monster","grade":"common","name":"키마이라","name_en":"Chimera","epithet":"불을 뿜는 세 몸의 괴물","domains":["불","혼종"],"summary":"사자의 머리, 염소의 몸, 뱀의 꼬리를 하고 불을 뿜었다는 리키아의 괴물입니다.","description":["「일리아스」는 키마이라를 앞은 사자, 가운데는 염소, 뒤는 뱀이며 무서운 불길을 내뿜는다고 묘사합니다. 그림과 조각에서는 흔히 등에 염소 머리가 하나 더 솟아 있습니다.","영웅 벨레로폰은 날개 달린 말 페가수스를 타고 하늘에서 화살을 쏘아 키마이라를 물리쳤습니다. 오늘날 여러 동물이 섞인 존재를 키메라라 부르는 말이 여기서 나왔습니다."],"sort_order":51},{"slug":"pegasus","pantheon_slug":"greek","kind":"monster","grade":"spirit","name":"페가수스","name_en":"Pegasus","epithet":"날개 달린 말","domains":["하늘","영감"],"summary":"메두사의 목에서 태어난 날개 달린 말로, 영웅 벨레로폰을 태우고 키마이라와 싸웠습니다.","description":["페르세우스가 메두사의 목을 베었을 때, 그 피에서 페가수스가 태어났다고 전합니다. 페가수스가 발굽으로 헬리콘산을 차자 시인들의 샘 히포크레네가 솟았다고 합니다.","벨레로폰은 아테나가 준 황금 굴레로 페가수스를 길들여 키마이라를 물리쳤지만, 뒤에 신들의 산 올림포스까지 날아오르려다 떨어졌습니다. 페가수스는 하늘에 올라 별자리가 되었습니다."],"sort_order":52},{"slug":"polyphemus","pantheon_slug":"greek","kind":"monster","grade":"spirit","name":"폴리페모스","name_en":"Polyphemus","epithet":"외눈박이 거인 키클롭스","domains":["거인","목축"],"summary":"이마 가운데 눈이 하나뿐인 거인 키클롭스로, 「오디세이아」에서 오디세우스 일행을 동굴에 가두었습니다.","description":["폴리페모스는 포세이돈의 아들로, 섬에서 양을 치며 살던 외눈박이 거인입니다. 오디세우스 일행이 그의 동굴에 들어가자 입구를 바위로 막고 부하들을 잡아먹었습니다.","오디세우스는 자기 이름을 ‘아무도 아니’라고 속이고 거인에게 술을 먹여 재운 뒤 그 눈을 찔렀습니다. 다른 키클롭스들이 누가 그랬냐 묻자 폴리페모스는 ‘아무도 아니’라고 외칠 수밖에 없었습니다."],"sort_order":53},{"slug":"typhon","pantheon_slug":"greek","kind":"monster","grade":"divine","name":"티폰","name_en":"Typhon","epithet":"신들과 맞선 가장 큰 괴물","domains":["폭풍","혼돈"],"summary":"어깨에서 뱀 머리 백 개가 솟았다는 거대한 괴물로, 제우스와 하늘의 주인 자리를 두고 싸웠습니다.","description":["헤시오도스의 「신들의 계보」에 따르면 티폰은 대지의 여신 가이아의 막내아들로, 어깨에서 뱀 머리 백 개가 자라고 눈에서 불을 뿜었습니다. 많은 괴물을 낳은 에키드나의 짝이기도 합니다.","제우스는 벼락으로 티폰을 물리쳐 타르타로스에 가두었습니다. 시칠리아의 에트나 화산이 티폰을 짓누르고 있는 산이라는 이야기도 전합니다."],"sort_order":54},{"slug":"talos","pantheon_slug":"greek","kind":"monster","grade":"common","name":"탈로스","name_en":"Talos","epithet":"크레타를 지킨 청동 거인","domains":["수호","청동"],"summary":"헤파이스토스가 만든 청동 거인으로, 하루 세 번 크레타섬을 돌며 바위를 던져 침입자를 막았습니다.","description":["탈로스는 대장장이 신 헤파이스토스가 만들어 미노스 왕에게 준, 또는 제우스가 에우로페에게 준 청동 거인이라고 전합니다. 몸에 흐르는 단 하나의 핏줄을 발목의 못이 막고 있었습니다.","아르고호 원정대가 크레타에 다가가자 탈로스가 바위를 던져 막았습니다. 마녀 메데이아가 그를 홀린 사이 발목의 못이 빠지면서 피가 흘러나와 쓰러졌다고 합니다."],"sort_order":55},{"slug":"fenrir","pantheon_slug":"norse","kind":"monster","grade":"divine","name":"펜리르","name_en":"Fenrir","epithet":"신들이 묶어 둔 거대한 늑대","domains":["파멸","속박"],"summary":"로키의 자식인 거대한 늑대로, 신들이 마법 끈으로 묶어 두었지만 라그나로크에 풀려나 오딘을 삼킨다고 합니다.","description":["신들은 갈수록 커지는 펜리르를 두려워해 쇠사슬로 두 번 묶었지만 모두 끊어졌습니다. 세 번째로 난쟁이들이 고양이 발소리, 물고기 숨결 같은 것으로 만든 끈 글레이프니르로 묶었습니다.","펜리르가 의심하자 티르가 믿음의 표시로 그 입에 손을 넣었고, 끈이 풀리지 않자 펜리르는 티르의 손을 물어뜯었습니다. 라그나로크에 풀려난 펜리르는 오딘을 삼키고, 오딘의 아들 비다르에게 죽는다고 전합니다."],"sort_order":14},{"slug":"jormungandr","pantheon_slug":"norse","kind":"monster","grade":"divine","name":"요르문간드","name_en":"Jörmungandr","epithet":"세상을 감은 뱀","domains":["바다","파멸"],"summary":"인간 세상 미드가르드를 한 바퀴 감고 제 꼬리를 문 거대한 바다뱀으로, 토르의 숙적입니다.","description":["로키의 자식인 요르문간드는 오딘이 바다에 던진 뒤 자라고 자라 온 세상을 감을 만큼 커졌다고 합니다. 그래서 ‘미드가르드의 뱀’이라고도 부릅니다.","토르는 거인 히미르와 고기잡이를 나가 황소 머리를 미끼로 요르문간드를 낚아 올렸지만, 겁에 질린 히미르가 줄을 끊어 놓쳤습니다. 라그나로크에 둘은 다시 맞서, 토르는 뱀을 죽이고 그 독에 아홉 걸음을 걸은 뒤 쓰러진다고 전합니다."],"sort_order":15},{"slug":"sleipnir","pantheon_slug":"norse","kind":"monster","grade":"spirit","name":"슬레이프니르","name_en":"Sleipnir","epithet":"오딘의 여덟 다리 말","domains":["여행","저승길"],"summary":"다리가 여덟 개인 회색 말로, 오딘을 태우고 하늘과 바다, 저승까지 달렸습니다.","description":["신들의 성벽을 쌓던 거인의 말을 로키가 암말로 변해 꾀어내는 바람에 성벽은 약속한 날까지 완성되지 못했고, 로키는 그 말과의 사이에서 슬레이프니르를 낳았다고 「산문 에다」는 전합니다.","슬레이프니르는 모든 말 가운데 가장 뛰어났다고 하며, 오딘의 아들 헤르모드는 죽은 발드르를 데려오려고 이 말을 타고 저승의 문을 뛰어넘었습니다."],"sort_order":16},{"slug":"nidhogg","pantheon_slug":"norse","kind":"monster","grade":"divine","name":"니드호그","name_en":"Níðhöggr","epithet":"세계수의 뿌리를 갉는 용","domains":["죽음","파멸"],"summary":"세계수 이그드라실의 뿌리를 갉아 먹고, 저승에서 죄지은 자들의 시체를 뜯는다는 용입니다.","description":["「에다」에 따르면 니드호그는 이그드라실의 세 뿌리 가운데 하나 아래, 흐베르겔미르 샘 곁에서 뿌리를 갉아 먹습니다. 다람쥐 라타토스크가 나무를 오르내리며 꼭대기의 독수리와 니드호그 사이에 욕설을 전한다고 합니다.","예언의 시 「뵐루스파」는 맹세를 깨뜨린 자와 살인자들이 가는 곳에서 니드호그가 시체를 뜯는다고 노래합니다."],"sort_order":17},{"slug":"huginn-muninn","pantheon_slug":"norse","kind":"monster","grade":"spirit","name":"후긴과 무닌","name_en":"Huginn and Muninn","epithet":"오딘의 두 까마귀","domains":["생각","기억","소식"],"summary":"‘생각’과 ‘기억’이라는 뜻의 이름을 가진 두 까마귀로, 날마다 세상을 날아다니며 오딘에게 소식을 전합니다.","description":["후긴과 무닌은 아침마다 온 세상을 날아다니고, 저녁이면 돌아와 오딘의 어깨에 앉아 보고 들은 것을 귀에 속삭인다고 합니다.","「그림니르의 노래」에서 오딘은 후긴이 돌아오지 않을까 걱정하지만 무닌이 더 걱정된다고 말합니다. 오딘을 ‘까마귀의 신’이라 부르는 이름도 여기서 나왔습니다."],"sort_order":18},{"slug":"fafnir","pantheon_slug":"norse","kind":"monster","grade":"spirit","name":"파프니르","name_en":"Fáfnir","epithet":"보물을 지키는 용","domains":["욕심","보물","독"],"summary":"아버지를 죽이고 저주받은 황금을 차지한 뒤 용으로 변해 보물을 지키다가 영웅 시구르드에게 죽은 존재입니다.","description":["파프니르는 난쟁이 왕 흐레이드마르의 아들로, 신들이 배상으로 내놓은 난쟁이 안드바리의 황금을 탐내 아버지를 죽였습니다. 그 황금에는 가진 자를 파멸시키는 저주가 걸려 있었습니다.","용으로 변해 보물을 지키던 파프니르는 동생 레긴의 꾐을 받은 시구르드가 길에 판 구덩이에 숨어 아래에서 칼을 찔러 죽였습니다. 그 피를 맛본 시구르드는 새들의 말을 알아들을 수 있게 되었다고 「볼숭가 사가」는 전합니다."],"sort_order":19},{"slug":"freyr","pantheon_slug":"norse","kind":"god","grade":null,"name":"프레이르","name_en":"Freyr","epithet":"풍요와 평화의 신","domains":["풍요","비와 햇빛","평화"],"summary":"바니르 신족 뇨르드의 아들이자 프레이야의 오빠로, 비와 햇빛과 땅의 소출을 다스리는 신입니다.","description":["「스노리 에다」는 그를 가장 이름난 신 가운데 하나로 꼽으며, 풍년과 평화를 빌 때 그를 부른다고 적었습니다. 황금 털 멧돼지 굴린부르스티가 끄는 수레를 탔고, 접어서 주머니에 넣을 수 있는 배 스키드블라드니르를 지녔습니다.","거인의 딸 게르드에게 반해 하인 스키르니르를 청혼하러 보내면서 스스로 싸우는 칼을 내주었습니다. 그 때문에 라그나로크에는 칼 없이 불의 거인 수르트와 맞서다 쓰러진다고 합니다."],"sort_order":20},{"slug":"hel","pantheon_slug":"norse","kind":"god","grade":null,"name":"헬","name_en":"Hel","epithet":"죽은 이들의 나라를 다스리는 여주인","domains":["저승","죽음"],"summary":"로키와 여자 거인 앙그르보다의 딸로, 병들거나 늙어 죽은 이들이 가는 저승 헬을 다스립니다.","description":["오딘은 로키의 자식들이 신들에게 큰 화를 부르리라는 예언을 듣고 헬을 니플헤임으로 던져, 그곳으로 오는 죽은 이들에게 거처를 나누어 주게 했습니다. 몸의 반은 산 사람의 살빛이고 반은 검푸르며, 얼굴이 어둡고 사납다고 합니다(「스노리 에다」).","발드르가 죽자 헤르모드가 저승까지 말을 달려 그를 돌려 달라고 청했고, 헬은 세상 만물이 그를 위해 운다면 돌려보내겠다고 답했습니다. 그러나 거인 여인 퇴크 한 사람만 울지 않아 발드르는 돌아오지 못했습니다."],"sort_order":21},{"slug":"idun","pantheon_slug":"norse","kind":"god","grade":null,"name":"이둔","name_en":"Iðunn","epithet":"젊음의 사과를 지키는 여신","domains":["젊음","불로의 사과"],"summary":"신들이 늙지 않도록 젊음의 사과를 나누어 주는 여신으로, 시의 신 브라기의 아내입니다.","description":["이둔은 상자에 사과를 담아 두었다가, 늙어 가는 신들이 그것을 먹고 다시 젊어지게 했습니다. 신들은 이 사과 덕분에 라그나로크 때까지 젊음을 지킨다고 합니다(「스노리 에다」).","거인 티아지에게 붙잡힌 로키가 목숨을 건지려고 이둔을 숲으로 꾀어내 넘기자, 신들은 금세 늙고 머리가 세었습니다. 신들의 추궁을 받은 로키는 프레이야의 매 깃옷을 빌려 날아가 이둔을 호두로 바꿔 데려왔습니다."],"sort_order":22},{"slug":"bragi","pantheon_slug":"norse","kind":"god","grade":null,"name":"브라기","name_en":"Bragi","epithet":"시와 웅변의 신","domains":["시","웅변"],"summary":"지혜와 말솜씨가 뛰어나 시의 신으로 불리며, 젊음의 여신 이둔의 남편입니다.","description":["「스노리 에다」는 브라기가 지혜롭고 말을 잘하며 특히 시에 뛰어나다고 적고, 시를 뜻하는 말 '브라구르'가 그의 이름에서 나왔다고 합니다. 「시그드리파의 말」에서는 그의 혀에 룬이 새겨져 있다고 노래합니다.","발할에 새로 오는 영웅들을 맞이하는 신으로 그려지기도 하고, 「로키의 말다툼」에서는 로키에게 싸움을 겁내는 자라고 조롱을 받습니다. 9세기 노르웨이의 시인 브라기 보다손이 신으로 높여진 것이라는 견해도 있습니다."],"sort_order":23},{"slug":"njord","pantheon_slug":"norse","kind":"god","grade":null,"name":"뇨르드","name_en":"Njörðr","epithet":"바다와 바람의 신","domains":["바다","바람","항해와 고기잡이","재물"],"summary":"바니르 신족 출신으로 바람과 바다를 다스리며 뱃사람과 어부에게 풍요를 내리는 신으로, 프레이르와 프레이야의 아버지입니다.","description":["에시르와 바니르 두 신족이 전쟁을 끝내고 인질을 주고받을 때 바니르 쪽에서 아스가르드로 왔습니다. 바닷가의 노아툰에 살며 바람의 흐름을 다스리고 바다와 불을 잠재우며, 그에게 빌면 재물을 얻는다고 합니다(「스노리 에다」).","거인 여인 스카디가 아버지 티아지를 잃은 보상으로 남편을 고를 때 발만 보고 고르다 그를 택했습니다. 그러나 바다를 좋아하는 뇨르드와 산을 좋아하는 스카디는 서로의 집에서 아흐레씩 지내 보고는 끝내 따로 살았습니다."],"sort_order":24},{"slug":"ymir","pantheon_slug":"norse","kind":"other","grade":null,"name":"이미르","name_en":"Ymir","epithet":"세상의 재료가 된 태초의 거인","domains":["태초","창조","서리 거인"],"summary":"세상이 생기기 전 긴눙가가프에서 생겨난 최초의 거인으로, 그의 몸으로 세상이 만들어졌습니다.","description":["남쪽 무스펠헤임의 열기가 북쪽 니플헤임의 서리에 닿아 녹아내린 물방울에서 이미르가 생겨났고, 함께 생겨난 암소 아우둠라의 젖을 먹고 자랐습니다. 잠든 그가 땀을 흘리자 겨드랑이와 다리에서 서리 거인들이 태어났습니다.","아우둠라가 소금 바위를 핥아 깨어난 부리의 손자 오딘과 그 형제들이 이미르를 죽였고, 그의 살로 땅을, 피로 바다를, 뼈로 산을, 두개골로 하늘을 만들었다고 합니다(「스노리 에다」)."],"sort_order":25},{"slug":"surtr","pantheon_slug":"norse","kind":"other","grade":null,"name":"수르트","name_en":"Surtr","epithet":"불꽃 칼을 든 무스펠의 거인","domains":["불","라그나로크"],"summary":"남쪽 불의 나라 무스펠헤임의 끝을 지키는 거인으로, 라그나로크에 온 세상을 불태운다고 합니다.","description":["「스노리 에다」에 따르면 수르트는 세상이 생기기 전부터 무스펠헤임의 경계에 앉아 불타는 칼을 들고 그 땅을 지켰습니다.","라그나로크가 오면 무스펠의 아들들을 이끌고 남쪽에서 쳐들어오는데, 그들이 지날 때 무지개다리 비프로스트가 무너집니다. 수르트는 칼 없이 맞선 프레이르를 쓰러뜨리고, 마지막에는 온 세상에 불을 질러 태운다고 합니다(「무녀의 예언」)."],"sort_order":26},{"slug":"sif","pantheon_slug":"norse","kind":"god","grade":null,"name":"시프","name_en":"Sif","epithet":"황금 머리카락의 여신","domains":["가정","대지의 풍요"],"summary":"토르의 아내로, 로키에게 머리카락을 잘린 뒤 드베르그들이 금으로 만든 머리카락을 얻은 여신입니다.","description":["「스노리 에다」에 따르면 로키가 장난삼아 시프의 머리카락을 모두 잘라 버리자, 화난 토르는 로키의 뼈를 모두 부러뜨리겠다고 했습니다. 로키는 이발디의 아들들인 드베르그에게 진짜처럼 자라나는 황금 머리카락을 만들게 했고, 그때 함께 배 스키드블라드니르와 창 궁니르도 만들어졌습니다.","토르와의 사이에서 딸 스루드를 낳았고, 앞선 혼인에서 얻은 아들은 활과 스키의 신 울르라고 합니다. 황금 머리카락을 여문 곡식에 빗대어 그녀를 대지의 풍요와 이어 보는 견해도 있습니다."],"sort_order":27},{"slug":"ammit","pantheon_slug":"egyptian","kind":"monster","grade":"divine","name":"암미트","name_en":"Ammit","epithet":"죽은 이의 심장을 삼키는 존재","domains":["심판","저승"],"summary":"악어의 머리, 사자의 앞몸, 하마의 뒷몸을 한 존재로, 심판을 통과하지 못한 죽은 이의 심장을 삼켰습니다.","description":["이집트 사람들은 죽은 뒤 저승에서 심장을 진리의 깃털과 함께 저울에 단다고 믿었습니다. 심장이 무거우면 저울 곁에서 기다리던 암미트가 그것을 삼켰고, 그 사람은 영원한 삶을 얻지 못했습니다.","이름은 ‘죽은 자를 먹는 이’라는 뜻입니다. 사람들이 가장 두려워한 세 짐승을 합친 모습이며, 섬기는 신전은 없었고 「사자의 서」의 심판 장면에 주로 그려졌습니다."],"sort_order":11},{"slug":"apep","pantheon_slug":"egyptian","kind":"monster","grade":"divine","name":"아펩","name_en":"Apep (Apophis)","epithet":"태양을 삼키려는 뱀","domains":["혼돈","어둠"],"summary":"밤마다 저승을 지나는 태양신 라의 배를 공격하는 거대한 뱀으로, 질서를 무너뜨리는 혼돈의 화신입니다.","description":["이집트 사람들은 해가 진 뒤 라의 배가 저승을 지나 다시 동쪽으로 떠오른다고 믿었고, 아펩은 그 길목에서 배를 삼키려 했습니다. 일식이나 폭풍은 아펩이 잠시 이긴 때로 여겼습니다.","세트와 여러 신이 배를 지켜 날마다 아펩을 물리쳤습니다. 데이르 엘메디나의 무덤 벽화에는 고양이 모습의 태양신이 칼로 아펩의 목을 베는 장면이 남아 있습니다."],"sort_order":12},{"slug":"sphinx","pantheon_slug":"egyptian","kind":"monster","grade":"spirit","name":"스핑크스","name_en":"Sphinx","epithet":"사자의 몸에 왕의 얼굴","domains":["왕권","수호"],"summary":"사자의 몸에 사람, 주로 파라오의 머리를 한 존재로, 신전과 무덤을 지키는 수호자였습니다.","description":["이집트의 스핑크스는 왕의 힘을 사자의 몸으로 나타낸 것으로, 대개 왕의 두건을 쓴 남자의 얼굴입니다. 기자의 대스핑크스는 카프레 왕 때 바위를 깎아 만든 것으로 봅니다.","그리스 신화의 스핑크스는 날개 달린 여성 괴물로, 테바이 사람들에게 수수께끼를 내고 풀지 못하면 잡아먹었습니다. 오이디푸스가 수수께끼를 풀자 스스로 목숨을 끊었다고 전합니다."],"sort_order":13},{"slug":"bennu","pantheon_slug":"egyptian","kind":"monster","grade":"spirit","name":"베누","name_en":"Bennu","epithet":"스스로 다시 태어나는 새","domains":["태양","부활","창조"],"summary":"태초의 언덕에 처음 내려앉아 울음으로 시간을 열었다는 왜가리 모습의 새로, 해와 부활을 상징합니다.","description":["헬리오폴리스의 신화에서 베누는 태양신의 영혼으로, 태초의 물에서 솟은 언덕에 앉아 처음 울어 세상의 시간을 열었다고 합니다. 머리에 긴 깃털 두 개가 달린 왜가리로 그려집니다.","해가 날마다 다시 떠오르듯 다시 태어나는 새로 여겨져, 그리스의 불사조 피닉스 이야기의 바탕이 되었다고 봅니다."],"sort_order":14},{"slug":"amun","pantheon_slug":"egyptian","kind":"god","grade":null,"name":"아문","name_en":"Amun","epithet":"숨은 자, 신들의 왕","domains":["왕권","창조","공기"],"summary":"'숨은 자'라는 이름의 테베 수호신으로, 태양신 라와 합쳐진 아문-라로서 이집트 신들의 왕이 되었습니다.","description":["아문은 처음에 헤르모폴리스의 태초의 여덟 신 가운데 하나로, 보이지 않는 공기와 숨은 힘을 나타냈습니다. 중왕국 때 테베가 왕국의 중심이 되면서 그 도시의 수호신으로 크게 높아졌습니다.","신왕국 시대에는 라와 합쳐진 아문-라가 신들의 왕으로 섬겨졌고, 카르나크 신전이 그의 중심 성소가 되었습니다. 아내 무트, 아들 콘수와 함께 테베의 세 신을 이루며, 그리스인들은 아문을 제우스와 같은 신으로 보았습니다."],"sort_order":15},{"slug":"ptah","pantheon_slug":"egyptian","kind":"god","grade":null,"name":"프타","name_en":"Ptah","epithet":"말로 세상을 지은 장인의 신","domains":["창조","장인","건축"],"summary":"멤피스의 수호신으로, 마음으로 생각하고 말로 불러 세상을 지었다고 전하는 장인과 건축가의 신입니다.","description":["프타는 몸에 꼭 맞는 옷에 머리에 딱 붙는 모자를 쓰고, 두 손으로 지팡이를 쥔 미라 모습으로 그려집니다. 고왕국의 수도 멤피스에서 섬긴 신으로, 장인과 건축가, 조각가들의 수호신이었습니다.","샤바카 석비에 새겨진 '멤피스 신학'에서는 프타가 마음으로 생각하고 혀로 이름을 불러 다른 신들과 세상을 지었다고 합니다. 사자 머리의 여신 세크메트가 아내, 연꽃의 신 네페르템이 아들로 함께 섬겨졌습니다."],"sort_order":16},{"slug":"sekhmet","pantheon_slug":"egyptian","kind":"god","grade":null,"name":"세크메트","name_en":"Sekhmet","epithet":"사자 머리를 한 라의 눈","domains":["전쟁","역병","치유"],"summary":"사자 머리를 한 전쟁과 역병의 여신으로, 라의 명으로 인간을 벌하다 붉게 물들인 맥주에 취해 멈추었다고 전합니다.","description":["세크메트의 이름은 '힘센 여인'이라는 뜻입니다. 「하늘 암소의 책」에 따르면 늙은 라를 업신여긴 인간들을 벌하려고 라가 보낸 눈(하토르)이 사나운 사자 여신 세크메트가 되어 사람들을 마구 죽였습니다.","인류가 모두 사라질까 걱정한 라는 맥주를 붉게 물들여 들판에 붓게 했고, 피인 줄 알고 마신 여신이 취해 잠들면서 학살이 멈추었습니다. 역병을 불러오는 여신이기에 병을 물리치는 힘도 있다고 믿어, 그 사제들은 의사 노릇도 했습니다."],"sort_order":17},{"slug":"nephthys","pantheon_slug":"egyptian","kind":"god","grade":null,"name":"네프티스","name_en":"Nephthys","epithet":"오시리스를 위해 우는 여신","domains":["애도","장례","보호"],"summary":"게브와 누트의 딸이자 세트의 아내로, 언니 이시스와 함께 죽은 오시리스를 찾아 애도하고 지킨 여신입니다.","description":["네프티스라는 이름은 '집의 여주인'이라는 뜻이며, 머리에 이 이름을 나타내는 상형문자를 얹은 모습으로 그려집니다. 세트의 아내였지만, 세트가 오시리스를 죽이자 이시스를 도와 흩어진 오시리스의 몸을 찾아 모았습니다.","두 자매는 솔개의 모습으로 오시리스를 위해 울었다고 하며, 그래서 관과 장례 그림에는 이시스와 네프티스가 죽은 이의 머리맡과 발치를 지키는 모습이 자주 나옵니다. 플루타르코스는 네프티스가 오시리스와의 사이에서 아누비스를 낳았다고 전합니다."],"sort_order":18},{"slug":"nut","pantheon_slug":"egyptian","kind":"god","grade":null,"name":"누트","name_en":"Nut","epithet":"별이 빛나는 하늘의 여신","domains":["하늘","별","재생"],"summary":"땅의 신 게브 위로 몸을 둥글게 굽혀 하늘이 된 여신으로, 저녁마다 해를 삼키고 아침마다 다시 낳는다고 여겼습니다.","description":["누트는 공기의 신 슈와 습기의 여신 테프누트의 딸이며 땅의 신 게브의 아내입니다. 아버지 슈가 둘 사이에 서서 누트를 들어 올려 하늘과 땅이 갈라졌다고 하며, 별이 박힌 몸으로 땅 위에 아치를 그린 모습으로 그려집니다.","해는 저녁에 누트의 입으로 들어가 밤새 그 몸속을 지난 뒤 아침에 다시 태어난다고 여겼습니다. 오시리스, 이시스, 세트, 네프티스의 어머니이며, 죽은 이를 품어 다시 살게 하는 여신이라 관 뚜껑 안쪽에 자주 그려졌습니다."],"sort_order":19},{"slug":"bes","pantheon_slug":"egyptian","kind":"god","grade":null,"name":"베스","name_en":"Bes","epithet":"집과 아이를 지키는 난쟁이 신","domains":["출산","가정","수호"],"summary":"사자 갈기 같은 수염에 혀를 내민 난쟁이 모습으로, 악한 것을 쫓아 산모와 아이, 집안을 지킨 신입니다.","description":["베스는 다른 이집트 신들과 달리 옆모습이 아닌 정면 얼굴로 그려지는 일이 많습니다. 짧은 다리에 큰 머리, 사자의 귀와 갈기, 내민 혀가 특징이며, 춤추고 악기를 울려 악귀와 뱀을 쫓는다고 믿었습니다.","큰 신전보다 집안에서 널리 섬긴 신으로, 침대와 거울, 화장품 그릇과 부적에 그 모습을 새겼습니다. 출산을 돕는 하마 여신 타웨레트와 함께 산모와 갓난아이를 지키는 신으로 여겨졌습니다."],"sort_order":20},{"slug":"sobek","pantheon_slug":"egyptian","kind":"god","grade":null,"name":"소베크","name_en":"Sobek","epithet":"나일강의 악어 신","domains":["나일강","힘","풍요"],"summary":"악어나 악어 머리를 한 사람의 모습으로 그려진 신으로, 나일강의 물과 풍요, 파라오의 힘을 나타냈습니다.","description":["소베크는 나일강의 사나운 악어를 신으로 섬긴 것으로, 그 힘이 위험을 막아 준다고 믿었습니다. 파이윰 오아시스의 셰데트(그리스 이름 크로코딜로폴리스)와 상이집트의 콤옴보가 중심지였고, 신전에서는 악어를 기르다 죽으면 미라로 만들어 묻었습니다.","중왕국 제12왕조의 왕들이 특히 섬겨, 이 왕조의 마지막 왕인 여왕 소베크네페루처럼 이름에 소베크를 넣기도 했습니다. 뒤에는 태양신 라와 합쳐진 소베크-라로도 섬겨졌습니다."],"sort_order":21},{"slug":"taweret","pantheon_slug":"egyptian","kind":"god","grade":null,"name":"타웨레트","name_en":"Taweret","epithet":"임신과 출산을 지키는 하마 여신","domains":["출산","임신","수호"],"summary":"하마의 머리와 몸에 사자의 팔다리, 악어의 꼬리를 한 여신으로, 임신한 여인과 갓난아이를 지켰습니다.","description":["타웨레트라는 이름은 '위대한 여인'이라는 뜻입니다. 두 발로 선 하마의 몸에 불룩한 배와 늘어진 가슴, 사자의 팔다리, 등에 늘어진 악어 꼬리를 한 모습으로, 사나운 짐승들의 힘을 모아 악한 것을 쫓는다고 여겼습니다.","보호를 뜻하는 '사(sa)' 매듭 기호를 짚고 선 모습으로 자주 그려졌으며, 출산 때 쓰는 상아 주술 지팡이와 부적, 침대 장식에 새겨졌습니다. 난쟁이 신 베스와 함께 집안에서 널리 섬긴 수호신이었습니다."],"sort_order":22},{"slug":"neith","pantheon_slug":"egyptian","kind":"god","grade":null,"name":"네이트","name_en":"Neith","epithet":"사이스의 활과 베틀의 여신","domains":["전쟁","사냥","창조","직조"],"summary":"방패와 엇갈린 두 화살을 상징으로 삼은 가장 오래된 여신 가운데 하나로, 하이집트의 붉은 관을 쓰고 사이스에서 섬겨졌습니다.","description":["네이트는 이집트 초기 왕조 때부터 이름이 보이는 오래된 여신으로, 방패와 엇갈린 두 화살이 상징입니다. 나일강 삼각주의 도시 사이스가 중심지였고, 사이스 출신 왕들이 다스린 제26왕조 때 크게 섬겨졌습니다. 베를 짜는 여신이기도 해 미라를 감싸는 아마포와도 이어졌습니다.","에스나 신전의 글에서는 태초의 물에서 스스로 생겨나 세상과 태양신 라를 낳은 창조의 여신으로 그려집니다. 「호루스와 세트의 다툼」에서는 신들이 판결을 묻자 왕위를 호루스에게 주라고 답했습니다. 그리스인들은 네이트를 아테나와 같은 여신으로 보았습니다."],"sort_order":23},{"slug":"khnum","pantheon_slug":"egyptian","kind":"god","grade":null,"name":"크눔","name_en":"Khnum","epithet":"물레로 사람을 빚는 숫양 머리의 신","domains":["창조","나일강의 범람"],"summary":"숫양 머리를 한 엘레판티네의 신으로, 도공의 물레 위에서 아이의 몸을 빚어 어머니의 배 속에 넣어 준다고 여겨졌습니다.","description":["크눔은 이집트 남쪽 끝 엘레판티네섬에서 섬긴 신으로, 나일강의 범람과 기름진 진흙을 다스린다고 여겼습니다. 도공처럼 물레를 돌려 사람과 그 영혼 카의 모습을 빚는다고 하며, 하트셉수트의 신전 부조에는 그가 여왕의 탄생을 위해 물레를 돌리는 모습이 새겨졌습니다.","프톨레마이오스 시대에 세헬섬 바위에 새긴 '기근 비석'은 조세르 왕 때 일곱 해 동안 이어진 흉년이 크눔의 신전에 땅을 바친 뒤 끝났다고 전합니다. 에스나에도 그의 큰 신전이 있었습니다."],"sort_order":24},{"slug":"khonsu","pantheon_slug":"egyptian","kind":"god","grade":null,"name":"콘수","name_en":"Khonsu","epithet":"밤하늘을 건너는 달의 신","domains":["달","시간","치유"],"summary":"'나그네'라는 이름처럼 밤하늘을 건너는 달의 신으로, 테베에서 아문과 무트의 아들로 섬겨졌습니다.","description":["콘수는 옆으로 땋은 머리를 늘어뜨린 소년이나 매의 머리를 한 모습으로, 머리 위에 초승달과 보름달 원반을 얹고 그려집니다. 아버지 아문, 어머니 무트와 함께 테베의 세 신을 이루며, 카르나크에 그의 신전이 있습니다.","카르나크에서 나온 '벤트레시 비석'에는 먼 나라 바크탄의 공주가 악령에 시달리자 콘수의 신상을 보내 병을 고쳤다는 이야기가 새겨져 있습니다. 이 때문에 병을 고치는 신으로도 받들어졌습니다."],"sort_order":25},{"slug":"circe","pantheon_slug":"greek","kind":"god","grade":null,"name":"키르케","name_en":"Circe","epithet":"아이아이에섬의 마녀 여신","domains":["마법","약초","변신"],"summary":"태양신 헬리오스의 딸로, 약초와 주문으로 사람을 짐승으로 바꾸는 아이아이에섬의 여신입니다.","description":["「오디세이아」에서 키르케는 섬에 온 오디세우스의 부하들에게 약을 탄 음식을 먹여 돼지로 바꾸었습니다. 헤르메스가 준 약초 몰리 덕에 마법에 걸리지 않은 오디세우스가 칼을 뽑자, 키르케는 부하들을 되돌려 놓았습니다.","오디세우스 일행은 그 뒤 한 해 동안 섬에 머물렀고, 키르케는 저승에 다녀오는 길과 세이렌, 스킬라와 카리브디스를 지나는 법을 일러 주었습니다."],"sort_order":56},{"slug":"sirens","pantheon_slug":"greek","kind":"monster","grade":"spirit","name":"세이렌","name_en":"Sirens","epithet":"노래로 뱃사람을 홀리는 존재","domains":["노래","유혹","바다"],"summary":"아름다운 노래로 지나가는 뱃사람을 홀려 죽음에 이르게 하는, 바다의 섬에 사는 존재입니다.","description":["「오디세이아」에서 오디세우스는 키르케의 조언대로 부하들의 귀를 밀랍으로 막고, 자신은 돛대에 몸을 묶은 채 세이렌의 노래를 들으며 섬을 지나갔습니다. 세이렌은 모든 것을 안다며 지혜를 들려주겠다고 노래했다고 합니다.","옛 그리스에서는 새의 몸에 여자의 머리를 한 모습으로 그렸고, 중세 이후에는 물고기 꼬리를 한 인어의 모습으로도 그려졌습니다. ‘사이렌’이라는 말이 여기서 나왔습니다."],"sort_order":57},{"slug":"scylla","pantheon_slug":"greek","kind":"monster","grade":"common","name":"스킬라","name_en":"Scylla","epithet":"머리 여섯 달린 바다 괴물","domains":["바다","해협"],"summary":"좁은 해협의 절벽 굴에 살며 머리 여섯으로 지나가는 배의 뱃사람을 낚아채 먹은 괴물입니다.","description":["「오디세이아」는 스킬라를 발이 열둘, 긴 목에 머리가 여섯이고 입마다 이가 세 줄로 난 괴물로 묘사합니다. 오디세우스는 카리브디스를 피하려 스킬라 쪽으로 배를 몰았고, 부하 여섯을 잃었습니다.","오비디우스의 「변신 이야기」는 스킬라가 원래 아름다운 님프였는데 마녀 키르케의 질투로 괴물이 되었다고 전합니다."],"sort_order":58},{"slug":"charybdis","pantheon_slug":"greek","kind":"monster","grade":"common","name":"카리브디스","name_en":"Charybdis","epithet":"바닷물을 삼키는 소용돌이","domains":["바다","소용돌이"],"summary":"하루 세 번 바닷물을 들이켰다 내뱉어 거대한 소용돌이를 만드는, 스킬라 맞은편의 바다 괴물입니다.","description":["「오디세이아」에서 카리브디스는 무화과나무가 자라는 바위 아래에 살며, 하루 세 번 바닷물을 삼켰다가 토해 냈습니다. 그 곁을 지나는 배는 모두 빨려 들어간다고 합니다.","배를 잃고 뗏목에 매달린 오디세우스는 카리브디스가 물을 삼킬 때 무화과나무 가지에 매달려 버티다가, 뗏목이 다시 떠오르자 붙잡아 살아났습니다. ‘스킬라와 카리브디스 사이’는 진퇴양난을 뜻하는 말이 되었습니다."],"sort_order":59},{"slug":"ares","pantheon_slug":"greek","kind":"god","grade":null,"name":"아레스","name_en":"Ares","epithet":"전쟁의 신","domains":["전쟁","싸움","용맹"],"summary":"제우스와 헤라의 아들로, 전쟁의 거칠고 사나운 면을 맡은 올림포스의 신입니다.","description":["같은 전쟁의 신이라도 아테나가 지혜로운 전략을 맡았다면, 아레스는 피 흘리는 싸움 그 자체를 상징했습니다. 「일리아스」에서는 트로이아 편에서 싸우다 아테나의 도움을 받은 디오메데스의 창에 찔려 울부짖으며 올림포스로 달아납니다.","아프로디테와 몰래 사랑하다 헤파이스토스의 그물에 함께 붙잡힌 이야기가 유명합니다. 로마에서는 로물루스의 아버지인 마르스와 동일시되어 훨씬 높이 받들어졌습니다."],"sort_order":60},{"slug":"hestia","pantheon_slug":"greek","kind":"god","grade":null,"name":"헤스티아","name_en":"Hestia","epithet":"화덕의 여신","domains":["화덕","가정","제사의 불"],"summary":"크로노스와 레아의 맏딸로, 집과 도시의 화덕을 지키는 처녀 여신입니다.","description":["크로노스가 가장 먼저 삼키고 가장 나중에 토해 내어 맏이이자 막내라고 불렸습니다. 포세이돈과 아폴론이 모두 청혼했지만 영원히 처녀로 살겠다고 맹세했고, 제우스는 그 대신 집의 한가운데 자리와 제물의 가장 좋은 몫을 주었다고 합니다(「호메로스 찬가」).","이야기에 나서는 일은 드물지만 집집의 화덕과 도시 공회당의 불이 그녀의 것이었고, 새 식민 도시를 세울 때는 모도시의 화덕에서 불씨를 옮겨 갔습니다. 로마에서는 베스타로 섬겨졌습니다."],"sort_order":61},{"slug":"persephone","pantheon_slug":"greek","kind":"god","grade":null,"name":"페르세포네","name_en":"Persephone","epithet":"저승의 여왕","domains":["저승","봄","곡식의 싹"],"summary":"데메테르의 딸로, 하데스에게 납치되어 저승의 왕비가 되었고 해마다 땅 위와 저승을 오가는 여신입니다.","description":["들판에서 꽃을 따던 페르세포네를 하데스가 저승으로 데려가자, 딸을 찾아 헤매던 데메테르가 곡식을 자라지 못하게 해 세상이 굶주렸습니다. 제우스의 중재로 돌아오게 되었지만 저승에서 석류 씨를 먹은 탓에 한 해의 3분의 1은 저승에서 지내야 했습니다(「호메로스 찬가」).","그녀가 땅 위로 올라오는 때가 곡식이 싹트는 봄이라고 풀이됩니다. 엘레우시스 비의에서 어머니 데메테르와 함께 섬겨졌고, 로마에서는 프로세르피나라고 불렸습니다."],"sort_order":62},{"slug":"prometheus","pantheon_slug":"greek","kind":"god","grade":null,"name":"프로메테우스","name_en":"Prometheus","epithet":"인간에게 불을 준 티탄","domains":["불","선견지명","인류"],"summary":"제우스의 뜻을 거스르고 하늘의 불을 훔쳐 인간에게 준 티탄입니다.","description":["티탄 이아페토스의 아들로, 이름은 '먼저 생각하는 자'라는 뜻입니다. 제우스가 인간에게서 불을 감추자 회향풀 줄기 속에 불씨를 숨겨 훔쳐 왔고(헤시오도스), 후대 전승에서는 진흙으로 인간을 빚었다고도 합니다.","그 벌로 바위에 묶여 날마다 독수리에게 간을 쪼였는데, 간은 밤마다 다시 자라났습니다. 오랜 뒤 헤라클레스가 독수리를 활로 쏘아 떨어뜨리고 그를 풀어 주었습니다."],"sort_order":63},{"slug":"pan","pantheon_slug":"greek","kind":"god","grade":null,"name":"판","name_en":"Pan","epithet":"목동과 들판의 신","domains":["목축","들판과 숲","갈대 피리"],"summary":"염소의 다리와 뿔을 한 아르카디아의 신으로, 목동과 양 떼를 지키며 갈대 피리를 불었습니다.","description":["「호메로스 찬가」에서는 헤르메스의 아들로, 태어날 때부터 염소 다리와 뿔, 수염이 있어 유모가 놀라 달아났다고 합니다. 님프 시링크스를 쫓았는데 그녀가 갈대로 변하자, 그 갈대를 엮어 피리를 만들었습니다(오비디우스).","한낮에 낮잠을 방해받으면 크게 노했고, 그가 불러일으키는 까닭 모를 두려움에서 '패닉'이라는 말이 나왔습니다. 마라톤 전투 때 아테네를 도왔다고 하여 그 뒤로 아테네에서도 섬겨졌습니다(헤로도토스)."],"sort_order":64},{"slug":"eros","pantheon_slug":"greek","kind":"god","grade":null,"name":"에로스","name_en":"Eros","epithet":"사랑의 신","domains":["사랑","욕망"],"summary":"날개를 달고 활과 화살로 신과 인간의 마음에 사랑을 일으키는 신입니다.","description":["헤시오도스는 그를 카오스, 가이아와 함께 맨 처음 생겨난 힘으로 보았지만, 후대에는 아프로디테의 아들인 날개 달린 소년으로 그려졌습니다. 금 화살에 맞으면 사랑에 빠지고 납 화살에 맞으면 사랑을 밀어낸다고 하며, 아폴론이 다프네를 쫓게 된 것도 그의 화살 탓이라고 합니다(오비디우스).","인간 공주 프시케와의 사랑 이야기가 유명합니다. 로마에서는 쿠피도(큐피드) 또는 아모르라고 불렸습니다."],"sort_order":65},{"slug":"helios","pantheon_slug":"greek","kind":"god","grade":null,"name":"헬리오스","name_en":"Helios","epithet":"태양의 신","domains":["태양","빛","맹세의 증인"],"summary":"네 마리 말이 끄는 황금 수레를 몰고 날마다 하늘을 가로지르는 태양의 신입니다.","description":["티탄 히페리온과 테이아의 아들이며, 달의 여신 셀레네, 새벽의 여신 에오스와 남매입니다. 아침마다 동쪽 끝에서 떠올라 하늘을 건넌 뒤, 밤에는 커다란 황금 잔을 타고 오케아노스강을 따라 동쪽으로 돌아간다고 합니다.","하늘에서 모든 것을 내려다보기에 페르세포네를 데려간 이가 하데스라는 것을 데메테르에게 알려 주었고, 아프로디테와 아레스의 밀회도 헤파이스토스에게 일러 주었습니다. 마녀 키르케가 그의 딸이고, 아들 파에톤은 그의 수레를 몰다 세상을 불태울 뻔했습니다."],"sort_order":66},{"slug":"hecate","pantheon_slug":"greek","kind":"god","grade":null,"name":"헤카테","name_en":"Hecate","epithet":"갈림길과 마법의 여신","domains":["마법","갈림길","밤","저승"],"summary":"횃불을 들고 갈림길과 밤을 지키며 마법과 저승의 일을 맡은 여신입니다.","description":["헤시오도스는 그녀를 티탄 페르세스와 아스테리아의 딸로 소개하며, 제우스가 땅과 바다와 하늘에서 두루 영예를 나누어 주었다고 노래합니다. 페르세포네가 납치되었을 때 횃불을 들고 데메테르와 함께 찾아 나섰고, 그 뒤 페르세포네의 시종이 되었다고 합니다.","세 갈래 길이 만나는 곳에 세 몸이 등을 맞댄 그녀의 상을 세우고 그믐 무렵 음식을 바쳤습니다. 후대로 갈수록 마법과 마녀의 여신으로 여겨졌고, 메데이아는 그녀를 섬기는 사제였습니다."],"sort_order":67},{"slug":"cronus","pantheon_slug":"greek","kind":"god","grade":null,"name":"크로노스","name_en":"Cronus","epithet":"티탄족의 왕","domains":["티탄족","수확","황금시대"],"summary":"아버지 우라노스를 몰아내고 세상을 다스렸지만, 자식들을 삼켰다가 막내 제우스에게 왕좌를 빼앗긴 티탄입니다.","description":["가이아와 우라노스의 막내아들로, 어머니가 건넨 낫으로 아버지를 몰아내고 왕이 되었습니다. 자신도 자식에게 왕좌를 빼앗긴다는 예언을 듣고, 아내 레아가 낳은 아이들을 태어나는 대로 삼켰습니다(헤시오도스 「신들의 계보」).","레아는 막내 제우스 대신 강보에 싼 돌을 건넸고, 자란 제우스는 형제들을 토해 내게 한 뒤 티탄족과 싸워 이겼습니다. 그가 다스리던 때는 사람들이 근심 없이 살던 황금시대로 기억되었고, 로마에서는 사투르누스와 동일시되었습니다."],"sort_order":68},{"slug":"pandora","pantheon_slug":"greek","kind":"hero","grade":null,"name":"판도라","name_en":"Pandora","epithet":"신들이 빚은 최초의 여성","domains":["최초의 여성","재앙","희망"],"summary":"프로메테우스가 불을 훔친 벌로 제우스가 인간에게 보낸 최초의 여성으로, 항아리를 열어 세상에 재앙을 퍼뜨렸습니다.","description":["제우스의 명으로 헤파이스토스가 흙과 물을 빚어 만들고 신들이 저마다 선물을 주어, '모든 선물을 받은 이'라는 뜻의 판도라라는 이름을 얻었습니다(헤시오도스 「일과 날」). 프로메테우스의 경고에도 그의 동생 에피메테우스가 그녀를 아내로 맞았습니다.","판도라가 큰 항아리의 뚜껑을 열자 질병과 고통이 세상에 흩어졌고, 희망만이 안에 남았습니다. 흔히 '판도라의 상자'라고 부르는 것은 16세기에 에라스뮈스가 항아리를 상자로 옮긴 데서 비롯했습니다."],"sort_order":69},{"slug":"icarus","pantheon_slug":"greek","kind":"hero","grade":null,"name":"이카로스","name_en":"Icarus","epithet":"태양 가까이 날아오른 소년","domains":["비행","무모함"],"summary":"아버지 다이달로스가 만든 날개를 달고 크레타를 탈출하다 너무 높이 날아올라 바다에 떨어진 소년입니다.","description":["미노스 왕에게 붙잡혀 있던 다이달로스는 깃털과 밀랍으로 날개를 만들어 아들에게 달아 주며, 바다에 너무 가까이도 태양에 너무 가까이도 날지 말라고 일렀습니다.","하늘을 나는 데 들뜬 이카로스가 높이 솟아오르자 태양열에 밀랍이 녹아 깃털이 떨어졌고, 그는 바다에 빠져 죽었습니다. 그가 떨어진 바다는 이카리아해, 시신을 묻은 섬은 이카리아섬이라고 불리게 되었다고 합니다(오비디우스)."],"sort_order":70},{"slug":"helen","pantheon_slug":"greek","kind":"hero","grade":null,"name":"헬레네","name_en":"Helen","epithet":"트로이아 전쟁을 부른 미녀","domains":["아름다움","트로이아 전쟁"],"summary":"제우스와 레다의 딸로, 스파르타의 왕비였다가 트로이아의 왕자 파리스와 떠나며 트로이아 전쟁을 불러온 그리스 제일의 미녀입니다.","description":["제우스가 백조로 변해 레다에게 다가가 낳은 딸로, 디오스쿠로이와 남매입니다. 수많은 왕이 청혼하자 누가 남편이 되든 그를 함께 돕겠다는 맹세를 받은 뒤 메넬라오스와 결혼했습니다.","아프로디테가 약속한 대로 파리스가 그녀를 데려가자, 맹세에 묶인 그리스 왕들이 트로이아로 출정했습니다. 전쟁 뒤 메넬라오스와 스파르타로 돌아갔다고 하며, 다른 전승에서는 트로이아에 간 것은 그녀의 환영이고 본인은 이집트에 있었다고도 합니다."],"sort_order":71},{"slug":"ariadne","pantheon_slug":"greek","kind":"hero","grade":null,"name":"아리아드네","name_en":"Ariadne","epithet":"미궁의 실을 건넨 공주","domains":["미궁","사랑"],"summary":"크레타 미노스 왕의 딸로, 테세우스에게 실타래를 주어 미궁에서 빠져나오게 했다가 낙소스섬에 홀로 남겨진 공주입니다.","description":["아리아드네는 미노타우로스를 죽이러 온 테세우스에게 반해 실타래를 건넸고, 테세우스는 실을 풀며 미궁에 들어갔다가 그 실을 따라 되돌아 나왔습니다.","함께 크레타를 떠났지만 테세우스는 낙소스섬에 잠든 그녀를 두고 떠났습니다. 그 뒤 디오니소스가 그녀를 아내로 맞았고, 결혼 선물로 준 관을 하늘에 올려 별자리(북쪽왕관자리)로 만들었다고 합니다."],"sort_order":72},{"slug":"midas","pantheon_slug":"greek","kind":"hero","grade":null,"name":"미다스","name_en":"Midas","epithet":"손대는 것마다 금이 된 왕","domains":["황금","탐욕"],"summary":"손에 닿는 것을 모두 금으로 바꾸는 소원을 빌었다가 곤경에 빠진 프리기아의 왕입니다.","description":["디오니소스의 스승 실레노스를 극진히 대접한 상으로 소원 하나를 얻은 미다스는 만지는 것마다 금이 되게 해 달라고 빌었습니다. 그러나 음식과 물마저 금으로 변하자 신에게 용서를 빌었고, 팍톨로스강에 몸을 씻어 그 힘을 떨쳐 냈습니다. 그 뒤로 이 강에서 사금이 났다고 합니다.","판과 아폴론의 음악 겨루기에서 판의 편을 들었다가 아폴론의 노여움을 사 당나귀 귀를 얻었다는 이야기도 전합니다(오비디우스)."],"sort_order":73},{"slug":"yucahu","pantheon_slug":"taino","kind":"god","grade":null,"name":"유카우","name_en":"Yúcahu","epithet":"카사바와 바다를 주는 최고신","domains":["카사바","바다","풍요"],"summary":"하늘에 살며 죽지 않고 아무도 볼 수 없다고 라몬 파네가 기록한 타이노의 최고신으로, 어머니 아타베이와 함께 섬겨졌습니다.","description":["1498년 무렵 히스파니올라섬에서 타이노 사람들의 이야기를 받아 적은 수도사 라몬 파네는, 그들이 '유카우 바과 마오로코티'라 부르는 신에게 시작이 없고 다섯 이름을 가진 어머니 아타베이가 있다고 썼습니다. 유카우는 주식인 카사바(유카)를, 바과는 바다를 뜻한다고 풀이합니다.","산처럼 솟은 세모꼴 돌 '삼각석'은 카사바 밭에 묻어 풍작을 빌던 제미로 보며, 이를 유카우의 모습으로 여기는 해석이 있습니다."],"sort_order":1},{"slug":"zemi","pantheon_slug":"taino","kind":"other","grade":null,"name":"제미","name_en":"Zemí","epithet":"정령이 깃든 신상","domains":["정령","조상","점"],"summary":"타이노 사람들이 섬긴 정령과 조상의 영, 그리고 그 힘이 깃든 나무·돌·솜 조각상을 함께 이르는 말입니다.","description":["라몬 파네에 따르면 제미는 나무와 돌, 뼈, 솜으로 만들었고, 어떤 나무는 지나는 사람을 불러 세워 자기를 제미로 깎게 했다고 합니다. 추장과 주술사 베이케는 제미 앞에서 코오바라는 가루를 코로 들이마시고, 환각 속에서 병의 원인과 앞일을 물었습니다.","제미마다 성격이 달라 비와 바람, 출산과 수확을 돕거나 해친다고 믿었으며, 다른 마을의 제미를 훔치거나 숨기기도 했습니다. 머리에 접시를 인 나무 제미는 코오바 가루를 올려놓는 받침으로 썼습니다."],"sort_order":2},{"slug":"ai-apaec","pantheon_slug":"moche","kind":"god","grade":null,"name":"아이 아파엑","name_en":"Ai Apaec","epithet":"목을 베는 송곳니의 신","domains":["창조","희생 제의","산"],"summary":"페루 북부 해안의 모체 사람들이 토기와 금속 공예, 신전 벽화에 즐겨 새긴 송곳니 난 신으로, 흔히 '목 베는 신'과 같은 존재로 봅니다.","description":["모체 미술에는 고양잇과 짐승의 송곳니를 드러낸 채 반달 모양 칼 투미와 사람 머리를 든 신이 자주 나오며, 달의 신전(우아카 데 라 루나) 벽에도 이 얼굴이 되풀이해 새겨졌습니다. 학자들은 전쟁에서 사로잡은 포로를 바치던 희생 제의와 이 신을 이어서 봅니다.","고고학자 라파엘 라르코 오일레가 이 신을 하나의 존재로 보면서, 식민지 시대 모치카어 문법서에서 '창조자'를 뜻하는 낱말을 이름으로 붙였습니다. 이 낱말은 본래 에스파냐 사람들이 기독교의 신을 옮길 때 쓴 말이어서, 여러 신을 하나로 묶어 버린 이름이라는 비판도 있습니다."],"sort_order":1}]$seed$::jsonb)
on conflict (slug) do nothing;
insert into public.exhibits (id, figure_slug, title, kind, date_label, holder, note, image)
select id, figure_slug, title, kind, date_label, holder, note, image from jsonb_populate_recordset(null::public.exhibits, $seed$[{"id":"zeus-otricoli","figure_slug":"zeus","title":"오트리콜리의 제우스","kind":"sculpture","date_label":"로마 시대 (그리스 원작의 모작)","holder":"바티칸 박물관 피오 클레멘티노관","note":null,"image":{"src":"/images/exhibits/zeus-otricoli.jpg","width":1051,"height":1600,"alt":"곱슬거리는 긴 머리와 풍성한 수염을 한 제우스의 대리석 두상","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Zeus_Otricoli_Pio-Clementino_Inv257.jpg"}}},{"id":"athena-giustiniani","figure_slug":"athena","title":"아테나 주스티니아니","kind":"sculpture","date_label":"로마 시대 (그리스 원작의 모작)","holder":"바티칸 박물관 브라초 누오보","note":null,"image":{"src":"/images/exhibits/athena-giustiniani.jpg","width":1006,"height":1600,"alt":"투구를 쓰고 긴 창을 든 채 서 있는 아테나의 대리석 전신상. 발치에 뱀이 감겨 있습니다.","credit":{"artist":"Daderot","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Athena_Giustiniani_-_Braccio_Nuovo,_Museo_Chiaramonti_-_Vatican_Museums_-_DSC00910.jpg"}}},{"id":"apollo-belvedere","figure_slug":"apollo","title":"벨베데레의 아폴론","kind":"sculpture","date_label":"2세기경 (로마 시대 모작)","holder":"바티칸 박물관 피오 클레멘티노관","note":null,"image":{"src":"/images/exhibits/apollo-belvedere.jpg","width":1067,"height":1600,"alt":"곱슬머리를 묶어 올리고 어깨에 망토를 걸친 아폴론 대리석상의 상반신","credit":{"artist":"Marie-Lan Nguyen","license":"CC BY 2.5","licenseUrl":"https://creativecommons.org/licenses/by/2.5","sourceUrl":"https://commons.wikimedia.org/wiki/File:Belvedere_Apollo_Pio-Clementino_Inv1015_n3.jpg"}}},{"id":"venus-de-milo","figure_slug":"aphrodite","title":"밀로의 비너스","kind":"sculpture","date_label":"기원전 2세기경","holder":"루브르 박물관","note":"밀로스섬에서 발견되었으며, 아프로디테를 표현한 것으로 봅니다.","image":{"src":"/images/exhibits/venus-de-milo.jpg","width":953,"height":1600,"alt":"두 팔이 없고 허리 아래를 천으로 두른 아프로디테의 대리석 상","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Venus_de_Milo_Louvre_Ma399_n4.jpg"}}},{"id":"artemision-bronze","figure_slug":"poseidon","title":"아르테미시온 청동상","kind":"sculpture","date_label":"기원전 460년경","holder":"아테네 국립고고학박물관","note":"손에 든 무기가 사라져 번개를 던지는 제우스인지, 삼지창을 던지는 포세이돈인지 의견이 갈립니다.","image":{"src":"/images/exhibits/artemision-bronze.jpg","width":1067,"height":1600,"alt":"두 팔을 넓게 벌리고 무언가를 던지려는 자세를 한 수염 난 남신 청동상의 상반신","credit":{"artist":"Gary Todd from Xinzheng, China","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Ancient_Greece_Bronze_statue_of_Zeus_or_Poseidon;_from_the_sea_near_Cape_Artemision,_Northern_Euboea;_c._460_BC.jpg"}}},{"id":"odin-wanderer","figure_slug":"odin","title":"방랑자 오딘","kind":"painting","date_label":"1886년","holder":null,"note":null,"image":{"src":"/images/exhibits/odin-wanderer.jpg","width":500,"height":733,"alt":"챙 넓은 모자를 눌러쓰고 긴 흰 수염을 늘어뜨린 노인 모습의 오딘이 지팡이를 쥔 흑백 그림","credit":{"artist":"Georg von Rosen","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Georg_von_Rosen_-_Oden_som_vandringsman,_1886_(Odin,_the_Wanderer).jpg"}}},{"id":"odin-sleipnir","figure_slug":"odin","title":"궁니르를 들고 슬레이프니르를 탄 오딘","kind":"print","date_label":"19세기","holder":null,"note":null,"image":{"src":"/images/exhibits/odin-sleipnir.jpg","width":686,"height":934,"alt":"긴 수염의 오딘이 창 궁니르를 세워 들고 말 슬레이프니르를 탄 모습을 그린 흑백 선 그림","credit":{"artist":"Lorenz Frølich","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Odin_holding_Gungnir_atop_Sleipnir_by_Fr%C3%B8lich.jpg"}}},{"id":"fenrir-odin","figure_slug":"odin","title":"펜리르와 오딘","kind":"print","date_label":"19세기","holder":null,"note":"라그나로크에서 오딘이 늑대 펜리르와 맞서는 장면입니다.","image":{"src":"/images/exhibits/fenrir-odin.jpg","width":1048,"height":627,"alt":"입을 크게 벌린 늑대 펜리르를 향해 창을 들고 말을 달리는 오딘을 덩굴무늬 테두리 안에 그린 흑백 삽화","credit":{"artist":"Lorenz Frølich","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Fenrir_and_Odin_by_Fr%C3%B8lich.jpg"}}},{"id":"thor-jotnar","figure_slug":"thor","title":"거인과 싸우는 토르","kind":"painting","date_label":"1872년","holder":"스웨덴 국립미술관","note":null,"image":{"src":"/images/exhibits/thor-jotnar.jpg","width":1081,"height":1600,"alt":"염소가 끄는 수레 위에서 망치를 치켜든 토르가 번개 속에서 거인들과 싸우는 그림","credit":{"artist":"Mårten Eskil Winge","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Thor%27s_Battle_Against_the_J%C3%B6tnar_(1872)_by_M%C3%A5rten_Eskil_Winge.jpg"}}},{"id":"thor-sam66","figure_slug":"thor","title":"토르 (아이슬란드 필사본 SÁM 66)","kind":"manuscript","date_label":"1765~1766년","holder":"아르니 마그누손 연구소","note":"망치 묠니르를 들고 힘의 띠 메긴교르드를 두르고 쇠장갑 야른그레이프르를 낀 토르를 그렸습니다.","image":{"src":"/images/exhibits/thor-sam66.jpg","width":928,"height":1167,"alt":"붉은 옷에 띠를 두른 토르가 쇠장갑 낀 손에 망치를 들고 선 채색 필사본 그림. 옆에 설명 글이 적혀 있습니다.","credit":{"artist":"Jakob Sigurðsson","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:S%C3%81M_66,_77v,_Thor.jpg"}}},{"id":"freyja-brisingamen","figure_slug":"freyja","title":"브리싱가멘을 돌려주는 헤임달","kind":"painting","date_label":"19세기","holder":null,"note":null,"image":{"src":"/images/exhibits/freyja-brisingamen.jpg","width":1176,"height":1600,"alt":"왕좌에 앉은 프레이야에게 투구를 쓴 헤임달이 몸을 기울여 목걸이를 건네고, 뒤에서 시녀들이 지켜보는 그림","credit":{"artist":"Nils Jakob Blommér","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Nils_Jakob_Blomm%C3%A9r_-_Heimdall_returns_Brisingamen_to_Freyja_-_Google_Art_Project.jpg"}}},{"id":"osiris-bronze","figure_slug":"osiris","title":"오시리스 청동 소상","kind":"sculpture","date_label":"고대 이집트","holder":"토리노 이집트 박물관","note":null,"image":{"src":"/images/exhibits/osiris-bronze.jpg","width":1102,"height":1600,"alt":"높은 관을 쓰고 두 팔을 가슴 앞에 모은 오시리스의 닳은 청동 소상. 옆에 크기를 재는 자가 놓여 있습니다.","credit":{"artist":null,"license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Osiris_statuette,_bronze_-_Museo_Egizio,_Turin_S_17631_p01.jpg"}}},{"id":"osiris-crook-flail","figure_slug":"osiris","title":"오시리스 좌상","kind":"sculpture","date_label":"기원전 600~550년경","holder":"월터스 미술관","note":"받침과 등기둥에 오시리스에게 바치는 기도문이 새겨져 있습니다.","image":{"src":"/images/exhibits/osiris-crook-flail.jpg","width":1049,"height":1600,"alt":"깃털 장식 관을 쓰고 가슴 앞에 갈고리 지팡이와 도리깨를 쥔 채 앉은 오시리스의 짙은 돌 소상","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Egyptian_-_Osiris,_Lord_of_the_Dead_-_Walters_22207.jpg"}}},{"id":"isis-horus","figure_slug":"isis","title":"호루스에게 젖을 먹이는 이시스","kind":"sculpture","date_label":"고대 이집트","holder":"메트로폴리탄 미술관","note":null,"image":{"src":"/images/exhibits/isis-horus.jpg","width":866,"height":1600,"alt":"소뿔과 해 원반 모양의 관을 쓰고 의자에 앉아 무릎 위의 아기 호루스에게 젖을 먹이는 이시스의 소상","credit":{"artist":null,"license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Isis_nursing_Horus_MET_17.190.1641_front.jpg"}}},{"id":"isis-tyet","figure_slug":"isis","title":"티엣 부적","kind":"sculpture","date_label":"기원전 664~304년","holder":"메트로폴리탄 미술관","note":null,"image":{"src":"/images/exhibits/isis-tyet.jpg","width":1200,"height":1600,"alt":"양옆의 고리가 아래로 처진 매듭 모양을 붉은 벽옥으로 깎은 작은 부적","credit":{"artist":null,"license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Red_jasper_amulet_of_tyet_MET_DP121806.jpg"}}},{"id":"anubis-shrine","figure_slug":"anubis","title":"투탕카멘 무덤의 아누비스 신당","kind":"photograph","date_label":"기원전 14세기 (1920년대 발굴 당시 사진)","holder":"이집트 박물관 (카이로)","note":"하워드 카터의 발굴단 사진가 해리 버턴이 무덤 안에서 찍은 사진입니다.","image":{"src":"/images/exhibits/anubis-shrine.jpg","width":1180,"height":1466,"alt":"투탕카멘 무덤 보물실 입구를 찍은 흑백 사진. 앞쪽 상자 모양 신당 위에 아누비스 조각이 엎드려 있고 뒤로 유물이 쌓여 있습니다.","credit":{"artist":"Harry Burton","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Anubis-shrine_(cropped).jpg"}}},{"id":"weighing-heart","figure_slug":"anubis","title":"심장의 무게 달기 (후네페르의 「사자의 서」)","kind":"manuscript","date_label":"기원전 13세기경","holder":"대영박물관","note":"아누비스가 죽은 이의 심장을 진리의 깃털과 함께 저울에 달고, 토트가 결과를 적습니다. 오른쪽의 괴물 암무트는 심판을 통과하지 못한 심장을 삼킵니다.","image":{"src":"/images/exhibits/weighing-heart.jpg","width":1280,"height":659,"alt":"자칼 머리의 아누비스가 저울로 심장의 무게를 달고, 따오기 머리의 토트가 결과를 적는 장면을 그린 파피루스","credit":{"artist":"Photographed by the British Museum; original artist unknown","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:BD_Weighing_of_the_Heart.jpg"}}},{"id":"hero-lion","figure_slug":"gilgamesh","title":"사자를 제압하는 영웅","kind":"relief","date_label":"기원전 8세기","holder":"루브르 박물관","note":"아시리아 사르곤 2세의 궁전(두르샤루킨) 부조입니다. 길가메시로 보는 견해가 있지만 확실하지 않습니다.","image":{"src":"/images/exhibits/hero-lion.jpg","width":686,"height":1600,"alt":"수염을 기른 영웅이 한 팔로 사자를 끌어안고 다른 손에 무언가를 쥔 모습을 새긴 석조 부조","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Hero_lion_Dur-Sharrukin_Louvre_AO19862.jpg"}}},{"id":"queen-of-night","figure_slug":"ishtar","title":"밤의 여왕 (버니 부조)","kind":"relief","date_label":"기원전 1800~1750년경","holder":"대영박물관","note":"날개 달린 여신을 이슈타르(인안나)로 보는 견해와 그 언니 에레슈키갈로 보는 견해 등이 있습니다.","image":{"src":"/images/exhibits/queen-of-night.jpg","width":1203,"height":1600,"alt":"날개와 새의 발을 가진 여신이 두 마리 사자 위에 서서 양손에 고리와 막대를 들고, 양옆에 부엉이가 있는 점토 부조","credit":{"artist":null,"license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:British_Museum_Queen_of_the_Night.jpg"}}},{"id":"ishtar-gate-lion","figure_slug":"ishtar","title":"바빌론 행렬로의 사자","kind":"relief","date_label":"기원전 6세기","holder":"이스탄불 고고학 박물관","note":"사자는 이슈타르의 상징으로, 이슈타르 문으로 이어지는 행렬로의 벽을 장식했습니다.","image":{"src":"/images/exhibits/ishtar-gate-lion.jpg","width":1280,"height":854,"alt":"푸른 유약 벽돌 바탕 위로 걸어가는 사자를 새긴 벽돌 부조","credit":{"artist":"Marie-Lan Nguyen","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Lion_Ishtar_gate_IAM_inv88.143.jpg"}}},{"id":"ishtar-sumerian-headdress","figure_slug":"ishtar","title":"수메르의 금 머리 장식","kind":"sculpture","date_label":"기원전 2600년경","holder":"메트로폴리탄 미술관","note":"이슈타르의 일곱 장신구를 그린 옛 그림은 전하지 않아, 같은 메소포타미아의 수메르 사람들이 만든 금 장신구를 실었습니다.","image":{"src":"/images/exhibits/ishtar-sumerian-headdress.jpg","width":1280,"height":1009,"alt":"금으로 만든 버들잎 모양 장식과 푸른 구슬을 꿴 머리 장식","credit":{"artist":null,"license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Headdress_MET_DP226592.jpg"}}},{"id":"marduk-seal","figure_slug":"marduk","title":"마르두크와 무슈후슈 (원통 인장 도판)","kind":"print","date_label":null,"holder":null,"note":"바빌로니아 원통 인장에 새긴 그림을 옮겨 그린 도판입니다.","image":{"src":"/images/exhibits/marduk-seal.jpg","width":778,"height":1274,"alt":"높은 관을 쓰고 장식이 많은 옷을 입은 마르두크와 그 발치의 용 모양 짐승 무슈후슈를 그린 선 그림","credit":{"artist":"Franz Heinrich Weißbach","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Marduk_and_pet.jpg"}}},{"id":"shiva-nataraja","figure_slug":"shiva","title":"나타라자 (춤추는 시바)","kind":"sculpture","date_label":null,"holder":"암스테르담 국립미술관 (라익스뮤지엄)","note":null,"image":{"src":"/images/exhibits/shiva-nataraja.jpg","width":1140,"height":1600,"alt":"불꽃 고리 안에서 네 팔을 펼치고 한 다리를 들어 춤추는 시바의 청동상","credit":{"artist":"Rijksmuseum","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Shiva_Nataraja,_AK-MAK-187.jpg"}}},{"id":"ganesha-rijks","figure_slug":"ganesha","title":"가네샤","kind":"sculpture","date_label":null,"holder":"암스테르담 국립미술관 (라익스뮤지엄)","note":null,"image":{"src":"/images/exhibits/ganesha-rijks.jpg","width":1132,"height":1600,"alt":"받침 위에 앉은 코끼리 머리의 가네샤를 새긴 석상","credit":{"artist":"Rijksmuseum","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Ganesha,_AK-MAK-237.jpg"}}},{"id":"vishnu-anantashayana","figure_slug":"vishnu","title":"아난타 위에 누운 비슈누","kind":"painting","date_label":"16~17세기","holder":"마탄체리 궁전 (인도 코치)","note":null,"image":{"src":"/images/exhibits/vishnu-anantashayana.jpg","width":1280,"height":1189,"alt":"머리가 여럿인 뱀 아난타 위에 누운 비슈누와 그 주위를 둘러싼 많은 신을 그린 궁전 벽화","credit":{"artist":"Rainer Halama","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Mattancherry_Palace-16-17th_Century_mural_paintings-Vishnu_Anantashayana-WUS09329.jpg"}}},{"id":"izanagi-izanami","figure_slug":"izanagi-izanami","title":"일본의 섬들을 만드는 이자나기와 이자나미","kind":"painting","date_label":"1880년대","holder":null,"note":null,"image":{"src":"/images/exhibits/izanagi-izanami.jpg","width":1280,"height":847,"alt":"구름 위에 선 이자나기와 이자나미. 한 신이 구슬 장식이 달린 창을 들고 있습니다.","credit":{"artist":"Kobayashi Eitaku","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Kobayashi_Eitaku_-_Izanami_and_Izanagi_creating_the_Japanese_Islands_alternate_version_HD.jpg"}}},{"id":"amaterasu-iwato","figure_slug":"amaterasu","title":"이와토 가구라의 기원","kind":"print","date_label":"1856년","holder":null,"note":"우타가와 구니사다(3대 도요쿠니)의 세 폭 목판화입니다.","image":{"src":"/images/exhibits/amaterasu-iwato.jpg","width":1280,"height":611,"alt":"세 폭으로 이어진 목판화. 가운데 위쪽에서 빛을 내며 동굴에서 나오는 아마테라스를 신들이 둘러싸고 있습니다.","credit":{"artist":"Toyokuni III","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Origin_of_Iwato_Kagura_Dance_Amaterasu_by_Toyokuni_III_(Kunisada)_1856.png"}}},{"id":"susanoo-orochi","figure_slug":"susanoo","title":"이즈모에서 야마타노오로치를 베는 스사노오","kind":"print","date_label":"19세기","holder":null,"note":null,"image":{"src":"/images/exhibits/susanoo-orochi.jpg","width":1280,"height":633,"alt":"거친 파도 위에서 검을 휘두르는 스사노오와 그에게 달려드는 뱀 야마타노오로치를 그린 목판화","credit":{"artist":"Yoshitoshi","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Susanoo-no-Mikoto-slays-Yamata-no-Orochi-in-Izumo-By-Tsukioka-Yoshitoshi_repaired.png"}}},{"id":"raijin-hokusai","figure_slug":"raijin","title":"뇌신","kind":"painting","date_label":"19세기","holder":null,"note":null,"image":{"src":"/images/exhibits/raijin-hokusai.jpg","width":590,"height":1600,"alt":"족자에 그린 그림. 소용돌이치는 먹구름 속에 붉은 몸의 뇌신이 있습니다.","credit":{"artist":"Katsushika Hokusai","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Katsushika_Hokusai_-_Thunder_God_-_Google_Art_Project.jpg"}}},{"id":"hera-barberini","figure_slug":"hera","title":"헤라 흉상","kind":"sculpture","date_label":"로마 시대 (그리스 원작의 모작)","holder":"바티칸 박물관","note":null,"image":{"src":"/images/exhibits/hera-barberini.jpg","width":1059,"height":1600,"alt":"물결치는 머리를 가운데로 가르고 머리띠를 두른 헤라의 대리석 흉상","credit":{"artist":null,"license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Hera_Barberini_Chiaramonti_Inv1210.jpg"}}},{"id":"artemis-versailles","figure_slug":"artemis","title":"베르사유의 디아나","kind":"sculpture","date_label":"1~2세기 (로마 시대 모작)","holder":"루브르 박물관","note":"로마에서는 아르테미스를 디아나라 불렀습니다.","image":{"src":"/images/exhibits/artemis-versailles.jpg","width":1200,"height":1600,"alt":"화살통에서 화살을 뽑으며 걸어가는 아르테미스와 그 곁에서 뛰어오르는 사슴을 새긴 대리석상","credit":{"artist":"Shonagon","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Diane_de_Versailles_-_Mus%C3%A9e_du_Louvre_AGER_Ma_589.jpg"}}},{"id":"hermes-ingenui","figure_slug":"hermes","title":"헤르메스 잉게누이","kind":"sculpture","date_label":"로마 시대 (그리스 원작의 모작)","holder":"바티칸 박물관","note":null,"image":{"src":"/images/exhibits/hermes-ingenui.jpg","width":731,"height":1600,"alt":"챙 있는 모자를 쓰고 어깨에 망토를 걸친 젊은 헤르메스가 지팡이를 든 대리석 전신상","credit":{"artist":null,"license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Hermes_Ingenui_Pio-Clementino_Inv544.jpg"}}},{"id":"hades-locri-pinax","figure_slug":"hades","title":"하데스와 페르세포네 (로크리의 봉헌판)","kind":"relief","date_label":"기원전 500~450년경","holder":"클리블랜드 미술관","note":"남이탈리아 로크리의 페르세포네 성소에서 나온 테라코타 봉헌판입니다.","image":{"src":"/images/exhibits/hades-locri-pinax.jpg","width":1200,"height":1600,"alt":"옥좌에 나란히 앉은 두 신과 옥좌 아래의 수탉을 새긴 테라코타 판. 한 신이 곡식 이삭과 꽃가지를 들고 있습니다.","credit":{"artist":"Daderot","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Pinax_with_Persephone_and_Hades_Enthroned,_500-450_BC,_Greek,_Locri_Epizephirii,_Mannella_district,_Sanctuary_of_Persephone,_terracotta_-_Cleveland_Museum_of_Art_-_DSC08242.JPG"}}},{"id":"baldr-eckersberg","figure_slug":"baldr","title":"발드르의 죽음","kind":"painting","date_label":"1817년","holder":null,"note":null,"image":{"src":"/images/exhibits/baldr-eckersberg.jpg","width":1280,"height":1014,"alt":"땅에 쓰러진 발드르를 둘러싸고 신들이 놀라고 슬퍼하는 그림","credit":{"artist":"Christoffer Wilhelm Eckersberg","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Baldr_dead_by_Eckersberg.jpg"}}},{"id":"heimdall-doepler","figure_slug":"heimdall","title":"무지개다리의 헤임달","kind":"print","date_label":"20세기 초","holder":null,"note":"에밀 되플러가 그린 북유럽 신화 삽화의 한 부분입니다.","image":{"src":"/images/exhibits/heimdall-doepler.jpg","width":752,"height":684,"alt":"투구를 쓴 헤임달이 무지개다리 곁에서 커다란 뿔피리를 부는 그림","credit":{"artist":"Emil Doepler","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Heimdall_an_der_Himmelsbr%C3%BCcke.jpg"}}},{"id":"ra-horakhty-stela","figure_slug":"ra","title":"라-호라크티 앞의 공양 석비","kind":"painting","date_label":"고대 이집트","holder":null,"note":null,"image":{"src":"/images/exhibits/ra-horakhty-stela.jpg","width":1280,"height":1525,"alt":"해 원반을 인 매 머리의 라-호라크티가 앉아 있고, 한 여인이 공물 상을 사이에 두고 마주 선 채색 석비","credit":{"artist":"Photograph by Oriental Institute, the University of Chicago; painter unknown","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Re-Horakhty_Stela.jpg"}}},{"id":"horus-edfu","figure_slug":"horus","title":"에드푸 신전의 호루스상","kind":"sculpture","date_label":"기원전 3~1세기 (프톨레마이오스 왕조)","holder":"에드푸 신전 (이집트)","note":null,"image":{"src":"/images/exhibits/horus-edfu.jpg","width":1280,"height":853,"alt":"신전 입구 앞에 서 있는 커다란 화강암 매 조각","credit":{"artist":"Vyacheslav Argenberg","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Temple_of_Edfu,_Statue_of_Horus,_Egypt.jpg"}}},{"id":"thoth-ibis","figure_slug":"thoth","title":"따오기 모습의 토트","kind":"sculpture","date_label":"고대 이집트","holder":"루브르 박물관","note":null,"image":{"src":"/images/exhibits/thoth-ibis.jpg","width":1280,"height":960,"alt":"검은 머리와 긴 굽은 부리, 흰 몸을 가진 따오기가 받침 위에 웅크린 조각","credit":{"artist":"Tangopaso","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Ibis_couch%C3%A9,_le_dieu_Thot_(Louvre,_E_17380).jpg"}}},{"id":"enki-adda-seal","figure_slug":"enki","title":"아다의 원통 인장","kind":"relief","date_label":"기원전 23세기경 (아카드 시대)","holder":"대영박물관","note":"어깨에서 물줄기와 물고기가 흘러나오는 신이 엔키(에아)입니다. 날개 달린 이슈타르와, 산 사이로 떠오르는 태양신 샤마시도 보입니다.","image":{"src":"/images/exhibits/enki-adda-seal.jpg","width":962,"height":611,"alt":"원통 인장을 굴려 찍은 자국. 어깨에서 물줄기가 흐르는 신, 날개 달린 여신, 산 사이에서 솟는 신이 나란히 새겨져 있습니다.","credit":{"artist":null,"license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Ea_(Babilonian)_-_EnKi_(Sumerian).jpg"}}},{"id":"tiamat-nimrud","figure_slug":"tiamat","title":"님루드 부조 도판 (번개를 든 신과 괴물)","kind":"print","date_label":"19세기 (원본 부조는 기원전 9세기)","holder":null,"note":"아시리아 님루드의 니누르타 신전 부조를 옮겨 그린 도판입니다. 마르두크와 티아마트의 싸움으로 흔히 소개되지만, 니누르타가 괴물을 물리치는 장면으로 보는 견해도 있습니다.","image":{"src":"/images/exhibits/tiamat-nimrud.jpg","width":1280,"height":944,"alt":"양손에 번개 다발을 든 날개 달린 신이 사자 머리에 새 발톱을 가진 괴물을 쫓는 선 그림","credit":{"artist":"editor Austen Henry Layard , drawing by L. Gruner","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Chaos_Monster_and_Sun_God.png"}}},{"id":"brahma-rijks","figure_slug":"brahma","title":"브라흐마","kind":"sculpture","date_label":null,"holder":"암스테르담 국립미술관 (라익스뮤지엄)","note":null,"image":{"src":"/images/exhibits/brahma-rijks.jpg","width":986,"height":1600,"alt":"여러 얼굴과 네 팔을 가진 브라흐마가 연꽃 받침 위에 선 청동상","credit":{"artist":"Rijksmuseum","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Brahma_en_Shiva_Brahma,_AK-MAK-249.jpg"}}},{"id":"krishna-govardhan","figure_slug":"krishna","title":"고바르다나산을 들어 올린 크리슈나","kind":"painting","date_label":"1590~1595년경 (무굴 제국)","holder":"메트로폴리탄 미술관","note":"무굴 궁정 화가 미스킨이 「하리밤샤」 사본에 그린 그림입니다.","image":{"src":"/images/exhibits/krishna-govardhan.jpg","width":1116,"height":1600,"alt":"푸른 피부의 크리슈나가 한 손으로 산을 들어 올리고, 그 아래로 마을 사람들과 소들이 비를 피한 그림","credit":{"artist":"Miskin","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Krishna_Holds_Up_Mount_Govardhan_to_Shelter_the_Villagers_of_Braj,_ca.1590%E2%80%9395,_The_Met.jpg"}}},{"id":"fujin-sotatsu","figure_slug":"fujin","title":"풍신뇌신도 (오른쪽 병풍, 후진)","kind":"painting","date_label":"17세기","holder":"겐닌지 (교토)","note":"다와라야 소타쓰의 두 폭 병풍 가운데 후진을 그린 오른쪽 폭입니다. 라이진은 왼쪽 폭에 있습니다.","image":{"src":"/images/exhibits/fujin-sotatsu.jpg","width":1280,"height":1136,"alt":"금박 바탕 위에서 바람 자루를 머리 위로 펼치고 구름을 타고 달리는 초록빛 몸의 후진","credit":{"artist":"Tawara Sōtatsu","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Tawaraya_S%C5%8Dtatsu_-_The_Gods_of_Wind_and_Thunder_(right_screen).jpg"}}},{"id":"inari-foxfires","figure_slug":"inari","title":"오지 팽나무 아래의 섣달그믐 여우불","kind":"print","date_label":"1857년","holder":null,"note":"우타가와 히로시게의 「명소 에도 백경」 가운데 한 장입니다.","image":{"src":"/images/exhibits/inari-foxfires.jpg","width":1049,"height":1600,"alt":"밤하늘 아래 큰 나무 곁에 여우들이 모여 있고, 여우마다 작은 불빛이 떠 있는 목판화","credit":{"artist":"Utagawa Hiroshige","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Hiroshige,_New_Year%27s_Eve_foxfires_at_the_changing_tree,_Oji,_1857.jpg"}}},{"id":"pangu","figure_slug":"pangu","title":"반고 (「삼재도회」)","kind":"print","date_label":"1609년","holder":null,"note":"명나라의 백과사전 「삼재도회」에 실린 삽화입니다.","image":{"src":"/images/exhibits/pangu.jpg","width":1014,"height":1546,"alt":"머리에 작은 뿔이 돋고 온몸이 긴 털로 덮인 반고를 그린 흑백 목판 삽화","credit":{"artist":"Wang Qi","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Pangu.jpg"}}},{"id":"fuxi-nuwa","figure_slug":"nuwa","title":"복희와 여와","kind":"painting","date_label":null,"holder":null,"note":"두 신의 윗몸은 사람이고 아랫몸은 서로 꼬인 뱀입니다. 둘레에 해와 별자리가 그려져 있습니다.","image":{"src":"/images/exhibits/fuxi-nuwa.jpg","width":766,"height":1600,"alt":"윗몸은 사람, 아랫몸은 서로 꼬인 뱀인 복희와 여와가 자와 컴퍼스를 들고, 위아래에 해와 달, 둘레에 별이 그려진 그림","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Anonymous-Fuxi_and_N%C3%BCwa.jpg"}}},{"id":"xiwangmu-kano","figure_slug":"xiwangmu","title":"서왕모","kind":"painting","date_label":"19세기","holder":"메트로폴리탄 미술관","note":"일본 가노파 화가 가노 오사노부가 그린 족자입니다.","image":{"src":"/images/exhibits/xiwangmu-kano.jpg","width":1200,"height":1600,"alt":"족자 그림. 소나무 가지 아래 흰 옷을 입은 서왕모가 서 있습니다.","credit":{"artist":"Kano Osanobu","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:%E8%A5%BF%E7%8E%8B%E6%AF%8D%E5%9B%B3-Queen_Mother_of_the_West_MET_DP333861.jpg"}}},{"id":"change-moon","figure_slug":"change","title":"달의 여신 항아","kind":"painting","date_label":null,"holder":null,"note":"명나라 화가 당인의 그림을 따라 그린 작품입니다.","image":{"src":"/images/exhibits/change-moon.jpg","width":841,"height":1600,"alt":"긴 소매 옷을 입은 항아가 서 있고 위쪽에 글이 적힌 세로 족자","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:The_Moon_Goddess_Chang_E_-_Unidentified_artist,_after_Tang_Yin.jpg"}}},{"id":"cernunnos-gundestrup","figure_slug":"cernunnos","title":"군데스트루프 솥의 뿔 달린 신","kind":"relief","date_label":"기원전 2~1세기","holder":"덴마크 국립박물관","note":null,"image":{"src":"/images/exhibits/cernunnos-gundestrup.jpg","width":1280,"height":871,"alt":"사슴뿔을 단 신이 다리를 꼬고 앉아 한 손에 목걸이, 다른 손에 뱀을 쥐고 사슴과 짐승들에 둘러싸인 은 부조","credit":{"artist":"Nationalmuseet, Roberto Fortuna og Kira Ursem","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Gundestrupkedlen-_00054_(cropped).jpg"}}},{"id":"cuchulainn-leyendecker","figure_slug":"cuchulainn","title":"전투하는 쿠 훌린","kind":"painting","date_label":"1911년","holder":null,"note":null,"image":{"src":"/images/exhibits/cuchulainn-leyendecker.jpg","width":1079,"height":1553,"alt":"투구를 쓴 쿠 훌린이 전차 위에서 창을 치켜들고 돌진하는 그림","credit":{"artist":"Joseph Christian Leyendecker","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Cuchulain_in_Battle.jpg"}}},{"id":"brigid-duncan","figure_slug":"brigid","title":"성녀 브리지다","kind":"painting","date_label":"1913년","holder":"스코틀랜드 국립미술관","note":"천사들이 성녀 브리지다를 바다 건너 베들레헴으로 데려간다는 스코틀랜드 헤브리디스의 전설을 그렸습니다.","image":{"src":"/images/exhibits/brigid-duncan.jpg","width":1280,"height":1081,"alt":"날개 달린 두 천사가 흰 옷의 브리지다를 안고 바다 위를 날아가는 그림","credit":{"artist":"John Duncan","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:John_Duncan_(1913)_Saint_Bride.jpg"}}},{"id":"morrigan","figure_slug":"morrigan","title":"까마귀 (「전투하는 쿠 훌린」 부분)","kind":"painting","date_label":"1911년","holder":null,"note":"라이엔데커의 「전투하는 쿠 훌린」에서 까마귀 부분을 잘라 낸 이미지입니다. 전장을 나는 까마귀는 모리안의 모습으로 여겨집니다.","image":{"src":"/images/exhibits/morrigan.jpg","width":500,"height":648,"alt":"붉은 하늘을 배경으로 창끝 곁을 날아가는 검은 까마귀","credit":{"artist":"Joseph Christian Leyendecker","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Morrigan.jpg"}}},{"id":"quetzalcoatl-borbonicus","figure_slug":"quetzalcoatl","title":"케찰코아틀과 테스카틀리포카 (보르보니쿠스 코덱스)","kind":"manuscript","date_label":"16세기 초","holder":"프랑스 국회도서관","note":null,"image":{"src":"/images/exhibits/quetzalcoatl-borbonicus.jpg","width":550,"height":496,"alt":"화려한 깃털과 장신구로 꾸민 두 신이 마주 보고 선 그림 문서","credit":{"artist":null,"license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Quetzalcoatl_and_Tezcatlipoca.jpg"}}},{"id":"tezcatlipoca-borgia","figure_slug":"tezcatlipoca","title":"보르자 코덱스 17쪽","kind":"manuscript","date_label":"15세기 말~16세기 초","holder":"바티칸 도서관","note":"가운데에 크게 그려진 신이 테스카틀리포카입니다.","image":{"src":"/images/exhibits/tezcatlipoca-borgia.jpg","width":1280,"height":1280,"alt":"가운데 화려한 장식의 신이 크게 그려지고, 둘레에 작은 그림 기호들이 빼곡한 그림 문서 한 쪽","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Codex_Borgia_page_17.jpg"}}},{"id":"huitzilopochtli-wdl","figure_slug":"huitzilopochtli","title":"우이칠로포치틀리 (토바르 코덱스)","kind":"manuscript","date_label":"16세기 후반","holder":"존 카터 브라운 도서관","note":"후안 데 토바르가 정리한 아즈텍 역사 사본의 그림입니다.","image":{"src":"/images/exhibits/huitzilopochtli-wdl.jpg","width":1280,"height":963,"alt":"새 머리 투구를 쓴 우이칠로포치틀리가 방패와 뱀 모양 무기를 들고 앉은 그림","credit":{"artist":"Tovar, Juan de, circa 1546-circa 1626","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Huitzilopochtli,_the_Principal_Aztec_God_WDL6725.png"}}},{"id":"tlaloc-borgia","figure_slug":"tlaloc","title":"틀랄록 (보르자 코덱스)","kind":"manuscript","date_label":"15세기 말~16세기 초","holder":"바티칸 도서관","note":null,"image":{"src":"/images/exhibits/tlaloc-borgia.jpg","width":1280,"height":601,"alt":"고글 같은 눈 테와 송곳니를 가진 틀랄록 여럿이 가로로 늘어선 그림 문서","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Tlaloc_Codex_Borgia.jpg"}}},{"id":"mictlantecuhtli-borgia","figure_slug":"mictlantecuhtli","title":"믹틀란테쿠틀리와 케찰코아틀 (보르자 코덱스 56쪽)","kind":"manuscript","date_label":"15세기 말~16세기 초","holder":"바티칸 도서관","note":"죽음의 신 믹틀란테쿠틀리와 바람의 신 에에카틀(케찰코아틀)이 등을 맞댄 장면으로, 1898년에 펴낸 영인본을 찍은 것입니다.","image":{"src":"/images/exhibits/mictlantecuhtli-borgia.jpg","width":1280,"height":1280,"alt":"해골 얼굴의 죽음의 신과 부리 가면을 쓴 바람의 신이 등을 맞대고 선 모습을 그린 그림 문서","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Codex_Borgia_page_56.jpg"}}},{"id":"coatlicue-statue","figure_slug":"coatlicue","title":"코아틀리쿠에 석상","kind":"sculpture","date_label":"15세기 말~16세기 초","holder":"멕시코 국립인류학박물관","note":"1790년 멕시코시티 중앙 광장에서 나온 높이 2.5미터가 넘는 석상입니다.","image":{"src":"/images/exhibits/coatlicue-statue.jpg","width":1067,"height":1600,"alt":"얼굴 자리에 마주 보는 두 뱀 머리가 있고, 뱀을 엮은 치마를 두른 거대한 석상의 정면","credit":{"artist":"Gary Todd from Xinzheng, China","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Aztec_Stone_Coatlique_(Cihuacoatl)_Earth_Goddess_(9754610555).jpg"}}},{"id":"chalchiuhtlicue-met","figure_slug":"chalchiuhtlicue","title":"물의 여신 찰치우틀리쿠에","kind":"sculpture","date_label":"15세기~16세기 초","holder":"메트로폴리탄 미술관","note":null,"image":{"src":"/images/exhibits/chalchiuhtlicue-met.jpg","width":1280,"height":1600,"alt":"술 장식이 달린 머리띠를 두르고 무릎에 손을 얹은 채 앉은 여신의 붉은 돌 조각","credit":{"artist":null,"license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Water_Deity_(Chalchiuhtlicue)_MET_DT1257.jpg"}}},{"id":"coyolxauhqui-head","figure_slug":"coyolxauhqui","title":"코욜사우키 두상","kind":"sculpture","date_label":"15세기 말~16세기 초","holder":"멕시코 국립인류학박물관","note":null,"image":{"src":"/images/exhibits/coyolxauhqui-head.jpg","width":1280,"height":853,"alt":"머리띠를 두르고 큰 귀걸이를 단 코욜사우키의 거대한 돌 두상. 볼에 둥근 방울 무늬가 있습니다.","credit":{"artist":"Gary Todd","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Aztec_Coyolxauhqui,_Moon_Goddess.jpg"}}},{"id":"xipe-totec-gardiner","figure_slug":"xipe-totec","title":"시페 토텍 두상","kind":"sculpture","date_label":"1428~1521년","holder":"가디너 박물관 (토론토)","note":"벗긴 가죽을 쓴 얼굴을 흙으로 빚은 아즈텍 양식의 두상입니다.","image":{"src":"/images/exhibits/xipe-totec-gardiner.jpg","width":1257,"height":1600,"alt":"두툼한 입술을 동그랗게 벌리고 눈이 텅 빈 시페 토텍의 민머리 토기 두상","credit":{"artist":"Daderot","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Head_of_Xipe_Totec,_1428-1521_AD,_Aztec_style,_Mexico,_earthenware_-_Gardiner_Museum,_Toronto_-_DSC01124.JPG"}}},{"id":"dangun-portrait","figure_slug":"dangun","title":"단군 영정","kind":"painting","date_label":"20세기 초","holder":null,"note":"근대 초상화가 채용신이 그린 단군 영정입니다.","image":{"src":"/images/exhibits/dangun-portrait.jpg","width":887,"height":1600,"alt":"관을 쓰고 긴 수염을 기른 단군이 붉은 옷 위에 흰 옷을 걸치고 의자에 앉은 채색 초상","credit":{"artist":"Chae Yong-sin","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Portrait_of_Dangun.jpg"}}},{"id":"bari-lacma","figure_slug":"bari","title":"귀부인 신령과 시녀 (바리공주로 추정)","kind":"painting","date_label":"조선 후기","holder":"로스앤젤레스 카운티 미술관 (LACMA)","note":"미술관은 이 무신도의 귀부인을 바리공주로 추정합니다.","image":{"src":"/images/exhibits/bari-lacma.jpg","width":1178,"height":1600,"alt":"화려한 관을 쓰고 초록과 붉은 옷을 입은 여신이 정면을 보고 앉아 있고, 왼쪽에 작은 시녀가 서 있는 무신도","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Spirit_of_a_Noble_Woman_(Probably_Princess_Pari)_and_Attendant_LACMA_M.2000.15.11.jpg"}}},{"id":"sansin-honolulu","figure_slug":"sansin","title":"범에 기대앉은 산신","kind":"painting","date_label":"조선 시대","holder":"호놀룰루 미술관","note":null,"image":{"src":"/images/exhibits/sansin-honolulu.jpg","width":1111,"height":1600,"alt":"붉은 옷을 입은 산신이 소나무 아래 범에 기대앉아 있고, 양옆에 동자 둘이 서 있는 그림","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Mountain_Spirit_Seated_on_Tiger,_Joseon_dynasty,_Honolulu_Museum_of_Art.jpg"}}},{"id":"jeseok-yongsan","figure_slug":"jeseok","title":"제석 무신도 (용산 남이장군 사당)","kind":"painting","date_label":"19세기","holder":"남이장군 사당 (서울 용산)","note":"삼불제석으로 불리는 세 제석을 그린 무신도입니다.","image":{"src":"/images/exhibits/jeseok-yongsan.jpg","width":456,"height":735,"alt":"붉은 휘장 아래 고깔을 쓰고 흰 장삼을 입은 세 제석이 나란히 선 무신도","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Painting_of_Jeseok_at_Yongsan-gu_Nam_I_shrine.jpg"}}},{"id":"vainamoinen-boat","figure_slug":"vainamoinen","title":"베이네뫼이넨의 떠남","kind":"painting","date_label":"20세기 초","holder":"핀란드 국립미술관","note":"「칼레발라」 마지막 노래에서 베이네뫼이넨이 배를 타고 떠나는 장면을 그린 스케치입니다.","image":{"src":"/images/exhibits/vainamoinen-boat.jpg","width":1148,"height":1600,"alt":"흰 수염의 베이네뫼이넨이 하늘로 솟구치는 배 위에서 팔을 벌리고, 아래에서 사람들이 올려다보는 그림","credit":{"artist":"Akseli Gallen-Kallela","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Akseli_Gallen-Kallela_-_The_Departure_of_V%C3%A4in%C3%A4m%C3%B6inen_-_A_III_2145_-_Finnish_National_Gallery.jpg"}}},{"id":"ilmarinen-sampo","figure_slug":"ilmarinen","title":"삼포를 벼리는 일마리넨","kind":"painting","date_label":"1893년","holder":"핀란드 국립미술관","note":null,"image":{"src":"/images/exhibits/ilmarinen-sampo.jpg","width":1200,"height":1600,"alt":"숲속 대장간에서 대장장이들이 불길 앞에 몸을 숙이고 풀무와 망치로 일하는 그림","credit":{"artist":"Akseli Gallen-Kallela","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Akseli_Gallen-Kallela_-_Sammon_taonta_-_A_I_513_-_Finnish_National_Gallery.jpg"}}},{"id":"ilmarinen-alanen-sampo","figure_slug":"ilmarinen","title":"삼포 벼리기 (요셉 알라넨)","kind":"painting","date_label":"1910~1911년","holder":null,"note":"황금 신부를 그린 옛 그림을 찾지 못해, 같은 대장장이 일마리넨이 대장간에서 삼포를 벼리는 장면을 실었습니다.","image":{"src":"/images/exhibits/ilmarinen-alanen-sampo.jpg","width":1280,"height":1012,"alt":"기하학 무늬로 꾸민 화면에서 대장장이가 풀무 앞에 몸을 숙이고 일하는 그림","credit":{"artist":"Joseph Alanen","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Joseph_Alanen_-_The_Forging_of_the_Sampo.jpg"}}},{"id":"louhi-sampo","figure_slug":"louhi","title":"삼포를 지키는 싸움","kind":"painting","date_label":"1896년","holder":"투르쿠 미술관","note":"독수리로 변한 로우히(오른쪽)가 삼포를 싣고 달아나는 베이네뫼이넨의 배를 덮칩니다.","image":{"src":"/images/exhibits/louhi-sampo.jpg","width":1280,"height":1259,"alt":"흰 머리의 베이네뫼이넨이 배 위에서 칼을 휘두르고, 거대한 날개를 펼친 로우히가 사람들을 태운 채 배를 덮치는 그림","credit":{"artist":"Akseli Gallen-Kallela","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Sammon_puolustus.jpg"}}},{"id":"lemminkainen-mother","figure_slug":"lemminkainen","title":"레민케이넨의 어머니","kind":"painting","date_label":"1897년","holder":"핀란드 국립미술관 (아테네움)","note":null,"image":{"src":"/images/exhibits/lemminkainen-mother.jpg","width":1280,"height":1007,"alt":"강가에 누운 레민케이넨의 몸 곁에서 어머니가 하늘을 올려다보며 앉아 있는 그림. 뒤쪽 검은 강에 백조가 떠 있습니다.","credit":{"artist":"Akseli Gallen-Kallela","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Akseli_Gallen-Kallela_-_Lemmink%C3%A4inen%27s_Mother_-_Google_Art_Project.jpg"}}},{"id":"itzamna-dresden","figure_slug":"itzamna","title":"「드레스덴 코덱스」의 하늘 짐승과 신들 (복원 그림)","kind":"manuscript","date_label":"현대 복원 그림 (원본은 13세기경)","holder":null,"note":"「드레스덴 코덱스」의 한 장면을 색을 살려 다시 그린 그림입니다.","image":{"src":"/images/exhibits/itzamna-dresden.jpg","width":1280,"height":489,"alt":"마야 문자 사이로 길게 누운 하늘 짐승과 그 오른쪽의 신들을 그린 그림 문서","credit":{"artist":"Lacambalam","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Codex_dresdensis_lacambalam_itzamn%C3%A1.jpg"}}},{"id":"chaac-dresden","figure_slug":"chaac","title":"「드레스덴 코덱스」의 차크","kind":"manuscript","date_label":"13세기경 (원본)","holder":"작센 주립도서관 (드레스덴)","note":"원본의 차크 그림을 깨끗하게 다듬은 선 그림입니다.","image":{"src":"/images/exhibits/chaac-dresden.jpg","width":599,"height":803,"alt":"긴 코와 화려한 머리 장식을 한 차크가 앉아 손에 무언가를 든 선 그림","credit":{"artist":"Un scribe maya précolombien non identifié avant 1500.","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Le_dieu_Chaac,_image_12_du_codex_de_Dresde.jpg"}}},{"id":"kukulkan-castillo","figure_slug":"kukulkan","title":"치첸이차의 엘 카스티요 (쿠쿨칸 신전)","kind":"photograph","date_label":null,"holder":"치첸이차 (멕시코 유카탄)","note":null,"image":{"src":"/images/exhibits/kukulkan-castillo.jpg","width":1280,"height":853,"alt":"풀밭 위에 선 계단식 석조 피라미드와 꼭대기의 작은 신전","credit":{"artist":"Arian Zwegers from Brussels, Belgium","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Chichen_Itza,_El_Castillo_(14180679857).jpg"}}},{"id":"maize-god-copan","figure_slug":"maize-god","title":"코판의 옥수수 신","kind":"sculpture","date_label":"8세기","holder":"대영박물관","note":"온두라스 코판의 22번 신전을 장식하던 조각입니다.","image":{"src":"/images/exhibits/maize-god-copan.jpg","width":901,"height":1600,"alt":"길게 늘인 머리에 장식을 단 젊은 신이 한 손을 들고 있는 석조 상반신","credit":{"artist":"BabelStone","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Maya_maize_god_statue.jpg"}}},{"id":"ix-chel-dresden","figure_slug":"ix-chel","title":"드레스덴 코덱스 74쪽","kind":"manuscript","date_label":"13세기경","holder":"작센 주립·대학 도서관 (드레스덴)","note":"하늘의 괴물이 물을 쏟고 늙은 여신이 항아리를 기울이는 장면으로, 세상을 쓸어버린 홍수로 풀이하기도 합니다. 이 늙은 여신을 이슈 첼로 볼지에는 견해가 갈립니다.","image":{"src":"/images/exhibits/ix-chel-dresden.jpg","width":711,"height":1600,"alt":"붉은 바탕 위에서 뱀 머리 장식을 한 늙은 여신이 항아리의 물을 쏟고, 아래에 창을 든 검은 신이 있는 그림 문서","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Dresden_p_74_large.jpg"}}},{"id":"hero-twins-popol-vuh-vessel","figure_slug":"hero-twins","title":"「포폴 부」 장면이 그려진 마야 그릇","kind":"sculpture","date_label":"600~850년","holder":"드 영 미술관 (샌프란시스코)","note":"쌍둥이 영웅의 이야기가 담긴 「포폴 부」의 한 장면을 그린 고전기 마야의 원통형 그릇입니다.","image":{"src":"/images/exhibits/hero-twins-popol-vuh-vessel.jpg","width":947,"height":1600,"alt":"붉은 테두리 안에 머리 장식을 한 인물들이 그려진 원통형 마야 토기","credit":{"artist":"Daderot","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Vessel_with_scene_from_the_Popol_Vuh,_600-850_AD,_Guatemala,_Maya,_earthenware,_stucco,_and_pigment_-_De_Young_Museum,_San_Francisco.jpg"}}},{"id":"vucub-caquix-macaw","figure_slug":"vucub-caquix","title":"마코앵무새","kind":"photograph","date_label":"2014년 사진","holder":null,"note":"부쿱 카킥스를 그린 옛 그림은 사진을 찾지 못해, 그 모습의 바탕인 마코앵무새를 찍은 사진을 실었습니다.","image":{"src":"/images/exhibits/vucub-caquix-macaw.jpg","width":1280,"height":1083,"alt":"파란 날개와 노란 가슴을 한 마코앵무새가 나뭇가지에 앉아 있습니다.","credit":{"artist":"Christopher Kuszajewski","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Macaw_parrot_sitting_on_a_tree_branch.jpg_.jpg"}}},{"id":"dionysus-caravaggio","figure_slug":"dionysus","title":"바쿠스","kind":"painting","date_label":"1598년경","holder":"우피치 미술관","note":"카라바조가 그린 디오니소스(로마 이름 바쿠스)입니다.","image":{"src":"/images/exhibits/dionysus-caravaggio.jpg","width":1280,"height":1456,"alt":"포도 잎 관을 쓰고 흰 천을 두른 젊은 바쿠스가 포도주 잔을 내밀고, 앞에 과일 바구니가 놓인 그림","credit":{"artist":"Caravaggio","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Bacchus_(by_Michelangelo_Merisi_da_Caravaggio)_%E2%80%93_Galleria_degli_Uffizi,_Florence.jpg"}}},{"id":"hephaestus-velazquez","figure_slug":"hephaestus","title":"불카누스의 대장간","kind":"painting","date_label":"1630년","holder":"프라도 미술관","note":"아폴론(왼쪽)이 대장간에 찾아와 헤파이스토스(로마 이름 불카누스)에게 아내 아프로디테와 아레스의 일을 알리는 장면입니다.","image":{"src":"/images/exhibits/hephaestus-velazquez.jpg","width":1280,"height":994,"alt":"월계관을 쓴 아폴론이 대장간에 들어서 말하고, 대장장이들이 일손을 멈추고 돌아보는 그림","credit":{"artist":"Diego Velázquez","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Vel%C3%A1zquez_-_La_Fragua_de_Vulcano_(Museo_del_Prado,_1630).jpg"}}},{"id":"heracles-farnese","figure_slug":"heracles","title":"파르네세의 헤라클레스","kind":"photograph","date_label":"19세기 사진 (조각은 3세기 초 로마 모작)","holder":"나폴리 국립고고학박물관","note":"조르조 조메르가 찍은 사진입니다. 지친 헤라클레스가 사자 가죽을 걸친 몽둥이에 기대 쉬고 있습니다.","image":{"src":"/images/exhibits/heracles-farnese.jpg","width":1159,"height":1600,"alt":"근육이 우람한 헤라클레스가 사자 가죽을 걸친 몽둥이에 기대 선 대리석상의 사진","credit":{"artist":null,"license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Giorgio_Sommer_(Italian,_1834-1914)_-_Farnese_Hercules,_Museum_of_Naples,_Italy_-_2018.436_-_Cleveland_Museum_of_Art.jpg"}}},{"id":"medusa-caravaggio","figure_slug":"medusa","title":"메두사","kind":"painting","date_label":"1597년경","holder":"우피치 미술관","note":"둥근 방패에 그린 그림입니다.","image":{"src":"/images/exhibits/medusa-caravaggio.jpg","width":1280,"height":1312,"alt":"둥근 방패 위에 그린, 뱀 머리카락을 한 메두사가 입을 벌리고 비명을 지르는 잘린 머리","credit":{"artist":"Caravaggio","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Caravaggio_-_Medusa_-_Google_Art_Project.jpg"}}},{"id":"set-ramesses","figure_slug":"set","title":"람세스 3세에게 관을 씌우는 세트 (부분)","kind":"sculpture","date_label":"기원전 12세기","holder":"이집트 박물관 (카이로)","note":"호루스와 세트가 함께 람세스 3세에게 관을 씌우는 조각에서 세트 부분을 찍은 사진입니다.","image":{"src":"/images/exhibits/set-ramesses.jpg","width":1280,"height":1190,"alt":"긴 주둥이와 위로 솟은 네모난 귀를 가진 세트의 석조 머리","credit":{"artist":"A. Parrot","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Horus_and_Seth_crowning_Ramesses_III,_detail_of_Seth.JPG"}}},{"id":"hathor-capital","figure_slug":"hathor","title":"하토르 얼굴 기둥머리","kind":"sculpture","date_label":"고대 이집트","holder":"제네바 미술역사박물관","note":null,"image":{"src":"/images/exhibits/hathor-capital.jpg","width":1280,"height":1280,"alt":"암소 귀를 가진 하토르의 얼굴 위에 작은 신전 모양을 얹은 석조 기둥머리","credit":{"artist":"Rama","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Capital_depicting_Hathor-MAHG_027868-P6130434-white.jpg"}}},{"id":"hathor-sistrum","figure_slug":"hathor","title":"시스트럼의 하토르 장식","kind":"sculpture","date_label":"기원전 664~332년","holder":"메트로폴리탄 미술관","note":"딸랑이 악기 시스트럼의 손잡이 위를 꾸미던 부분입니다.","image":{"src":"/images/exhibits/hathor-sistrum.jpg","width":1280,"height":1505,"alt":"암소 귀를 단 여신의 얼굴 위에 작은 신전 문 모양을 얹은 연녹색 파이앙스 장식","credit":{"artist":null,"license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Bat_-_Hathor_emblem_from_a_sistrum_MET_DP318530.jpg"}}},{"id":"bastet-met","figure_slug":"bastet","title":"바스테트 소상","kind":"sculpture","date_label":"고대 이집트","holder":"메트로폴리탄 미술관","note":null,"image":{"src":"/images/exhibits/bastet-met.jpg","width":1069,"height":1600,"alt":"고양이 머리를 한 여인이 받침 위에 똑바로 선 청동 소상","credit":{"artist":null,"license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Bastet_MET_DP310891.jpg"}}},{"id":"lakshmi-varma","figure_slug":"lakshmi","title":"락슈미","kind":"painting","date_label":"1896년","holder":null,"note":"인도 화가 라자 라비 바르마의 그림입니다.","image":{"src":"/images/exhibits/lakshmi-varma.jpg","width":1057,"height":1496,"alt":"붉은 사리를 입고 두 손에 연꽃을 든 네 팔의 락슈미가 물 위의 연꽃에 서 있고, 뒤에서 코끼리들이 물을 뿜는 그림","credit":{"artist":"Raja Ravi Varma","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Raja_Ravi_Varma,_Goddess_Lakshmi,_1896.jpg"}}},{"id":"hanuman-cleveland","figure_slug":"hanuman","title":"하누만","kind":"sculpture","date_label":"촐라 왕조 시대","holder":"클리블랜드 미술관","note":null,"image":{"src":"/images/exhibits/hanuman-cleveland.jpg","width":1147,"height":1600,"alt":"한 손을 입가에 대고 몸을 살짝 숙인 채 연꽃 받침 위에 선 하누만의 청동상","credit":{"artist":null,"license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Clevelandart_1980.26.jpg"}}},{"id":"hanuman-gada","figure_slug":"hanuman","title":"악마를 치는 하누만","kind":"painting","date_label":"19세기 말","holder":"빅토리아 앨버트 박물관","note":null,"image":{"src":"/images/exhibits/hanuman-gada.jpg","width":1252,"height":1592,"alt":"원숭이 얼굴의 하누만이 한 손에 철퇴를 치켜들고 다른 손으로 뿔 난 악마의 머리를 움켜쥔 그림","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Hanuman_striking_a_demon.jpg"}}},{"id":"durga-dallas","figure_slug":"durga","title":"마히샤를 무찌르는 두르가","kind":"relief","date_label":"12세기 (팔라 왕조)","holder":"댈러스 미술관","note":null,"image":{"src":"/images/exhibits/durga-dallas.jpg","width":1067,"height":1600,"alt":"여러 팔에 무기를 든 두르가가 발아래의 물소 악마를 무찌르는 석조 부조","credit":{"artist":"Daderot","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Durga_Mahishasuramardini_slaying_the_Buffalo_Demon,_Bengal,_India,_or_Bangladesh,_Pala_dynasty,_1100s_AD,_phyllite_-_Dallas_Museum_of_Art_-_DSC05056.jpg"}}},{"id":"frigg-doepler","figure_slug":"frigg","title":"프리그","kind":"print","date_label":"19세기 말","holder":null,"note":"카를 에밀 되플러의 삽화입니다.","image":{"src":"/images/exhibits/frigg-doepler.jpg","width":835,"height":1006,"alt":"왕좌에 앉은 프리그 곁에 시녀들과 창을 든 여인이 서 있는 흑백 판화","credit":{"artist":"Carl Emil Doepler","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Frigg_by_Doepler.jpg"}}},{"id":"tyr-bauer","figure_slug":"tyr","title":"티르와 펜리르","kind":"print","date_label":"1911년","holder":null,"note":"스웨덴 화가 욘 바우에르의 삽화입니다.","image":{"src":"/images/exhibits/tyr-bauer.jpg","width":733,"height":855,"alt":"거대한 늑대 펜리르의 입에 한 팔을 넣은 티르가 곁에 서 있는 그림","credit":{"artist":"John Bauer","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Tyr_and_Fenrir-John_Bauer.jpg"}}},{"id":"ahura-mazda-faravahar","figure_slug":"ahura-mazda","title":"페르세폴리스 왕묘 부조의 파라바하르 (도판)","kind":"print","date_label":"19세기 도판 (부조는 기원전 5~4세기)","holder":null,"note":"외젠 플랑댕이 페르세폴리스 왕묘 정면 부조를 옮겨 그린 도판입니다. 맨 위에 날개 달린 원반 파라바하르가 있습니다.","image":{"src":"/images/exhibits/ahura-mazda-faravahar.jpg","width":422,"height":1024,"alt":"맨 위에 날개 달린 원반 문양이 있고, 그 아래 단 위의 왕과 여러 단의 인물들을 새긴 왕묘 정면을 그린 선 그림","credit":{"artist":"Eugène Flandin","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Persepolis_Bas-relief_Flandin.jpg"}}},{"id":"mithra-taq-bostan","figure_slug":"mithra","title":"아르다시르 2세의 왕권 수여 부조","kind":"relief","date_label":"4세기","holder":"타크에 보스탄 (이란 케르만샤)","note":"가운데 왕이 왕권의 고리를 받고, 왼쪽에 머리에 햇살을 두른 미트라가 연꽃 위에 서 있습니다.","image":{"src":"/images/exhibits/mithra-taq-bostan.jpg","width":1024,"height":920,"alt":"햇살 관을 쓴 신, 가운데의 왕, 오른쪽의 다른 인물이 나란히 선 바위 부조","credit":{"artist":"Philippe Chavin","license":"CC BY 2.5","licenseUrl":"https://creativecommons.org/licenses/by/2.5","sourceUrl":"https://commons.wikimedia.org/wiki/File:Taq-e_Bostan_-_High-relief_of_Ardeshir_II_investiture.jpg"}}},{"id":"anahita-taq-bostan","figure_slug":"anahita","title":"타크에 보스탄 큰 동굴 부조 (도판)","kind":"print","date_label":"19세기 도판 (부조는 7세기)","holder":null,"note":"호스로 2세가 가운데 서서 아후라 마즈다와 아나히타 사이에서 왕권을 받는 장면을 옮겨 그린 도판입니다.","image":{"src":"/images/exhibits/anahita-taq-bostan.jpg","width":1280,"height":908,"alt":"화려한 옷을 입은 왕이 가운데 서고, 양옆의 신이 왕권의 고리를 건네는 아치형 부조를 그린 선 그림","credit":{"artist":"Scan by NYPL","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Tak-i_Bostan._Figures_comprises_dans_la_vo%C3%BBte_no._1_(NYPL_b12482496-1542715)_(cropped).jpg"}}},{"id":"baal-ugarit","figure_slug":"baal","title":"번개를 든 바알 석비","kind":"relief","date_label":"기원전 15~13세기","holder":"루브르 박물관","note":"시리아 우가리트에서 나온 석비입니다.","image":{"src":"/images/exhibits/baal-ugarit.jpg","width":688,"height":1600,"alt":"뿔 달린 투구를 쓴 바알이 한 손에 몽둥이를 치켜들고 다른 손에 번개 창을 든 채 걸어가는 석비","credit":{"artist":"Jastrow","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Baal_thunderbolt_Louvre_AO15775.jpg"}}},{"id":"astarte-throne","figure_slug":"astarte","title":"옥좌에 앉은 여신 (아스타르테로 보는 상)","kind":"sculpture","date_label":null,"holder":"빈 미술사 박물관","note":"페니키아 여신 좌상으로, 아스타르테로 소개됩니다.","image":{"src":"/images/exhibits/astarte-throne.jpg","width":1156,"height":1600,"alt":"긴 베일을 쓰고 옥좌에 앉은 여신 석상. 옆에 작은 인물상이 붙어 있습니다.","credit":{"artist":"Faustyna E.","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:PhoenicianGoddess(Astarte_)onThrone_ViennaKunsthistorischesMuseum_cropped_FaustynaE.jpg"}}},{"id":"el-megiddo","figure_slug":"el","title":"메기도의 금박 신상","kind":"sculpture","date_label":"기원전 1400~1200년경","holder":"시카고 대학교 오리엔탈 연구소 박물관","note":"메기도의 신전 터에서 나온 금박 입힌 청동 좌상으로, 박물관은 엘로 봅니다.","image":{"src":"/images/exhibits/el-megiddo.jpg","width":1067,"height":1600,"alt":"높은 원뿔 관을 쓰고 수염을 기른 신이 의자에 앉아 한 손을 들어 올린 금박 청동 좌상","credit":{"artist":"Daderot","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:El,_the_Canaanite_creator_deity,_Megiddo,_Stratum_VII,_Late_Bronze_II,_1400-1200_BC,_bronze_with_gold_leaf_-_Oriental_Institute_Museum,_University_of_Chicago_-_DSC07734.JPG"}}},{"id":"anat-ramesses","figure_slug":"anat","title":"람세스 2세와 아낫","kind":"sculpture","date_label":"기원전 13세기","holder":null,"note":"이집트 신왕국은 가나안의 여신 아낫을 받아들여 섬겼습니다.","image":{"src":"/images/exhibits/anat-ramesses.jpg","width":899,"height":1600,"alt":"높은 관을 쓴 아낫과 람세스 2세가 나란히 앉은 화강암 조각","credit":{"artist":"A. Parrot","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Anat_and_Ramesses_II.JPG"}}},{"id":"kirta-baal-cycle-tablet","figure_slug":"kirta","title":"바알 이야기가 적힌 우가리트 서판","kind":"manuscript","date_label":"기원전 14~13세기","holder":"루브르 박물관","note":"키르타 이야기를 적은 서판은 사진을 찾지 못해, 같은 우가리트에서 나온 바알 신화 서판을 실었습니다.","image":{"src":"/images/exhibits/kirta-baal-cycle-tablet.jpg","width":1196,"height":1600,"alt":"세로 단으로 나뉜 면에 쐐기 문자가 빼곡하게 새겨진 길쭉한 점토판","credit":{"artist":"Shonagon","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Tablette_avec_po%C3%A8me_mythologique_du_cycle_de_Ba%27al_-_Mus%C3%A9e_du_Louvre_Antiquit%C3%A9s_orientales_AO_16636.jpg"}}},{"id":"teshub-yazilikaya","figure_slug":"teshub","title":"야즐르카야 바위 성소의 신들","kind":"relief","date_label":"기원전 13세기","holder":"야즐르카야 (튀르키예 보아즈칼레)","note":"하투샤 근처 바위 성소의 신들 행렬 부조로, 테슈브와 헤바트가 마주 서는 장면이 새겨져 있습니다.","image":{"src":"/images/exhibits/teshub-yazilikaya.jpg","width":1064,"height":1600,"alt":"햇빛과 그림자가 드리운 바위 벽에 긴 옷을 입은 신들이 새겨진 부조","credit":{"artist":"Dosseman","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Yaz%C4%B1l%C4%B1kaya_room_A_Teshub,_Hebat_and_others_3496.jpg"}}},{"id":"illuyanka-malatya","figure_slug":"illuyanka","title":"뱀 일루얀카를 치는 폭풍의 신","kind":"relief","date_label":"기원전 11~9세기","holder":"아나톨리아 문명 박물관 (앙카라)","note":"튀르키예 말라티야에서 나온 부조입니다.","image":{"src":"/images/exhibits/illuyanka-malatya.jpg","width":1280,"height":767,"alt":"굽이치는 큰 뱀과, 그 위에서 무기를 휘두르는 신들을 새긴 석조 부조","credit":{"artist":"Dosseman","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Anatolian_Civilizations_Museum_slaying_of_the_serpent_Illuyanka_by_the_Storm_God_in_2011_03.jpg"}}},{"id":"telipinu-hittite-goddess","figure_slug":"telipinu","title":"아이를 안은 히타이트 여신상","kind":"sculpture","date_label":"기원전 14~13세기","holder":"메트로폴리탄 미술관","note":"텔리피누를 직접 나타낸 유물은 전하지 않아, 같은 시대 히타이트 사람들이 만든 금 여신상을 실었습니다. 누구를 나타냈는지는 알 수 없습니다.","image":{"src":"/images/exhibits/telipinu-hittite-goddess.jpg","width":1203,"height":1600,"alt":"머리 뒤에 둥근 원반을 두른 여신이 무릎에 작은 아이를 안고 앉은 금 조각","credit":{"artist":null,"license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Seated_goddess_with_a_child_MET_DT873.jpg"}}},{"id":"kumarbi-hittite-tablet","figure_slug":"kumarbi","title":"히타이트 쐐기 문자 점토판","kind":"manuscript","date_label":"기원전 2천년기 후반","holder":"시카고 대학교 동양학연구소","note":"쿠마르비를 그린 옛 그림이나 조각은 전하지 않습니다. 쿠마르비 신화는 이런 히타이트 점토판에 쐐기 문자로 적혀 전합니다.","image":{"src":"/images/exhibits/kumarbi-hittite-tablet.jpg","width":1280,"height":1524,"alt":"갈색 점토판에 쐐기 문자가 가로줄을 이루며 빼곡하게 새겨져 있습니다.","credit":{"artist":"Mx. Granger","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Hittite_Cuneiform_Tablet-_Cultic_Festival_Script.jpg"}}},{"id":"ullikummi-mount-casius","figure_slug":"ullikummi","title":"바다에서 본 카시오스산 (존 칸)","kind":"print","date_label":"1836년","holder":null,"note":"울리쿰미를 그린 옛 그림은 전하지 않습니다. 신화에서 폭풍의 신 테슈브는 하치산(카시오스산)에 올라 바다에서 자라는 돌 거인 울리쿰미를 바라봅니다.","image":{"src":"/images/exhibits/ullikummi-mount-casius.jpg","width":800,"height":608,"alt":"달빛 아래 바다 너머로 높은 산이 솟아 있고, 앞쪽에 돛단배들이 떠 있는 동판화","credit":{"artist":"John Carne","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Mount_Casius_from_the_Sea_-_Carne_John_-_1836.jpg"}}},{"id":"allat-palmyra","figure_slug":"allat","title":"팔미라의 알라트 신전 터","kind":"photograph","date_label":null,"holder":"팔미라 (시리아)","note":null,"image":{"src":"/images/exhibits/allat-palmyra.jpg","width":1280,"height":852,"alt":"사막 언덕 아래 낮은 돌담과 기둥 받침이 남은 신전 터","credit":{"artist":"Dosseman","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Palmyra_Temple_of_Allat_0066.jpg"}}},{"id":"dushara-nabataean","figure_slug":"dushara","title":"두샤라로 보는 신의 부조","kind":"relief","date_label":"로마 시대","holder":null,"note":"수염 난 신의 모습으로 새겨진 부조로, 나바테아의 두샤라로 소개됩니다.","image":{"src":"/images/exhibits/dushara-nabataean.jpg","width":1200,"height":1600,"alt":"곱슬 수염을 기른 신이 긴 옷을 입고 서 있는 붉은 돌 부조","credit":{"artist":null,"license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Dhushara.JPG"}}},{"id":"perun-slavic","figure_slug":"perun","title":"천둥의 신 페룬","kind":"painting","date_label":"21세기","holder":null,"note":"러시아 화가 안드레이 시시킨이 그린 현대 그림입니다.","image":{"src":"/images/exhibits/perun-slavic.jpg","width":877,"height":1122,"alt":"투구를 쓰고 갑옷을 입은 수염 난 페룬이 칼과 방패를 들고 붉은 하늘을 배경으로 앉은 그림","credit":{"artist":"Andrey Shishkin","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Perun_Gromoverzhecz_by_Andrey_Shishkin.jpg"}}},{"id":"svetovid-zbruch","figure_slug":"svetovid","title":"즈브루치의 우상","kind":"sculpture","date_label":"9~10세기경 (논란 있음)","holder":"크라쿠프 고고학 박물관","note":"네 면에 얼굴을 새긴 돌기둥으로, 흔히 스뱌토비트와 이어서 소개됩니다.","image":{"src":"/images/exhibits/svetovid-zbruch.jpg","width":1280,"height":1280,"alt":"꼭대기에 모자를 쓴 네 얼굴이 있고, 기둥 면마다 인물을 새긴 길쭉한 돌기둥","credit":{"artist":null,"license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Svetovid_%E2%80%93_Zbruch_Idol_(MAK-63).jpg"}}},{"id":"baba-yaga-bilibin","figure_slug":"baba-yaga","title":"바바 야가","kind":"print","date_label":"1900년","holder":null,"note":"이반 빌리빈이 러시아 민담 그림책에 그린 삽화입니다.","image":{"src":"/images/exhibits/baba-yaga-bilibin.jpg","width":1249,"height":1600,"alt":"흰 머리를 휘날리는 바바 야가가 절구를 타고 절굿공이를 휘두르며 숲 위를 나는 그림","credit":{"artist":"Ivan Bilibin","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Bilibin._Baba_Yaga.jpg"}}},{"id":"perkunas-baltic","figure_slug":"perkunas","title":"페르쿠나스로 소개되는 청동 소상 (사진)","kind":"photograph","date_label":null,"holder":null,"note":"리투아니아에서 페르쿠나스로 소개된 소상의 흑백 사진입니다. 소상의 출처와 시기는 확인하지 못했습니다.","image":{"src":"/images/exhibits/perkunas-baltic.jpg","width":1143,"height":1600,"alt":"한 팔을 들어 올리고 웅크린 수염 난 인물의 청동 소상을 찍은 흑백 사진","credit":{"artist":"Society for the Protection of Monuments and Local History of the Lithuanian SSR","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Perkunas_of_Kernav%C4%97s.jpg"}}},{"id":"laima-ciurlionis-fairy-tale","figure_slug":"laima","title":"왕들의 동화 (추를료니스)","kind":"painting","date_label":"1909년","holder":"추를료니스 국립미술관 (카우나스)","note":"라이마를 그린 옛 그림은 전하지 않아, 리투아니아 화가 추를료니스가 그린 동화 그림을 실었습니다.","image":{"src":"/images/exhibits/laima-ciurlionis-fairy-tale.jpg","width":1280,"height":1201,"alt":"어두운 숲속에서 왕관 쓴 두 왕이 손바닥 위에 빛나는 작은 세상을 받쳐 든 그림","credit":{"artist":"Mikalojus Konstantinas Čiurlionis","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Mikalojus_Konstantinas_Ciurlionis_-_FAIRY_TALE_(FAIRY_TALE_OF_KINGS)_-_1909.jpg"}}},{"id":"kalevipoeg-raud","figure_slug":"kalevipoeg","title":"칼레비포에그와 바나파간","kind":"painting","date_label":"1930년대","holder":"타르투 미술관","note":"크리스티안 라우드가 서사시 「칼레비포에그」를 위해 그린 그림입니다.","image":{"src":"/images/exhibits/kalevipoeg-raud.jpg","width":1280,"height":1016,"alt":"근육질의 두 거인이 몸을 맞붙이고 씨름하는 모습을 그린 갈색조 그림","credit":{"artist":"Kristjan Raud","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:TKM_2797B_Kristjan_Raud_-_Kalevipoeg_ja_Vanapagan.jpg"}}},{"id":"tinia-etruscan","figure_slug":"tinia","title":"티니아와 신들이 새겨진 에트루리아 거울 (도판)","kind":"print","date_label":"19세기 도판 (거울은 기원전 4세기경)","holder":null,"note":"청동 거울 뒷면의 선각을 옮겨 그린 도판으로, 티니아·우니·멘르바·투란 등의 이름이 새겨져 있습니다.","image":{"src":"/images/exhibits/tinia-etruscan.jpg","width":1280,"height":1554,"alt":"둥근 거울 안에 여러 신이 모여 앉고 서 있으며, 손잡이 쪽에 얼굴 하나를 그린 선 그림","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Etruscan_mirror_with_Tinia_Uni_Hercle_Menrva_Turan_Mean.jpg"}}},{"id":"charun-etruscan","figure_slug":"charun","title":"프랑수아 무덤 벽화 (트로이 포로의 희생)","kind":"painting","date_label":"기원전 4세기","holder":"토를로니아 컬렉션 (로마)","note":"에트루리아 불치의 프랑수아 무덤 벽화로, 푸른 피부의 카룬이 장면 오른쪽에 서 있습니다.","image":{"src":"/images/exhibits/charun-etruscan.jpg","width":1280,"height":637,"alt":"여러 전사가 포로를 끌어다 희생시키는 장면을 그린 벽화","credit":{"artist":"Askelladd","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Achilles%27_Sacrifice_of_Trojan_Prisoners.jpg"}}},{"id":"menrva-etruscan","figure_slug":"menrva","title":"헤르클레·멘르바·아풀루가 새겨진 거울 (도판)","kind":"print","date_label":"19세기 도판 (거울은 기원전 4세기경)","holder":null,"note":"가운데 투구를 쓴 멘르바, 양옆에 헤르클레(헤라클레스)와 아풀루(아폴론)가 서 있습니다.","image":{"src":"/images/exhibits/menrva-etruscan.jpg","width":1280,"height":1513,"alt":"둥근 거울 안에 투구를 쓴 여신과 양옆의 두 남신이 서 있는 선 그림","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Etruscan_mirror_with_Hercle_Menrva_Apulu.jpg"}}},{"id":"snake-goddess-minoan","figure_slug":"snake-goddess","title":"뱀의 여신 소상","kind":"sculpture","date_label":"기원전 1600년경","holder":"이라클리온 고고학 박물관","note":"크노소스 궁전에서 발견된 파양스 소상입니다.","image":{"src":"/images/exhibits/snake-goddess-minoan.jpg","width":1008,"height":1600,"alt":"층층 치마를 입은 여인이 양팔을 들어 뱀을 쥐고, 머리 위에 작은 짐승이 앉은 소상","credit":{"artist":"Jebulon","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Snake_goddess_archmus_Heraklion.jpg"}}},{"id":"mistress-animals-minoan","figure_slug":"mistress-of-animals","title":"짐승들 사이의 여신을 새긴 인장","kind":"relief","date_label":"청동기 시대","holder":null,"note":"둥근 인장 돌과 그것을 찍은 자국을 함께 찍은 사진입니다.","image":{"src":"/images/exhibits/mistress-animals-minoan.jpg","width":865,"height":1600,"alt":"둥근 인장 돌 아래에, 양옆에 짐승을 거느린 인물이 새겨진 인장 자국","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:P1010631_CROP_crop.jpg"}}},{"id":"anahit-satala","figure_slug":"anahit","title":"사탈라 청동 두상 (도판)","kind":"print","date_label":"19세기 도판 (두상은 기원전 2~1세기)","holder":"대영박물관 (두상)","note":"아르메니아 사탈라에서 나온 청동 두상을 그린 도판입니다. 아프로디테로 이름 붙었지만 아나히트로 보는 견해가 있습니다.","image":{"src":"/images/exhibits/anahit-satala.jpg","width":1245,"height":1600,"alt":"머리띠를 두른 여인의 옆얼굴을 그린 흑백 도판. 아래에 ‘ΑΦΡΟΔΙΤΗ’라고 적혀 있습니다.","credit":{"artist":"Thomas Eyre Macklin","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:T.E._Macklin_Aphrodite_bronze_mask.jpg"}}},{"id":"hayk-zasso","figure_slug":"hayk","title":"벨을 쓰러뜨리는 하이크","kind":"print","date_label":"19세기","holder":null,"note":"이탈리아 화가 줄리아노 차소(1833~1889)가 아르메니아 역사를 주제로 그린 그림입니다.","image":{"src":"/images/exhibits/hayk-zasso.jpg","width":1280,"height":989,"alt":"산기슭 싸움터 한가운데서 하이크가 활시위를 당기고, 언덕 위에서 창을 치켜든 벨이 군사를 이끄는 그림","credit":{"artist":"Juliano Zasso","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Hayk_defeats_Bel_-_Guiliano_Zasso.jpg"}}},{"id":"ara-sureniants","figure_slug":"ara","title":"세미라미스와 아름다운 아라","kind":"painting","date_label":"1899년","holder":null,"note":"바르게스 수레냔츠(1921년 사망)의 그림입니다.","image":{"src":"/images/exhibits/ara-sureniants.jpg","width":460,"height":981,"alt":"부조로 꾸민 궁전 기둥 곁에서 세미라미스가 의자에 앉아 턱을 괴고, 앞쪽 침상에 아라의 시신이 누워 있는 그림","credit":{"artist":"Vardges Sureniants","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Shamiram_ara.jpeg"}}},{"id":"vahagn-vishap","figure_slug":"vahagn","title":"아르메니아의 용 돌 (비샤파카르)","kind":"photograph","date_label":"옛 사진 (돌은 청동기 시대)","holder":null,"note":"바하근을 직접 나타낸 옛 그림·조각은 전하지 않습니다. 바하근은 '용을 베는 이(비샤파카흐)'라 불렸는데, 아르메니아 고원에는 용(비샤프)이라 부르는 물고기 모양 선돌이 전합니다.","image":{"src":"/images/exhibits/vahagn-vishap.jpg","width":1280,"height":875,"alt":"풀밭에 물고기 모양으로 깎은 길쭉한 돌이 누워 있는 흑백 사진","credit":{"artist":null,"license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Vishap06.jpg"}}},{"id":"turul-hungarian","figure_slug":"turul","title":"타타바냐의 투룰상","kind":"sculpture","date_label":"1907년","holder":"타타바냐 (헝가리)","note":null,"image":{"src":"/images/exhibits/turul-hungarian.jpg","width":1024,"height":576,"alt":"나무가 우거진 바위 언덕 꼭대기에서 날개를 펼친 큰 새 조각","credit":{"artist":"Gyula Donáth","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Turul_-_B%C3%A1nhida_(Tatab%C3%A1nya)_-_2.jpg"}}},{"id":"emese-dream","figure_slug":"emese","title":"에메세의 꿈","kind":"painting","date_label":"1850년경","holder":null,"note":"에메세가 꿈에 투룰 새를 보고 아르파드 왕가의 시조 알모시를 낳았다는 이야기를 그린 그림입니다.","image":{"src":"/images/exhibits/emese-dream.jpg","width":674,"height":600,"alt":"구슬 장식 머리쓰개를 쓴 여인의 어깨 옆에 매 모양의 새가 앉아 있는 그림","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Emese_%C3%A1lma.jpg"}}},{"id":"weland-franks-casket","figure_slug":"weland","title":"프랭크스 상자 (도판)","kind":"print","date_label":"1901년 도판 (상자는 8세기)","holder":"대영박물관 (상자)","note":"8세기 노섬브리아에서 고래뼈로 만든 상자로, 앞면에 대장장이 웨일랜드의 이야기가 새겨져 있습니다.","image":{"src":"/images/exhibits/weland-franks-casket.jpg","width":1280,"height":894,"alt":"룬 문자 테두리 안에 여러 인물을 새긴 상자 판을 찍은 흑백 도판","credit":{"artist":"Unknown artist","license":"No restrictions","licenseUrl":"https://www.flickr.com/commons/usage/","sourceUrl":"https://commons.wikimedia.org/wiki/File:Contributions_to_Old_English_literature_(1901)_(14597378649).jpg"}}},{"id":"beowulf-anglo-saxon","figure_slug":"beowulf","title":"그렌델 (「베오울프 이야기」 삽화)","kind":"print","date_label":"1908년","holder":null,"note":"J. R. 스켈턴이 그린 삽화로, 베오울프가 맞선 괴물 그렌델을 그렸습니다.","image":{"src":"/images/exhibits/beowulf-anglo-saxon.jpg","width":1055,"height":1356,"alt":"노을 진 물가에 털이 덥수룩한 거대한 괴물 그렌델이 입을 벌리고 서 있는 그림","credit":{"artist":"Joseph Ratcliffe Skelton","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Stories_of_beowulf_grendel.jpg"}}},{"id":"grendel-skelton","figure_slug":"grendel","title":"그렌델의 머리를 메고 돌아오는 전사들","kind":"print","date_label":"1908년","holder":null,"note":"H. E. 마셜의 「베오울프 이야기」에 실린 조지프 래트클리프 스켈턴의 삽화입니다.","image":{"src":"/images/exhibits/grendel-skelton.jpg","width":1059,"height":1371,"alt":"금빛 투구를 쓴 베오울프 앞에서 전사들이 창 자루에 매단 그렌델의 거대한 머리를 메고 가는 삽화","credit":{"artist":"Joseph Ratcliffe Skelton","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Stories_of_beowulf_head_of_grendel.jpg"}}},{"id":"beowulf-dragon-skelton","figure_slug":"beowulf","title":"용과 싸우는 베오울프","kind":"print","date_label":"1908년","holder":null,"note":"H. E. 마셜의 「베오울프 이야기」에 실린 조지프 래트클리프 스켈턴의 삽화입니다.","image":{"src":"/images/exhibits/beowulf-dragon-skelton.jpg","width":1045,"height":1335,"alt":"용이 내뿜는 불길을 방패로 막으며 베오울프가 긴 칼을 휘두르는 삽화","credit":{"artist":"J. R. Skelton","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Stories_of_beowulf_fighting_the_dragon.jpg"}}},{"id":"thracian-horseman","figure_slug":"thracian-heros","title":"트라키아의 기수 부조","kind":"relief","date_label":"1세기 초","holder":"테살로니키 고고학 박물관","note":null,"image":{"src":"/images/exhibits/thracian-horseman.jpg","width":1280,"height":746,"alt":"말을 타고 달리는 기수와 양옆의 인물, 나무를 감은 뱀을 새긴 대리석 부조","credit":{"artist":"Yair-haklai","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Relief_of_a_Thracian_horseman,_Marble,_early_1st_Century_CE_Thessaloniki.jpg"}}},{"id":"zalmoxis-sarmizegetusa-sanctuary","figure_slug":"zalmoxis","title":"사르미제게투사 레지아의 작은 석회암 성소","kind":"photograph","date_label":"2009년 사진 (성소는 기원전 1세기~1세기)","holder":"루마니아 오러슈티에산맥","note":"잘목시스를 나타낸 유물은 전하지 않아, 잘목시스를 섬긴 다키아 사람들의 성소 터를 찍은 사진을 실었습니다.","image":{"src":"/images/exhibits/zalmoxis-sarmizegetusa-sanctuary.jpg","width":1280,"height":960,"alt":"숲으로 둘러싸인 풀밭에 둥근 돌 받침들이 줄지어 놓인 성소 터","credit":{"artist":"Oroles","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Sanctuarul_mic_de_calcar.JPG"}}},{"id":"shango-yoruba","figure_slug":"shango","title":"오셰 샹고 (샹고의 춤 지팡이)","kind":"sculpture","date_label":null,"holder":"리버풀 월드 뮤지엄","note":null,"image":{"src":"/images/exhibits/shango-yoruba.jpg","width":1200,"height":1600,"alt":"꼭대기에 양날 도끼 모양이 달린 사람 모습의 나무 지팡이가 진열장 안에 서 있는 모습","credit":{"artist":"Rept0n1x","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Shango_staff,_oshe_Shango,_World_Museum_Liverpool.JPG"}}},{"id":"eshu-yoruba","figure_slug":"eshu","title":"에슈 신상","kind":"sculpture","date_label":"19세기 말","holder":"뮌헨 오대륙 박물관","note":null,"image":{"src":"/images/exhibits/eshu-yoruba.jpg","width":1200,"height":1600,"alt":"머리 뒤로 길게 뻗은 장식을 한 인물이 무언가를 입에 문 채 서 있는 나무 조각","credit":{"artist":"Daderot","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Figure_of_deity_Eshu,_Yoruba,_Nigeria,_end_of_19th_century_-_Staatliches_Museum_f%C3%BCr_V%C3%B6lkerkunde_M%C3%BCnchen_-_DSC08551.JPG"}}},{"id":"orunmila-ifa","figure_slug":"orunmila","title":"이파 점술 쟁반 (오폰 이파)","kind":"sculpture","date_label":null,"holder":"브루클린 미술관","note":null,"image":{"src":"/images/exhibits/orunmila-ifa.jpg","width":1236,"height":1536,"alt":"가장자리에 얼굴과 무늬를 빙 둘러 새긴 둥근 나무 쟁반의 흑백 사진","credit":{"artist":"Unknown artist","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Brooklyn_Museum_75.147.1_Divination_Tray_Opon_Ifa.jpg"}}},{"id":"obatala-ife-head","figure_slug":"obatala","title":"이페 왕(오니)의 두상","kind":"sculpture","date_label":"14~15세기 초","holder":"영국 박물관","note":"오바탈라를 나타낸 유물은 특정하기 어려워, 요루바 신화에서 세상이 시작된 곳으로 여기는 이페에서 나온 왕의 두상을 실었습니다.","image":{"src":"/images/exhibits/obatala-ife-head.jpg","width":907,"height":1600,"alt":"구슬을 엮은 높은 관을 쓰고 얼굴에 가는 세로줄이 새겨진 금속 두상","credit":{"artist":"Vassil","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:British_Museum_Room_25_Head_of_a_king_Ife_17022019_5147.jpg"}}},{"id":"yemoja-ekiti-vessel","figure_slug":"yemoja","title":"무릎 꿇은 어머니 모양 그릇","kind":"sculpture","date_label":"1850년경","holder":"클리블랜드 미술관","note":"예모자를 직접 나타낸 조각을 찾지 못해, 요루바 사람들이 신 앞에 무릎 꿇은 어머니를 새긴 제의용 그릇을 실었습니다.","image":{"src":"/images/exhibits/yemoja-ekiti-vessel.jpg","width":578,"height":893,"alt":"아이를 업은 여인이 무릎을 꿇고 머리 위로 둥근 그릇을 받쳐 든 나무 조각","credit":{"artist":null,"license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Clevelandart_1994.200.1.jpg"}}},{"id":"ogun-blacksmith","figure_slug":"ogun","title":"쇠를 벼리는 대장장이","kind":"photograph","date_label":"2024년 사진","holder":null,"note":"오군을 직접 나타낸 조각을 찾지 못해, 쇠를 벼리는 서아프리카 대장장이를 찍은 사진을 실었습니다. 오군은 대장장이와 쇠를 다루는 이들이 섬기는 신입니다.","image":{"src":"/images/exhibits/ogun-blacksmith.jpg","width":1280,"height":853,"alt":"땅바닥에 앉은 대장장이가 모루 위의 쇠를 망치로 두드리는 모습","credit":{"artist":"Cherif sidi","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Cr%C3%A9ativit%C3%A9s_Africaines.jpg"}}},{"id":"oshun-agere-ifa","figure_slug":"oshun","title":"그릇을 받쳐 든 여인 모양 상아 그릇 (요루바)","kind":"sculpture","date_label":"17~19세기","holder":"메트로폴리탄 미술관","note":"오순을 직접 나타낸 조각을 찾지 못해, 무릎 꿇은 여인이 그릇을 받쳐 든 요루바의 점술 그릇을 실었습니다. 오순 축제에서도 처녀(아루그바)가 제물 그릇을 이고 강으로 갑니다.","image":{"src":"/images/exhibits/oshun-agere-ifa.jpg","width":1280,"height":1549,"alt":"무릎을 꿇은 여인이 두 팔을 올려 머리 위의 둥근 그릇을 받쳐 든 상아 조각","credit":{"artist":"Unknown artist","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:%C3%80g%C3%A9r%C3%A9_If%C3%A1_(If%C3%A1_divination_vessel)_with_kneeling_woman_(MET_1991.17.127)_DP-31157-001.jpg"}}},{"id":"nommo-dogon","figure_slug":"nommo","title":"도곤 인물 조각","kind":"sculpture","date_label":null,"holder":"케 브랑리 박물관","note":"놈모로 소개되기도 하는 도곤의 나무 조각입니다. 어떤 존재를 나타내는지는 해석이 갈립니다.","image":{"src":"/images/exhibits/nommo-dogon.jpg","width":1280,"height":1280,"alt":"같은 나무 조각을 앞과 옆에서 찍은 사진. 길쭉한 몸에 가슴 앞으로 팔을 모은 인물입니다.","credit":{"artist":"Rama","license":"CC BY-SA 3.0 fr","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0/fr/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Dogon_sculpture-73.1977.6.1-DSC00255-58-black.jpg"}}},{"id":"amma-dogon-couple","figure_slug":"amma","title":"도곤족의 남녀 좌상","kind":"sculpture","date_label":"18~19세기 초","holder":"메트로폴리탄 미술관","note":"암마를 직접 나타낸 조각은 전하지 않아, 도곤 사람들이 조상 부부를 나타낸 것으로 보는 나무 조각을 실었습니다.","image":{"src":"/images/exhibits/amma-dogon-couple.jpg","width":1280,"height":1600,"alt":"길쭉한 몸의 남녀가 둥근 의자에 나란히 앉아, 남자가 여자의 어깨에 팔을 두른 나무 조각","credit":{"artist":null,"license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Figure-_Seated_Couple_MET_DT1217.jpg"}}},{"id":"gu-fon","figure_slug":"gu","title":"구의 신상","kind":"sculpture","date_label":"1858년 이전","holder":"루브르 박물관 (파리)","note":"다호메의 대장장이 아카티 에클레켄도가 고철로 만든 것으로 알려진 신상입니다.","image":{"src":"/images/exhibits/gu-fon.jpg","width":535,"height":1600,"alt":"머리에 칼과 도구 모양 장식을 얹고, 쇠 치마를 입은 인물이 큰 칼을 들고 선 쇠 조각","credit":{"artist":"Sailko","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Benin,_fon,_il_dio_gou_protettore_del_ferro_battuto_e_della_guerra,_ante_1858,_artista_akati_ekpl%C3%A9kendo,_01.JPG"}}},{"id":"mawu-lisa-asen","figure_slug":"mawu-lisa","title":"제단 지팡이 아센 (폰족)","kind":"sculpture","date_label":"19세기","holder":"메트로폴리탄 미술관","note":"마우-리사를 직접 나타낸 조각을 찾지 못해, 다호메이 왕국의 폰족이 조상을 모시는 제단에 세우던 쇠 지팡이를 실었습니다.","image":{"src":"/images/exhibits/mawu-lisa-asen.jpg","width":821,"height":1600,"alt":"가는 쇠막대 위에 둥근 받침을 얹고, 가장자리에 작은 장식을 늘어뜨린 채 그 위에 작은 형상들을 세운 지팡이","credit":{"artist":null,"license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Altar_Staff_(Asen)_MET_DP-14818-003.jpg"}}},{"id":"inti-inca","figure_slug":"inti","title":"코리칸차의 잉카 우주관 금판","kind":"sculpture","date_label":"현대 재현","holder":"코리칸차 (페루 쿠스코)","note":"원주민 연대기 작가 파차쿠티 얌키가 그린 잉카 우주관 그림을 금판으로 재현한 작품입니다. 위쪽 타원은 창조신, 양옆의 원은 해와 달을 나타냅니다.","image":{"src":"/images/exhibits/inti-inca.jpg","width":1189,"height":1600,"alt":"오각형 금판에 타원과 해, 달, 별, 사람과 동물 같은 기호들이 새겨진 작품","credit":{"artist":"Pierre André Leclercq","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Cuzco.-_Temple_Koricancha_cosmologie_Inca,_(2).jpg"}}},{"id":"viracocha-tiwanaku","figure_slug":"viracocha","title":"티와나쿠의 태양의 문","kind":"photograph","date_label":"6~10세기경 (티와나쿠 문명)","holder":"티와나쿠 (볼리비아)","note":"잉카 이전 티와나쿠 문명의 돌문입니다. 가운데 위에 새겨진 지팡이 든 신을 비라코차로 보기도 합니다.","image":{"src":"/images/exhibits/viracocha-tiwanaku.jpg","width":1280,"height":960,"alt":"갈라진 금이 간 커다란 돌문. 윗부분 가운데에 신의 얼굴이 새겨지고 양옆에 작은 형상들이 줄지어 있습니다.","credit":{"artist":"Bgabel","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Bol-tihuanaco-sonnentor.jpg"}}},{"id":"pachamama-inca","figure_slug":"pachamama","title":"포토시 산의 성모","kind":"painting","date_label":"18세기","holder":"카사 데 모네다 (볼리비아 포토시)","note":"포토시의 은광 산 세로 리코를 성모 마리아의 몸으로 그린 그림으로, 성모와 대지의 여신 파차마마가 겹쳐진 모습을 보여 줍니다.","image":{"src":"/images/exhibits/pachamama-inca.jpg","width":1200,"height":1600,"alt":"금빛 액자 안에 성모의 얼굴을 한 붉은 산이 있고, 위에 삼위일체, 아래에 지구와 사람들이 그려진 그림","credit":{"artist":"Dan Lundberg","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:20170808_Bolivia_1411_Potos%C3%AD_sRGB_(26204035019).jpg"}}},{"id":"manco-capac-murua","figure_slug":"manco-capac","title":"망코 카팍 (무루아 「페루 통사」)","kind":"manuscript","date_label":"1616년","holder":"J. 폴 게티 미술관","note":"메르세드회 수도사 마르틴 데 무루아가 엮은 잉카 역사서의 손그림입니다.","image":{"src":"/images/exhibits/manco-capac-murua.jpg","width":1061,"height":1600,"alt":"산꼭대기에서 지팡이를 든 망코 카팍이 서 있고, 산 아래 사람들이 그를 올려다보는 채색 손그림","credit":{"artist":"Fray Martín de Murúa","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:La_adoraci%C3%B3n_de_Manco_C%C3%A1pac.jpg"}}},{"id":"manco-capac-brooklyn","figure_slug":"manco-capac","title":"첫 잉카 망코 카팍","kind":"painting","date_label":"18세기 후반","holder":"브루클린 미술관","note":"쿠스코에서 그린 잉카 왕 초상 14점 연작의 첫 장입니다.","image":{"src":"/images/exhibits/manco-capac-brooklyn.jpg","width":1280,"height":1374,"alt":"둥근 테두리 안에 해 모양 장식을 든 망코 카팍과 퓨마를 그린 초상화","credit":{"artist":null,"license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Brooklyn_Museum_-_Manco_Capac,_First_Inca,_1_of_14_Portraits_of_Inca_Kings.jpg"}}},{"id":"mama-ocllo-fogg","figure_slug":"mama-ocllo","title":"마마 오클료","kind":"painting","date_label":"1835~1845년경","holder":"하버드 대학교 포그 미술관","note":"쿠스코 화파의 작품입니다.","image":{"src":"/images/exhibits/mama-ocllo-fogg.jpg","width":1164,"height":1600,"alt":"깃털 머리 장식에 흰 치마를 입은 마마 오클료가 새를 들고 서 있고, 곁에 작은 아이가 있는 유화","credit":{"artist":"Daderot","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Mama_Ocllo,_artist_unknown,_Cuzco,_Peru,_c._1835-1845,_oil_on_canvas_-_Fogg_Art_Museum,_Harvard_University_-_DSC02018.jpg"}}},{"id":"pachacamac-idol","figure_slug":"pachacamac","title":"파차카막 나무 신상","kind":"sculpture","date_label":"8~9세기","holder":"파차카막 유적 박물관 (페루)","note":"파차카막 신전에서 나온 나무 기둥 신상으로, 기둥 전체에 무늬를 새겼습니다.","image":{"src":"/images/exhibits/pachacamac-idol.jpg","width":1200,"height":1600,"alt":"어두운 진열장 안에 선, 위쪽에 사람 모양을 새기고 기둥 전체에 무늬를 깎은 높은 나무 기둥","credit":{"artist":"Rodrigozu","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:%C3%8Ddolo_tallado_en_madera_del_Dios_Pachac%C3%A1mac.jpg"}}},{"id":"mama-quilla-full-moon","figure_slug":"mama-quilla","title":"보름달 (갈릴레오 탐사선)","kind":"photograph","date_label":"1990년대 사진","holder":"미국 항공우주국(NASA)","note":"마마 킬랴를 그린 옛 그림은 크기가 작아, 잉카 사람들이 마마 킬랴로 섬긴 달을 찍은 사진을 실었습니다.","image":{"src":"/images/exhibits/mama-quilla-full-moon.jpg","width":1280,"height":1280,"alt":"검은 우주를 배경으로 밝고 어두운 무늬가 또렷한 둥근 보름달","credit":{"artist":"NASA/JPL/USGS","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Full_moon.jpeg"}}},{"id":"illapa-lightning","figure_slug":"illapa","title":"번개","kind":"photograph","date_label":null,"holder":"미국 국립해양대기청(NOAA)","note":"이야파를 그린 옛 그림은 전하지 않아, 그가 무릿매로 울린다는 천둥번개를 찍은 사진을 실었습니다.","image":{"src":"/images/exhibits/illapa-lightning.jpg","width":1280,"height":861,"alt":"어두운 밤하늘에서 여러 갈래의 번개가 땅으로 내리꽂히는 모습","credit":{"artist":"C. Clark","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Lightning_NOAA.jpg"}}},{"id":"raven-haida","figure_slug":"raven","title":"까마귀를 새긴 기둥 조각","kind":"sculpture","date_label":null,"holder":"싯카 국립역사공원 (알래스카)","note":"기둥 일부가 남은 조각으로, 아래 안내판에 ‘까마귀’라고 적혀 있습니다.","image":{"src":"/images/exhibits/raven-haida.jpg","width":699,"height":1600,"alt":"커다란 눈과 굽은 부리를 가진 까마귀 얼굴을 새긴 낡은 나무 기둥 조각","credit":{"artist":"Hiart","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Totemic_raven_carving_(fragment)_in_the_Visitor_Center,_Sitka_National_Historical_Park,.jpg"}}},{"id":"were-jaguar-olmec","figure_slug":"were-jaguar","title":"재규어 용 무늬 그릇","kind":"sculpture","date_label":"기원전 1천년기","holder":"월터스 미술관","note":null,"image":{"src":"/images/exhibits/were-jaguar-olmec.jpg","width":1280,"height":1032,"alt":"붉은 띠 모양의 무늬를 새긴 검은 원통형 토기 그릇","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Olmec_-_Carved_Bowl_with_Jaguar_Dragon_Motif_-_Walters_482797.jpg"}}},{"id":"cocijo-zapotec","figure_slug":"cocijo","title":"코시호 토기 단지","kind":"sculpture","date_label":null,"holder":"월터스 미술관","note":null,"image":{"src":"/images/exhibits/cocijo-zapotec.jpg","width":1280,"height":1491,"alt":"커다란 머리 장식과 갈라진 혀를 내민 얼굴의 신이 앉아 있는 모습을 빚은 토기 단지","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Zapotec_-_Effigy_Urn_of_Cocijo_-_Walters_482788.jpg"}}},{"id":"zouche-nuttall-75","figure_slug":"eight-deer","title":"주슈-너톨 코덱스 75쪽","kind":"manuscript","date_label":"14~15세기","holder":"대영박물관","note":"8 사슴 재규어 발톱의 일생이 그려진 뒷면의 한 쪽입니다.","image":{"src":"/images/exhibits/zouche-nuttall-75.jpg","width":1280,"height":1008,"alt":"붉은 선으로 칸을 나눈 그림 문서 한 쪽. 화려하게 꾸민 인물들과 물속의 짐승, 날짜 기호가 그려져 있습니다.","credit":{"artist":"Zelia Nuttall","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Codex_Zouche-Nuttall_Page_75.png"}}},{"id":"maui-polynesian","figure_slug":"maui","title":"해를 붙잡는 마우이","kind":"print","date_label":"1927년경","holder":"호놀룰루 미술관","note":"아르만 마누키안의 그림입니다.","image":{"src":"/images/exhibits/maui-polynesian.jpg","width":1189,"height":1600,"alt":"산꼭대기의 굽은 나무 곁에서 마우이가 떠오르는 해에 밧줄을 걸어 끌어당기는 선 그림","credit":{"artist":"Hiart","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Maui_Snaring_the_Sun_by_Arman_Tateos_Manookian,_c._1927,_drawing,_Honolulu_Museum_of_Art.jpg"}}},{"id":"maui-dittmer","figure_slug":"maui","title":"바다에서 뉴질랜드를 낚아 올리는 마우이","kind":"print","date_label":"1907년","holder":null,"note":"독일 화가 빌헬름 디트머가 마오리 전승을 엮은 책 「테 토훙가」에 그린 삽화입니다.","image":{"src":"/images/exhibits/maui-dittmer.jpg","width":1187,"height":1600,"alt":"파도 위 카누에서 마우이가 낚싯줄을 힘껏 당기고, 물결 아래로 거대한 물고기의 눈이 보이는 흑백 삽화","credit":{"artist":"Wilhelm Dittmer","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Te_Tohunga_-_p49.png"}}},{"id":"tangaroa-rurutu","figure_slug":"tangaroa","title":"루루투의 신상 아아 (도판)","kind":"print","date_label":"1910년 도판 (신상은 18세기 이전)","holder":"대영박물관 (신상)","note":"온몸에 작은 신들이 붙어 나오는 모습의 나무 신상을 앞뒤에서 찍은 도판입니다. 등이 열려 속이 비어 있습니다.","image":{"src":"/images/exhibits/tangaroa-rurutu.jpg","width":1152,"height":1600,"alt":"온몸에 작은 인물들이 붙은 나무 신상의 앞모습과, 뒤가 열려 속이 빈 뒷모습을 나란히 실은 흑백 도판","credit":{"artist":"Unknown artist","license":"No restrictions","licenseUrl":"https://www.flickr.com/commons/usage/","sourceUrl":"https://commons.wikimedia.org/wiki/File:Handbook_to_the_ethnographical_collections_(1910)_(14596837587).jpg"}}},{"id":"ku-hawaii","figure_slug":"ku","title":"깃털로 만든 쿠의 신상","kind":"sculpture","date_label":"18세기","holder":null,"note":"붉고 노란 깃털로 덮고 진주조개 눈과 개의 이빨을 단 신상입니다.","image":{"src":"/images/exhibits/ku-hawaii.jpg","width":1200,"height":1600,"alt":"붉고 노란 깃털로 덮인 머리에 진주조개 눈을 달고, 크게 벌린 입에 이빨이 줄지어 박힌 신상","credit":{"artist":"Lebrac","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Kuka%27ilimoku.jpg"}}},{"id":"hina-gauguin","figure_slug":"hina","title":"히나 테파투 (달과 땅)","kind":"painting","date_label":"1893년","holder":"뉴욕 현대미술관 (MoMA)","note":"폴 고갱이 타히티 전승을 바탕으로 그린 그림으로, 달의 여신 히나와 땅의 신 파투의 대화를 다뤘습니다. 유럽 화가의 상상이 더해진 그림입니다.","image":{"src":"/images/exhibits/hina-gauguin.jpg","width":857,"height":1600,"alt":"옷을 입지 않은 여인이 등을 보인 채 물병을 들어 마시고, 그 뒤로 거대한 남자 얼굴이 보이는 유화","credit":{"artist":"Paul Gauguin","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Paul_Gauguin_-_Hina_Tefatou_-_Google_Art_Project.jpg"}}},{"id":"tane-dittmer","figure_slug":"tane","title":"숲의 신 타네","kind":"print","date_label":"1907년","holder":null,"note":"빌헬름 디트머가 「테 토훙가」에 그린 삽화입니다. 하늘의 얼굴과 땅에 누운 여인 사이로 나무가 솟은 모습은 타네가 하늘과 땅을 떼어 놓은 이야기를 나타낸 것으로 보입니다.","image":{"src":"/images/exhibits/tane-dittmer.jpg","width":1268,"height":1600,"alt":"하늘에 문신한 큰 얼굴이 떠 있고, 그 아래 땅에 누운 여인의 머리카락 사이로 나무가 솟아오른 흑백 삽화","credit":{"artist":"Wilhelm Dittmer","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Te_Tohunga_-_p11.png"}}},{"id":"pele-hitchcock","figure_slug":"pele","title":"펠레 (하워드 히치콕)","kind":"painting","date_label":"1927~1929년경","holder":null,"note":"하와이 화산 국립공원 방문자 센터에 걸려 있던 그림입니다.","image":{"src":"/images/exhibits/pele-hitchcock.jpg","width":819,"height":1079,"alt":"어두운 분화구에서 붉은 용암과 불길이 치솟는 유화","credit":{"artist":"D. Howard Hitchcock","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Pele_by_D._Howard_Hitchcock_(ca.1927-1929).png"}}},{"id":"rangi-papa-pataka-carving","figure_slug":"rangi-and-papa","title":"껴안은 남녀 (마오리 창고 조각)","kind":"sculpture","date_label":null,"holder":null,"note":"랑기와 파파를 새긴 것인지는 알 수 없지만, 테 아라와의 식량 창고(파타카)에 새긴 껴안은 남녀 조각을 실었습니다.","image":{"src":"/images/exhibits/rangi-papa-pataka-carving.jpg","width":934,"height":1594,"alt":"문신을 새긴 남자와 여자의 얼굴이 맞닿고, 둘레에 소용돌이무늬를 새긴 나무 조각","credit":{"artist":"Kahuroa","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:WahineTane.jpg"}}},{"id":"makemake-rapanui","figure_slug":"makemake","title":"마케마케 바위그림","kind":"relief","date_label":null,"holder":"라파누이 (칠레)","note":null,"image":{"src":"/images/exhibits/makemake-rapanui.jpg","width":1280,"height":853,"alt":"거친 화산암 표면에 희미하게 새겨진 얼굴 모양의 바위그림","credit":{"artist":"Dennis G. Jarvis","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Chile-03609_-_Make-make_(49072531058).jpg"}}},{"id":"moai-rapanui","figure_slug":"moai","title":"아후 통가리키의 모아이","kind":"photograph","date_label":null,"holder":"라파누이 (칠레)","note":"제단 아후 통가리키 위에 늘어선 모아이 가운데 일부입니다.","image":{"src":"/images/exhibits/moai-rapanui.jpg","width":1280,"height":851,"alt":"푸른 하늘 아래 돌 제단 위에 나란히 선 거대한 석상들","credit":{"artist":"Rivi","license":"CC BY-SA 3.0","licenseUrl":"http://creativecommons.org/licenses/by-sa/3.0/","sourceUrl":"https://commons.wikimedia.org/wiki/File:Ahu_Tongariki_cropped.jpg"}}},{"id":"kim-un-kamuy-ainu","figure_slug":"kimun-kamuy","title":"이오만테 (곰 보내기 의식)","kind":"painting","date_label":"1875년","holder":null,"note":"히라사와 뵤잔이 그린 그림입니다.","image":{"src":"/images/exhibits/kim-un-kamuy-ainu.jpg","width":1280,"height":730,"alt":"넓은 마당에 아이누 사람들이 모여 앉아 곰 보내기 의식을 치르는 모습을 그린 두루마리 그림","credit":{"artist":"Hirasawa Byōzan","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Ainu-iomante-bear-spirit-sending-ceremony-by-Hirasawa-Byozan-1875.png"}}},{"id":"poiyaunpe-ainu-man","figure_slug":"poiyaunpe","title":"아이누 남자 (히라사와 뵤잔)","kind":"painting","date_label":"19세기 중반","holder":"도쿄 국립박물관","note":"포이야운페를 그린 옛 그림은 전하지 않아, 에도 시대 화가가 그린 아이누 남자를 실었습니다.","image":{"src":"/images/exhibits/poiyaunpe-ainu-man.jpg","width":538,"height":958,"alt":"수염이 덥수룩한 아이누 남자가 무늬 놓은 겉옷을 입고 활을 든 채 짐을 지고 선 그림","credit":{"artist":"Hirasawa Byōzan","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:HirasawaByozanHomme.png"}}},{"id":"shitonai-ainu-coat","figure_slug":"shitonai","title":"아이누 아이의 겉옷","kind":"sculpture","date_label":null,"holder":"스톡홀름 민족지 박물관","note":"시토나이를 그린 옛 그림은 전하지 않아, 느릅나무 속껍질로 짠 아이누 아이의 옷을 실었습니다.","image":{"src":"/images/exhibits/shitonai-ainu-coat.jpg","width":1266,"height":1600,"alt":"누런 천에 검은 무늬 천을 덧대고 끈을 맨 아이 겉옷이 진열대에 걸려 있습니다.","credit":{"artist":"Daderot","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Coat_for_small_child,_Ainu_people,_Japan,_woven_from_inner_bark_of_elm_tree,_repaired_with_cotton_-_Etnografiska_museet_-_Stockholm,_Sweden_-_DSC01166.JPG"}}},{"id":"gesar-tibet","figure_slug":"gesar","title":"게사르 왕","kind":"painting","date_label":null,"holder":"웰컴 컬렉션 (런던)","note":null,"image":{"src":"/images/exhibits/gesar-tibet.jpg","width":876,"height":1600,"alt":"가운데에 말을 탄 게사르가 그려지고, 위와 아래에 신들과 인물들이 둘러싼 티베트 탱화","credit":{"artist":null,"license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Gesar_of_Ling_riding_a_deer._Distemper_painting._Wellcome_L0040371.jpg"}}},{"id":"palden-lhamo-tibet","figure_slug":"palden-lhamo","title":"팔덴 라모","kind":"painting","date_label":"1750~1850년","holder":"로스앤젤레스 카운티 미술관 (LACMA)","note":null,"image":{"src":"/images/exhibits/palden-lhamo-tibet.jpg","width":1153,"height":1600,"alt":"검푸른 몸의 여신이 노새를 타고 불길과 구름 속을 달리고, 둘레에 여러 신이 그려진 탱화","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Shri_(Palden_Lhamo)_1750-1850_LACMA.jpg"}}},{"id":"thanh-giong-vietnam","figure_slug":"thanh-giong","title":"부동천왕 (동호 민화)","kind":"print","date_label":null,"holder":null,"note":"베트남 동호 마을의 목판 민화로, 타인지옹을 높여 부르는 이름 ‘부동천왕’이 위에 적혀 있습니다.","image":{"src":"/images/exhibits/thanh-giong-vietnam.jpg","width":1280,"height":967,"alt":"붉은 말을 탄 소년 장수가 채찍을 휘두르고, 말 아래로 적들이 쓰러지는 목판 민화","credit":{"artist":"Vietnamese artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Tranh_%C4%90%C3%B4ng_H%E1%BB%93_v%E1%BA%BD_Ph%C3%B9_%C4%90%E1%BB%95ng_Thi%C3%AAn_V%C6%B0%C6%A1ng.jpg"}}},{"id":"tosakanth-thai","figure_slug":"thotsakan","title":"왓 프라깨우의 「라마끼안」 벽화","kind":"painting","date_label":"19세기 (여러 차례 다시 그림)","holder":"왓 프라깨우 (방콕)","note":"왕궁 사원 회랑에 「라마끼안」 전체를 그린 벽화의 한 부분입니다.","image":{"src":"/images/exhibits/tosakanth-thai.jpg","width":1280,"height":960,"alt":"금빛 지붕의 궁전과 정원을 위에서 내려다보듯 그리고, 뒤쪽 하늘에 거인 형상이 있는 벽화","credit":{"artist":"Prof Ranga Sai","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Ramakien_00.jpg"}}},{"id":"mae-phosop-thai","figure_slug":"mae-phosop","title":"매포솝 상","kind":"sculpture","date_label":null,"holder":"시암 소사이어티 (방콕)","note":null,"image":{"src":"/images/exhibits/mae-phosop-thai.jpg","width":1280,"height":960,"alt":"볏단을 안은 여신상이 낟알이 깔린 상자 위에 앉아 있는 모습","credit":{"artist":"Iudexvivorum","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Siam_Society_-_Bangkok_-_2017-07-25_(059).jpg"}}},{"id":"mahagiri-myanmar","figure_slug":"mahagiri","title":"마하기리 낫 (「37 낫」 삽화)","kind":"print","date_label":"1906년","holder":null,"note":"리처드 템플의 책 「37 낫」에 실린 삽화입니다.","image":{"src":"/images/exhibits/mahagiri-myanmar.jpg","width":537,"height":913,"alt":"붉은 옷을 입은 낫이 칼과 부채를 들고 흰 코끼리를 탄 인물들 위에 서 있는 그림","credit":{"artist":"Sir Richard Carnac Temple","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Mahagiri_Nat.jpg"}}},{"id":"thagyamin-myanmar","figure_slug":"thagyamin","title":"인도의 신들이 된 낫 (「37 낫」 삽화)","kind":"print","date_label":"1906년","holder":null,"note":"해, 불, 따자민(인드라), 브라흐마, 스칸다를 낫으로 그린 삽화입니다. 가운데가 흰 코끼리를 탄 따자민입니다.","image":{"src":"/images/exhibits/thagyamin-myanmar.jpg","width":1280,"height":477,"alt":"가로로 늘어선 다섯 신이 각자 수레, 양, 흰 코끼리, 거위, 공작을 타고 있는 그림","credit":{"artist":"Temple, Richard Carnac, Sir","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Thuriya_(Suriya),_Agni,_Thagyamin_(Indra),_Byamma_(Brahma)_and_Thukanda_(Skanda).jpg"}}},{"id":"barong-bali","figure_slug":"barong","title":"바롱 켓","kind":"sculpture","date_label":null,"holder":"스펄록 박물관 (일리노이 대학교)","note":null,"image":{"src":"/images/exhibits/barong-bali.jpg","width":1280,"height":1247,"alt":"붉은 얼굴의 가면에 금빛 장식과 긴 털을 단 바롱 옷이 천장에 매달려 있는 모습","credit":{"artist":"Daderot","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Barong_Ket,_Bali,_undated_-_Spurlock_Museum,_UIUC_-_DSC05997.jpg"}}},{"id":"rangda-bali","figure_slug":"rangda","title":"랑다 가면","kind":"sculpture","date_label":null,"holder":null,"note":null,"image":{"src":"/images/exhibits/rangda-bali.jpg","width":1012,"height":1600,"alt":"부릅뜬 눈과 송곳니를 가진 붉은 가면에 긴 검은 머리카락과 장식 띠가 늘어진 모습","credit":{"artist":"Silar","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:02021_0109_(1)_Rangda_mask.jpg"}}},{"id":"dewi-sri-java","figure_slug":"dewi-sri","title":"데위 스리로 소개된 석상 (사진)","kind":"photograph","date_label":"20세기 초 사진","holder":null,"note":"네덜란드 시기에 찍은 사진으로, 사진 설명에 데위 스리라고 적혀 있습니다.","image":{"src":"/images/exhibits/dewi-sri-java.jpg","width":844,"height":1600,"alt":"높은 관을 쓰고 장식 옷을 입은 여신이 양옆에 연꽃 화병을 둔 채 선 석상의 흑백 사진","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Statue_of_Dewi_Sri,_Wanita_di_Indonesia_p4_(Lichtbeelden_Institute).jpg"}}},{"id":"semar-mask","figure_slug":"semar","title":"스마르 가면","kind":"sculpture","date_label":"19세기","holder":"레이크스 미술관","note":"자와에서 만든 채색 나무 가면입니다.","image":{"src":"/images/exhibits/semar-mask.jpg","width":1280,"height":1437,"alt":"넓적한 코에 입꼬리를 올려 웃는 스마르의 얼굴을 깎아 칠한 낡은 나무 가면","credit":{"artist":"Rijksmuseum","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Masker_van_de_ponokawan_Semar,_AK-RAK-1998-3.jpg"}}},{"id":"gatotkaca-abimanyu","figure_slug":"gatotkaca","title":"가토트카차 앞에 무릎 꿇은 아비마뉴","kind":"painting","date_label":"1870년대","holder":"영국 도서관","note":"발리의 화가들이 그린 와양 인물 그림 모음에 들어 있는 그림입니다.","image":{"src":"/images/exhibits/gatotkaca-abimanyu.jpg","width":1280,"height":1061,"alt":"화려한 관과 장식을 갖춘 가토트카차 앞에서 아비마뉴가 무릎을 꿇은 채색 그림","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Abimanyu_kneels_in_front_of_Gatotkaca,_Or._3390_152.tiff"}}},{"id":"dongmyeong-tomb","figure_slug":"dongmyeong","title":"동명왕릉 앞의 무인 석상","kind":"photograph","date_label":null,"holder":"동명왕릉 (평양)","note":"고구려 시조 동명성왕의 무덤으로 전하는 평양 동명왕릉 앞에 세운 석상입니다.","image":{"src":"/images/exhibits/dongmyeong-tomb.jpg","width":1200,"height":1600,"alt":"갑옷을 입고 칼을 짚은 무인 석상이 말 석상 옆에 서 있고, 뒤로 단청을 한 건물이 보이는 사진","credit":{"artist":"yeowatzup","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Tomb_of_King_Tongmyong,_Pyongyang,_North_Korea.jpg"}}},{"id":"hyeokgeose-oreung","figure_slug":"hyeokgeose","title":"경주 오릉","kind":"photograph","date_label":null,"holder":"경주 오릉","note":"박혁거세와 신라 초기 왕들의 무덤으로 전합니다. 흩어진 유해를 다섯 곳에 묻었다는 전설과 이어집니다.","image":{"src":"/images/exhibits/hyeokgeose-oreung.jpg","width":1280,"height":850,"alt":"맑은 하늘 아래 넓은 잔디밭 너머로 둥근 봉분 다섯 기가 나란히 솟은 풍경","credit":{"artist":"Minquddyd","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:%EA%B2%BD%EC%A3%BC%EC%9D%98_%EC%98%A4%EB%A6%89.jpg"}}},{"id":"suro-tomb","figure_slug":"suro","title":"수로왕릉","kind":"photograph","date_label":null,"holder":"수로왕릉 (김해)","note":null,"image":{"src":"/images/exhibits/suro-tomb.jpg","width":1280,"height":853,"alt":"단청을 한 기와 건물 왼쪽 뒤로 풀로 덮인 둥근 봉분이 보이는 수로왕릉 사진","credit":{"artist":"xiquinhosilva","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Royal_Tomb_of_King_Suro.jpg"}}},{"id":"suro-gaya-pottery-stand","figure_slug":"suro","title":"가야 토기 그릇받침","kind":"sculpture","date_label":"삼국 시대 (5~6세기)","holder":"영국 박물관","note":"구지봉의 금합을 그린 옛 그림은 전하지 않아, 수로왕이 세웠다는 가야의 토기를 실었습니다.","image":{"src":"/images/exhibits/suro-gaya-pottery-stand.jpg","width":1280,"height":1484,"alt":"굽에 세모난 구멍을 뚫은 회색 가야 토기 그릇받침","credit":{"artist":"14GTR","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Gaya_pottery_stand,_British_Museum_02.jpg"}}},{"id":"cheoyong-akhak","figure_slug":"cheoyong","title":"「악학궤범」의 처용 탈","kind":"print","date_label":"1493년","holder":null,"note":"조선 성종 때 펴낸 음악 책 「악학궤범」에 실린 처용무 탈 그림입니다.","image":{"src":"/images/exhibits/cheoyong-akhak.jpg","width":1254,"height":1296,"alt":"모란꽃과 복숭아 가지로 꾸민 사모를 쓰고 귀걸이를 단 처용 탈의 얼굴을 그린 목판 그림. 오른쪽에 한자 설명이 적혀 있습니다.","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Cheoyong_in_the_Akhak_Gwebeom.jpg"}}},{"id":"siwang-lacma","figure_slug":"siwang","title":"시왕도","kind":"painting","date_label":"1798년","holder":"로스앤젤레스 카운티 미술관 (LACMA)","note":"열 대왕 가운데 여섯을 그린 조선 불화 연작의 한 폭입니다.","image":{"src":"/images/exhibits/siwang-lacma.jpg","width":1197,"height":1600,"alt":"붉은 관복을 입은 대왕이 판관과 사자들에게 둘러싸여 앉아 있고, 아래쪽에서 죄인들이 벌을 받는 장면을 그린 불화","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Six_of_the_Ten_Kings_of_Hell_LACMA_AC1998.268.3.1-.6_(1_of_5).jpg"}}},{"id":"ilwol-seoul","figure_slug":"ilwol","title":"일월신 무신도","kind":"painting","date_label":"18세기경","holder":null,"note":"서울에서 무당의 굿에 쓰려고 그린 그림으로 소개됩니다. 왼쪽이 달, 오른쪽이 해를 나타냅니다.","image":{"src":"/images/exhibits/ilwol-seoul.jpg","width":454,"height":687,"alt":"머리 뒤에 둥근 광배를 두르고 관복을 입은 두 신이 나란히 서 있는 무신도","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Korean_sun_and_moon_gods.png"}}},{"id":"choeyeong-sasindang","figure_slug":"choeyeong","title":"최영장군도","kind":"painting","date_label":null,"holder":"사신당 (서울)","note":"서울특별시 민속문화재 ‘사신당 무신도 및 현판 일괄’ 가운데 한 폭입니다.","image":{"src":"/images/exhibits/choeyeong-sasindang.jpg","width":597,"height":944,"alt":"푸른 관복을 입고 수염을 기른 장군이 의자에 앉아 칼을 쥐고, 뒤로 화살과 깃발이 꽂힌 무신도","credit":{"artist":"서울특별시","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:%EC%82%AC%EC%8B%A0%EB%8B%B9_%EB%AC%B4%EC%8B%A0%EB%8F%84_%EB%B0%8F_%ED%98%84%ED%8C%90_%EC%9D%BC%EA%B4%84_-_%EC%B5%9C%EC%98%81%EC%9E%A5%EA%B5%B0%EB%8F%84.jpg"}}},{"id":"jangseung-bourdaret","figure_slug":"jangseung","title":"장승과 솟대","kind":"photograph","date_label":"1903년경 사진","holder":null,"note":"프랑스인 에밀 부르다레가 쓴 한국 견문기에 실린 사진입니다.","image":{"src":"/images/exhibits/jangseung-bourdaret.jpg","width":939,"height":1258,"alt":"들판에 세운 나무 장승 두 기와 끝에 새를 깎아 단 장대를 찍은 흑백 사진. 장승 몸에 대장군이라는 한자가 보입니다.","credit":{"artist":"Émile Bourdaret","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Bourdaret_-_Religion_et_Superstition_en_Cor%C3%A9e_-_p19.jpg"}}},{"id":"chiyou-han","figure_slug":"chiyou","title":"치우 (한나라 화상석 탁본)","kind":"print","date_label":"한나라 시대 (탁본)","holder":null,"note":"한나라 무덤 돌에 새긴 그림을 떠낸 탁본입니다.","image":{"src":"/images/exhibits/chiyou-han.jpg","width":400,"height":487,"alt":"머리에 쇠뇌를 얹고 손발에 도끼와 칼, 창을 든 짐승 같은 형상을 검게 찍어 낸 탁본","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Chi_You.gif"}}},{"id":"king-arthur-butler","figure_slug":"king-arthur","title":"아서 왕","kind":"painting","date_label":"1903년","holder":null,"note":null,"image":{"src":"/images/exhibits/king-arthur-butler.jpg","width":931,"height":1600,"alt":"갑옷에 붉은 망토를 두른 젊은 아서가 두 손으로 왕관을 높이 들어 올리는 모습","credit":{"artist":"Charles Ernest Butler","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Charles_Ernest_Butler_-_King_Arthur.jpg"}}},{"id":"round-table-winchester","figure_slug":"king-arthur","title":"윈체스터 원탁","kind":"painting","date_label":"13세기 (그림은 1516년경)","holder":"윈체스터 그레이트 홀","note":"아서 왕 전설을 본떠 13세기에 만든 원탁으로, 16세기에 헨리 8세를 닮은 아서 왕과 기사들의 이름을 그려 넣었습니다.","image":{"src":"/images/exhibits/round-table-winchester.jpg","width":1205,"height":1600,"alt":"홀의 벽에 걸린 커다란 둥근 탁자 판. 초록과 흰색으로 나뉜 칸마다 기사의 이름이 적혀 있고 위쪽에 왕좌의 아서 왕이 그려져 있습니다.","credit":{"artist":"Andy Li","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Round_Table_of_Winchester_2026-07-12.jpg"}}},{"id":"roland-roncevaux-dore","figure_slug":"roland","title":"론세스바예스의 롤랑","kind":"painting","date_label":"19세기","holder":null,"note":null,"image":{"src":"/images/exhibits/roland-roncevaux-dore.jpg","width":1280,"height":905,"alt":"깎아지른 절벽 사이 어두운 협곡에서 벌어진 전투를 멀리서 내려다본 장면","credit":{"artist":"Gustave Doré","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Gustave_Dor%C3%A9_-_Roland_%C3%A0_Roncevaux.jpg"}}},{"id":"siegfried-forge-hauschild","figure_slug":"siegfried","title":"레긴의 대장간의 지크프리트","kind":"painting","date_label":"1880년경","holder":null,"note":null,"image":{"src":"/images/exhibits/siegfried-forge-hauschild.jpg","width":1097,"height":1051,"alt":"불이 이글거리는 대장간에서 일하는 대장장이들 곁에 갑옷과 붉은 망토를 갖춘 지크프리트가 서 있는 장면","credit":{"artist":"Wilhelm Ernst Ferdinand Franz Hauschild","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Siegfried_dans_la_forge_de_Regin.jpg"}}},{"id":"romulus-remus-rubens","figure_slug":"romulus","title":"로물루스와 레무스","kind":"painting","date_label":"1615~1616년","holder":"카피톨리니 박물관","note":null,"image":{"src":"/images/exhibits/romulus-remus-rubens.jpg","width":1280,"height":1293,"alt":"암늑대의 젖을 먹는 쌍둥이 아기 로물루스와 레무스 곁에 강의 신이 기대 앉아 있고, 나무 뒤에서 목동이 엿보는 장면","credit":{"artist":"Peter Paul Rubens","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Peter_Paul_Rubens_-_Romulus_and_Remus_-_Google_Art_Project.jpg"}}},{"id":"saint-george-uccello","figure_slug":"saint-george","title":"성 게오르기우스와 용","kind":"painting","date_label":"1456년경","holder":"런던 내셔널 갤러리","note":null,"image":{"src":"/images/exhibits/saint-george-uccello.jpg","width":1171,"height":900,"alt":"동굴 앞에서 백마를 탄 기사가 창으로 용을 찌르고, 공주가 용을 끈으로 매어 잡고 있는 장면","credit":{"artist":"Paolo Uccello","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Saint_George_and_the_Dragon_by_Paolo_Uccello_(London)_01.jpg"}}},{"id":"paul-bunyan-bemidji","figure_slug":"paul-bunyan","title":"베미지의 폴 버니언과 베이브 조각상","kind":"photograph","date_label":"1937년 건립","holder":"미국 미네소타주 베미지","note":null,"image":{"src":"/images/exhibits/paul-bunyan-bemidji.jpg","width":749,"height":549,"alt":"체크무늬 셔츠를 입은 거인 벌목꾼 폴 버니언 조각상과 그 옆의 푸른 소 베이브","credit":{"artist":null,"license":"Copyrighted free use","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Paul_Bunyan_and_Babe_statues_Bemidji_Minnesota_crop.JPG"}}},{"id":"john-henry-co-tunnel-postcard","figure_slug":"john-henry","title":"체서피크 오하이오 철도의 메이슨 터널 (그림엽서)","kind":"photograph","date_label":"1898년 이후","holder":"뉴욕 공립도서관","note":"존 헨리는 체서피크 오하이오 철도의 터널 공사에서 증기 드릴과 겨뤘다고 전합니다. 그를 그린 옛 그림은 전하지 않아, 같은 철도의 터널을 담은 그림엽서를 실었습니다.","image":{"src":"/images/exhibits/john-henry-co-tunnel-postcard.jpg","width":1280,"height":849,"alt":"꽃이 핀 산비탈을 따라 놓인 철길이 산속 터널로 들어가는 모습을 담은 채색 그림엽서","credit":{"artist":"Detroit Publishing Company","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Mason_Tunnel_on_the_C._%26_O._R._R.,_Virginia_(NYPL_b12647398-74287).tiff"}}},{"id":"alpamysh-stamp","figure_slug":"alip-manash","title":"서사시 「알파미시」 우표","kind":"print","date_label":"1988년","holder":null,"note":"우즈베크 서사시 「알파미시」를 그린 우표입니다. 알타이의 「알립마나시」와 줄거리가 같은 갈래의 이야기라 함께 둡니다.","image":{"src":"/images/exhibits/alpamysh-stamp.jpg","width":720,"height":1005,"alt":"말을 탄 용사 알파미시가 연인을 함께 태우고 달리는 모습을 그린 1988년 소련 우표","credit":{"artist":"USSR Post","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:The_Soviet_Union_1988_CPA_5990_stamp_(Alpamysh,_Uzbek_epic_poem._R._Khalilov).jpg"}}},{"id":"erkhii-mergen-horse-archer","figure_slug":"erkhii-mergen","title":"말 탄 궁수","kind":"painting","date_label":"15세기","holder":null,"note":"에르히 메르겡을 그린 옛 그림은 전하지 않아, 몽골 일 칸국 시대의 기마 궁수를 티무르 왕조 때 옮겨 그린 그림을 실었습니다.","image":{"src":"/images/exhibits/erkhii-mergen-horse-archer.jpg","width":892,"height":699,"alt":"말을 달리며 활시위를 당기는 궁수를 가는 먹선으로 그린 그림","credit":{"artist":"Muhammad ibn Mahmudshah al-Khayyam","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:IlkhanidHorseArcher.jpg"}}},{"id":"scheherazade-anderson","figure_slug":"scheherazade","title":"셰에라자드","kind":"painting","date_label":"19세기","holder":null,"note":null,"image":{"src":"/images/exhibits/scheherazade-anderson.jpg","width":1200,"height":1521,"alt":"공작 깃털 머리 장식과 분홍 베일, 금화 목걸이를 한 셰에라자드의 상반신 초상","credit":{"artist":"Sophie Gengembre Anderson","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Sophie_Gengembre_Anderson_-_Scheherazade.jpg"}}},{"id":"cerberus-louvre","figure_slug":"cerberus","title":"케르베로스를 데려온 헤라클레스","kind":"sculpture","date_label":"기원전 525년경","holder":"루브르 박물관","note":"에트루리아 카이레에서 만든 물항아리(히드리아)입니다. 겁에 질린 에우리스테우스 왕이 항아리 속에 숨어 있습니다.","image":{"src":"/images/exhibits/cerberus-louvre.jpg","width":1280,"height":972,"alt":"머리 여럿 달린 검은 개를 끌고 온 헤라클레스 앞에서 왕이 큰 항아리 속에 몸을 숨기는 장면을 그린 도기","credit":{"artist":"Eagle Painter","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Herakles_Kerberos_Eurystheus_Louvre_E701.jpg"}}},{"id":"minotaur-louvre","figure_slug":"minotaur","title":"테세우스와 미노타우로스","kind":"sculpture","date_label":"기원전 450~440년경","holder":"루브르 박물관","note":"아테네의 흑색상 술잔 안쪽 그림입니다.","image":{"src":"/images/exhibits/minotaur-louvre.jpg","width":1280,"height":1110,"alt":"둥근 술잔 바닥에 테세우스가 황소 머리를 한 미노타우로스를 붙잡고 칼로 찌르는 장면","credit":{"artist":null,"license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Kylix_Theseus_Minotauros_Louvre_F83.jpg"}}},{"id":"hydra-pollaiuolo","figure_slug":"hydra","title":"헤라클레스와 히드라","kind":"painting","date_label":"1475년경","holder":"우피치 미술관 (피렌체)","note":"안토니오 델 폴라이우올로가 그린 작은 패널화입니다.","image":{"src":"/images/exhibits/hydra-pollaiuolo.jpg","width":1140,"height":1600,"alt":"사자 가죽을 걸친 헤라클레스가 몽둥이를 치켜들고 머리 여럿 달린 뱀을 붙잡은 그림. 뒤로 강이 흐르는 들판이 펼쳐집니다.","credit":{"artist":"Antonio del Pollaiuolo","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Antonio_Pollaiuolo_002.jpg"}}},{"id":"pegasus-louvre","figure_slug":"pegasus","title":"페가수스 (벨레로폰 항아리)","kind":"sculpture","date_label":"기원전 440년경","holder":"루브르 박물관","note":"아테네의 적색상 항아리(펠리케)로, 앞면에는 페가수스를 탄 벨레로폰이 키마이라와 싸우는 장면이 있습니다.","image":{"src":"/images/exhibits/pegasus-louvre.jpg","width":1280,"height":1019,"alt":"검은 바탕에 날개를 펼친 말이 앞발을 들고 뛰어오르는 모습을 그린 붉은 그림 도기의 한 부분","credit":{"artist":"Barclay Painter","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Pelike_Bellerophon_Louvre_G535.jpg"}}},{"id":"polyphemus-redon","figure_slug":"polyphemus","title":"키클롭스","kind":"painting","date_label":"1914년경","holder":"크뢸러뮐러 미술관","note":"오딜롱 르동의 그림으로, 바위 위에 잠든 님프 갈라테이아를 바라보는 외눈박이 폴리페모스를 그렸습니다.","image":{"src":"/images/exhibits/polyphemus-redon.jpg","width":1272,"height":1600,"alt":"거대한 외눈 얼굴이 산 너머에서 내려다보고, 앞쪽 꽃 핀 언덕에 여인이 누워 있는 몽환적인 그림","credit":{"artist":"Odilon Redon","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Odilon_Redon_-_The_Cyclops,_c._1914.jpg"}}},{"id":"typhon-munich","figure_slug":"typhon","title":"티폰","kind":"sculpture","date_label":"기원전 540~530년경","holder":"뮌헨 국립 고미술 박물관","note":"칼키스식 물항아리에 그린 그림의 한 부분으로, 다른 쪽에는 벼락을 든 제우스가 있습니다.","image":{"src":"/images/exhibits/typhon-munich.jpg","width":1280,"height":1056,"alt":"날개를 펼치고 아래가 두 갈래 뱀 꼬리인 수염 난 괴물을 그린 흑색상 도기 그림","credit":{"artist":"User:Bibi Saint-Pol","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Typhon_Staatliche_Antikensammlungen_596.jpg"}}},{"id":"fenrir-binding","figure_slug":"fenrir","title":"펜리르를 묶다","kind":"print","date_label":"1909년","holder":null,"note":"도로시 하디가 그린 삽화로, H. A. 거버의 「북유럽 신화」에 실렸습니다.","image":{"src":"/images/exhibits/fenrir-binding.jpg","width":1111,"height":1600,"alt":"바위 언덕에서 거대한 늑대가 끈에 묶여 울부짖고, 멀리 신들이 서 있는 흑백 삽화","credit":{"artist":"Mabel Dorothy Hardy","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Fenrir_binded.png"}}},{"id":"jormungandr-fuseli","figure_slug":"jormungandr","title":"토르와 요르문간드","kind":"painting","date_label":"1790년","holder":"왕립 미술 아카데미 (런던)","note":"요한 하인리히 퓌슬리의 그림으로, 고기잡이배에서 토르가 뱀과 싸우는 장면입니다.","image":{"src":"/images/exhibits/jormungandr-fuseli.jpg","width":1132,"height":1600,"alt":"근육질의 토르가 배 위에서 망치를 치켜들고, 물결 속에서 뱀이 몸을 비트는 어두운 그림. 배 뒤쪽에서 거인이 웅크리고 있습니다.","credit":{"artist":"Henry Fuseli","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Johann_Heinrich_Fussli-Tor_and_Jormundgandr.jpg"}}},{"id":"sleipnir-sam66","figure_slug":"sleipnir","title":"슬레이프니르를 탄 오딘","kind":"manuscript","date_label":"18세기","holder":"아르니 마그누손 연구소 (레이캬비크)","note":"아이슬란드 필사본 SÁM 66에 그린 삽화입니다.","image":{"src":"/images/exhibits/sleipnir-sam66.jpg","width":957,"height":1187,"alt":"창을 든 오딘이 다리 여덟 개 달린 말을 타고 달리는 색칠한 필사본 삽화","credit":{"artist":"Jakob Sigurðsson","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:S%C3%81M_66,_80v,_Odin_on_Sleipnir.jpg"}}},{"id":"nidhogg-yggdrasil","figure_slug":"nidhogg","title":"이그드라실","kind":"manuscript","date_label":"1680년","holder":null,"note":"아이슬란드 필사본 AM 738 4to의 세계수 그림입니다. 나무 위아래로 독수리와 사슴, 뿌리의 용 니드호그가 그려져 있습니다.","image":{"src":"/images/exhibits/nidhogg-yggdrasil.jpg","width":515,"height":1600,"alt":"곧게 뻗은 나무 둥치 꼭대기에 새가 앉고, 가지 사이에 사슴이 있으며, 뿌리 쪽에 용이 그려진 필사본 그림","credit":{"artist":null,"license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:AM_738_4to_Yggdrasill.png"}}},{"id":"huginn-muninn-nks","figure_slug":"huginn-muninn","title":"오딘과 두 까마귀","kind":"manuscript","date_label":"1760년","holder":"덴마크 왕립 도서관","note":"아이슬란드 필사본 NKS 1867 4to의 삽화입니다. 오딘의 두 어깨에 후긴과 무닌이 앉아 있습니다.","image":{"src":"/images/exhibits/huginn-muninn-nks.jpg","width":607,"height":751,"alt":"모자를 쓰고 칼과 지팡이를 든 오딘의 양어깨에 ‘후긴’, ‘무닌’이라고 적힌 까마귀 두 마리가 앉아 있는 필사본 삽화","credit":{"artist":"Ólafur Brynjúlfsson","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:NKS_1867_4to,_94r,_Odin.jpg"}}},{"id":"fafnir-rackham","figure_slug":"fafnir","title":"파프니르를 찌른 시구르드","kind":"print","date_label":"1911년","holder":null,"note":"아서 래컴이 바그너의 「지크프리트」를 위해 그린 삽화입니다.","image":{"src":"/images/exhibits/fafnir-rackham.jpg","width":1162,"height":1600,"alt":"어두운 동굴 앞에서 젊은 영웅이 거대한 용의 몸에 칼을 찔러 넣는 삽화","credit":{"artist":"Arthur Rackham","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Sigurd_pierced_him_with_his_sword_(1901)_by_Arthur_Rackham.jpg"}}},{"id":"ammit-hunefer","figure_slug":"ammit","title":"후네페르의 「사자의 서」 심판 장면","kind":"manuscript","date_label":"기원전 1300년경","holder":"대영박물관","note":"저울 곁에 암미트가 앉아 심판 결과를 기다리고 있습니다.","image":{"src":"/images/exhibits/ammit-hunefer.jpg","width":493,"height":380,"alt":"저울 곁에 악어 머리와 사자 앞몸을 한 짐승이 앉아 있고, 자칼 머리의 신이 저울을 다는 파피루스 그림","credit":{"artist":"Hunefer","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:BD_Hunefer_cropped_1.jpg"}}},{"id":"sphinx-giza","figure_slug":"sphinx","title":"기자의 대스핑크스","kind":"photograph","date_label":"19세기 사진","holder":null,"note":"모래를 일부만 걷어 낸 무렵에 찍은 알부민 인화 사진입니다.","image":{"src":"/images/exhibits/sphinx-giza.jpg","width":1280,"height":940,"alt":"모래에 반쯤 묻힌 대스핑크스와 뒤로 피라미드 두 기가 보이는 오래된 흑백 사진","credit":{"artist":"Maison Bonfils","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Sphinx_partially_excavated2.jpg"}}},{"id":"chimera-engraving","figure_slug":"chimera","title":"키마이라와 싸우는 벨레로폰","kind":"print","date_label":"1878년","holder":null,"note":"그리스 도기 그림을 바탕으로 한 19세기 목판화입니다.","image":{"src":"/images/exhibits/chimera-engraving.jpg","width":853,"height":900,"alt":"날개 달린 말을 탄 젊은이가 창을 겨누고, 아래에서 사자 몸의 키마이라가 고개를 쳐들며, 등에서 염소 머리가 솟은 목판화","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Bellerophon_on_Pegasus_kill_the_Chim%C3%A4re.jpg"}}},{"id":"bennu-amulet","figure_slug":"bennu","title":"베누를 새긴 심장 부적","kind":"sculpture","date_label":null,"holder":"에르미타주 박물관 (상트페테르부르크)","note":"무덤에 함께 넣은 심장 모양 부적으로, 앞면에 왜가리 모습의 베누를 새겼습니다.","image":{"src":"/images/exhibits/bennu-amulet.jpg","width":1200,"height":1600,"alt":"심장 모양의 하얀 돌 부적 앞면에 푸른빛 왜가리 한 마리가 새겨진 모습","credit":{"artist":"MihailEF","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Heart_amulet.jpg"}}},{"id":"circe-waterhouse","figure_slug":"circe","title":"오디세우스에게 잔을 건네는 키르케","kind":"painting","date_label":"1891년","holder":"올덤 미술관 (영국)","note":"존 윌리엄 워터하우스의 그림입니다. 키르케 뒤의 둥근 거울에 오디세우스와 배가 비칩니다.","image":{"src":"/images/exhibits/circe-waterhouse.jpg","width":977,"height":1600,"alt":"옥좌에 앉은 여인이 한 손에 잔을, 다른 손에 지팡이를 들어 올리고, 발치에 돼지가 엎드려 있으며 뒤의 거울에 배와 남자가 비치는 그림","credit":{"artist":"John William Waterhouse","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Circe_Offering_the_Cup_to_Odysseus_(2457_x_4023px_ed.).jpg"}}},{"id":"sirens-waterhouse","figure_slug":"sirens","title":"오디세우스와 세이렌","kind":"painting","date_label":"1891년","holder":"빅토리아 국립 미술관 (멜버른)","note":"존 윌리엄 워터하우스의 그림입니다. 옛 그리스 도기 그림처럼 세이렌을 여자 머리의 새로 그렸습니다.","image":{"src":"/images/exhibits/sirens-waterhouse.jpg","width":1280,"height":628,"alt":"돛대에 묶인 남자와 노 젓는 뱃사람들이 탄 배를 사람 얼굴을 한 새들이 에워싸는 그림","credit":{"artist":"John William Waterhouse","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:John_William_Waterhouse_-_Ulysses_and_the_Sirens_-_Google_Art_Project.jpg"}}},{"id":"scylla-bnf","figure_slug":"scylla","title":"스킬라와 카리브디스 해협을 지나는 오디세우스","kind":"print","date_label":"1633년","holder":null,"note":"테오도르 판튈던이 프리마티초의 퐁텐블로 벽화를 따라 새긴 판화로, 왼쪽 위에서 용 머리의 스킬라가 뱃사람들을 덮칩니다.","image":{"src":"/images/exhibits/scylla-bnf.jpg","width":1280,"height":1113,"alt":"왼쪽 위 바위 곁에서 용 머리 여럿이 배의 사람들을 덮치고, 앞쪽 바닷가에 여인들이 앉아 배를 바라보는 판화. 아래에 프랑스어 설명이 새겨져 있습니다.","credit":{"artist":"Theodoor van Thulden","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Ulysse_et_les_sir%C3%A8nes._Ulysse_passe_le_d%C3%A9troit_de_Scylla_et_Charybde._-_btv1b104880665.jpg"}}},{"id":"charybdis-bromley","figure_slug":"charybdis","title":"스킬라와 카리브디스 사이의 오디세우스","kind":"print","date_label":"1806년","holder":null,"note":"헨리 퓌슬리의 그림을 윌리엄 브롬리가 판화로 옮겼습니다.","image":{"src":"/images/exhibits/charybdis-bromley.jpg","width":546,"height":726,"alt":"남자가 무화과나무 가지에 매달려 아래의 거센 소용돌이를 내려다보고, 왼쪽에 뱀 같은 형상이 보이는 판화","credit":{"artist":"William Bromley / After Henry Fuseli","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:William_Bromley_-_Odysseus_Between_Scylla_and_Charybdis,_1806.jpg"}}},{"id":"loki-commons","figure_slug":"loki","title":"로키 (아이슬란드 필사본 삽화)","kind":"manuscript","date_label":"18세기","holder":"아르니 마그누손 연구소 (레이캬비크)","note":"아이슬란드 필사본 SÁM 66의 삽화입니다.","image":{"src":"/images/exhibits/loki-commons.jpg","width":903,"height":1125,"alt":"그물을 든 로키가 서 있는 모습을 색칠한 필사본 삽화","credit":{"artist":null,"license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Processed_SAM_loki.jpg"}}},{"id":"vanapagan-commons","figure_slug":"vanapagan","title":"칼레비포에그와 바나파간","kind":"painting","date_label":null,"holder":"에스토니아 미술관","note":"크리스티안 라우드의 연필 그림입니다.","image":{"src":"/images/exhibits/vanapagan-commons.jpg","width":1280,"height":1134,"alt":"두 거인이 뒤엉켜 씨름하는 모습을 그린 연필 그림","credit":{"artist":"Kristjan Raud","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:TKM_2797B_Kristjan_Raud_-_Kalevipoeg_ja_Vanapagan.tif"}}},{"id":"lac-long-quan-commons","figure_slug":"lac-long-quan","title":"락롱꾸언 목조 부조","kind":"sculpture","date_label":null,"holder":"락롱꾸언 사당 (베트남 빈다)","note":"사당에 모신 나무 부조입니다.","image":{"src":"/images/exhibits/lac-long-quan-commons.jpg","width":480,"height":336,"alt":"붉은 바탕에 금빛으로 새긴 인물들이 줄지어 앉은 사당의 나무 부조","credit":{"artist":null,"license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Ph%C3%B9_%C4%91i%C3%AAu_Qu%E1%BB%91c_t%E1%BB%95_L%E1%BA%A1c_Long_Qu%C3%A2n_t%E1%BA%A1i_%C4%90%E1%BB%81n_N%E1%BB%99i_B%C3%ACnh_%C4%90%C3%A0.jpg"}}},{"id":"an-duong-vuong-co-loa-drum","figure_slug":"an-duong-vuong","title":"꼬로아 청동북","kind":"sculpture","date_label":"기원전 3세기경","holder":"하노이 박물관","note":"안즈엉 왕을 그린 옛 그림은 전하지 않아, 그가 쌓은 꼬로아 성에서 나온 동선 문화의 청동북을 실었습니다.","image":{"src":"/images/exhibits/an-duong-vuong-co-loa-drum.jpg","width":1280,"height":960,"alt":"넓적한 북면과 잘록한 몸통에 고리 손잡이가 달린 청동북이 받침 위에 놓여 있습니다.","credit":{"artist":"Daaé","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Co_Loa_drums.JPG"}}},{"id":"kim-quy-turtle-tower","figure_slug":"kim-quy","title":"호안끼엠 호수의 거북 탑","kind":"photograph","date_label":"2006년경 사진 (탑은 1886년)","holder":"하노이 호안끼엠 호수","note":"낌꾸이를 그린 옛 그림은 전하지 않습니다. 금거북이 레 러이 왕에게서 칼을 돌려받았다는 호안끼엠 호수에 그 전설을 기리는 탑이 서 있습니다.","image":{"src":"/images/exhibits/kim-quy-turtle-tower.jpg","width":1280,"height":958,"alt":"나무가 우거진 작은 섬 위에 선 3층 탑과 그 둘레의 호수","credit":{"artist":"Lilli Ann","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Turtle_Tower_c2006.jpg"}}},{"id":"an-duong-vuong-crossbow-trigger","figure_slug":"an-duong-vuong","title":"한나라 청동 쇠뇌 방아쇠","kind":"sculpture","date_label":"1~2세기","holder":"도쿄 국립박물관","note":"신기 쇠뇌를 그린 옛 그림은 전하지 않아, 같은 무렵 동아시아의 청동 쇠뇌 방아쇠를 실었습니다. 꼬로아 성터에서는 청동 화살촉이 수천 개 나왔습니다.","image":{"src":"/images/exhibits/an-duong-vuong-crossbow-trigger.jpg","width":1280,"height":853,"alt":"막대 모양 부품들이 맞물린 녹슨 청동 쇠뇌 방아쇠","credit":{"artist":"Gary Todd","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Eastern_Han_Bronze_Crossbow_Trigger_Mechanism_01.jpg"}}},{"id":"yuhwa-commons","figure_slug":"yuhwa","title":"유화를 찾은 금와왕","kind":"print","date_label":"1854년","holder":null,"note":"우타가와 사다히데가 그린 일본 목판화입니다.","image":{"src":"/images/exhibits/yuhwa-commons.jpg","width":800,"height":563,"alt":"물가에서 왕과 신하들이 여인을 찾아낸 장면을 그린 흑백 목판화","credit":{"artist":"Sadahide Utagawa","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Lady_Yuhwa_and_King_Geumwa.png"}}},{"id":"aladdin-commons","figure_slug":"aladdin","title":"등잔을 찾은 알라딘","kind":"print","date_label":"19세기","holder":null,"note":"펠릭스 달리가 그린 삽화입니다.","image":{"src":"/images/exhibits/aladdin-commons.jpg","width":488,"height":632,"alt":"동굴 속에서 소년이 등잔을 들어 올리는 흑백 판화","credit":{"artist":"Felix Octavius Carr Darley","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:FOCDarley-Aladdin-finds-the-lamp.JPG"}}},{"id":"ali-baba-commons","figure_slug":"ali-baba","title":"숲속의 알리바바","kind":"print","date_label":"1897년","holder":null,"note":"오브리 비어즐리의 그림입니다.","image":{"src":"/images/exhibits/ali-baba-commons.jpg","width":1115,"height":1600,"alt":"나무 사이에 선 사내를 검은 선과 면으로 그린 흑백 그림","credit":{"artist":"Aubrey Beardsley","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Ali_Baba_in_the_Wood.jpg"}}},{"id":"ali-baba-cave-batten","figure_slug":"ali-baba","title":"도둑들의 보물 동굴","kind":"print","date_label":"1915년","holder":null,"note":"존 D. 배튼이 「천일야화」 동화집에 그린 삽화입니다.","image":{"src":"/images/exhibits/ali-baba-cave-batten.jpg","width":1280,"height":1085,"alt":"어두운 동굴 안에 항아리와 왕관, 칼, 방패, 짐 자루가 쌓여 있고 안쪽으로 돌계단이 이어진 흑백 삽화","credit":{"artist":"John D. Batten","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Fairy_tales_from_the_Arabian_nights_-_Batten_illustration_at_page_306.png"}}},{"id":"merlin-commons","figure_slug":"merlin","title":"예언을 받아 적게 하는 멀린","kind":"manuscript","date_label":"13세기","holder":null,"note":"멀린이 서기 블레즈에게 예언을 받아 적게 하는 프랑스 필사본 그림입니다.","image":{"src":"/images/exhibits/merlin-commons.jpg","width":642,"height":700,"alt":"의자에 앉은 멀린과 책을 펼친 서기를 그린 중세 필사본 그림","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Merlin_(illustration_from_middle_ages).jpg"}}},{"id":"lancelot-commons","figure_slug":"lancelot","title":"팔라메데스와 싸우는 랜슬롯","kind":"manuscript","date_label":"14세기","holder":"프랑스 국립도서관","note":null,"image":{"src":"/images/exhibits/lancelot-commons.jpg","width":1280,"height":794,"alt":"말을 탄 두 기사가 창을 겨누고 맞붙는 중세 필사본 그림","credit":{"artist":"Unknown artist","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Lancelot_battles_Palamedes_(5152629).jpg"}}},{"id":"gawain-commons","figure_slug":"gawain","title":"로트 왕의 아들 가웨인 경","kind":"print","date_label":"1903년","holder":null,"note":"하워드 파일이 「아서 왕 이야기」에 그린 삽화입니다.","image":{"src":"/images/exhibits/gawain-commons.jpg","width":1280,"height":1441,"alt":"갑옷을 입고 방패를 든 기사의 흑백 펜화","credit":{"artist":"Howard Pyle","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Arthur-Pyle_Sir_Gawaine_the_Son_of_Lot,_King_of_Orkney.JPG"}}},{"id":"gawain-lady-cotton-nero","figure_slug":"gawain","title":"가웨인을 찾아온 성주의 아내","kind":"manuscript","date_label":"1400년 무렵","holder":"대영도서관","note":"코튼 네로 A.x 필사본의 그림으로, 성주의 아내는 이렇게 찾아온 끝에 가웨인에게 녹색 띠를 건넵니다.","image":{"src":"/images/exhibits/gawain-lady-cotton-nero.jpg","width":1146,"height":1539,"alt":"휘장을 친 침대에 누운 가웨인에게 성주의 아내가 다가와 몸을 숙이는 필사본 그림","credit":{"artist":null,"license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Green_Knight%27s_wife_and_Gawain_-_Sir_Gawain_and_the_Green_Knight_(c.1400-1410),_f.129_-_BL_Cotton_MS_Nero_A_X.jpg"}}},{"id":"tristan-commons","figure_slug":"tristan","title":"트리스탄과 아내 이죄, 그 오빠 카헤댕","kind":"manuscript","date_label":"14세기","holder":"프랑스 국립도서관","note":null,"image":{"src":"/images/exhibits/tristan-commons.jpg","width":1280,"height":950,"alt":"글씨가 적힌 쪽 아래에 붉은 옷을 입은 사람들이 서 있는 중세 필사본 그림","credit":{"artist":"Unknown artist","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Tristan,_his_wife_Yzeut_and_her_brother_Kahedin_(5152712).jpg"}}},{"id":"tristan-isolde-potion","figure_slug":"tristan","title":"묘약을 든 트리스탄과 이졸데","kind":"painting","date_label":"1916년경","holder":null,"note":null,"image":{"src":"/images/exhibits/tristan-isolde-potion.jpg","width":1174,"height":1600,"alt":"배 위에서 갑옷을 입은 트리스탄과 붉은 옷의 이졸데가 금잔을 함께 맞잡고 마주 선 그림","credit":{"artist":"John William Waterhouse","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:John_william_waterhouse_tristan_and_isolde_with_the_potion.jpg"}}},{"id":"bedivere-commons","figure_slug":"bedivere","title":"엑스칼리버를 호수에 던지는 베디비어","kind":"print","date_label":"1911년","holder":null,"note":"월터 크레인의 삽화입니다.","image":{"src":"/images/exhibits/bedivere-commons.jpg","width":743,"height":1024,"alt":"갑옷 입은 기사가 호숫가에서 칼을 하늘로 던지는 그림","credit":{"artist":"Walter Crane","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:King_Arthur_Sir_Bedivere_throwing_Excalibur_into_the_lake_by_Walter_Crane.jpg"}}},{"id":"mordred-commons","figure_slug":"mordred","title":"아서 왕과 모드레드의 싸움","kind":"painting","date_label":"1928년","holder":null,"note":"윌리엄 해서렐의 그림입니다.","image":{"src":"/images/exhibits/mordred-commons.jpg","width":1280,"height":1041,"alt":"바닷가 들판에서 붉은 망토의 기사와 검은 갑옷의 기사가 칼을 맞대는 그림","credit":{"artist":"William Hatherell","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Battle_Between_King_Arthur_and_Sir_Mordred_by_William_Hatherell.jpg"}}},{"id":"morgan-le-fay-commons","figure_slug":"morgan-le-fay","title":"모르간 르 페이","kind":"painting","date_label":"1864년","holder":"버밍엄 미술관","note":"프레더릭 샌즈의 그림입니다.","image":{"src":"/images/exhibits/morgan-le-fay-commons.jpg","width":1138,"height":1600,"alt":"녹색과 노란 옷을 입은 여인이 마법 도구들 사이에서 손을 뻗고 선 그림","credit":{"artist":"Frederick Sandys","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Sandys,_Frederick_-_Morgan_le_Fay.JPG"}}},{"id":"gareth-commons","figure_slug":"gareth","title":"오크니의 가레스 경","kind":"print","date_label":"1907년","holder":null,"note":"하워드 파일이 그린 삽화입니다.","image":{"src":"/images/exhibits/gareth-commons.jpg","width":505,"height":730,"alt":"갑옷을 입은 기사를 장식 글씨와 함께 그린 흑백 펜화","credit":{"artist":"Howard Pyle","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Sir_Gareth_of_Orkney.png"}}},{"id":"galahad-commons","figure_slug":"galahad","title":"갤러해드 경","kind":"painting","date_label":"19세기","holder":null,"note":"조지프 노엘 페이턴의 그림입니다.","image":{"src":"/images/exhibits/galahad-commons.jpg","width":465,"height":700,"alt":"어두운 숲길에서 말을 탄 기사가 빛을 받으며 나아가는 그림","credit":{"artist":"Joseph Noel Paton","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Joseph_Noel_Paton_Sir_Galahad_JKAM.jpg"}}},{"id":"lohengrin-commons","figure_slug":"lohengrin","title":"로엔그린으로 분한 하인리히 포글","kind":"print","date_label":"1890년","holder":null,"note":"잡지 「가르텐라우베」에 실린 그림으로, 바그너의 오페라에서 로엔그린을 맡은 가수입니다.","image":{"src":"/images/exhibits/lohengrin-commons.jpg","width":831,"height":1200,"alt":"백조 장식 투구와 갑옷을 입은 가수를 그린 흑백 그림","credit":{"artist":"various","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Die_Gartenlaube_(1890)_b_769.jpg"}}},{"id":"charlemagne-commons","figure_slug":"charlemagne","title":"샤를마뉴와 이탈리아 왕 피핀","kind":"manuscript","date_label":"10세기","holder":null,"note":"9세기 원본을 10세기에 베낀 필사본 그림입니다.","image":{"src":"/images/exhibits/charlemagne-commons.jpg","width":488,"height":768,"alt":"왼쪽에 샤를마뉴, 오른쪽에 아들 피핀이 앉아 있고 아래에 서기가 있는 중세 필사본 그림","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Karl_der_Grosse_-_Pippin_von_Italien.jpg"}}},{"id":"joyeuse-louvre","figure_slug":"charlemagne","title":"주아이외즈라고 불리는 대관식 칼","kind":"sculpture","date_label":"10~13세기 (부분마다 다름)","holder":"루브르 박물관","note":"프랑스 왕의 대관식에 쓰인 칼로, 샤를마뉴의 칼 주아이외즈라고 전해 왔지만 실제로는 샤를마뉴 시대보다 뒤에 만든 것입니다.","image":{"src":"/images/exhibits/joyeuse-louvre.jpg","width":1280,"height":849,"alt":"금빛 손잡이의 긴 칼과 보석이 박힌 칼집이 진열장 안에 나란히 놓인 모습","credit":{"artist":"Shonagon","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:%C3%89p%C3%A9e_du_sacre_des_rois_de_France,_dite_Joyeuse_-_Mus%C3%A9e_du_Louvre_Objets_d%27art_MS_84.jpg"}}},{"id":"astolfo-commons","figure_slug":"astolfo","title":"하르피이아를 물리치는 아스톨포","kind":"painting","date_label":"1835년","holder":null,"note":"마시모 다첼리오의 그림입니다.","image":{"src":"/images/exhibits/astolfo-commons.jpg","width":1280,"height":969,"alt":"어두운 산골짜기 위 하늘에서 날개 달린 말을 탄 기사가 괴물들을 쫓는 그림","credit":{"artist":"Massimo d'Azeglio","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Massimo_d%27Azeglio_-_Astolfo_debella_le_arpie.jpg"}}},{"id":"astolfo-moon-dore","figure_slug":"astolfo","title":"엘리야의 수레를 타고 달로 가는 성 요한과 아스톨포","kind":"print","date_label":"1879년","holder":null,"note":"귀스타브 도레가 그린 「광란의 오를란도」 삽화입니다.","image":{"src":"/images/exhibits/astolfo-moon-dore.jpg","width":1010,"height":1283,"alt":"별이 뜬 어둠 속에서 성 요한과 아스톨포를 태운 수레가 구름을 끌며 거대한 달을 향해 날아오르는 흑백 판화","credit":{"artist":"Gustave Doré","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Gustave_Dor%C3%A9_-_In_Elijah%27s_chariot,_St._John_and_Astolfo_travel_to_the_moon.jpg"}}},{"id":"bradamante-commons","figure_slug":"bradamante","title":"멀린의 무덤 앞의 브라다만테","kind":"painting","date_label":"1820년경","holder":"하이 미술관","note":"알렉상드르에바리스트 프라고나르의 그림입니다.","image":{"src":"/images/exhibits/bradamante-commons.jpg","width":561,"height":768,"alt":"어두운 동굴 속 빛 아래에서 갑옷 입은 여전사가 무덤 앞에 서 있는 그림","credit":{"artist":"Alexandre-Évariste Fragonard","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Bradamante_at_Merlin%27s_Tomb_by_Alexandre-Evariste_Fragonard,_High_Museum_of_Art.jpg"}}},{"id":"mandricardo-commons","figure_slug":"mandricardo","title":"만드리카르도의 흉상","kind":"print","date_label":"1550~1590년경","holder":"레이크스 박물관","note":"「광란의 오를란도」 인물을 그린 판화 연작의 한 장입니다.","image":{"src":"/images/exhibits/mandricardo-commons.jpg","width":1157,"height":1600,"alt":"투구를 쓴 남자의 옆얼굴 흉상을 새긴 판화","credit":{"artist":"Rijksmuseum","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Buste_van_Mandricardo_Mandricardo_(titel_op_object)_Karakters_uit_%27Orlando_Furioso%27_(serietitel),_RP-P-H-H-1425.jpg"}}},{"id":"ogier-commons","figure_slug":"ogier","title":"오지에 르 다누아","kind":"painting","date_label":"16세기","holder":"스케빙에 교회 (덴마크)","note":"교회 벽에 그린 벽화입니다.","image":{"src":"/images/exhibits/ogier-commons.jpg","width":1200,"height":1600,"alt":"교회 흰 벽에 그린 붉은 옷의 서 있는 기사 벽화","credit":{"artist":"Saddhiyama","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Holger_Danske_i_Sk%C3%A6vinge_kirke.jpg"}}},{"id":"renaud-commons","figure_slug":"renaud","title":"르노 드 몽토방의 죽음","kind":"print","date_label":"1896년","holder":null,"note":"「아이몽의 네 아들」 이야기의 한 장면을 담은 도판입니다.","image":{"src":"/images/exhibits/renaud-commons.jpg","width":1280,"height":1268,"alt":"일꾼들이 사람을 둘러싸 내리치는 장면을 그린 색 도판","credit":{"artist":"Louis Petit de Julleville","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:HLLF-T1-d264-265_Les_quatre_fils_Aimon.png"}}},{"id":"fergus-commons","figure_slug":"fergus","title":"세탄타를 어깨에 태운 퍼거스","kind":"print","date_label":"1909년","holder":null,"note":"조지 덴엄의 삽화로, 세탄타는 어린 쿠 훌린입니다.","image":{"src":"/images/exhibits/fergus-commons.jpg","width":1122,"height":1600,"alt":"장식 테두리 안에 남자가 소년을 어깨에 태우고 선 모습을 그린 삽화","credit":{"artist":"George Denham","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Fergus_mac_R%C3%B3ich_carrying_S%C3%A9tanta_on_his_shoulder.png"}}},{"id":"medb-commons","figure_slug":"medb","title":"메이브 여왕","kind":"print","date_label":"1904년","holder":null,"note":"아일랜드의 「쿨리의 소 습격」 이야기를 그린 삽화입니다.","image":{"src":"/images/exhibits/medb-commons.jpg","width":1099,"height":790,"alt":"망토를 두른 여왕이 사람들 앞에 선 모습을 그린 삽화","credit":{"artist":"Seóirse Ua Fágáin","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Queen_Medb_(Se%C3%B3irse_Ua_F%C3%A1g%C3%A1in,_1904).jpg"}}},{"id":"lugh-millar","figure_slug":"lugh","title":"루의 마법 창","kind":"print","date_label":"1905년","holder":null,"note":"찰스 스콰이어의 「켈트 신화와 전설」에 실린 해럴드 로버트 밀러의 삽화입니다.","image":{"src":"/images/exhibits/lugh-millar.jpg","width":991,"height":1600,"alt":"투구를 쓴 전사들이 뒤엉켜 싸우는 한가운데로 커다란 창이 날아드는 흑백 삽화","credit":{"artist":"Harold Robert Millar","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Lugh_spear_Millar.jpg"}}},{"id":"lugh-coronation-chair","figure_slug":"lugh","title":"잉글랜드의 대관식 의자와 왕관 (동판화)","kind":"print","date_label":"1820년","holder":null,"note":"리아 팔은 지금도 타라 언덕에 서 있다고 하지만, 스코틀랜드에는 리아 팔이 건너와 왕들이 즉위할 때 앉던 '스쿤의 돌'이 되었다는 전설이 있습니다. 가운데 대관식 의자 밑에 스쿤의 돌을 넣어 두었습니다.","image":{"src":"/images/exhibits/lugh-coronation-chair.jpg","width":900,"height":1195,"alt":"가운데 등받이 높은 대관식 의자 둘레에 왕관, 홀, 칼, 메달을 그린 동판화","credit":{"artist":"Thomas Kelly","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:EnglishCoronationRegalia2.jpg"}}},{"id":"rhiannon-batten","figure_slug":"rhiannon","title":"흰 말을 탄 리안논","kind":"print","date_label":"1895년","holder":null,"note":"조지프 제이컵스가 엮은 「켈트 요정 이야기 속편」에 실린 존 D. 배튼의 삽화입니다.","image":{"src":"/images/exhibits/rhiannon-batten.jpg","width":1280,"height":1264,"alt":"둥근 테두리 안에서 말을 탄 여인이 고개를 들고 지나가는 선화. '나는 내 볼일로 간다'는 영어 글귀가 함께 적혀 있습니다.","credit":{"artist":"John D. Batten","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Page_30_illustration_in_More_Celtic_Fairy_Tales.png"}}},{"id":"ceridwen-williams","figure_slug":"ceridwen","title":"케리드웬","kind":"painting","date_label":"1910년","holder":"글린 비비언 미술관 (스완지)","note":null,"image":{"src":"/images/exhibits/ceridwen-williams.jpg","width":1093,"height":1600,"alt":"붉은 옷을 입은 검은 머리의 여인이 불빛 앞에 앉아 턱을 괴고 생각에 잠긴 그림","credit":{"artist":"Christopher Williams","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Ceridwen.jpg"}}},{"id":"aengus-duncan","figure_slug":"aengus","title":"여름 바다를 잠재우는 앵거스 오그","kind":"painting","date_label":"1908년","holder":"스코틀랜드 국립미술관","note":null,"image":{"src":"/images/exhibits/aengus-duncan.jpg","width":1051,"height":1600,"alt":"바닷가 바위 위에서 흰 날개를 단 앵거스 오그가 두 팔을 벌리고 하늘을 올려다보는 그림","credit":{"artist":"John Duncan","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:John_Duncan_-_Angus_Og,_God_of_Love_and_Courtesy,_Putting_a_Spell_of_Summer_Calm_on_the_Sea_-_NG_2033_-_National_Galleries_Scotland.jpg"}}},{"id":"deirdre-russell","figure_slug":"deirdre","title":"성채의 데어드레","kind":"painting","date_label":"1900~1915년경","holder":"아마 카운티 박물관 (북아일랜드)","note":"시인이자 화가인 조지 윌리엄 러셀(필명 Æ)의 그림입니다.","image":{"src":"/images/exhibits/deirdre-russell.jpg","width":1200,"height":970,"alt":"어두운 방의 열린 문 앞에서 흰 옷의 데어드레가 별이 뜬 밤하늘을 향해 한 팔을 들어 올린 그림","credit":{"artist":"George William Russell","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Deirdre_at_her_Dun_-_George_William_Russell.jpg"}}},{"id":"diarmuid-reid","figure_slug":"diarmuid","title":"샘가에서 뿔잔을 든 디어무드","kind":"print","date_label":"1910년","holder":null,"note":"T. W. 롤스턴의 「핀의 위대한 업적」에 실린 스티븐 리드의 삽화입니다.","image":{"src":"/images/exhibits/diarmuid-reid.jpg","width":817,"height":1200,"alt":"투구를 쓴 젊은 전사 디어무드가 바위 곁 샘가에서 뿔잔을 들어 입에 대는 삽화","credit":{"artist":"Stephen Reid","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:13_Dermot_took_the_horn_and_would_have_filled_it.jpg"}}},{"id":"fionn-reid","figure_slug":"fionn","title":"요정의 하프 소리를 들은 핀","kind":"print","date_label":"1910년","holder":null,"note":"T. W. 롤스턴의 「핀의 위대한 업적」에 실린 스티븐 리드의 삽화입니다.","image":{"src":"/images/exhibits/fionn-reid.jpg","width":829,"height":1200,"alt":"투구를 쓰고 창을 든 핀이 망토를 두른 채 성벽 위에서 해 질 녘 들판을 내려다보는 뒷모습을 그린 삽화","credit":{"artist":"Stephen Reid","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:1_Finn_heard_far_off_the_first_notes_of_the_fairy_harp.jpg"}}},{"id":"oisin-reid","figure_slug":"oisin","title":"땅을 밟고 늙어 버린 오신","kind":"print","date_label":"1910년","holder":null,"note":"T. W. 롤스턴의 「핀의 위대한 업적」에 실린 스티븐 리드의 삽화입니다.","image":{"src":"/images/exhibits/oisin-reid.jpg","width":826,"height":1200,"alt":"흰 말이 안개처럼 하늘로 흩어지는 아래, 한순간에 늙어 버린 오신이 땅에 주저앉아 있는 삽화. 뒤에서 사람들이 바위를 들고 있습니다.","credit":{"artist":"Stephen Reid","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:16_The_white_steed_had_vanished_from_their_eyes_like_a_wreath_of_mist.jpg"}}},{"id":"taliesin-finding","figure_slug":"taliesin","title":"탈리에신의 발견 (헨리 클래런스 웨이트)","kind":"painting","date_label":"1876년","holder":"웨일스 국립도서관","note":"엘핀이 어살에 걸린 가죽 자루에서 아기 탈리에신을 건져 내는 장면입니다.","image":{"src":"/images/exhibits/taliesin-finding.jpg","width":1200,"height":747,"alt":"강가의 굽은 나무들 아래에서 한 남자가 몸을 숙여 무언가를 들여다보는 풍경화","credit":{"artist":"Henry Clarence Whaite","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Finding_of_Taliesin.jpg"}}},{"id":"balor-fomors-duncan","figure_slug":"balor","title":"포모르족 (존 덩컨)","kind":"painting","date_label":"1912년","holder":null,"note":"발로르가 이끈 포모르족을 그린 그림으로, '세상을 떠도는 악의 힘'이라는 부제가 붙어 있습니다.","image":{"src":"/images/exhibits/balor-fomors-duncan.jpg","width":942,"height":624,"alt":"흰 천을 두른 기괴한 형상들이 말을 타거나 걸어서 어두운 언덕을 넘어가는 행렬","credit":{"artist":"John Duncan","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:The_Fomors_-_Duncan_1912.png"}}},{"id":"dagda-cerne-giant","figure_slug":"dagda","title":"선 애버스의 거인","kind":"photograph","date_label":"2006년 사진","holder":"영국 도싯","note":"다그다를 그린 옛 그림·조각은 전하지 않습니다. 큰 몽둥이를 든 이 언덕 그림을 다그다와 견주는 이도 있지만, 헤라클레스로 보는 견해 등 정체와 연대는 의견이 갈립니다.","image":{"src":"/images/exhibits/dagda-cerne-giant.jpg","width":1280,"height":960,"alt":"풀이 덮인 언덕 비탈에 흰 선으로 몽둥이를 든 거인을 그린 모습","credit":{"artist":"Qz10","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Cerne_Abbas_Giant_View.jpg"}}},{"id":"dagda-trinity-harp","figure_slug":"dagda","title":"트리니티 칼리지의 하프","kind":"photograph","date_label":"19세기 말 사진 (하프는 14~15세기)","holder":"트리니티 칼리지 더블린","note":"다그다의 하프를 그린 옛 그림은 전하지 않아, 아일랜드에서 가장 오래된 하프 가운데 하나를 찍은 로버트 프렌치의 사진을 실었습니다.","image":{"src":"/images/exhibits/dagda-trinity-harp.jpg","width":1280,"height":975,"alt":"나무 몸통과 휘어진 기둥 사이에 줄을 건 아일랜드 옛 하프를 찍은 흑백 사진","credit":{"artist":"Robert French","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Trinity_College,_Brian_Boro%27s_Harp,_Dublin_City,_Co._Dublin_(28907881440).jpg"}}},{"id":"nuada-celtic-sword","figure_slug":"nuada","title":"켈트족의 칼과 칼집","kind":"sculpture","date_label":"기원전 60년경","holder":"메트로폴리탄 미술관","note":"누아다의 칼을 그린 옛 그림은 전하지 않아, 같은 시대 켈트 사람들의 칼을 실었습니다.","image":{"src":"/images/exhibits/nuada-celtic-sword.jpg","width":1280,"height":1600,"alt":"손잡이 끝이 둥글게 갈라진 청동 칼과 칼집이 푸른 녹으로 덮여 있습니다.","credit":{"artist":null,"license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Sword_and_Scabbard_MET_DT107.jpg"}}},{"id":"manannan-boat-reid","figure_slug":"manannan","title":"마나난의 배 (스티븐 리드)","kind":"print","date_label":"1910년","holder":null,"note":"'마나난의 배여, 헤스페리데스의 정원으로 우리를 빨리 데려다 다오'라는 글과 함께 실린 삽화입니다. 마나난의 배는 노 없이 바다를 건넜다고 전합니다.","image":{"src":"/images/exhibits/manannan-boat-reid.jpg","width":846,"height":1200,"alt":"높은 물결 위를 미끄러지는 작은 배에 투구 쓴 사람들이 타고 있는 채색 삽화","credit":{"artist":"Stephen Reid","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:4_Bear_us_swiftly,_Boat_of_Mananan,_to_the_Garden_of_the_Hesperides.jpg"}}},{"id":"scathach-cuchulainn-essers","figure_slug":"scathach","title":"바다와 싸우는 쿠훌린 (베르나르트 에서르스)","kind":"print","date_label":"1915년","holder":"레이크스 미술관","note":"스카하크를 그린 옛 그림은 전하지 않아, 그가 무예를 가르친 제자 쿠훌린을 그린 목판화를 실었습니다.","image":{"src":"/images/exhibits/scathach-cuchulainn-essers.jpg","width":1207,"height":1600,"alt":"높은 물결 속에서 창을 든 쿠훌린이 바다와 맞서는 흑백 목판화","credit":{"artist":"Bernard Essers","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Cuchulainn_vechtend_tegen_de_branding,_RP-P-2014-83-86.jpg"}}},{"id":"manannan-kirkburn-sword","figure_slug":"manannan","title":"커크번의 칼","kind":"sculpture","date_label":"기원전 3~2세기","holder":"영국 박물관","note":"프라가라흐를 그린 옛 그림은 전하지 않아, 같은 켈트 세계의 철검을 실었습니다. 칼집에 붉은 유리 장식을 박았습니다.","image":{"src":"/images/exhibits/manannan-kirkburn-sword.jpg","width":1280,"height":433,"alt":"붉은 장식을 박은 칼집에 든 철검이 가로로 놓여 있고, 위쪽에 쇠붙이 조각들이 함께 놓여 있습니다.","credit":{"artist":"Daderot","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Kirkburn_Sword,_from_Kirkburn,_East_Yorkshire,_buried_300-200_BC,_iron_sword_with_scabbard_of_decorate_bronze_and_iron_-_British_Museum_-_DSC01343.jpg"}}},{"id":"huyan-zhuo-commons","figure_slug":"huyan-zhuo","title":"「수호전」의 호연작","kind":"print","date_label":"1845~1850년경","holder":null,"note":"우타가와 구니요시의 「수호전」 연작 판화입니다.","image":{"src":"/images/exhibits/huyan-zhuo-commons.jpg","width":1280,"height":1420,"alt":"갑옷 차림의 장수가 의자에 앉아 칼을 든 채색 목판화","credit":{"artist":"Utagawa Kuniyoshi","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Utagawa_Kuniyoshi_-_%E6%B0%B4%E6%BB%B8%E5%82%B3_-_%E5%91%BC%E5%BB%B6%E7%81%BC.jpg"}}},{"id":"jade-rabbit-commons","figure_slug":"jade-rabbit","title":"달의 토끼 메달리온","kind":"sculpture","date_label":"17세기","holder":"쿠퍼휴잇 디자인 박물관","note":null,"image":{"src":"/images/exhibits/jade-rabbit-commons.jpg","width":1280,"height":1282,"alt":"둥근 비단 수놓이 가운데에 토끼가 절구에 약을 찧는 모습이 있는 메달리온","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Medallion,_Rabbit_in_the_Moon,_17th_century_(CH_18474079).jpg"}}},{"id":"sun-wukong-commons","figure_slug":"sun-wukong","title":"손오공","kind":"print","date_label":"19세기","holder":null,"note":"「서유기」를 그린 옛 삽화입니다.","image":{"src":"/images/exhibits/sun-wukong-commons.jpg","width":1124,"height":1600,"alt":"구름 위에서 여의봉을 든 원숭이를 그린 흑백 목판 삽화","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Xiyou.PNG"}}},{"id":"hua-mulan-commons","figure_slug":"hua-mulan","title":"화목란","kind":"painting","date_label":"18세기","holder":null,"note":"비단에 먹과 색으로 그린 그림입니다.","image":{"src":"/images/exhibits/hua-mulan-commons.jpg","width":932,"height":1600,"alt":"붉은 겉옷을 걸친 여인이 서 있는 비단 그림","credit":{"artist":null,"license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Mulan,_18th_century,_ink_and_colors_on_silk.jpg"}}},{"id":"robin-hood-commons","figure_slug":"robin-hood","title":"로빈 후드와 메이드 메리언","kind":"print","date_label":"1700년 이전","holder":null,"note":"로빈 후드 노래를 실은 낱장 인쇄물(브로드사이드)의 목판입니다.","image":{"src":"/images/exhibits/robin-hood-commons.jpg","width":568,"height":543,"alt":"모자를 쓰고 활과 방패를 든 남자 곁에 여인과 사람들이 서 있는 흑백 목판","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Robin-hood-and-maid-marion-01.png"}}},{"id":"william-tell-commons","figure_slug":"william-tell","title":"퀴스나흐트의 빌헬름 텔","kind":"painting","date_label":"1820년경","holder":"클리블랜드 미술관","note":"샤를 사뮈엘 지라르데의 그림입니다.","image":{"src":"/images/exhibits/william-tell-commons.jpg","width":1280,"height":1085,"alt":"어두운 숲길에서 사람들이 모인 장면을 그린 흑백 그림","credit":{"artist":"Charles Samuel Girardet","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Charles_Samuel_Girardet_-_William_Tell_at_K%C3%BCssnacht_-_1940.1116_-_Cleveland_Museum_of_Art.tif"}}},{"id":"melusine-commons","figure_slug":"melusine","title":"「멜뤼진 이야기」 표지","kind":"print","date_label":"1517년","holder":null,"note":"파리의 미셸 르 누아르가 펴낸 장 다라스 「멜뤼진 이야기」의 표지 목판입니다.","image":{"src":"/images/exhibits/melusine-commons.jpg","width":1088,"height":1600,"alt":"제목 글자 아래 인물들이 새겨진 옛 책의 목판 표지","credit":{"artist":"Michel Le Noir, printer, active Paris, 1486-1520","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Melusine_(Paris,_Michel_Le_Noir,_1517).jpg"}}},{"id":"oberon-commons","figure_slug":"oberon","title":"티타니아와 오베론의 화해","kind":"painting","date_label":"1847년","holder":"스코틀랜드 국립 미술관","note":"조지프 노엘 페이턴의 그림으로, 셰익스피어 「한여름 밤의 꿈」의 장면입니다.","image":{"src":"/images/exhibits/oberon-commons.jpg","width":956,"height":640,"alt":"달빛 아래 숲속에서 요정 왕과 왕비를 수많은 작은 요정들이 둘러싼 그림","credit":{"artist":"Joseph Noel Paton","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Joseph_Noel_Paton_-_The_Reconciliation_of_Titania_and_Oberon.jpg"}}},{"id":"el-cid-commons","figure_slug":"el-cid","title":"발렌시아를 에워싼 엘 시드","kind":"painting","date_label":"1872년경","holder":null,"note":"조제프 세라 이 포르손의 그림입니다.","image":{"src":"/images/exhibits/el-cid-commons.jpg","width":1012,"height":1385,"alt":"성벽 아래에서 말을 탄 기사들이 싸우는 장면을 그린 흑백 그림","credit":{"artist":"Josep Serra i Porsón","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Siege_of_Valencia_by_El_Cid,_1092-1094.png"}}},{"id":"el-cid-sword-hilts","figure_slug":"el-cid","title":"엘 시드의 칼 손잡이 (1893년 박람회)","kind":"photograph","date_label":"1893년","holder":null,"note":"1893년 마드리드 유럽 역사 박람회 도록에 실린 사진으로, 엘 시드와 보압딜 등의 칼 손잡이를 나란히 찍었습니다.","image":{"src":"/images/exhibits/el-cid-sword-hilts.jpg","width":1141,"height":768,"alt":"십자 모양 손잡이 끝이 아래로 말려 내려간 칼을 비롯해 세 자루의 칼 손잡이를 찍은 흑백 사진","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Empu%C3%B1aduras.jpg"}}},{"id":"prester-john-commons","figure_slug":"prester-john","title":"옥좌의 사제왕 요한","kind":"manuscript","date_label":"1559년경","holder":"대영도서관","note":"디오구 오멩이 그린 「메리 여왕 지도첩」의 동아프리카 지도에 있는 그림입니다.","image":{"src":"/images/exhibits/prester-john-commons.jpg","width":1110,"height":1164,"alt":"금빛 지도 위에 왕관을 쓴 왕이 옥좌에 앉아 있는 그림","credit":{"artist":"Diogo Homem","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Prester_John.jpg"}}},{"id":"saint-margaret-commons","figure_slug":"saint-margaret","title":"성 마르가리타와 용","kind":"print","date_label":"16세기","holder":"메트로폴리탄 미술관","note":null,"image":{"src":"/images/exhibits/saint-margaret-commons.jpg","width":1233,"height":1600,"alt":"십자가를 든 성녀가 발밑의 용 위에 선 모습을 그린 드로잉","credit":{"artist":"Unknown artist","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Saint_Margaret_and_the_Dragon_MET_DP801859.jpg"}}},{"id":"kriemhild-commons","figure_slug":"kriemhild","title":"지크프리트와 크림힐트","kind":"print","date_label":"1914년","holder":null,"note":null,"image":{"src":"/images/exhibits/kriemhild-commons.jpg","width":1280,"height":1437,"alt":"갑옷 입은 기사와 머리를 땋은 여인이 마주 선 흑백 삽화","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Siegfried_and_Kriemhild.jpg"}}},{"id":"dietrich-commons","figure_slug":"dietrich","title":"디트리히와 지크프리트의 결투","kind":"manuscript","date_label":"1420년","holder":"하이델베르크 대학 도서관","note":"필사본 「보름스의 장미 정원」의 그림입니다.","image":{"src":"/images/exhibits/dietrich-commons.jpg","width":522,"height":569,"alt":"두 기사가 칼을 들고 맞서는 모습을 채색한 필사본 그림","credit":{"artist":"vermutlich aus der „Elsässischen Werkstatt von 1418“, evtl. in Straßburg entstanden","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Dietrich_and_Siegfried.png"}}},{"id":"hildebrand-commons","figure_slug":"hildebrand","title":"기비히 왕과 싸우는 힐데브란트","kind":"manuscript","date_label":"14세기","holder":null,"note":"「보름스의 장미 정원」의 한 장면입니다.","image":{