ia.org/wiki/File:%E4%B9%9D%E4%BB%A3%E7%9B%AE%E5%B8%82%E6%9D%91%E7%BE%BD%E5%B7%A6%E8%A1%9B%E9%96%80%E3%83%BB%E4%B8%89%E4%BB%A3%E7%9B%AE%E5%A4%A7%E8%B0%B7%E5%BB%A3%E6%AC%A1-Kabuki_Actors_Ichimura_Uzaemon_IX_as_Ko-kakeyama_and_%C5%8Ctani_Hiroji_III_as_K%C5%8Dga_Sabur%C5%8D_MET_DP132796.jpg"}}},{"id":"jeon-u-chi-commons","figure_slug":"jeon-u-chi","title":"「전우치전」","kind":"manuscript","date_label":"1914년","holder":null,"note":"조선 시대 소설 「전우치전」의 옛 책입니다.","image":{"src":"/images/exhibits/jeon-u-chi-commons.jpg","width":1280,"height":930,"alt":"표지 그림과 한글 본문이 나란히 펼쳐진 옛 책","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Jeon_Woo-chi_Story.png"}}},{"id":"hong-gil-dong-commons","figure_slug":"hong-gil-dong","title":"「홍길동전」 첫 장","kind":"manuscript","date_label":"17세기 소설","holder":null,"note":"허균이 지었다고 전하는 「홍길동전」 판본의 첫 장입니다.","image":{"src":"/images/exhibits/hong-gil-dong-commons.jpg","width":567,"height":385,"alt":"누렇게 바랜 종이에 한글 글자가 빽빽한 옛 책의 첫 장","credit":{"artist":"Heo Gyun","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Honggildongjeon.jpg"}}},{"id":"enkidu-commons","figure_slug":"enkidu","title":"하늘의 황소를 제압하는 엔키두 원통 인장","kind":"sculpture","date_label":"기원전 1970~1670년경","holder":null,"note":"원통 인장으로 찍은 그림입니다.","image":{"src":"/images/exhibits/enkidu-commons.jpg","width":1081,"height":1600,"alt":"원통형 돌 인장과 거기에 새긴 사람과 황소 그림","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Near_Eastern_-_Cylinder_Seal_with_Enkidu_Vanquishing_the_Bull_of_Heaven_-_Walters_42786_-_Side_B.jpg"}}},{"id":"semiramis-commons","figure_slug":"semiramis","title":"세미라미스 의상 도안","kind":"print","date_label":"1825년","holder":null,"note":"로시니의 오페라 「세미라미데」 파리 공연을 위해 이폴리트 르콩트가 그린 의상 도안입니다.","image":{"src":"/images/exhibits/semiramis-commons.jpg","width":621,"height":837,"alt":"왕관을 쓰고 붉은 망토를 두른 여왕의 의상