insert into public.relics (slug, name, name_en, kind, figure_slugs, origin, power, price, source, exhibit_id, sort_order)
select slug, name, name_en, kind, figure_slugs, origin, power, price, source, exhibit_id, sort_order from jsonb_populate_recordset(null::public.relics, $seed$[{"slug":"mjolnir","name":"묠니르","name_en":"Mjölnir","kind":"weapon","figure_slugs":["thor","loki"],"origin":"로키가 드베르그 형제 브로크와 에이트리(신드리)에게 내기를 걸어 만들게 한 망치입니다. 로키가 파리로 변해 브로크의 눈꺼풀을 무는 바람에 손잡이가 짧게 나왔습니다.","power":"던지면 반드시 맞히고 토르의 손으로 돌아오며, 거인들의 머리를 부숩니다.","price":"거인 스림이 망치를 훔쳐 프레이야를 신부로 요구하자, 토르는 신부 옷을 입고 거인의 집에 들어가 되찾아야 했습니다.","source":"「스노리 에다」, 「스림의 노래」","exhibit_id":"thor-jotnar","sort_order":1},{"slug":"gungnir","name":"궁니르","name_en":"Gungnir","kind":"weapon","figure_slugs":["odin","loki"],"origin":"로키의 부탁으로 이발디의 아들들인 드베르그들이 만든 창입니다.","power":"던지면 빗나가지 않습니다. 오딘이 이 창을 바니르 쪽으로 던지며 세상의 첫 전쟁이 시작되었다고 합니다.","price":"「높은 이의 말」에서 오딘은 창에 찔린 채 아흐레 밤을 세계수에 매달려 스스로를 바친 끝에 룬을 얻습니다.","source":"「스노리 에다」, 「무녀의 예언」, 「높은 이의 말」","exhibit_id":"odin-sleipnir","sort_order":2},{"slug":"draupnir","name":"드라우프니르","name_en":"Draupnir","kind":"ornament","figure_slugs":["odin","baldr"],"origin":"묠니르와 같은 내기에서 브로크와 에이트리가 만들어 오딘에게 바친 금반지입니다.","power":"아홉째 밤마다 같은 무게의 금반지 여덟 개를 떨어뜨립니다.","price":"오딘은 죽은 아들 발드르의 화장 장작에 이 반지를 함께 올렸고, 발드르는 저승에서 반지를 아버지에게 돌려보냈습니다.","source":"「스노리 에다」","exhibit_id":"loki-forge","sort_order":3},{"slug":"brisingamen","name":"브리싱가멘","name_en":"Brísingamen","kind":"ornament","figure_slugs":["freyja","heimdall","loki"],"origin":"네 드베르그가 만든 목걸이로, 프레이야가 그들과 하룻밤씩 지내는 값을 치르고 얻었다고 합니다.","power":"프레이야를 상징하는 보물로, 토르가 프레이야로 꾸밀 때도 이 목걸이를 걸었습니다.","price":"로키가 목걸이를 훔치자 헤임달이 바다표범으로 변해 로키와 싸운 끝에 되찾았습니다.","source":"「소를리 이야기」, 「스림의 노래」, 「후스드라파」","exhibit_id":"freyja-brisingamen","sort_order":4},{"slug":"gjallarhorn","name":"걀라르호른","name_en":"Gjallarhorn","kind":"tool","figure_slugs":["heimdall"],"origin":"신들의 파수꾼 헤임달이 지닌 뿔피리입니다.","power":"온 세상에 울려 퍼지는 소리로 신들을 부릅니다.","price":"헤임달이 이 뿔피리를 크게 부는 날이 라그나로크, 곧 신들의 마지막 싸움이 시작되는 날입니다.","source":"「무녀의 예언」, 「스노리 에다」","exhibit_id":"heimdall-doepler","sort_order":5},{"slug":"gleipnir","name":"글레이프니르","name_en":"Gleipnir","kind":"tool","figure_slugs":["tyr","fenrir"],"origin":"고양이 발소리, 여자의 수염, 산의 뿌리, 곰의 힘줄, 물고기의 숨, 새의 침이라는 여섯 가지로 드베르그들이 만든 끈입니다.","power":"비단처럼 가늘고 부드럽지만, 어떤 쇠사슬도 끊던 늑대 펜리르를 묶어 둡니다.","price":"펜리르가 의심하자 티르가 오른손을 늑대의 입에 넣어 보증했고, 끈이 풀리지 않자 그 손을 잃었습니다.","source":"「스노리 에다」","exhibit_id":"fenrir-binding","sort_order":6},{"slug":"gram","name":"그람","name_en":"Gram","kind":"weapon","figure_slugs":["sigurd"],"origin":"오딘이 나무에 꽂아 둔 칼을 시그문드가 뽑았고, 부러진 조각을 대장장이 레긴이 다시 벼려 시구르드에게 주었습니다.","power":"시험 삼아 내리치자 모루가 둘로 갈라졌고, 시구르드는 이 칼로 용 파프니르를 찔러 죽였습니다.","price":"파프니르가 지키던 저주받은 황금을 얻은 뒤 시구르드도 결국 배신 속에 죽습니다.","source":"「뵐숭 일족의 사가」","exhibit_id":"sigurd-commons","sort_order":7},{"slug":"andvaranaut","name":"안드바라나우트","name_en":"Andvaranaut","kind":"ornament","figure_slugs":["loki","sigurd"],"origin":"로키가 수달로 변해 있던 오트르를 죽인 몸값을 채우려고, 강꼬치고기로 숨어 살던 드베르그 안드바리를 붙잡아 황금과 함께 빼앗은 금반지입니다.","power":"지닌 이에게 금을 불려 줍니다.","price":"빼앗긴 안드바리가 반지와 황금에 저주를 걸어, 흐레이드마르와 아들 파프니르, 그리고 시구르드까지 이 황금을 가진 이들이 차례로 죽었습니다.","source":"「레긴의 노래」, 「스노리 에다」, 「뵐숭 일족의 사가」","exhibit_id":"alberich-ring-stassen","sort_order":8},{"slug":"sword-of-freyr","name":"프레이르의 칼","name_en":"Sword of Freyr","kind":"weapon","figure_slugs":["skirnir"],"origin":"풍요의 신 프레이르의 칼입니다. 거인 여인 게르드에게 반한 프레이르가 사자 스키르니르에게 구혼을 맡기며 그 값으로 내주었습니다.","power":"지혜로운 이가 쥐면 스스로 거인들과 싸웁니다.","price":"칼을 내준 프레이르는 라그나로크 때 사슴뿔 하나로 불의 거인 수르트와 맞서다 쓰러집니다.","source":"「스키르니르의 여행」, 「스노리 에다」","exhibit_id":"skirnir-commons","sort_order":9},{"slug":"hringhorni","name":"흐링호르니","name_en":"Hringhorni","kind":"treasure","figure_slugs":["baldr","odin"],"origin":"빛의 신 발드르의 배로, 모든 배 가운데 가장 크다고 합니다.","power":"발드르가 죽자 신들은 이 배에서 그를 화장하려 했지만 배가 꿈쩍하지 않아, 거인 여인 히로킨을 불러 겨우 바다로 밀어 띄웠습니다.","price":"발드르의 몸과 함께 슬픔에 죽은 아내 난나, 그의 말, 오딘이 올린 반지 드라우프니르까지 이 배 위에서 불탔습니다.","source":"「스노리 에다」","exhibit_id":"baldr-hringhorni","sort_order":10},{"slug":"mead-of-poetry","name":"시의 꿀술","name_en":"Mead of Poetry","kind":"treasure","figure_slugs":["odin"],"origin":"가장 지혜로운 이 크바시르를 죽인 드베르그들이 그의 피에 꿀을 섞어 빚은 술로, 뒤에 거인 수퉁이 산속에 감추고 딸 군로드에게 지키게 했습니다.","power":"마시면 누구든 시인이나 학자가 됩니다.","price":"오딘은 군로드와 사흘 밤을 지낸 대가로 세 모금을 얻어 술을 모두 마셔 버렸고, 독수리로 변해 아스가르드로 달아났습니다.","source":"「스노리 에다」 시어법, 「높은 이의 말」","exhibit_id":"odin-gunnlod","sort_order":11},{"slug":"aegis","name":"아이기스","name_en":"Aegis","kind":"armor","figure_slugs":["zeus","athena","perseus"],"origin":"제우스가 지닌 방패(또는 염소 가죽 흉갑)로, 아테나가 함께 씁니다. 페르세우스가 바친 메두사의 머리가 한가운데 달렸습니다.","power":"흔들면 폭풍이 일고, 맞선 이들을 공포로 무너뜨립니다.","price":"그 한가운데 달린 것은 페르세우스가 목을 벤 메두사의 머리입니다.","source":"「일리아스」, 아폴로도로스 「비블리오테케」","exhibit_id":"athena-aegis","sort_order":12},{"slug":"trident","name":"트리아이나","name_en":"Trident of Poseidon","kind":"weapon","figure_slugs":["poseidon"],"origin":"티탄과의 전쟁 때 키클롭스들이 포세이돈에게 만들어 준 삼지창입니다.","power":"땅을 흔들고 바다에 폭풍을 일으키며, 바위를 내리쳐 샘을 솟게 합니다.","price":"아테네를 두고 아테나와 겨룰 때 이 창으로 아크로폴리스에 짠물 샘을 냈지만, 올리브를 준 아테나에게 도시를 내주었습니다.","source":"아폴로도로스 「비블리오테케」, 헤로도토스 「역사」","exhibit_id":"poseidon-trident","sort_order":13},{"slug":"helm-of-darkness","name":"하데스의 투구","name_en":"Helm of Darkness","kind":"armor","figure_slugs":["hades","perseus","athena"],"origin":"티탄과의 전쟁 때 키클롭스들이 하데스에게 만들어 준 투구입니다.","power":"쓰면 모습이 보이지 않습니다. 페르세우스는 이 투구를 빌려 메두사의 자매들에게서 달아났고, 「일리아스」에서는 아테나가 쓰고 아레스에게 다가갑니다.","price":null,"source":"아폴로도로스 「비블리오테케」, 「일리아스」","exhibit_id":"perseus-nymphs","sort_order":14},{"slug":"caduceus","name":"케리케이온","name_en":"Caduceus","kind":"tool","figure_slugs":["hermes","apollo"],"origin":"아기 헤르메스가 아폴론의 소를 훔친 뒤 리라를 주고 화해하자, 아폴론이 답례로 건넨 황금 지팡이라고 합니다.","power":"잠들게 하고 깨우며, 죽은 이의 혼을 저승으로 이끄는 전령의 지팡이입니다. 뒤에는 뱀 두 마리가 감긴 모습으로 그려졌습니다.","price":null,"source":"「헤르메스 찬가」, 히기누스 「천문」","exhibit_id":"hermes-caduceus","sort_order":15},{"slug":"harpe","name":"하르페","name_en":"Harpe","kind":"weapon","figure_slugs":["perseus","hermes"],"origin":"헤르메스가 페르세우스에게 건넨 굽은 칼입니다.","power":"단단한 금강석 칼날로 메두사의 목을 단번에 베었습니다.","price":"메두사의 머리는 보는 이를 돌로 만들었고, 페르세우스는 방패에 비친 모습만 보고 다가가야 했습니다.","source":"아폴로도로스 「비블리오테케」","exhibit_id":"perseus-cellini","sort_order":16},{"slug":"golden-fleece","name":"황금 양털","name_en":"Golden Fleece","kind":"treasure","figure_slugs":["jason","medea"],"origin":"프릭소스를 태우고 콜키스로 날아간 황금 숫양의 털가죽으로, 아레스의 숲에서 잠들지 않는 용이 지켰습니다.","power":"왕권의 증표로, 이아손은 이것을 가져와야 빼앗긴 왕위를 돌려받을 수 있었습니다.","price":"메데이아의 도움으로 양털을 얻었지만, 달아나는 길에 메데이아는 동생 압시르토스를 죽였고 두 사람의 끝도 비극이었습니다.","source":"아폴로니오스 「아르고나우티카」","exhibit_id":"jason-fleece","sort_order":17},{"slug":"shield-of-achilles","name":"아킬레우스의 방패","name_en":"Shield of Achilles","kind":"armor","figure_slugs":["achilles","hephaestus"],"origin":"파트로클로스가 아킬레우스의 갑옷을 입고 싸우다 죽자, 테티스의 부탁으로 헤파이스토스가 하룻밤 사이에 새로 벼린 방패입니다.","power":"하늘과 땅, 평화로운 도시와 전쟁하는 도시, 결혼과 재판, 추수까지 온 세상이 새겨져 있습니다.","price":"아킬레우스가 죽은 뒤 이 무구를 두고 아이아스와 오디세우스가 다투었고, 진 아이아스는 스스로 목숨을 끊었습니다.","source":"「일리아스」 18권, 소포클레스 「아이아스」","exhibit_id":"achilles-shield","sort_order":18},{"slug":"lyre","name":"리라","name_en":"Lyre","kind":"tool","figure_slugs":["hermes","apollo","orpheus"],"origin":"태어난 날 헤르메스가 거북 등껍질에 줄을 매어 만들고 아폴론에게 넘겨준 현악기입니다.","power":"오르페우스가 타면 짐승과 나무, 바위까지 따라왔고 저승의 신들도 마음을 움직였습니다.","price":"저승에서 데려 나오던 아내 에우리디케를 오르페우스가 돌아보는 바람에 영영 잃었습니다.","source":"「헤르메스 찬가」, 오비디우스 「변신 이야기」","exhibit_id":"orpheus-commons","sort_order":19},{"slug":"ariadnes-thread","name":"아리아드네의 실타래","name_en":"Ariadne's Thread","kind":"tool","figure_slugs":["theseus"],"origin":"크레타의 공주 아리아드네가 미궁에 들어가는 테세우스에게 건넨 실타래입니다.","power":"입구에 묶고 풀며 들어가면, 미노타우로스를 죽인 뒤 실을 따라 미궁을 빠져나올 수 있습니다.","price":"테세우스는 함께 떠난 아리아드네를 낙소스섬에 두고 떠났습니다.","source":"플루타르코스 「테세우스 전」, 오비디우스 「변신 이야기」","exhibit_id":"theseus-thread","sort_order":20},{"slug":"nemean-lion-skin","name":"네메아 사자 가죽","name_en":"Skin of the Nemean Lion","kind":"armor","figure_slugs":["heracles"],"origin":"헤라클레스가 첫 번째 과업에서 맨손으로 목 졸라 죽인 사자의 가죽입니다.","power":"어떤 칼과 화살도 뚫지 못해, 헤라클레스는 이 가죽을 갑옷처럼 둘렀습니다.","price":"날붙이가 들지 않아 사자 자신의 발톱으로 가죽을 벗겨야 했습니다.","source":"아폴로도로스 「비블리오테케」","exhibit_id":"heracles-farnese","sort_order":21},{"slug":"apple-of-discord","name":"불화의 황금 사과","name_en":"Apple of Discord","kind":"treasure","figure_slugs":["paris","aphrodite","hera","athena"],"origin":"펠레우스와 테티스의 결혼식에 초대받지 못한 불화의 여신 에리스가 '가장 아름다운 이에게'라고 적어 던져 넣은 사과입니다.","power":"헤라와 아테나, 아프로디테가 서로 제 것이라 다투었고, 제우스는 판정을 트로이의 왕자 파리스에게 맡겼습니다.","price":"아프로디테를 고른 파리스는 헬레네를 얻었지만, 그 일로 트로이 전쟁이 일어나 트로이가 무너졌습니다.","source":"「키프리아」 요약, 히기누스 「이야기」","exhibit_id":"paris-commons","sort_order":22},{"slug":"keraunos","name":"케라우노스","name_en":"Thunderbolt of Zeus","kind":"weapon","figure_slugs":["zeus"],"origin":"제우스가 타르타로스에서 풀어 준 키클롭스들이 고마움의 뜻으로 만들어 준 벼락입니다.","power":"이 벼락으로 제우스는 티탄들과 괴물 티폰을 쓰러뜨리고 신들의 왕이 되었습니다.","price":"아스클레피오스가 죽은 이를 되살리자 제우스는 벼락으로 그를 죽였고, 분노한 아폴론은 벼락을 만든 키클롭스들을 죽였습니다.","source":"헤시오도스 「신들의 계보」, 아폴로도로스 「비블리오테케」","exhibit_id":"zeus-dodona","sort_order":23},{"slug":"talaria","name":"날개 달린 샌들","name_en":"Talaria","kind":"tool","figure_slugs":["hermes","perseus"],"origin":"신들의 전령 헤르메스가 신는 황금 샌들입니다.","power":"신으면 바다와 땅 위를 바람처럼 날 수 있습니다. 페르세우스는 님프들에게서 이 샌들을 받아 메두사가 사는 곳까지 날아갔습니다.","price":null,"source":"「오디세이아」 5권, 아폴로도로스 「비블리오테케」","exhibit_id":"hermes-talaria","sort_order":24},{"slug":"girdle-of-hippolyta","name":"히폴리테의 허리띠","name_en":"Girdle of Hippolyta","kind":"ornament","figure_slugs":["hippolyta","heracles"],"origin":"아마조네스의 여왕 히폴리테가 군신 아레스에게 받은 허리띠로, 헤라클레스의 아홉째 과업이 이것을 가져오는 일이었습니다.","power":"아마조네스를 다스리는 여왕의 권위를 나타냅니다.","price":"히폴리테는 띠를 내주려 했지만 헤라가 아마조네스를 부추겨 싸움이 났고, 헤라클레스는 히폴리테를 죽이고 띠를 빼앗았습니다.","source":"아폴로도로스 「비블리오테케」","exhibit_id":"heracles-girdle","sort_order":25},{"slug":"necklace-of-harmonia","name":"하르모니아의 목걸이","name_en":"Necklace of Harmonia","kind":"ornament","figure_slugs":["cadmus","hephaestus"],"origin":"테바이를 세운 카드모스가 하르모니아와 혼인할 때 준 목걸이입니다. 아내의 바람을 원망한 헤파이스토스가 만들었다고도 합니다.","power":"지닌 여인을 영원히 젊고 아름답게 한다고 합니다.","price":"대대로 지닌 이들에게 불행을 불러와, 목걸이를 받고 남편을 전쟁터로 보낸 에리필레를 비롯해 테바이 왕가가 차례로 파멸했습니다.","source":"아폴로도로스 「비블리오테케」, 스타티우스 「테바이스」","exhibit_id":"harmonia-necklace-eriphyle","sort_order":26},{"slug":"bow-of-odysseus","name":"오디세우스의 활","name_en":"Bow of Odysseus","kind":"weapon","figure_slugs":["odysseus"],"origin":"오이칼리아의 이피토스가 우정의 표시로 준 활로, 오디세우스는 트로이로 떠날 때 집에 두고 갔습니다.","power":"오디세우스 말고는 누구도 시위를 걸지 못했습니다.","price":"스무 해 만에 거지 차림으로 돌아온 오디세우스는 이 활로 열두 도끼 구멍을 꿰뚫은 뒤, 아내에게 구혼하던 이들을 모두 쏘아 죽였습니다.","source":"「오디세이아」 21~22권","exhibit_id":"odysseus-bow","sort_order":27},{"slug":"cestus","name":"아프로디테의 띠","name_en":"Cestus of Aphrodite","kind":"ornament","figure_slugs":["aphrodite","hera"],"origin":"사랑의 여신 아프로디테가 가슴에 두르는 수놓은 띠입니다.","power":"사랑과 그리움, 마음을 빼앗는 달콤한 말이 수놓여 있어 누구든 사로잡습니다.","price":"헤라는 이 띠를 빌려 제우스를 홀린 뒤 잠들게 했고, 그사이 포세이돈이 트로이 전쟁에서 그리스군을 도왔습니다.","source":"「일리아스」 14권","exhibit_id":"hera-cestus","sort_order":28},{"slug":"net-of-hephaestus","name":"헤파이스토스의 그물","name_en":"Net of Hephaestus","kind":"tool","figure_slugs":["hephaestus","aphrodite"],"origin":"아내 아프로디테가 아레스와 몰래 만난다는 것을 태양신 헬리오스에게 전해 들은 헤파이스토스가 만든 사슬 그물입니다.","power":"거미줄처럼 가늘어 눈에 보이지 않지만, 신도 빠져나갈 수 없습니다.","price":"그물에 걸린 두 신을 본 신들은 크게 웃었고, 헤파이스토스는 자기 집안의 부끄러움을 모두에게 드러낸 셈이 되었습니다.","source":"「오디세이아」 8권","exhibit_id":"hephaestus-net","sort_order":29},{"slug":"wedjat","name":"우제트(호루스의 눈)","name_en":"Eye of Horus","kind":"ornament","figure_slugs":["horus","set","thoth"],"origin":"왕위를 두고 세트와 싸우다 뽑힌 호루스의 눈을 토트가 되살렸다고 합니다.","power":"온전함과 치유, 보호를 뜻해 산 이와 죽은 이 모두 부적으로 지녔습니다.","price":"호루스는 되찾은 눈을 죽은 아버지 오시리스에게 바쳐 그를 되살렸다고 전합니다.","source":"「호루스와 세트의 다툼」, 피라미드 문서","exhibit_id":"horus-wedjat","sort_order":30},{"slug":"feather-of-maat","name":"마아트의 깃털","name_en":"Feather of Maat","kind":"tool","figure_slugs":["anubis","thoth","ammit"],"origin":"진리와 질서의 여신 마아트를 나타내는 타조 깃털입니다.","power":"저승의 심판에서 죽은 이의 심장을 이 깃털과 함께 저울에 올려, 아누비스가 달고 토트가 적습니다.","price":"심장이 깃털보다 무거우면 암미트가 삼켜 두 번째 죽음을 맞습니다.","source":"「사자의 서」 125장","exhibit_id":"weighing-heart","sort_order":31},{"slug":"book-of-thoth","name":"토트의 책","name_en":"Book of Thoth","kind":"treasure","figure_slugs":["thoth"],"origin":"지혜의 신 토트가 손수 쓴 마법서로, 강물 속 상자 안의 상자에 겹겹이 감춰져 있었습니다.","power":"읽으면 하늘과 땅, 바다의 비밀과 새와 짐승의 말을 알게 됩니다.","price":"책을 찾아낸 왕자 네페르카프타는 아내와 아들을 잃고 스스로 목숨을 끊었고, 뒤에 그 무덤에서 책을 가져간 왕자 세트네도 화를 당한 끝에 책을 돌려놓았습니다.","source":"「세트네 카엠와세트 이야기」(데모틱 문서)","exhibit_id":"thoth-sacred-books","sort_order":32},{"slug":"tablet-of-destinies","name":"운명의 서판","name_en":"Tablet of Destinies","kind":"treasure","figure_slugs":["marduk","tiamat"],"origin":"티아마트가 군대의 장수 킨구에게 걸어 준 점토판입니다.","power":"지닌 이에게 신들 위의 권위와 운명을 정하는 힘을 줍니다.","price":"마르두크는 티아마트를 쓰러뜨리고 킨구에게서 서판을 빼앗아 신들의 왕이 되었습니다.","source":"「에누마 엘리시」, 「안주 이야기」","exhibit_id":"tiamat-nimrud","sort_order":33},{"slug":"plant-of-youth","name":"젊음의 풀","name_en":"Plant of Rejuvenation","kind":"treasure","figure_slugs":["gilgamesh"],"origin":"홍수에서 살아남아 영생을 얻은 우트나피쉬팀이 길가메시에게 알려 준, 바다 밑에 자라는 가시 돋친 풀입니다.","power":"먹으면 늙은이가 다시 젊어집니다.","price":"길가메시가 샘에서 몸을 씻는 사이 뱀이 풀을 물고 가 허물을 벗었고, 길가메시는 빈손으로 우루크에 돌아왔습니다.","source":"「길가메시 서사시」 11서판","exhibit_id":"gilgamesh-flood-tablet","sort_order":34},{"slug":"seven-ornaments-of-ishtar","name":"이슈타르의 일곱 장신구","name_en":"Seven Ornaments of Ishtar","kind":"ornament","figure_slugs":["ishtar","ereshkigal"],"origin":"저승으로 내려가는 이슈타르가 몸에 걸친 관, 귀걸이, 목걸이, 가슴 장식, 허리띠, 팔찌와 발찌, 옷입니다.","power":"하늘의 여신이 지닌 권능을 나타냅니다.","price":"저승의 일곱 문을 지날 때마다 하나씩 벗겨져, 이슈타르는 알몸으로 언니 에레쉬키갈 앞에 섰다가 죽임을 당했습니다.","source":"「이슈타르의 저승 하강」, 수메르 「인안나의 저승 하강」","exhibit_id":"ishtar-sumerian-headdress","sort_order":35},{"slug":"vajra","name":"바즈라","name_en":"Vajra","kind":"weapon","figure_slugs":["indra","vritra"],"origin":"현자 다디치가 스스로 내놓은 뼈로 장인 트바시트리가 만든 벼락 무기라고 합니다.","power":"물을 가두던 뱀 브리트라를 쓰러뜨려 세상에 물을 다시 흐르게 했습니다.","price":"이 무기는 다디치가 자기 목숨을 내준 대가로 만들어졌습니다.","source":"「리그베다」, 「마하바라타」","exhibit_id":"indra-vajra","sort_order":36},{"slug":"sudarshana-chakra","name":"수다르샤나 차크라","name_en":"Sudarshana Chakra","kind":"weapon","figure_slugs":["vishnu","krishna"],"origin":"비슈누가 지닌 원반으로, 장인 비슈바카르마가 태양의 빛을 깎아 만들었다고도 합니다.","power":"던지면 적을 베고 다시 손가락으로 돌아옵니다. 크리슈나는 이 원반으로 시슈팔라의 목을 베었습니다.","price":null,"source":"「마하바라타」, 「비슈누 푸라나」","exhibit_id":"vishnu-chakra","sort_order":37},{"slug":"trishula","name":"트리슐라","name_en":"Trishula","kind":"weapon","figure_slugs":["shiva","ganesha"],"origin":"시바가 늘 지니는 삼지창입니다.","power":"세 갈래 날은 창조·유지·파괴, 또는 과거·현재·미래를 뜻한다고 풀이합니다.","price":"널리 알려진 이야기에서 시바는 문을 막아선 아이의 목을 이 창으로 베었고, 그 아이에게 코끼리 머리를 붙여 가네샤로 되살렸습니다.","source":"「시바 푸라나」","exhibit_id":"shiva-trishula","sort_order":38},{"slug":"gandiva","name":"간디바","name_en":"Gandiva","kind":"weapon","figure_slugs":["arjuna","krishna"],"origin":"카운다바 숲을 태우려는 불의 신 아그니를 돕는 대가로 아르주나가 받은 활입니다.","power":"어떤 무기로도 부서지지 않고, 마르지 않는 화살통과 함께 쿠루크셰트라 전쟁을 치렀습니다.","price":"이 활을 얻은 날 숲의 생명들은 불길에 휩싸였고, 전쟁이 끝난 뒤 아르주나는 활을 바다의 신에게 돌려주었습니다.","source":"「마하바라타」","exhibit_id":"arjuna-gandiva-chariot","sort_order":39},{"slug":"kavacha-kundala","name":"카르나의 갑옷과 귀걸이","name_en":"Kavacha and Kundala","kind":"armor","figure_slugs":["karna","indra"],"origin":"태양신 수리야의 아들 카르나가 태어날 때부터 몸에 붙어 있던 갑옷과 귀걸이입니다.","power":"지니고 있는 한 카르나는 어떤 무기에도 다치지 않습니다.","price":"아들 아르주나를 지키려는 인드라가 사제로 꾸며 이것을 청하자, 카르나는 살을 베어 내어 주었습니다. 대신 받은 인드라의 창은 한 번밖에 쓸 수 없었는데, 이 창을 가토트카차에게 써 버려 아르주나와 맞설 때는 쓰지 못했고 끝내 전장에서 쓰러졌습니다.","source":"「마하바라타」","exhibit_id":"karna-shakti","sort_order":40},{"slug":"parashu","name":"파라슈","name_en":"Parashu","kind":"weapon","figure_slugs":["parashurama","shiva"],"origin":"시바가 수행을 마친 라마에게 내린 도끼로, 이때부터 그는 '도끼를 든 라마', 파라슈라마로 불렸습니다.","power":"왕 카르타비랴 아르주나를 쓰러뜨리고 크샤트리아를 스물한 번 쓸어 냈다고 합니다.","price":null,"source":"「마하바라타」, 「바가바타 푸라나」","exhibit_id":"parashurama-commons","sort_order":41},{"slug":"brahmastra","name":"브라마스트라","name_en":"Brahmastra","kind":"weapon","figure_slugs":["ashwatthama","arjuna","krishna"],"origin":"창조신 브라마의 힘을 담은 무기로, 주문을 외워 불러냅니다.","power":"세상을 태울 만큼 강해, 같은 브라마스트라로만 맞설 수 있습니다.","price":"쿠루크셰트라 전쟁 끝에 아르주나는 무기를 거두었지만 아슈바타만은 거두지 못해 판다바 가문의 태아에게 돌렸고, 크리슈나의 저주로 3천 년 동안 떠돌게 되었습니다.","source":"「마하바라타」","exhibit_id":"ashwatthama-razmnama-battle","sort_order":42},{"slug":"pinaka","name":"피나카","name_en":"Pinaka","kind":"weapon","figure_slugs":["shiva","rama"],"origin":"시바의 활로, 미틸라의 자나카 왕 집안에 대대로 맡겨져 있었습니다.","power":"수백 명이 끌어야 움직일 만큼 무거워 누구도 시위를 걸지 못했습니다.","price":"시타의 신랑을 고르는 자리에서 라마가 활을 들어 시위를 당기다 둘로 부러뜨려 시타와 혼인했지만, 이 일로 시바를 따르는 파라슈라마의 노여움을 샀습니다.","source":"「라마야나」","exhibit_id":"rama-pinaka","sort_order":43},{"slug":"amrita","name":"암리타","name_en":"Amrita","kind":"treasure","figure_slugs":["vishnu","indra","shiva"],"origin":"신들과 아수라가 만다라산을 막대로, 뱀 바수키를 줄로 삼아 우유 바다를 휘저어 얻은 불사의 감로입니다.","power":"마시면 죽지 않습니다. 비슈누가 아름다운 여인 모히니로 변해 아수라를 속이고 신들에게만 나누어 주었습니다.","price":"휘젓는 동안 독 할라할라가 솟자 시바가 삼켜 목이 푸르게 되었고, 감로를 몰래 마시던 아수라 라후는 비슈누에게 목이 베였습니다.","source":"「마하바라타」, 「바가바타 푸라나」","exhibit_id":"vishnu-churning","sort_order":44},{"slug":"syamantaka","name":"시야만타카","name_en":"Syamantaka","kind":"ornament","figure_slugs":["krishna"],"origin":"태양신 수리야가 사트라지트에게 준 보석입니다.","power":"날마다 금을 낳고, 지닌 나라에는 가뭄과 재앙이 들지 않는다고 합니다.","price":"보석을 차고 사냥 나간 프라세나가 사자에게 죽자 사람들은 크리슈나가 훔쳤다고 의심했고, 크리슈나는 곰의 왕 잠바반과 싸워 보석을 되찾은 뒤에야 누명을 벗었습니다.","source":"「비슈누 푸라나」, 「바가바타 푸라나」","exhibit_id":"krishna-syamantaka","sort_order":45},{"slug":"kusanagi","name":"구사나기의 검","name_en":"Kusanagi no Tsurugi","kind":"weapon","figure_slugs":["susanoo","amaterasu","yamato-takeru"],"origin":"스사노오가 야마타노오로치를 베었을 때 꼬리에서 나온 칼로, 아마테라스에게 바쳤습니다. 처음 이름은 아메노무라쿠모였습니다.","power":"야마토타케루가 들판에서 불에 갇혔을 때 이 칼로 풀을 베어 살아 나왔고, 그래서 '풀을 벤 칼'이라 불립니다.","price":null,"source":"「고사기」, 「일본서기」","exhibit_id":"susanoo-orochi","sort_order":46},{"slug":"yata-no-kagami","name":"야타의 거울","name_en":"Yata no Kagami","kind":"treasure","figure_slugs":["amaterasu"],"origin":"아마테라스가 동굴에 숨어 세상이 어두워지자, 신들이 그녀를 꾀어내려고 만든 거울입니다.","power":"거울에 비친 빛에 이끌려 아마테라스가 나오자 세상에 다시 빛이 돌아왔습니다. 구사나기·곡옥과 함께 세 가지 신기로 전합니다.","price":null,"source":"「고사기」, 「일본서기」","exhibit_id":"amaterasu-iwato","sort_order":47},{"slug":"yasakani-no-magatama","name":"야사카니의 곡옥","name_en":"Yasakani no Magatama","kind":"ornament","figure_slugs":["amaterasu"],"origin":"아마테라스를 동굴에서 꾀어내려고 신들이 야타의 거울과 함께 비쭈기나무에 걸어 둔 굽은 구슬 꾸러미입니다.","power":"구사나기의 검, 야타의 거울과 함께 세 가지 신기로 전합니다.","price":null,"source":"「고사기」, 「일본서기」","exhibit_id":"magatama-yato","sort_order":48},{"slug":"ame-no-nuboko","name":"아메노누보코","name_en":"Ame-no-Nuboko","kind":"weapon","figure_slugs":["izanagi-izanami"],"origin":"하늘의 신들이 땅을 만들라며 이자나기와 이자나미에게 내린 구슬 장식 창입니다.","power":"두 신이 하늘에 걸린 다리에 서서 이 창으로 바다를 휘저었고, 창끝에서 떨어진 소금물이 굳어 첫 섬 오노고로가 되었습니다.","price":null,"source":"「고사기」","exhibit_id":"izanagi-izanami","sort_order":49},{"slug":"ruyi-jingu-bang","name":"여의금고봉","name_en":"Ruyi Jingu Bang","kind":"weapon","figure_slugs":["sun-wukong"],"origin":"우임금이 바다의 깊이를 재던 쇠기둥으로, 손오공이 동해 용궁에서 얻었습니다.","power":"무게가 만삼천오백 근이고, 마음대로 늘고 줄어 평소에는 바늘만 하게 줄여 귀에 넣어 둡니다.","price":null,"source":"「서유기」","exhibit_id":"sun-wukong-commons","sort_order":50},{"slug":"bow-of-hou-yi","name":"후예의 활","name_en":"Bow of Hou Yi","kind":"weapon","figure_slugs":["hou-yi"],"origin":"천제 제준이 후예에게 내린 붉은 활과 흰 화살입니다.","power":"요임금 때 열 개의 해가 한꺼번에 떠오르자, 후예는 아홉 개를 쏘아 떨어뜨렸습니다.","price":"해들은 천제의 아들이었고, 이 일로 후예는 하늘로 돌아가지 못했다고 전합니다.","source":"「산해경」, 「회남자」","exhibit_id":"hou-yi-commons","sort_order":51},{"slug":"elixir-of-immortality","name":"불사약","name_en":"Elixir of Immortality","kind":"treasure","figure_slugs":["change","hou-yi"],"origin":"후예가 곤륜산의 서왕모에게서 얻은 약입니다.","power":"먹으면 죽지 않고 하늘로 오릅니다.","price":"항아가 이 약을 혼자 먹고 달로 올라가, 남편과 영영 떨어져 달에서 살게 되었습니다.","source":"「회남자」","exhibit_id":"change-moon","sort_order":52},{"slug":"five-colored-stones","name":"오색석","name_en":"Five-colored Stones","kind":"treasure","figure_slugs":["nuwa"],"origin":"하늘을 받치던 기둥이 무너져 하늘에 구멍이 나자, 여와가 다섯 빛깔 돌을 녹여 만든 돌입니다.","power":"구멍 난 하늘을 메웠고, 여와는 큰 거북의 다리를 잘라 네 기둥으로 세웠습니다.","price":null,"source":"「회남자」","exhibit_id":"nuwa-stones","sort_order":53},{"slug":"peaches-of-immortality","name":"반도","name_en":"Peaches of Immortality","kind":"treasure","figure_slugs":["xiwangmu","sun-wukong"],"origin":"서왕모의 정원 반도원에 자라는 복숭아로, 가장 오래된 나무는 9천 년에 한 번 열매가 익습니다.","power":"먹으면 하늘과 땅만큼 오래 삽니다.","price":"반도원을 지키던 손오공이 몰래 따 먹고 잔치를 망쳤다가, 끝내 오행산 아래 5백 년 동안 갇혔습니다.","source":"「서유기」","exhibit_id":"xiwangmu-peaches","sort_order":54},{"slug":"qiankun-quan","name":"건곤권과 혼천릉","name_en":"Qiankun Quan and Huntian Ling","kind":"weapon","figure_slugs":["nezha"],"origin":"나타가 태어날 때부터 지니고 나온 금 고리와 붉은 비단띠로, 스승 태을진인이 내렸다고 합니다.","power":"혼천릉을 바다에 담가 흔들자 동해 용궁이 흔들렸고, 건곤권을 던져 용왕의 셋째 아들을 쓰러뜨렸습니다.","price":"용왕이 부모를 벌하려 하자 나타는 살을 베어 어머니에게, 뼈를 발라 아버지에게 돌려준 뒤 연꽃 몸으로 다시 태어났습니다.","source":"「봉신연의」","exhibit_id":"nezha-opera","sort_order":55},{"slug":"cheonbuin","name":"천부인 세 개","name_en":"Three Heavenly Seals","kind":"treasure","figure_slugs":["hwanin","hwanung","dangun"],"origin":"하늘의 환인이 인간 세상을 다스리려는 아들 환웅에게 내려 준 세 가지 증표입니다.","power":"환웅은 이것을 지니고 무리 삼천과 함께 태백산 신단수 아래로 내려왔습니다. 무엇이었는지는 전하지 않아 거울·칼·방울로 보는 견해가 있습니다.","price":null,"source":"「삼국유사」 고조선 조","exhibit_id":"korean-bronze-daggers","sort_order":56},{"slug":"flowers-of-life","name":"바리공주의 약수와 꽃","name_en":"Water and Flowers of Life","kind":"treasure","figure_slugs":["bari"],"origin":"버려진 일곱째 공주 바리가 병든 부모를 살리려고 저승 너머 서천 서역국에서 구해 온 약수와 꽃입니다.","power":"뼈살이꽃, 살살이꽃 같은 꽃과 약수로 이미 숨이 끊어진 부모를 되살렸습니다.","price":"바리는 약수를 지키는 이에게 물 긷기, 나무하기, 불 때기를 아홉 해 동안 하고 그와 혼인해 아들 일곱을 낳은 뒤에야 약수를 얻었습니다.","source":"무가 「바리공주」","exhibit_id":"bari-lacma","sort_order":57},{"slug":"oryongeo","name":"오룡거","name_en":"Five-Dragon Chariot","kind":"treasure","figure_slugs":["haemosu","yuhwa"],"origin":"천제의 아들 해모수가 하늘에서 타고 내려온, 다섯 마리 용이 끄는 수레입니다.","power":"해모수는 아침에 내려와 인간 세상을 다스리고 저녁이면 하늘로 올라갔습니다.","price":"해모수는 유화를 데려가려다 그 아버지 하백과 재주를 겨루었고, 끝내 유화를 두고 홀로 하늘로 돌아갔습니다.","source":"이규보 「동명왕편」","exhibit_id":"haemosu-han-chariot-fitting","sort_order":58},{"slug":"gold-box-of-gujibong","name":"구지봉의 금합","name_en":"Golden Box of Gujibong","kind":"treasure","figure_slugs":["suro"],"origin":"구지봉에서 아홉 촌장과 사람들이 「구지가」를 부르자, 하늘에서 자줏빛 줄에 매달려 내려온 붉은 보자기 속 금빛 상자입니다.","power":"상자 안의 황금 알 여섯 개에서 수로왕과 다섯 가야의 왕이 태어났습니다.","price":null,"source":"「삼국유사」 가락국기","exhibit_id":"suro-gaya-pottery-stand","sort_order":59},{"slug":"gae-bulg","name":"게 볼그","name_en":"Gáe Bulg","kind":"weapon","figure_slugs":["cuchulainn"],"origin":"여전사 스카타크가 제자 쿠 훌린에게만 쓰는 법을 가르친 창입니다.","power":"발로 던지며, 몸에 들어가면 미늘이 펴져 빼낼 수 없습니다.","price":"쿠 훌린은 이 창으로 아들 콘라와 의형제 페르디아드를 죽였습니다.","source":"「쿨리의 소 습격」, 「아이페의 외아들의 죽음」","exhibit_id":"cuchulainn-leyendecker","sort_order":60},{"slug":"fragarach","name":"프라가라흐","name_en":"Fragarach","kind":"weapon","figure_slugs":["manannan"],"origin":"바다의 신 마난난 막 리르의 칼로, 이름은 '답하는 자'라는 뜻입니다. 빛의 신 루에게 건넸다고도 합니다.","power":"겨누어진 이는 움직이지 못하고 진실만 말하게 되며, 어떤 갑옷도 벤다고 전합니다.","price":null,"source":"후대 아일랜드 전승","exhibit_id":"manannan-kirkburn-sword","sort_order":61},{"slug":"excalibur","name":"엑스칼리버","name_en":"Excalibur","kind":"weapon","figure_slugs":["king-arthur","bedivere","merlin","morgan-le-fay"],"origin":"맬러리의 이야기에서 아서는 멀린의 안내로 호수의 여인에게서 이 칼을 받습니다.","power":"칼보다 칼집이 더 귀해, 칼집을 지닌 이는 피를 흘리지 않았습니다.","price":"모건 르 페이가 칼집을 훔쳐 버렸고, 마지막 싸움에서 크게 다친 아서는 베디비어에게 칼을 호수로 돌려보내게 했습니다.","source":"토머스 맬러리 「아서의 죽음」","exhibit_id":"bedivere-commons","sort_order":62},{"slug":"holy-grail","name":"성배","name_en":"Holy Grail","kind":"treasure","figure_slugs":["galahad","percival","lancelot","king-arthur"],"origin":"맬러리의 이야기에서 성배는 오순절에 원탁 위로 빛과 함께 나타나, 기사들을 탐색의 길로 떠나게 했습니다.","power":"병을 고치고 은총을 내리며, 마음이 깨끗한 기사만 가까이 갈 수 있습니다.","price":"탐색에 나선 많은 기사가 돌아오지 못해 원탁이 흩어지기 시작했고, 성배를 본 갤러해드는 그대로 세상을 떠났습니다.","source":"토머스 맬러리 「아서의 죽음」","exhibit_id":"galahad-grail","sort_order":63},{"slug":"sampo","name":"삼포","name_en":"Sampo","kind":"treasure","figure_slugs":["ilmarinen","vainamoinen","louhi"],"origin":"대장장이 일마리넨이 북쪽 땅 포욜라의 여주인 로우히에게 딸을 얻으려고 백조 깃털, 새끼 못 낳는 소의 젖, 보리 한 알, 양털 한 올로 벼린 맷돌입니다.","power":"저절로 돌아 밀가루와 소금, 금을 끝없이 쏟아 냅니다.","price":"영웅들이 삼포를 훔쳐 달아나다 로우히와 바다에서 싸웠고, 삼포는 부서져 조각만 바다에 흩어졌습니다.","source":"「칼레발라」","exhibit_id":"ilmarinen-sampo","sort_order":64},{"slug":"kantele","name":"칸텔레","name_en":"Kantele","kind":"tool","figure_slugs":["vainamoinen"],"origin":"베이네뫼이넨이 커다란 강꼬치고기의 턱뼈로 만든 현악기입니다.","power":"그가 연주하면 하늘의 새와 숲의 짐승, 바닷속 물고기까지 모여들어 들었습니다.","price":"삼포를 두고 싸우는 동안 바다에 잃어버려, 자작나무로 새 칸텔레를 다시 만들어야 했습니다.","source":"「칼레발라」","exhibit_id":"vainamoinen-kantele","sort_order":65},{"slug":"golden-bride","name":"황금 신부","name_en":"Golden Bride","kind":"treasure","figure_slugs":["ilmarinen","vainamoinen"],"origin":"아내를 잃은 대장장이 일마리넨이 금과 은을 불에 넣어 벼려 낸 신부입니다.","power":"눈부시게 아름답지만, 곁에 누우면 닿은 쪽 몸이 얼어붙을 만큼 차갑습니다.","price":"일마리넨이 신부를 베이네뫼이넨에게 주려 하자, 베이네뫼이넨은 금으로 만든 아내를 찾지 말라며 물리쳤습니다.","source":"「칼레발라」","exhibit_id":"ilmarinen-alanen-sampo","sort_order":66},{"slug":"needle-of-koschei","name":"코셰이의 바늘","name_en":"Needle of Koschei","kind":"treasure","figure_slugs":["koschei"],"origin":"죽지 않는 코셰이가 자기 죽음을 숨겨 둔 바늘입니다.","power":"바늘은 알 속에, 알은 오리 속에, 오리는 토끼 속에, 토끼는 쇠 상자 속에 들어 참나무 아래 묻혀 있어 아무도 코셰이를 죽이지 못했습니다.","price":"짐승들의 도움으로 알을 찾아낸 이반 왕자가 바늘을 부러뜨리자 코셰이는 죽었습니다.","source":"러시아 민담 「마리야 모레브나」","exhibit_id":"koschei-commons","sort_order":67},{"slug":"mortar-of-baba-yaga","name":"바바 야가의 절구","name_en":"Mortar of Baba Yaga","kind":"tool","figure_slugs":["baba-yaga"],"origin":"숲속 닭다리 오두막에 사는 마녀 바바 야가가 타고 다니는 절구입니다.","power":"절구를 타고 절굿공이로 노를 저으며 숲 위를 날고, 빗자루로 지나간 자취를 쓸어 지웁니다.","price":null,"source":"러시아 민담 「아름다운 바실리사」","exhibit_id":"baba-yaga-bilibin","sort_order":68},{"slug":"jawbone-of-maui","name":"마우이의 턱뼈","name_en":"Jawbone of Muri-ranga-whenua","kind":"weapon","figure_slugs":["maui"],"origin":"마우이가 할머니 무리랑아훼누아에게서 얻은 마법의 턱뼈입니다.","power":"마우이는 밧줄로 해를 붙잡고 이 턱뼈로 때려 해가 천천히 지나가게 했고, 턱뼈로 만든 낚싯바늘로 바다에서 땅을 낚아 올렸습니다.","price":null,"source":"마오리 전승","exhibit_id":"maui-polynesian","sort_order":69},{"slug":"smoking-mirror","name":"연기 나는 거울","name_en":"Smoking Mirror","kind":"tool","figure_slugs":["tezcatlipoca","quetzalcoatl"],"origin":"밤의 신 테스카틀리포카의 이름('연기 나는 거울')이 된 흑요석 거울입니다.","power":"세상과 사람의 마음을 비춰 봅니다.","price":"대지의 괴물과 싸우다 발 하나를 잃어 그 자리에 거울을 달았다고 하며, 이 거울에 늙은 모습을 비춰 보인 꾀로 케찰코아틀을 톨란에서 떠나게 했습니다.","source":"나우아 전승(「피렌체 코덱스」 등)","exhibit_id":"tezcatlipoca-borgia","sort_order":70},{"slug":"xiuhcoatl","name":"시우코아틀","name_en":"Xiuhcoatl","kind":"weapon","figure_slugs":["huitzilopochtli"],"origin":"전쟁과 태양의 신 우이칠로포치틀리가 태어나자마자 쥔 불의 뱀입니다.","power":"어머니 코아틀리쿠에를 죽이려던 누이 코욜샤우키를 이 무기로 베고, 사백 형제를 물리쳤습니다.","price":"코욜샤우키의 몸은 코아테펙산 아래로 굴러떨어져 산산조각 났습니다.","source":"「피렌체 코덱스」 3권","exhibit_id":"huitzilopochtli-wdl","sort_order":71},{"slug":"derafsh-kaviani","name":"카베의 깃발","name_en":"Derafsh Kaviani","kind":"treasure","figure_slugs":["kaveh","fereydun"],"origin":"대장장이 카베가 폭군 자하크에 맞서 일어서며 가죽 앞치마를 창끝에 달아 든 깃발입니다.","power":"사람들이 이 깃발 아래 모여 페레이둔을 왕으로 세웠고, 뒤에 보석으로 꾸며져 이란 왕들의 깃발이 되었습니다.","price":"카베는 아들 열여덟 가운데 열일곱을 자하크의 어깨에 돋은 뱀의 먹이로 잃은 뒤에 일어섰습니다.","source":"페르도우시 「샤나메」","exhibit_id":"kaveh-commons","sort_order":72},{"slug":"durendal","name":"뒤랑달","name_en":"Durendal","kind":"weapon","figure_slugs":["roland","charlemagne"],"origin":"롤랑이 샤를마뉴에게서 받은 칼로, 황금 손잡이 안에 성유물이 들어 있었다고 합니다.","power":"무엇이든 벨 만큼 날카롭습니다.","price":"롱스보 고개에서 홀로 남은 롤랑은 칼이 적의 손에 들어가지 않게 바위에 내리쳤지만 바위만 갈라졌고, 너무 늦게 뿔피리 올리판트를 불어 숨을 거두었습니다.","source":"「롤랑의 노래」","exhibit_id":"roland-durendal","sort_order":73},{"slug":"tarnkappe","name":"타른카페","name_en":"Tarnkappe","kind":"armor","figure_slugs":["siegfried"],"origin":"지크프리트가 난쟁이 알베리히에게서 빼앗은 망토입니다.","power":"걸치면 모습이 보이지 않고 힘이 열두 사람만큼 세집니다.","price":"지크프리트는 이 망토를 쓰고 몰래 군터를 도와 브륀힐트를 이기게 했는데, 이 속임수가 드러나 하겐에게 죽임을 당했습니다.","source":"「니벨룽의 노래」","exhibit_id":"siegfried-tarnkappe","sort_order":74},{"slug":"olifant","name":"올리판트","name_en":"Olifant","kind":"tool","figure_slugs":["roland","charlemagne"],"origin":"롤랑이 지니고 다닌 상아 뿔나팔로, 이름부터 코끼리를 뜻하는 옛 프랑스어에서 왔습니다.","power":"론세스바예스에서 롤랑이 마지막으로 불자 그 소리가 30리그 떨어진 샤를마뉴의 군대까지 들렸습니다.","price":"올리비에가 처음부터 불자고 했지만 롤랑은 체면 때문에 거절했고, 너무 늦게 힘껏 부느라 관자놀이가 터져 죽음을 맞았습니다.","source":"「롤랑의 노래」","exhibit_id":"roland-olifant-fouquet","sort_order":75},{"slug":"joyeuse","name":"주아이외즈","name_en":"Joyeuse","kind":"weapon","figure_slugs":["charlemagne"],"origin":"샤를마뉴의 칼로, 황금 칼자루 끝에 그리스도를 찌른 창의 끝이 박혀 있어 그 영광을 기려 '기쁨'이라는 이름이 붙었다고 합니다.","power":"하루에 서른 번 빛깔이 바뀌었다고 하며, 프랑크군의 함성 '몽주아'도 이 칼에서 나왔다고 전합니다.","price":null,"source":"「롤랑의 노래」","exhibit_id":"joyeuse-louvre","sort_order":76},{"slug":"wits-of-orlando","name":"롤랑의 정신이 든 병","name_en":"Orlando's Wits","kind":"treasure","figure_slugs":["astolfo","roland"],"origin":"「광란의 오를란도」에서 안젤리카를 잃고 미쳐 버린 롤랑(오를란도)의 정신은, 땅에서 잃어버린 모든 것이 모인다는 달의 골짜기에 병에 담겨 있었습니다. 아스톨포가 성 요한과 함께 엘리야의 불 수레를 타고 달에 올라 '오를란도의 정신'이라고 적힌 병을 찾아왔습니다.","power":"병에 담긴 것을 코로 들이마시게 하자 롤랑은 제정신을 되찾았습니다. 아스톨포는 그곳에서 자기가 잃었던 정신도 조금 되찾아 왔습니다.","price":"제정신을 찾은 롤랑은 안젤리카를 향한 사랑도 함께 잊어버렸습니다.","source":"아리오스토 「광란의 오를란도」","exhibit_id":"astolfo-moon-dore","sort_order":77},{"slug":"hrunting-and-naegling","name":"흐룬팅과 내글링","name_en":"Hrunting and Nægling","kind":"weapon","figure_slugs":["beowulf"],"origin":"흐룬팅은 덴마크 궁정의 운페르스가 그렌델의 어미와 싸우러 가는 베오울프에게 빌려준 칼이고, 내글링은 늙은 베오울프가 용과 싸울 때 든 오래된 칼입니다.","power":"흐룬팅은 독이 밴 무늬를 새기고 싸움의 피로 단련해 한 번도 주인을 저버린 적이 없었고, 내글링은 회색 무늬가 빛나는 이름난 옛 칼이었습니다.","price":"흐룬팅은 그렌델 어미의 몸에 먹히지 않아 베오울프가 내던졌고, 내글링은 용의 머리를 내리치다 부러졌습니다. 베오울프는 단검으로 용을 쓰러뜨렸지만 그 독에 목숨을 잃었습니다.","source":"「베오울프」","exhibit_id":"beowulf-dragon-skelton","sort_order":78},{"slug":"nibelung-hoard","name":"니벨룽의 보물","name_en":"Nibelung Hoard","kind":"treasure","figure_slugs":["siegfried","hagen","kriemhild"],"origin":"지크프리트가 니벨룽 왕자들을 쓰러뜨리고 난쟁이 알베리히를 굴복시켜 얻은 보물로, 크림힐트가 남편에게 혼인 선물로 받았다가 그가 죽은 뒤 보름스로 가져왔습니다.","power":"열두 대의 수레가 나흘 밤낮을 날라야 할 만큼 많은 금과 보석이었고, 그 안에는 온 세상 사람을 다스릴 수 있다는 금 막대도 있었다고 합니다.","price":"하겐은 크림힐트가 보물로 세력을 모을까 두려워 라인강에 가라앉히고 그 자리를 끝내 말하지 않았고, 이 보물을 둘러싼 원한이 부르군트족의 멸망으로 이어졌습니다.","source":"「니벨룽의 노래」","exhibit_id":"hagen-nibelung-hoard","sort_order":79},{"slug":"balmung","name":"발뭉","name_en":"Balmung","kind":"weapon","figure_slugs":["siegfried","hagen","kriemhild"],"origin":"니벨룽 왕자들이 보물을 나누어 달라며 지크프리트에게 품삯으로 준 칼입니다. 나눔이 끝나기 전에 다툼이 일자 지크프리트는 바로 이 칼로 그들을 쓰러뜨렸습니다.","power":"투구와 갑옷을 쉽게 가르는 명검입니다.","price":"지크프리트가 죽은 뒤 하겐이 이 칼을 차지했고, 마지막에 크림힐트는 이 칼로 하겐의 목을 베었습니다. 크림힐트도 곧 힐데브란트의 칼에 쓰러졌습니다.","source":"「니벨룽의 노래」","exhibit_id":"hagen-balmung-hundeshagen","sort_order":80},{"slug":"love-potion","name":"사랑의 묘약","name_en":"Love Potion","kind":"treasure","figure_slugs":["tristan","isolde"],"origin":"이졸데의 어머니인 아일랜드 왕비가 딸과 마크 왕이 서로 사랑하도록 지어 시녀 브랑지앵에게 맡긴 약입니다.","power":"함께 마신 두 사람은 서로 떨어질 수 없을 만큼 사랑하게 됩니다. 베룰의 판본에서는 약효가 3년 동안 간다고 합니다.","price":"콘월로 가는 배에서 트리스탄과 이졸데가 이 약을 포도주로 알고 마셔 버렸고, 두 사람은 평생 금지된 사랑에 매여 죽음에 이르렀습니다.","source":"베룰과 토마의 「트리스탄 이야기」, 고트프리트 폰 슈트라스부르크 「트리스탄」","exhibit_id":"tristan-isolde-potion","sort_order":81},{"slug":"green-girdle","name":"녹색 띠","name_en":"Green Girdle","kind":"ornament","figure_slugs":["gawain","green-knight"],"origin":"녹색 기사와의 약속을 지키러 가던 가웨인이 머문 성에서, 성주의 아내가 건넨 금실로 수놓은 초록 비단 띠입니다.","power":"이 띠를 두른 사람은 누구도 해칠 수 없다고 했습니다.","price":"가웨인은 목숨이 아까워 띠를 성주에게 숨겼고, 그 대가로 녹색 기사의 세 번째 일격에 목에 작은 상처를 입었습니다. 그는 부끄러움을 잊지 않으려 띠를 두르고 돌아왔고, 원탁의 기사들은 모두 같은 띠를 매어 그를 위로했습니다.","source":"「가웨인 경과 녹색 기사」","exhibit_id":"gawain-lady-cotton-nero","sort_order":82},{"slug":"round-table","name":"원탁","name_en":"Round Table","kind":"treasure","figure_slugs":["king-arthur","merlin","galahad","guinevere"],"origin":"바스의 「브뤼 이야기」(1155)에서 아서가 기사들의 자리다툼을 막으려고 만든 둥근 탁자입니다. 다른 전승에서는 멀린이 우서 펜드래건을 위해 만들었고, 귀네비어의 아버지가 혼인 선물로 아서에게 보냈다고 합니다.","power":"윗자리와 아랫자리가 없어 모든 기사가 같은 자격으로 앉았습니다. 한 자리는 '위험한 자리'라 하여 성배를 찾을 기사만이 앉을 수 있었고, 갤러해드가 그 주인이 되었습니다.","price":"랜슬롯과 귀네비어의 일, 모드레드의 반란으로 기사들이 갈라져 서로 싸우면서 원탁의 기사단은 무너졌습니다.","source":"바스 「브뤼 이야기」, 로베르 드 보롱 「멀린」, 토머스 맬러리 「아서의 죽음」","exhibit_id":"round-table-winchester","sort_order":83},{"slug":"wings-of-daedalus","name":"다이달로스의 날개","name_en":"Wings of Daedalus","kind":"tool","figure_slugs":["daedalus"],"origin":"미노스 왕이 크레타를 떠나지 못하게 하자, 다이달로스가 새 깃털을 길이대로 늘어놓고 가운데는 실로, 끝은 밀랍으로 붙여 만든 날개입니다.","power":"새처럼 바다를 건너 날 수 있게 해 주었고, 다이달로스는 이 날개로 시칠리아까지 날아갔습니다.","price":"아들 이카로스가 너무 높이 날아오르자 태양열에 밀랍이 녹아 바다에 떨어져 죽었습니다. 다이달로스는 자신의 재주를 저주하며 아들을 묻었습니다.","source":"오비디우스 「변신 이야기」, 아폴로도로스 「비블리오테케」","exhibit_id":"daedalus-icarus-leighton","sort_order":84},{"slug":"pandoras-jar","name":"판도라의 항아리","name_en":"Pandora's Jar","kind":"treasure","figure_slugs":["pandora","zeus"],"origin":"헤시오도스의 「일과 날」에서 판도라가 연 큰 항아리(피토스)입니다. 누가 그 안에 재앙을 넣었는지는 밝히지 않으며, 후대에는 신들이 판도라에게 들려 보낸 상자로 전해졌습니다.","power":"그 안에는 그때까지 인간이 몰랐던 고된 노동과 질병 같은 온갖 재앙이 갇혀 있었습니다.","price":"판도라가 뚜껑을 열자 재앙이 세상에 퍼졌고, 서둘러 닫았을 때는 희망만이 항아리 속에 남았습니다.","source":"헤시오도스 「일과 날」","exhibit_id":"pandora-waterhouse","sort_order":85},{"slug":"psyches-box","name":"프시케의 상자","name_en":"Psyche's Box","kind":"treasure","figure_slugs":["psyche","aphrodite","persephone"],"origin":"아프로디테가 마지막 시련으로 프시케를 저승에 보내며, 페르세포네의 아름다움을 조금 담아 오라고 들려 보낸 상자입니다.","power":"페르세포네가 담아 준 것은 아름다움이 아니라 저승의 깊은 잠이었습니다.","price":"열지 말라는 당부를 어기고 아름다움을 조금 덜어 쓰려 상자를 연 프시케는 그 자리에서 잠에 빠졌고, 에로스가 잠을 다시 상자에 거두어 그녀를 깨웠습니다.","source":"아풀레이우스 「황금 당나귀」","exhibit_id":"psyche-box-waterhouse","sort_order":86},{"slug":"brand-of-meleager","name":"멜레아그로스의 장작","name_en":"Brand of Meleager","kind":"treasure","figure_slugs":["meleager"],"origin":"멜레아그로스가 태어났을 때 운명의 여신들이 화로의 장작이 다 타면 아이가 죽는다고 예언했고, 어머니 알타이아가 곧바로 불을 꺼 숨겨 둔 장작입니다.","power":"장작이 남아 있는 동안 멜레아그로스의 목숨도 이어졌습니다.","price":"칼리돈의 멧돼지 사냥 뒤 멜레아그로스가 상을 두고 다투다 외삼촌들을 죽이자, 알타이아는 장작을 불에 던졌고 멜레아그로스는 멀리서 불에 타는 듯한 고통 속에 숨졌습니다. 알타이아도 뒤에 스스로 목숨을 끊었습니다.","source":"오비디우스 「변신 이야기」, 아폴로도로스 「비블리오테케」","exhibit_id":"meleager-althaea-print","sort_order":87},{"slug":"chariot-of-helios","name":"헬리오스의 태양 수레","name_en":"Chariot of the Sun","kind":"tool","figure_slugs":["helios"],"origin":"헤파이스토스가 만든 황금 수레로, 굴대와 채와 바퀴 테는 금, 바큇살은 은이며 불을 내뿜는 네 마리 말이 끌었다고 합니다(오비디우스).","power":"헬리오스는 날마다 이 수레를 몰아 동쪽에서 서쪽으로 하늘을 가로지르며 세상에 빛을 비춥니다.","price":"아들 파에톤이 하루만 몰게 해 달라고 졸라 수레를 맡았다가 말을 다루지 못해 땅과 하늘을 불태웠고, 제우스의 번개에 맞아 에리다노스강에 떨어져 죽었습니다.","source":"오비디우스 「변신 이야기」","exhibit_id":"helios-phaethon-palace","sort_order":88},{"slug":"apples-of-idunn","name":"이둔의 사과","name_en":"Apples of Iðunn","kind":"treasure","figure_slugs":["idun","loki"],"origin":"젊음의 여신 이둔이 물푸레나무 상자에 담아 지키는 사과입니다.","power":"신들은 늙어 갈 때마다 이 사과를 먹고 다시 젊어져, 라그나로크 때까지 젊음을 지킵니다.","price":"로키가 이둔과 사과를 거인 티아지에게 넘기자 신들은 순식간에 늙어 버렸고, 로키는 매로 변해 이둔을 되찾아 와야 했습니다. 뒤쫓던 티아지는 신들이 피운 불에 타 죽었고, 이 일로 그의 딸 스카디가 복수하러 왔습니다.","source":"「스노리 에다」","exhibit_id":"idun-penrose","sort_order":89},{"slug":"spear-of-lugh","name":"루의 창","name_en":"Spear of Lugh","kind":"weapon","figure_slugs":["lugh"],"origin":"투어허 데 다넌이 북쪽 섬들의 네 도시에서 가져온 네 보물 가운데 하나로, 고리아스에서 온 창입니다.","power":"이 창을 든 이에게 맞서 이긴 싸움은 없었다고 합니다. 후대 이야기에서는 끝이 너무 뜨거워 늘 물을 채운 가마솥에 담가 두어야 하는 창으로도 그려집니다.","price":"후대의 「투렌의 아들들의 운명」에서 루는 아버지 키안을 죽인 투렌의 세 아들에게 보상으로 이런 불타는 창과 여러 보물을 구해 오게 했고, 세 형제는 그 일을 해내다 입은 상처로 모두 목숨을 잃었습니다.","source":"「마그 투이레드의 둘째 전투」, 「투렌의 아들들의 운명」","exhibit_id":"lugh-millar","sort_order":90},{"slug":"rake-of-lemminkainens-mother","name":"레민케이넨 어머니의 갈퀴","name_en":"Rake of Lemminkäinen's Mother","kind":"tool","figure_slugs":["lemminkainen","ilmarinen"],"origin":"아들이 저승 투오넬라의 강에서 죽었다는 것을 안 레민케이넨의 어머니가 대장장이 일마리넨에게 부탁해 만든 구리 갈퀴로, 쇠로 된 이가 백 길이나 되었다고 합니다.","power":"어머니는 이 갈퀴로 투오넬라의 강바닥을 훑어 갈가리 찢긴 아들의 몸을 건져 냈고, 조각을 이어 붙인 뒤 꿀벌이 날라 온 연고로 아들을 되살렸습니다.","price":null,"source":"「칼레발라」 15장","exhibit_id":"lemminkainen-mother","sort_order":91},{"slug":"gusli-of-sadko","name":"사드코의 구슬리","name_en":"Sadko's Gusli","kind":"tool","figure_slugs":["sadko"],"origin":"노브고로드의 가난한 악사 사드코가 연회에서 켜던 현악기로, 무릎에 올려놓고 줄을 뜯는 러시아의 옛 악기입니다.","power":"일멘 호숫가에서 그가 구슬리를 켜자 바다 왕이 나타나 부자가 될 길을 알려 주었고, 바닷속 궁전에서 켰을 때는 바다 왕이 춤을 추어 바다에 폭풍이 일었습니다.","price":"춤이 그치지 않아 배들이 가라앉자, 사드코는 성 니콜라이의 말대로 구슬리 줄을 끊고 나서야 바다 왕의 궁전을 떠날 수 있었습니다.","source":"노브고로드 브일리나 「사드코」","exhibit_id":"sadko-repin","sort_order":92},{"slug":"crossbow-of-william-tell","name":"빌헬름 텔의 석궁","name_en":"William Tell's Crossbow","kind":"weapon","figure_slugs":["william-tell"],"origin":"스위스 우리주의 명사수 빌헬름 텔이 지니던 석궁입니다.","power":"합스부르크의 대관 게슬러가 장대에 건 모자에 절하지 않은 벌로 아들의 머리에 얹은 사과를 쏘게 하자, 텔은 화살 한 발로 사과를 꿰뚫었습니다.","price":"두 번째 화살은 무엇에 쓰려 했느냐는 물음에 첫 화살이 빗나가면 게슬러를 쏘려 했다고 답했다가 붙잡혔고, 배에 실려 끌려가다 폭풍 속에서 탈출한 뒤 퀴스나흐트의 좁은 길에서 이 석궁으로 게슬러를 쏘아 죽였습니다.","source":"「자르넨의 백서」(1470년경), 프리드리히 실러 「빌헬름 텔」","exhibit_id":"william-tell-commons","sort_order":93},{"slug":"crook-and-flail","name":"오시리스의 왕홀과 도리깨","name_en":"Crook and Flail","kind":"treasure","figure_slugs":["osiris"],"origin":"양치기의 갈고리 지팡이(헤카)와 도리깨(네하하)에서 나온 왕권의 상징으로, 저승의 왕 오시리스는 늘 이 둘을 가슴 앞에 엇갈려 쥔 모습으로 그려집니다. 도리깨는 곡식을 터는 도구라는 설과 파리채라는 설이 함께 있습니다.","power":"갈고리는 백성을 양 떼처럼 이끄는 왕의 돌봄을, 도리깨는 땅의 풍요와 왕의 권위를 나타낸다고 풉니다. 파라오들도 오시리스를 잇는 왕임을 보이려고 이 둘을 들었고, 투탕카멘의 무덤에서도 실물이 나왔습니다.","price":null,"source":"「사자의 서」의 오시리스 그림, 투탕카멘 무덤 출토품","exhibit_id":"osiris-crook-flail","sort_order":94},{"slug":"sistrum-of-hathor","name":"하토르의 시스트럼","name_en":"Sistrum of Hathor","kind":"tool","figure_slugs":["hathor","bastet"],"origin":"손잡이 위에 암소 귀를 단 하토르의 얼굴을 새기고, 쇠막대에 금속 고리를 꿴 딸랑이 악기입니다. 사제와 여사제들이 하토르를 섬기는 의식에서 흔들었습니다.","power":"흔들 때 나는 찰랑이는 소리가 하토르를 기쁘게 하고, 플루타르코스에 따르면 세트 같은 악한 힘을 쫓아낸다고 믿었습니다. 고양이 여신 바스테트도 이 악기를 든 모습으로 자주 그려집니다.","price":null,"source":"플루타르코스 「이시스와 오시리스」, 덴데라 신전 부조","exhibit_id":"hathor-sistrum","sort_order":95},{"slug":"tyet","name":"티엣 (이시스의 매듭)","name_en":"Tyet (Knot of Isis)","kind":"ornament","figure_slugs":["isis"],"origin":"옷의 띠를 묶은 매듭처럼 생긴 부적으로, 앙크와 닮았지만 양팔이 아래로 처져 있습니다. 이시스의 피를 뜻한다고 여겨 붉은 벽옥이나 붉은 유리로 많이 만들었습니다.","power":"「사자의 서」 156장은 붉은 벽옥 티엣을 죽은 이의 목에 걸면 이시스의 피와 힘, 마법이 그를 지켜 준다고 적고 있습니다.","price":null,"source":"「사자의 서」 156장","exhibit_id":"isis-tyet","sort_order":96},{"slug":"saw-of-shamash","name":"샤마시의 톱니 칼","name_en":"Saw of Shamash","kind":"weapon","figure_slugs":["shamash"],"origin":"날이 톱니처럼 깔쭉깔쭉한 칼로, 아카드 시대 원통 인장에는 샤마시가 두 산 사이로 솟아오르며 이 칼을 든 모습이 새겨졌습니다.","power":"아침마다 산을 갈라 해가 나올 길을 내는 도구라고도 하고, 옳고 그름을 갈라 판결하는 재판관의 상징이라고도 풉니다.","price":null,"source":"아카드 시대 원통 인장","exhibit_id":"enki-adda-seal","sort_order":97},{"slug":"yagrush-and-ayamur","name":"야그루시와 아이아무르","name_en":"Yagrush and Ayamur","kind":"weapon","figure_slugs":["baal"],"origin":"장인의 신 코타르와하시스가 바다의 신 얌과 싸우는 바알을 위해 만들어 준 두 철퇴로, 이름은 각각 '쫓는 자', '모는 자'라는 뜻입니다.","power":"독수리처럼 바알의 손에서 날아가, 첫째는 얌의 어깨를 쳤지만 쓰러뜨리지 못했고 둘째가 얌의 이마를 쳐서 무너뜨렸습니다.","price":null,"source":"우가리트 「바알 신화」 점토판","exhibit_id":"baal-ugarit","sort_order":98},{"slug":"simurgh-feather","name":"시무르그의 깃털","name_en":"Feather of the Simurgh","kind":"treasure","figure_slugs":["simurgh","zal","rostam"],"origin":"시무르그가 길러 낸 잘을 아버지에게 돌려보내며 건넨 깃털로, 위급할 때 불에 태우면 곧바로 날아오겠다고 약속했습니다.","power":"잘이 깃털을 태우자 시무르그가 나타나 난산에 빠진 루다베의 배를 갈라 루스탐을 꺼내고 깃털로 상처를 쓰다듬어 낫게 하는 법을 일러 주었습니다. 뒤에 에스판디야르와 싸워 다친 루스탐과 락시도 이 깃털로 불러낸 시무르그가 고쳤습니다.","price":"시무르그는 에스판디야르를 쓰러뜨릴 위성류 화살을 알려 주면서, 그를 죽인 이는 이승과 저승에서 불행을 겪으리라고 경고했습니다.","source":"페르도우시 「샤나메」","exhibit_id":"simurgh-rostam-birth","sort_order":99},{"slug":"gavsar-mace","name":"페레이둔의 소머리 철퇴","name_en":"Ox-headed Mace of Fereydun","kind":"weapon","figure_slugs":["fereydun","zahhak"],"origin":"페레이둔이 자하크를 치러 나서기 전, 대장장이들에게 손가락으로 땅에 모양을 그려 보이며 만들게 한 쇠철퇴로, 머리가 소머리 모양입니다.","power":"페레이둔은 자하크의 궁전에 들어가 이 철퇴로 그를 내리쳤습니다. 그러나 천사 소루시가 나타나 아직 죽일 때가 아니라며 다마반드산에 묶어 두라고 일렀습니다.","price":null,"source":"페르도우시 「샤나메」","exhibit_id":"fereydun-gavsar","sort_order":100},{"slug":"babr-e-bayan","name":"바브레 바얀 (루스탐의 호피 갑옷)","name_en":"Babr-e Bayan","kind":"armor","figure_slugs":["rostam"],"origin":"루스탐이 싸움터에 나설 때 갑옷 위에 걸친 짐승 가죽 겉옷으로, 호랑이나 표범 가죽으로 그려집니다. 「샤나메」는 어떻게 얻었는지 밝히지 않으며, 뒤의 민간 서사에서는 루스탐이 바얀이라는 괴물을 잡아 그 가죽으로 지었다고도 합니다.","power":"불에 타지 않고 물에 젖지 않으며 어떤 무기도 뚫지 못한다고 전해, 루스탐은 이 옷을 입고 일곱 시련과 수많은 싸움을 치렀습니다.","price":null,"source":"페르도우시 「샤나메」, 민간 서사 「바브레 바얀」","exhibit_id":"rostam-commons","sort_order":101},{"slug":"kaumodaki","name":"카우모다키","name_en":"Kaumodaki","kind":"weapon","figure_slugs":["vishnu","krishna"],"origin":"비슈누가 네 손 가운데 하나에 든 철퇴입니다. 「마하바라타」에서는 칸다바 숲을 태우려는 불의 신 아그니가 도움을 청하며 크리슈나에게 원반 수다르샤나와 함께 이 철퇴를 주었고, 같은 때 아르주나는 활 간디바를 받았습니다.","power":"던지면 벼락 같은 소리를 내며 악마들을 쳐부순다고 하며, 「비슈누 푸라나」는 이 철퇴가 지성의 힘을 나타낸다고 풉니다. 조각에서는 가다데비라는 여신의 모습으로 비슈누 곁에 서 있기도 합니다.","price":null,"source":"「마하바라타」, 「비슈누 푸라나」","exhibit_id":"vishnu-garuda-met","sort_order":102},{"slug":"panchajanya","name":"판차잔야","name_en":"Panchajanya","kind":"tool","figure_slugs":["krishna","vishnu"],"origin":"크리슈나가 물에 빠져 죽은 스승 산디파니의 아들을 찾아 바다에 들어가, 소라고둥 속에 살던 악마 판차자나를 무찌르고 얻은 소라고둥입니다.","power":"「바가바드 기타」 첫머리에서 크리슈나가 쿠루크셰트라 싸움의 시작을 알리며 이 고둥을 불었고, 그 소리가 적들의 마음을 찢었다고 합니다. 비슈누의 조각과 그림에서는 손에 든 흰 소라고둥으로 나타납니다.","price":null,"source":"「바가바타 푸라나」, 「바가바드 기타」","exhibit_id":"vishnu-garuda-met","sort_order":103},{"slug":"vasavi-shakti","name":"바사비 샤크티","name_en":"Vasavi Shakti","kind":"weapon","figure_slugs":["karna","indra"],"origin":"인드라가 브라만으로 꾸며 카르나에게서 타고난 갑옷과 귀걸이를 얻어 간 뒤, 그 대가로 내준 창입니다.","power":"단 한 번 던지면 누구든 반드시 죽이지만 그 뒤에는 인드라에게 돌아갑니다. 카르나는 아르주나에게 쓰려고 이 창을 아껴 두었습니다.","price":"쿠루크셰트라 싸움의 어느 밤, 비마의 아들 가토트카차가 카우라바 군을 휩쓸자 카르나는 이 창을 그에게 쓸 수밖에 없었고, 아르주나를 쓰러뜨릴 마지막 수단을 잃었습니다.","source":"「마하바라타」","exhibit_id":"karna-shakti","sort_order":104},{"slug":"pushpaka-vimana","name":"푸시파카 비마나","name_en":"Pushpaka Vimana","kind":"tool","figure_slugs":["ravana","rama"],"origin":"신들의 장인 비슈바카르마가 브라흐마를 위해 만든 하늘을 나는 수레로, 브라흐마가 재물의 신 쿠베라에게 주었으나 라바나가 쿠베라를 무찌르고 빼앗았습니다.","power":"주인의 뜻대로 하늘을 날며, 아무리 많은 사람이 타도 늘 한 자리가 남는다고 합니다. 라바나를 무찌른 라마는 이 수레를 타고 시타와 함께 아요디야로 돌아온 뒤 쿠베라에게 돌려주었습니다.","price":null,"source":"발미키 「라마야나」","exhibit_id":"ravana-pushpaka","sort_order":105},{"slug":"pashupatastra","name":"파슈파타스트라","name_en":"Pashupatastra","kind":"weapon","figure_slugs":["arjuna","shiva"],"origin":"아르주나가 히말라야에서 고행할 때, 사냥꾼 모습으로 나타난 시바와 멧돼지 한 마리를 두고 다투어 싸운 뒤 그 용기를 높이 산 시바가 준 무기입니다.","power":"시바의 가장 무서운 무기로 온 세상을 멸할 수 있으며, 마음이나 눈길, 말, 활로 쏠 수 있다고 합니다. 자기보다 약한 적에게 쓰면 세상이 무너진다는 경고와 함께 주어졌습니다.","price":"아르주나는 사냥꾼과 맞서다 화살이 다 떨어지고 활 간디바까지 빼앗긴 채 쓰러지고 나서야 상대가 시바임을 알아보았습니다.","source":"「마하바라타」 숲의 책, 바라비 「키라타르주니야」","exhibit_id":"arjuna-kirata","sort_order":106},{"slug":"noose-of-yama","name":"야마의 올가미","name_en":"Noose of Yama","kind":"tool","figure_slugs":["yama"],"origin":"죽음의 신 야마가 수명이 다한 이의 넋을 묶어 끌고 가는 올가미(파샤)입니다.","power":"「마하바라타」에서 야마는 이 올가미로 사티아반의 몸에서 엄지만 한 넋을 끌어냈습니다. 어린 성자 마르칸데야가 시바의 링가를 끌어안자 야마가 링가째 올가미를 던졌다가, 노한 시바에게 걷어차였다는 이야기도 전합니다.","price":null,"source":"「마하바라타」, 푸라나 문헌","exhibit_id":"yama-buffalo","sort_order":107},{"slug":"gada-of-hanuman","name":"하누만의 철퇴","name_en":"Gada of Hanuman","kind":"weapon","figure_slugs":["hanuman"],"origin":"하누만이 늘 들고 다니는 철퇴(가다)로, 많은 그림과 조각에서 한 손에 이 철퇴를 든 모습으로 나옵니다. 「라마야나」 본문보다는 뒤의 전승과 신앙에서 그의 상징으로 자리 잡았습니다.","power":"힘과 용기, 악을 물리치는 헌신을 나타냅니다. 인도의 전통 씨름 도장(아카라)은 하누만을 수호신으로 모시고, 무거운 철퇴를 휘두르며 몸을 단련합니다.","price":null,"source":"「라마야나」 뒤의 전승, 하누만 신앙","exhibit_id":"hanuman-gada","sort_order":108},{"slug":"aladdin-lamp","name":"알라딘의 램프","name_en":"Aladdin's Lamp","kind":"treasure","figure_slugs":["aladdin"],"origin":"아프리카에서 온 마법사가 알라딘을 시켜 땅속 보물 동굴에서 꺼내 오게 한 낡은 놋쇠 램프입니다. 마법사는 동굴에 들어가는 알라딘에게 반지도 끼워 주었는데, 이 반지에도 정령이 깃들어 있었습니다.","power":"문지르면 거대한 정령이 나타나 주인의 소원을 들어줍니다. 알라딘은 이 힘으로 궁전을 짓고 술탄의 딸 바드르 알부두르와 혼인했으며, 동굴에 갇혔을 때는 반지의 정령에게 도움을 받았습니다.","price":"마법사가 '헌 램프를 새 램프로 바꿔 준다'며 공주에게서 램프를 가로채, 알라딘은 궁전과 아내를 한꺼번에 잃을 뻔했습니다.","source":"「천일야화」 (앙투안 갈랑의 프랑스어 번역본)","exhibit_id":"aladdin-commons","sort_order":109},{"slug":"forty-thieves-treasure","name":"도둑 소굴의 보물","name_en":"Treasure of the Forty Thieves","kind":"treasure","figure_slugs":["ali-baba"],"origin":"마흔 명의 도둑이 바위 동굴에 모아 둔 금은과 비단으로, '열려라 참깨'라는 주문을 외워야 바위 문이 열립니다.","power":"나무꾼 알리바바는 몰래 엿들은 주문으로 동굴에 들어가 금을 가져와 부자가 되었습니다.","price":"욕심 많은 형 카심은 동굴에 들어갔다가 주문을 잊어 갇힌 채 도둑들에게 죽임을 당했고, 알리바바의 집도 도둑들의 노림을 받았지만 하녀 모르지아나가 지혜로 막아 냈습니다.","source":"「천일야화」 (앙투안 갈랑의 프랑스어 번역본)","exhibit_id":"ali-baba-cave-batten","sort_order":110},{"slug":"oshe-shango","name":"오셰 샹고","name_en":"Oshe Shango","kind":"weapon","figure_slugs":["shango"],"origin":"샹고를 섬기는 이들이 의식에서 드는 나무 지팡이로, 머리에 양날 도끼 모양이 달려 있습니다. 이 도끼는 샹고가 하늘에서 던진다는 벼락돌(에둔 아라)을 나타냅니다.","power":"샹고는 이 도끼로 벼락을 내려 거짓말쟁이와 도둑을 벌한다고 여기며, 사제들은 이 지팡이를 들고 춤추며 샹고의 힘을 불러옵니다.","price":"오요의 왕이던 샹고가 번개를 부르는 힘을 시험하다 자기 궁전을 불태우고 가족을 잃었다는 전승도 있습니다.","source":"요루바 구전 전승","exhibit_id":"shango-yoruba","sort_order":111},{"slug":"opon-ifa","name":"오폰 이파 (이파 점판)","name_en":"Opon Ifa","kind":"tool","figure_slugs":["orunmila","eshu"],"origin":"이파 점술사(바발라워)가 점을 칠 때 쓰는 둥근 나무 쟁반으로, 가장자리 위쪽에는 늘 전령의 신 에슈의 얼굴을 새깁니다.","power":"쟁반에 나무 가루를 뿌리고 야자 열매를 던져 나온 표시를 그어, 지혜의 신 오룬밀라가 전한 256가지 시가(오두) 가운데 하나를 찾아 신들의 뜻을 읽습니다.","price":null,"source":"요루바 이파 점술 시가","exhibit_id":"orunmila-ifa","sort_order":112},{"slug":"jingu-er","name":"긴고아","name_en":"Golden Headband","kind":"ornament","figure_slugs":["sun-wukong"],"origin":"석가여래가 관음보살에게 준 세 개의 테 가운데 하나로, 관음보살은 이것을 꽃 모자 속에 감춰 삼장법사에게 주었습니다. 손오공이 모자를 쓰자 테가 머리에 뿌리내리듯 박혀 빠지지 않았습니다.","power":"삼장법사가 긴고아주를 외면 테가 조여 손오공이 땅을 구를 만큼 머리가 아팠습니다. 성미 급한 손오공을 다스리는 고삐 구실을 했으며, 나머지 두 테는 홍해아와 흑풍산의 곰 요괴에게 씌워졌습니다.","price":"손오공은 삼장법사를 떠나고 싶어도 떠날 수 없었습니다. 여정을 마치고 투전승불이 된 뒤에야 테는 저절로 사라졌습니다.","source":"「서유기」","exhibit_id":"sun-wukong-commons","sort_order":113},{"slug":"nine-toothed-rake","name":"구치정파","name_en":"Nine-toothed Rake","kind":"weapon","figure_slugs":["zhu-bajie"],"origin":"저팔계의 말에 따르면 태상노군이 직접 망치를 들고 신령한 쇠를 두드려 만든 쇠스랑으로, 옥황상제가 그를 천봉원수로 삼으며 손수 내려 주었습니다.","power":"쇠 이빨 아홉 개가 달려 한 번 내려치면 구멍 아홉 개가 났고, 저팔계는 이것으로 서천 길의 수많은 요괴와 싸웠습니다. 가시덤불을 걷어 내 막힌 길을 트는 데도 썼습니다.","price":null,"source":"「서유기」","exhibit_id":"zhu-bajie-xiyouji","sort_order":114},{"slug":"south-pointing-chariot","name":"지남거","name_en":"South-pointing Chariot","kind":"tool","figure_slugs":["yellow-emperor","chiyou"],"origin":"진나라 최표의 「고금주」에 따르면 황제가 탁록 들판에서 치우와 싸울 때 만들었습니다. 역사 속의 지남거는 자석이 아니라 톱니바퀴로 방향을 지키는 수레로, 삼국 시대 위나라의 마균 등이 다시 만들었습니다.","power":"수레가 어느 쪽으로 돌든 수레 위 나무 인형의 손이 늘 남쪽을 가리켰습니다. 치우가 일으킨 짙은 안개 속에서 길을 잃은 황제의 군사들은 이 수레를 따라 방향을 찾았습니다.","price":null,"source":"「고금주」, 「송서」","exhibit_id":"chariot-nordenskiold","sort_order":115},{"slug":"xirang","name":"식양","name_en":"Xirang","kind":"treasure","figure_slugs":["yu-the-great"],"origin":"천제가 간직한 흙으로, 스스로 끝없이 불어나는 성질이 있었습니다. 우의 아버지 곤이 천제의 허락 없이 이 흙을 훔쳐 홍수를 막으려 했습니다.","power":"조금만 뿌려도 저절로 자라나 둑과 산이 되어 물을 막았습니다. 「회남자」에는 우가 이 흙으로 홍수를 메워 이름난 산들을 만들었다고 합니다.","price":"명을 기다리지 않고 흙을 훔친 곤은 천제의 명을 받은 불의 신 축융에게 우산(羽山) 들판에서 죽임을 당했습니다.","source":"「산해경」, 「회남자」","exhibit_id":"yu-ma-lin","sort_order":116},{"slug":"nine-tripods","name":"구정","name_en":"Nine Tripod Cauldrons","kind":"treasure","figure_slugs":["yu-the-great"],"origin":"「춘추좌씨전」에 따르면 하나라가 덕이 있을 때 아홉 주의 우두머리들이 바친 쇠로 아홉 개의 솥을 부어 만들고, 먼 곳의 온갖 사물을 새겼습니다. 후대에는 우 임금이 만들었다고 이야기합니다.","power":"솥에 새긴 그림으로 백성이 산과 물에서 만나는 요괴들을 미리 알아 피할 수 있었습니다. 솥은 하늘의 뜻을 받은 왕조를 따라 하나라에서 상나라, 주나라로 옮겨 가며 천하를 다스리는 권리의 상징이 되었습니다.","price":"초나라 장왕이 솥의 크기와 무게를 묻자 주나라의 왕손만은 천하는 덕에 달렸지 솥에 달리지 않았다고 답했습니다. 진시황은 사수에 가라앉은 솥을 건지려고 천 명을 물에 들여보냈으나 찾지 못했다고 「사기」에 전합니다.","source":"「춘추좌씨전」, 「사기」","exhibit_id":"yu-ma-lin","sort_order":117},{"slug":"three-pointed-blade","name":"삼첨양인도","name_en":"Three-pointed Double-edged Blade","kind":"weapon","figure_slugs":["erlang-shen"],"origin":"이랑신이 쓰는 긴 자루의 칼로, 끝이 세 갈래로 갈라지고 양쪽에 날이 서 있습니다. 「봉신연의」의 양전도 같은 칼을 듭니다.","power":"「서유기」에서 이랑신은 이 칼로 여의봉을 휘두르는 손오공과 300합 넘게 맞붙어 승부를 가리지 못할 만큼 팽팽히 싸웠습니다.","price":null,"source":"「서유기」, 「봉신연의」","exhibit_id":"erlang-shen-opera","sort_order":118},{"slug":"ochre-whip","name":"자편","name_en":"Ochre Whip of Shennong","kind":"tool","figure_slugs":["shennong"],"origin":"신농이 지녔다는 붉은 갈색의 채찍입니다.","power":"동진의 간보가 엮은 「수신기」에 따르면 신농은 이 채찍으로 온갖 풀을 쳐서 독이 있는지 없는지, 성질이 찬지 더운지를 모두 알아냈고, 이를 바탕으로 백성에게 곡식을 심게 했습니다.","price":"민간에서는 풀을 직접 맛보던 신농이 끝내 단장초를 먹고 목숨을 잃었다는 이야기도 전합니다.","source":"「수신기」","exhibit_id":"shennong-shoryo","sort_order":119},{"slug":"dashen-bian","name":"타신편","name_en":"Dashen Bian","kind":"weapon","figure_slugs":["jiang-ziya"],"origin":"원시천존이 제자 강태공에게 내린 채찍으로, 길이는 석 자 여섯 치 다섯 푼이고 스물한 마디마다 부적이 넷씩, 모두 여든네 개 새겨져 있습니다.","power":"봉신방에 이름이 오를 신들만 칠 수 있었고, 신선이나 사람에게는 쓸 수 없었습니다. 강태공은 이 채찍으로 상나라 편에 선 장수들을 쓰러뜨렸습니다.","price":null,"source":"「봉신연의」","exhibit_id":"jiang-ziya-commons","sort_order":120},{"slug":"totsuka-no-tsurugi","name":"도쓰카노쓰루기","name_en":"Totsuka no Tsurugi","kind":"weapon","figure_slugs":["susanoo","yamata-no-orochi"],"origin":"'주먹 열 개 길이의 칼'이라는 뜻의 긴 칼로, 「고사기」에서 스사노오가 야마타노오로치를 벨 때 쓴 칼입니다. 이자나기가 불의 신 가구쓰치를 벤 칼도 같은 이름으로 불립니다.","power":"스사노오는 술에 취해 잠든 오로치를 이 칼로 토막 내어 물리쳤습니다. 「일본서기」에서는 이 칼을 오로치노아라마사라고도 부르며, 이소노카미에 모셨다고 전합니다.","price":"가운데 꼬리를 벨 때 칼날이 이가 빠졌는데, 그 속에서 더 단단한 구사나기의 검이 나왔습니다.","source":"「고사기」, 「일본서기」","exhibit_id":"orochi-kiyomasu","sort_order":121},{"slug":"higekiri","name":"히게키리","name_en":"Higekiri","kind":"weapon","figure_slugs":["watanabe-no-tsuna","minamoto-no-raiko","ibaraki-doji"],"origin":"「헤이케 이야기」 「검의 권」에 따르면 미나모토노 미쓰나카가 만들게 한 두 자루 칼 가운데 하나로, 죄인을 시험 삼아 베었을 때 수염까지 잘렸다 하여 히게키리(수염 베기)라 불렸습니다. 다른 한 자루는 무릎까지 잘렸다 하여 히자마루라 했습니다.","power":"미나모토노 라이코가 물려받은 뒤 와타나베노 쓰나가 이 칼로 오니의 팔을 베어 떨어뜨렸고, 그 뒤 오니키리마루(오니 베기)로 이름을 바꿨습니다. 교토 기타노텐만구에 이 칼로 전하는 칼이 있습니다.","price":"팔을 잃은 오니는 쓰나의 양어머니로 꾸며 찾아와 팔을 되찾아 날아갔다고 합니다. 훗날 이 오니를 이바라키도지로 보는 이야기가 퍼졌습니다.","source":"「헤이케 이야기」 「검의 권」, 노 「라쇼몬」","exhibit_id":"watanabe-no-tsuna-commons","sort_order":122},{"slug":"dojigiri-yasutsuna","name":"도지기리 야스쓰나","name_en":"Dōjigiri Yasutsuna","kind":"weapon","figure_slugs":["minamoto-no-raiko","shuten-doji"],"origin":"헤이안 시대 호키국의 도공 야스쓰나가 만든 칼로, 일본의 이름난 칼 다섯 자루를 이르는 '천하오검'의 하나입니다. 지금은 도쿄 국립박물관에 국보로 전합니다.","power":"미나모토노 라이코가 오에산에서 술에 취한 슈텐도지의 목을 이 칼로 베었다고 하여 '동자 베기(도지기리)'라는 이름이 붙었습니다.","price":"라이코 일행은 산속 수행자로 꾸미고 신들이 내린 독주를 먹여 슈텐도지를 속였는데, 잘린 슈텐도지의 머리가 날아올라 라이코의 투구를 물었다고 합니다.","source":"「오토기조시」 「슈텐도지」","exhibit_id":"minamoto-no-raiko-commons","sort_order":123},{"slug":"ryugu-rice-bale-and-bell","name":"용궁의 쌀가마와 종","name_en":"Rice Bale and Bell of the Dragon Palace","kind":"treasure","figure_slugs":["tawara-toda"],"origin":"다와라 도타가 비와호 용신의 부탁을 받고 미카미산의 큰 지네를 활로 쏘아 죽이자, 용신이 답례로 준 보물들입니다.","power":"아무리 퍼내도 쌀이 줄지 않는 쌀가마와 끊임없이 풀려 나오는 비단 두루마리 같은 보물이 있었고, 쌀가마 덕분에 그를 다와라(쌀가마) 도타라고 불렀다는 이야기도 있습니다. 용궁에 초대받아 받은 구리 종은 미이데라(온조지)에 바쳤습니다.","price":null,"source":"「태평기」, 「다와라 도타 이야기」","exhibit_id":"tawara-toda-ryugu","sort_order":124},{"slug":"tamatebako","name":"다마테바코","name_en":"Tamatebako","kind":"treasure","figure_slugs":["urashima-taro"],"origin":"용궁의 오토히메가 고향으로 돌아가는 우라시마 다로에게 절대 열지 말라며 건넨 보석 상자입니다. 8세기의 「단고국 풍토기」 일문과 「만엽집」의 노래에도 같은 상자가 나옵니다.","power":"상자를 여는 순간 흰 연기가 피어올라, 용궁에서 멈춰 있던 세월이 한꺼번에 그를 덮쳤습니다.","price":"고향에 아는 사람이 아무도 없자 상자를 열어 버린 우라시마는 한순간에 백발노인이 되었습니다. 학이 되어 날아갔다는 판본도 있습니다.","source":"「단고국 풍토기」 일문, 「만엽집」, 「오토기조시」","exhibit_id":"urashima-yoshitoshi","sort_order":125},{"slug":"hanasaka-ashes","name":"꽃 피우는 재","name_en":"Ashes of Hanasaka Jiisan","kind":"treasure","figure_slugs":["hanasaka-jiisan"],"origin":"착한 할아버지의 개 시로가 묻힌 자리에서 자란 나무로 절구를 만들었는데, 욕심 많은 이웃 노인이 그 절구를 태워 버리고 남은 재입니다.","power":"할아버지가 이 재를 마른 나무에 뿌리자 순식간에 꽃이 활짝 피었고, 지나가던 영주가 크게 기뻐하며 상을 내렸습니다.","price":"흉내를 내어 재를 뿌린 이웃 노인은 꽃을 피우지 못하고 재가 영주의 눈에 들어가 벌을 받았습니다.","source":"일본 옛이야기 「꽃 피우는 할아버지」","exhibit_id":"hanasaka-jiisan-commons","sort_order":126},{"slug":"uchide-no-kozuchi","name":"우치데노코즈치","name_en":"Uchide no Kozuchi","kind":"tool","figure_slugs":["daikokuten"],"origin":"흔들면 바라는 것이 무엇이든 나온다는 요술 망치로, 다이코쿠텐이 늘 손에 들고 있습니다. 옛이야기 「잇슨보시」에서는 오니가 떨어뜨리고 달아난 보물로 나옵니다.","power":"잇슨보시는 이 망치를 흔들어 엄지만 하던 몸을 보통 사람만큼 키웠습니다. 다이코쿠텐의 망치는 복과 재물을 두드려 내는 상징으로 여겨집니다.","price":null,"source":"「오토기조시」 「잇슨보시」","exhibit_id":"daikokuten-mallet","sort_order":127},{"slug":"ikutachi-ikuyumiya","name":"이쿠타치와 이쿠유미야","name_en":"Ikutachi and Ikuyumiya","kind":"weapon","figure_slugs":["okuninushi","susanoo"],"origin":"네노쿠니를 다스리던 스사노오의 칼과 활, 화살로, 오나무지가 스사노오의 딸 스세리비메를 업고 달아날 때 거문고 아메노노리고토와 함께 가지고 나왔습니다.","power":"'살아 있는 칼, 살아 있는 활'이라는 이름처럼 생명의 힘이 깃든 무기로 여겨집니다. 뒤쫓던 스사노오는 저승 비탈에서 이 칼과 활로 형제들을 쫓아내고 오쿠니누시가 되라고 외쳤고, 그는 그 말대로 나라의 주인이 되었습니다.","price":"달아날 때 거문고가 나무에 스쳐 땅이 울리는 바람에 잠든 스사노오가 깨어났고, 서까래에 머리카락이 묶여 있던 스사노오는 집을 무너뜨리며 뒤쫓아왔습니다.","source":"「고사기」","exhibit_id":"okuninushi-gakutei","sort_order":128},{"slug":"golden-staff-of-manco-capac","name":"망코 카팍의 황금 지팡이","name_en":"Golden Staff of Manco Cápac","kind":"tool","figure_slugs":["manco-capac","mama-ocllo"],"origin":"해의 신이 아들 망코 카팍과 딸 마마 오클료를 티티카카호로 내려보내며 준, 손가락 두 개 굵기의 황금 막대입니다.","power":"두 사람은 가는 곳마다 막대를 땅에 꽂아 보고, 단번에 땅속 깊이 들어가는 곳에 도읍을 세우라는 명을 받았습니다. 막대가 우아나카우리 언덕에서 땅속으로 사라지자 그 아래 골짜기에 쿠스코를 세웠습니다.","price":null,"source":"잉카 가르실라소 데 라 베가 「잉카 왕실사」","exhibit_id":"manco-capac-murua","sort_order":129},{"slug":"manaiakalani","name":"마나이아칼라니","name_en":"Mānaiakalani","kind":"tool","figure_slugs":["maui","hina"],"origin":"하와이 전승에서 마우이가 지닌 요술 낚싯바늘의 이름으로, 어머니 히나가 아끼던 새 알라에의 날개를 미끼로 꿰었다고 합니다. 마오리 전승에서는 할머니의 턱뼈로 만든 낚싯바늘로 바다에서 땅을 낚았다고 합니다.","power":"마우이는 이 바늘을 바다 밑에 걸고 형들에게 큰 물고기가 걸렸다며 힘껏 노를 젓게 해 하와이의 섬들을 끌어 올렸습니다.","price":"섬들을 하나로 이으려던 마지막 낚시에서 형들이 뒤돌아보지 말라는 당부를 어기자 낚싯줄이 끊어져, 섬들은 지금처럼 떨어진 채로 남았습니다.","source":"하와이 전승","exhibit_id":"maui-dittmer","sort_order":130},{"slug":"cauldron-of-the-dagda","name":"다그다의 가마솥","name_en":"The Dagda's Cauldron","kind":"treasure","figure_slugs":["dagda"],"origin":"투어허 데 다넌이 아일랜드로 오기 전 북쪽 섬들의 네 도시에서 지식을 배우고 가져온 네 보물 가운데 하나로, 무리아스에서 온 가마솥입니다.","power":"아무리 많은 무리가 먹어도 배부르지 않은 채 떠나는 이가 없었다고 합니다.","price":null,"source":"「마그 투이레드의 둘째 전투」","exhibit_id":null,"sort_order":131},{"slug":"harp-of-the-dagda","name":"다그다의 하프","name_en":"The Dagda's Harp","kind":"tool","figure_slugs":["dagda","lugh"],"origin":"다그다가 지닌 하프로, 그가 부르면 스스로 날아왔다고 합니다. 포모르족과의 싸움 뒤 포모르족이 이 하프를 가지고 달아났습니다.","power":"다그다와 루, 오그마가 포모르족의 연회장을 찾아가자 벽에 걸려 있던 하프가 다그다의 부름에 날아오며 그 자리의 아홉 사람을 쓰러뜨렸습니다. 다그다는 이 하프로 슬픔의 노래와 웃음의 노래, 잠의 노래를 차례로 연주해 포모르족을 잠재우고 빠져나왔습니다.","price":null,"source":"「마그 투이레드의 둘째 전투」","exhibit_id":"dagda-trinity-harp","sort_order":132},{"slug":"sword-of-nuada","name":"누아다의 칼","name_en":"Sword of Nuada","kind":"weapon","figure_slugs":["nuada"],"origin":"투어허 데 다넌의 네 보물 가운데 하나로, 핀디아스에서 가져온 칼입니다. 후대 민담의 '빛의 칼'(클라우 솔러시)과 이어 보기도 합니다.","power":"칼집에서 뽑히면 그 칼을 피해 달아난 이가 없었고, 맞서 견딜 수 있는 이도 없었다고 합니다.","price":null,"source":"「마그 투이레드의 둘째 전투」","exhibit_id":"nuada-celtic-sword","sort_order":133},{"slug":"lia-fail","name":"리아 팔 (운명의 돌)","name_en":"Lia Fáil","kind":"treasure","figure_slugs":["lugh","cuchulainn"],"origin":"투어허 데 다넌의 네 보물 가운데 하나로, 팔리아스에서 가져온 돌입니다. 아일랜드 왕들이 즉위하던 타라 언덕에 놓였다고 하며, 지금도 타라에는 이 이름으로 불리는 선돌이 서 있습니다.","power":"참된 왕이 위에 서면 돌이 소리를 질러 그를 알렸다고 합니다. 「환영의 예언」에서는 콘 왕이 이 돌을 밟자 돌이 외쳤고, 안개 속에서 나타난 루가 그 뒤를 이을 왕들을 일러 주었습니다.","price":"한 전승에서는 쿠 훌린이 자신이 아끼던 루가이드가 위에 섰는데도 돌이 외치지 않자 화가 나 칼로 쪼개 버렸고, 그 뒤로 돌은 콘 왕 때 말고는 다시 외치지 않았다고 합니다.","source":"「마그 투이레드의 둘째 전투」, 「환영의 예언」","exhibit_id":"lugh-coronation-chair","sort_order":134},{"slug":"golden-hair-of-sif","name":"시프의 황금 머리카락","name_en":"Sif's Golden Hair","kind":"ornament","figure_slugs":["sif","loki"],"origin":"로키가 시프의 머리카락을 모두 잘라 버린 뒤, 토르의 노여움을 피하려고 이발디의 아들들인 드베르그에게 만들게 한 황금 머리카락입니다.","power":"머리에 대기만 하면 뿌리를 내려 진짜 머리카락처럼 자랐다고 합니다.","price":"이 일로 시작된 보물 내기에서 로키는 드베르그 브로크에게 자기 머리를 걸었다가 졌고, 목까지는 내줄 수 없다고 버틴 끝에 입술을 꿰매이고 말았습니다.","source":"「스노리 에다」 시어법","exhibit_id":"sif-dollman","sort_order":135},{"slug":"skidbladnir","name":"스키드블라드니르","name_en":"Skíðblaðnir","kind":"tool","figure_slugs":["freyr","loki"],"origin":"시프의 머리카락을 만든 이발디의 아들들이 함께 만들어 프레이르에게 준 배입니다.","power":"모든 신이 무기와 갑옷을 갖추고 타도 될 만큼 크지만, 쓰지 않을 때는 천처럼 접어 주머니에 넣을 수 있고, 돛을 올리면 어디로 가든 늘 순풍이 붑니다.","price":null,"source":"「스노리 에다」 길피의 속임, 시어법","exhibit_id":"freyr-gokstad-ship","sort_order":136},{"slug":"megingjord","name":"메긴교르드와 야른그레이프르","name_en":"Megingjörð and Járngreipr","kind":"ornament","figure_slugs":["thor"],"origin":"토르가 지닌 힘의 허리띠와 쇠장갑으로, 망치 묠니르와 함께 그의 세 보물로 꼽힙니다.","power":"허리띠를 매면 신의 힘이 두 배가 되고, 쇠장갑을 껴야 손잡이가 짧은 묠니르를 쥘 수 있었다고 합니다.","price":"거인 게이르뢰드에게 갈 때 토르는 망치도 허리띠도 없이 떠났다가, 여자 거인 그리드에게서 다른 힘의 허리띠와 쇠장갑, 지팡이를 빌려야 했습니다.","source":"「스노리 에다」 길피의 속임, 시어법","exhibit_id":"thor-sam66","sort_order":137},{"slug":"sharur","name":"샤루르","name_en":"Sharur","kind":"weapon","figure_slugs":["ninurta"],"origin":"닌우르타가 지닌 철퇴로, 이름은 '수많은 것을 쳐부수는 것'이라는 뜻으로 풉니다.","power":"스스로 말을 하고 날아다니며, 적의 동태를 살펴 닌우르타에게 알리고 싸울 방법을 일러 주었습니다. 「루갈에」에서는 돌 괴물 아사그가 일어났다는 소식을 닌우르타에게 전하고 맞서 싸우라고 부추깁니다.","price":null,"source":"수메르 시 「루갈에」, 「안주 이야기」","exhibit_id":"ninurta-bull-mace-head","sort_order":138},{"slug":"divine-crossbow","name":"신기 쇠뇌","name_en":"Divine Crossbow of Âu Lạc","kind":"weapon","figure_slugs":["an-duong-vuong","kim-quy"],"origin":"금거북 낌꾸이가 꼬로아 성이 완성된 뒤 남긴 발톱을 신하 까오로가 방아쇠로 삼아 만든 쇠뇌입니다.","power":"한 번 쏘면 수많은 적군이 쓰러졌고, 남월의 조타는 이 쇠뇌 앞에서 번번이 물러났습니다.","price":"조타의 아들 쫑투이가 왕의 딸 미쩌우와 혼인한 뒤 몰래 발톱을 바꿔치기해 쇠뇌는 힘을 잃었고, 어울락은 무너졌습니다. 안즈엉 왕은 딸을 벤 뒤 바다로 걸어 들어갔다고 합니다.","source":"「영남척괴」, 「대월사기전서」","exhibit_id":"an-duong-vuong-crossbow-trigger","sort_order":139},{"slug":"blowgun-of-the-hero-twins","name":"쌍둥이 영웅의 바람총","name_en":"Blowgun of the Hero Twins","kind":"weapon","figure_slugs":["hero-twins","vucub-caquix"],"origin":"「포폴 부」의 쌍둥이 영웅 우나푸와 슈발랑케가 사냥에 쓰던 바람총입니다.","power":"쌍둥이는 이 바람총으로 나무 위에서 열매를 먹던 부쿱 카킥스의 턱을 맞혀 떨어뜨렸습니다.","price":"저승 시발바의 박쥐의 집에서 쌍둥이는 바람총 속에 숨어 밤을 났는데, 날이 밝았는지 보려고 고개를 내민 우나푸의 머리를 박쥐 카마소츠가 베어 갔습니다.","source":"「포폴 부」","exhibit_id":null,"sort_order":140},{"slug":"manpasikjeok","name":"만파식적","name_en":"Manpasikjeok","kind":"tool","figure_slugs":["munmu"],"origin":"「삼국유사」에 따르면 682년 신문왕이 동해에 떠 온 작은 산에서 얻은 대나무로 만든 피리입니다. 바다의 용이 된 문무왕과 하늘의 신이 된 김유신이 함께 보낸 것이라고 했습니다.","power":"불면 적군이 물러가고 병이 나으며, 가뭄에는 비가 오고 장마에는 날이 개며, 바람이 자고 물결이 잔잔해졌다고 합니다. 그래서 '온갖 물결을 잠재우는 피리'라는 이름이 붙었습니다.","price":null,"source":"「삼국유사」 만파식적 조","exhibit_id":"munmu-danwon-mudong","sort_order":141},{"slug":"jamyeonggo","name":"자명고","name_en":"Jamyeonggo","kind":"tool","figure_slugs":["nangnang-princess","hodong"],"origin":"낙랑에 있었다는 북과 나팔로, 「삼국사기」는 적병이 오면 저절로 울렸다고만 적었습니다.","power":"적이 쳐들어오면 저절로 울려 나라에 알렸기에, 고구려는 낙랑을 쉽게 치지 못했습니다.","price":"고구려 왕자 호동의 부탁으로 낙랑공주가 북을 찢고 나팔을 부수자 고구려 군대가 성 밑까지 들이닥쳤고, 낙랑의 왕 최리는 딸을 죽인 뒤 항복했습니다.","source":"「삼국사기」 고구려본기 대무신왕 15년","exhibit_id":"nangnang-buk-drum","sort_order":142},{"slug":"tizona-and-colada","name":"티소나와 콜라다","name_en":"Tizona and Colada","kind":"weapon","figure_slugs":["el-cid"],"origin":"「엘 시드의 노래」에서 엘 시드가 싸움에서 얻은 두 칼로, 콜라다는 바르셀로나 백작에게서, 티소나는 발렌시아를 치러 온 모로코의 왕 부카르에게서 얻었습니다.","power":"두 칼은 엘 시드의 손에서 수많은 적을 쓰러뜨려, 그 이름만으로도 적이 두려워했다고 합니다.","price":"엘 시드는 두 칼을 사위가 된 카리온의 왕자들에게 주었지만, 그들은 겁쟁이라는 놀림을 받자 앙심을 품고 엘 시드의 딸들을 숲에 버렸습니다. 엘 시드는 왕의 재판에서 두 칼을 돌려받고 결투로 명예를 되찾았습니다.","source":"「엘 시드의 노래」","exhibit_id":"el-cid-sword-hilts","sort_order":143},{"slug":"was","name":"와스 홀","name_en":"Was-sceptre","kind":"treasure","figure_slugs":["set","anubis","khnum"],"origin":"고대 이집트의 신과 파라오, 사제가 쥐던 긴 홀입니다. 이름은 이집트 말로 '힘'을 뜻하며, 제1왕조 때의 것부터 남아 있습니다.","power":"힘과 다스림을 나타내고, 뒤에는 세트가 몰고 오는 혼돈을 다스리는 힘의 표지가 되었습니다. 죽은 이의 안녕을 지키는 부적으로 무덤에도 넣었고, 하늘을 떠받치는 기둥을 이 모양으로 그리기도 했습니다.","price":null,"source":"고대 이집트의 무덤·신전 그림(투트모세 3세·호렘헤브의 무덤 등)과 상형 문자","exhibit_id":"was-scepter-met","sort_order":144},{"slug":"galatine","name":"갈라틴","name_en":"Galatine","kind":"weapon","figure_slugs":["gawain"],"origin":"토머스 맬러리의 「아서왕의 죽음」(15세기)이 로마 원정 대목에서 가웨인의 칼을 부르는 이름입니다. 앞선 「두운시 아서왕의 죽음」에서는 갈루스라고 불렸습니다.","power":"칼 자체의 힘은 전하지 않지만, 「아서왕의 죽음」에서 가웨인은 해가 높이 뜰수록 힘이 세져 한낮에는 누구도 당해 내지 못했다고 합니다.","price":null,"source":"토머스 맬러리 「아서왕의 죽음」, 「두운시 아서왕의 죽음」","exhibit_id":null,"sort_order":145},{"slug":"arondight","name":"아론다이트","name_en":"Arondight","kind":"weapon","figure_slugs":["lancelot"],"origin":"14세기 영국 로맨스 「햄턴의 베비스」의 한 필사본에 덧붙은 대목에서, 기사 가이가 런던의 러드게이트에서 '한때 호수의 기사 랜슬롯의 것이었던' 검 아라운다이트를 들고 싸웁니다.","power":"원전은 랜슬롯이 지녔던 검이라는 내력만 적었고, 생김새나 힘은 전하지 않습니다.","price":null,"source":"「햄턴의 베비스」(14세기 중세 영어 로맨스)의 덧붙은 대목","exhibit_id":"lancelot-commons","sort_order":146},{"slug":"gae-dearg","name":"게 데아그","name_en":"Gáe Dearg","kind":"weapon","figure_slugs":["diarmuid"],"origin":"피아나 전설의 영웅 디어무드가 지닌 붉은 창입니다. 그는 노란 창 게 부이와, 바다의 신 마나난이 앵거스 오그를 거쳐 준 두 칼 모랄타흐(큰 분노)와 베갈타흐(작은 분노)도 지녔습니다.","power":"이 창들에 입은 상처는 낫지 않는다고 합니다. 디어무드는 날아다니는 수련 잎 위에서 독을 바른 작은 창을 던지던 핀의 늙은 유모 보드말을 게 데아그로 쓰러뜨렸습니다.","price":"벤 굴번의 멧돼지 사냥에 디어무드는 가장 좋은 무기 대신 작은 칼 베갈타흐와 노란 창 게 부이만 가져갔다가 멧돼지에게 받혀 쓰러졌습니다. 핀은 상처를 낫게 하는 물을 두 번 손가락 사이로 흘려 버렸고, 세 번째로 떠 왔을 때는 이미 늦었습니다.","source":"「디어무드와 그라냐의 추격」 등 피아나 전설","exhibit_id":null,"sort_order":147},{"slug":"caladbolg","name":"칼라드볼그","name_en":"Caladbolg","kind":"weapon","figure_slugs":["fergus"],"origin":"「쿨리의 소 습격」에서 퍼거스 막 로이가 지닌 칼로, 이름은 '단단한 칼날'로 풀이됩니다. 후대의 「핀의 노래집」은 쿠 훌린이 이 칼을 퍼거스에게 주었다고 합니다.","power":"치려고 휘두르면 허공에서 무지개만큼 커졌다고 합니다. 마지막 싸움에서 콘코바르를 베려다 코르막에게 말려지자, 퍼거스는 대신 언덕 셋의 꼭대기를 베어 냈습니다.","price":"퍼거스가 메이브와 함께 있는 사이 알릴이 칼을 훔쳐 갔고(알릴의 마부가 훔쳤다는 이야기도 있습니다), 퍼거스는 나무로 깎은 칼을 칼집에 넣어 잃은 것을 숨겼습니다. 알릴은 마지막 싸움을 앞두고서야 칼을 돌려주었습니다.","source":"「쿨리의 소 습격」(얼스터 이야기), 「핀의 노래집」","exhibit_id":null,"sort_order":148},{"slug":"arash-arrow","name":"아라시의 화살","name_en":"Arrow of Arash","kind":"weapon","figure_slugs":["arash"],"origin":"이란과 투란이 왕의 영광을 두고 싸우다 화해할 때, 투란의 아프라시아브와 이란의 마누체르는 화살이 닿는 곳까지를 이란의 땅으로 삼기로 했습니다. 천사의 가르침대로 만든 활과 화살로 아라시가 새벽에 시위를 당겼습니다.","power":"화살은 천 파르상(마흔 날 걸음)을 날았다고 하며, 떨어진 곳은 옥수스강이나 메르브, 발흐의 강 등 문헌마다 다릅니다. 「아베스타」는 그를 '빠른 화살의 에레크샤'라고 부릅니다.","price":"아라시는 자기 목숨을 화살에 실어 쏘았기에, 발아미 등은 시위를 놓은 그의 몸이 부서져 사라졌다고 전합니다. 타바리는 그가 활잡이의 우두머리가 되어 영예를 누렸다고 적었습니다.","source":"「아베스타」 야슈트 8장, 타바리 「예언자들과 왕들의 역사」, 발아미, 알비루니","exhibit_id":null,"sort_order":149},{"slug":"kinto-un","name":"근두운","name_en":"Somersault Cloud","kind":"tool","figure_slugs":["sun-wukong"],"origin":"「서유기」에서 손오공이 스승 수보리조사에게 배운 재주입니다. 스승은 재주를 남 앞에서 뽐내지 말고 스승의 이름도 밝히지 말라며 그를 내보냈습니다.","power":"구름을 타고 한 번 공중제비를 돌면 십만 팔천 리를 날아갑니다.","price":"하늘에서 소란을 피운 손오공은 석가여래의 손바닥을 벗어나 보라는 내기에 근두운을 타고 하늘 끝의 기둥까지 날아갔지만, 그것은 여래의 손가락이었습니다. 그는 오행산 아래에 오백 년 동안 갇혔습니다.","source":"오승은 「서유기」 2회·7회","exhibit_id":"sun-wukong-commons","sort_order":150},{"slug":"yeouiju","name":"여의주","name_en":"Cintamani (Wish-fulfilling Jewel)","kind":"treasure","figure_slugs":["munmu","cheoyong"],"origin":"산스크리트어로 '생각대로 되는 보석'이라는 뜻의 친타마니로, 힌두교와 대승 불교의 문헌에 나오는 구슬입니다. 인도 신화에서는 뱀의 왕 나가와 바다 짐승 마카라가 지니고, 동아시아에서는 용의 구슬로 전합니다.","power":"병을 고치고 물을 맑게 하며, 옷과 먹을 것과 보물을 내어 준다고 합니다. 관세음보살과 지장보살이 손에 들고, 동아시아에서는 이무기가 용이 되려면 꼭 얻어야 하는 구슬로 여겨졌습니다.","price":null,"source":"「바가바타 푸라나」 등 힌두교 문헌, 대승 불교 경전, 동아시아의 용 이야기","exhibit_id":null,"sort_order":151},{"slug":"ankh","name":"앙크","name_en":"Ankh","kind":"ornament","figure_slugs":["horus","osiris","ptah"],"origin":"'생명'을 뜻하는 이집트 상형 문자로, 제1왕조 때부터 쓰였고 고왕국 말기부터는 부적으로도 만들었습니다. 생김새가 무엇에서 왔는지는 샌들 끈, 매듭 부적, 거울 등 여러 설이 있습니다.","power":"생명과 그것을 지키는 힘, 저승에서 넋을 되살리는 힘을 나타냅니다. 신들은 앙크를 손에 들고 왕의 코에 대어 생명의 숨을 불어넣습니다.","price":null,"source":"고대 이집트의 신전·무덤 부조와 상형 문자","exhibit_id":"ankh-model-met","sort_order":152}]$seed$::jsonb)
on conflict (slug) do nothing;
commit;
